pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally to fill ratio.
    let fill = (item_size as f64) / cap;
    score -= 2.5 * fill * (bin_residual as f64);

    // Penalize creating small unusable dead space (post_residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: bonus if next item fits the post residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * (next_item_size as f64);
        } else if next_item_size as f64 > post_residual as f64 {
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely better.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin scaled by how many bins already fit the item.
        score += 25.0 + 8.0 * (fitting_bins_count as f64);
        // Early in stream, opening bins is cheaper (build diversity); late, expensive.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - t);
        // If item is large and mean residual is small, new bin is attractive.
        score -= 0.15 * (item_size as f64) * (mean_residual / cap);
    }

    // Slight preference for bins with residual below mean (use crowded bins first).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Mild penalty for many open bins: encourage consolidation.
    score += 0.02 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits strongly (post_residual small relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residual too small for typical future items (1..100)
    if post_residual < 20 && post_residual > 0 {
        score += 12.0 * (20.0 - post_residual as f64);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item won't fit here; mild penalty proportional to mismatch
        score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: only one bin can fit the item; use it rather than open new
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Many alternatives: mild penalty to discourage wasting a scarce-fit bin
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying over time and with many open bins
        let mut new_bin_cost = 20.0
            - 10.0 * progress
            - 0.5 * (open_bins_count as f64).min(10.0);
        // If no open bin fits (this is the only candidate), strongly favor new bin
        if fitting_bins_count == 0 {
            new_bin_cost -= 60.0;
        }
        // If next item is large and current item small, deferring packing is fine
        if next_item_size >= item_size && item_size <= 30 {
            new_bin_cost -= 5.0;
        }
        score += new_bin_cost.max(-60.0);
    }

    // Global state: high mean residual across open bins -> prefer filling existing bins
    if mean_residual > 40.0 {
        score -= 0.10 * (mean_residual - 40.0);
    }

    // Late in stream: consolidate aggressively, avoid leaving many half-full bins
    if progress > 0.8 {
        score += 6.0 * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize bins whose residual deviates above the mean (fragmented bins).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 + 10.0;
        // If this is a last-chance situation for existing bins, new bin is bad.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        score -= 0.3 * next_item_size as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Lookahead synergy: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: very small post_residual is excellent.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead space penalty: gaps too small to ever hold an item (min size 1..100 unknown,
    // so treat gaps below a conservative threshold as wasted, scaled by how dead they are).
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }

    // Penalize gaps that cannot fit the next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward keeping room for the next item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size).min(30) as f64 * 0.5;
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it over opening new.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // but allow it when many bins are open (consolidation phase).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 - 0.4 * progress);

    // New-bin candidate: penalize mildly so it's only chosen when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if next item is large and mean residual is tiny, opening fresh is fine.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 45.0;
        }
    }

    // Slight preference for bins with residual close to item size (best-fit shaping).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // Penalize if next item cannot fit here anyway (wasted pairing opportunity).
            score += 3.0;
        }
        // Perfect chain: next item exactly fills remaining space.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: opening a new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Cheaper to open new bins early in the stream (more future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // If many bins are open and none fit well, new bin is more acceptable.
        score -= 2.0 * open_bins_count as f64;
        // If mean residual is high, existing bins have room; discourage new bin.
        score += 0.3 * mean_residual;
    }

    // Prefer bins below mean residual (smaller bins absorb items, keeping large gaps free).
    if bin_residual != bin_capacity {
        score += 0.1 * ((bin_residual as f64) - mean_residual);
    }

    // Mild penalty for spreading across many open bins late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify by integer division into bands of 10.
    let band = post_residual / 10;
    // Residuals that are small-but-nonzero are dead space; residuals that are
    // multiples of 10 (or zero) are "harmonic" and reusable. Reward harmonic classes.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 6.0 + (band as f64) * 0.5;
    } else {
        // Penalize off-class residuals, worse when far from a class boundary.
        let frac = (post_residual % 10) as f64;
        score += (10.0 - frac) * 0.4;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Fits, but leaves another residual: mild reward scaled by leftover class.
            let nxt_post = post_residual - next_item_size;
            score -= 8.0 - (nxt_post % 10) as f64 * 0.3;
        } else {
            // Next item won't fit here: penalize, scaled by overshoot magnitude.
            let over = (next_item_size - post_residual) as f64;
            score += 3.0 + over * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible (tiny post_residual that is off-harmonic).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual > 0 && post_residual < 10 {
            score += 10.0; // near-dead space: reconsider new bin
        }
    }

    // Perfect fit is always excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should win only when all open bins
    // would leave badly fragmented state. Base new-bin score near mean residual.
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.3 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Mild late-stream tightening: prefer compacting into few bins early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = post / cap;
    let fill = item / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = post * (1.0 + 0.35 * fit_ratio * (1.0 - fit_ratio));

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post-residual) are worth more.
    score -= 18.0 * progress * (1.0 - fit_ratio).powi(2) * fill;

    // Penalize large unusable dead space quadratically.
    if post < item {
        let dead = (item - post) / cap;
        score += 25.0 * dead * dead * cap;
    }

    // Lookahead coupling: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = (post - nxt).abs();
        score -= 8.0 * (1.0 - slack / cap) * (post >= nxt) as i32 as f64;
        score += 5.0 * (slack / cap).powi(2);
    }

    // Last-chance bonus: only one fitting bin -> strong smooth reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - fit_ratio);
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - fit_ratio;
        score += 45.0 * (1.0 - tightness.powi(3));
        score += 10.0 * (1.0 - progress);
    }

    // Mild diversity term: prefer bins deviating from mean residual smoothly.
    score += 0.15 * (res - mean_residual).powi(2) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
