    // (below-mean residual bins are "nearly full" -> use them first).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual gap is "dead" if no plausible future item (>=1) could ever
    // use it well; treat gaps below a small threshold as wasted capacity.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Mid-range dead space (hard to fill exactly) gets a softer penalty.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Perfect fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the leftover gap -> penalize proportional gap
        score += (post_residual as f64) * 0.4;
    }

    // New-bin candidate logic: only attractive when open bins are tight or
    // this placement would create severe dead space.
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        // With few bins and roomy residuals, opening a new bin is bad.
        score += 15.0;
        score -= tightness * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for tighter bins overall.
    score += (bin_capacity as f64 - bin_residual as f64) * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tight fit preferred (low post_residual).
    let mut score = post;

    // Non-linear coupling: quadratic dead-space penalty grows with stream progress
    // (late in the stream, wasted space is costlier to amortize).
    let tight = post / cap;
    score += tight * tight * cap * (0.5 + progress);

    // Reward placing into a bin when it is the last chance to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; keep flexibility.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit here: penalize residuals just below next size (dead space).
            let miss = (nxt - post) / cap;
            score += 6.0 * miss * miss * cap;
        }
    }

    // Prefer filling bins that are already relatively empty vs. the fleet mean:
    // steer consolidation toward low-residual bins.
    score += 0.15 * (mean_residual - post);

    // Slight preference to use more-open-bins states early (spread) and
    // consolidate later via progress-coupled term on bin count.
    score += 0.5 * open_bins_count as f64 * (0.2 + progress);

    // New-bin candidate (empty bin): only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral base plus penalty that shrinks as fits elsewhere get worse.
        // If item fits badly in existing bins (large post_residual elsewhere),
        // opening a new bin becomes competitive.
        score = 0.55 * cap + 0.25 * item_size as f64 - 0.1 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in stream, prefer reusing existing bins: raise new-bin cost.
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tightest fit).
    score = post_residual as f64;

    // Strict dead-space penalty: small gaps (< 10, minimum item size) are unusable.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 60.0; // full waste, heavily penalize
    } else if post_residual < 20 {
        score += 15.0; // risky small gap
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward filling a bin substantially (post_residual small relative to capacity).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: many open bins -> favor compacting into existing bins,
    // penalize opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins fit poorly
        // or post_residual would be dead space.
        let poor_fit = dead || post_residual > (bin_capacity as f64 * 0.45) as u32;
        let pressure = open_bins_count as f64 / 8.0;
        if poor_fit {
            score -= 30.0 + 10.0 * pressure;
        } else {
            score += 40.0 + 15.0 * pressure;
        }
    } else {
        // Existing bin: reward using it, more so when many bins are open.
        score -= 5.0 + (open_bins_count as f64).min(20.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // blocks the next item
    }

    // Early stream: be more conservative about opening new bins early
    // (bins may combine later); late stream: compact aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty when this bin's residual is far from mean residual
    // (prefer balancing? no — prefer using below-mean bins to drain them).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fill is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0 + (next_item_size as f64) * 0.5;
        } else {
            // dead space that next item cannot use
            score += 15.0;
        }
        // exact 2-chain: post_residual == next_item_size exactly
        if post_residual == next_item_size {
            score -= 120.0;
        }
    }

    // Penalize tiny unusable residuals (< 10, minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Tight fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 50.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless they're bad fits
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if no good fit exists (large dead space everywhere), opening new bin is fine
        if mean_residual < (item_size as f64) * 1.1 {
            score -= 80.0;
        }
    }

    // Relative to mean residual: prefer placing into bins with below-average residual
    // (keeps many medium bins rather than one huge + fragmented ones)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 40.0 + 60.0 * tightness;
    } else if next_item_size > 0 {
        // Penalize dead space that cannot fit the next item, scaled by how close it is to being useless.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 15.0 * (1.0 - waste);
    }

    // Prefer tightest relative fit vs mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing residuals are poor
    // or too fragmented to fit the item.
    if bin_residual == bin_capacity {
        let usable = if next_item_size > 0 { post_residual >= next_item_size } else { post_residual == 0 };
        let poor_open = mean_residual < item_size as f64 * 1.1 || fitting_bins_count == 0;
        if usable && !poor_open {
            score += 250.0; // keep using open bins when they work
        } else {
            score -= 60.0;  // open a new bin when open bins are hopeless
        }
    }

    // Mild penalty for wasting space in bins with large residual (avoid squandering flexible bins).
    if bin_residual >= bin_capacity * 3 / 4 && bin_residual < bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Core: quadratic coupling of post_residual with stream progress.
    // Later in the stream, leaving residual is more costly -> steeper penalty.
    let mut score = post * (1.0 + 0.9 * progress * progress) + 0.004 * post * post;

    // Reward tight fits (small post_residual) with a smooth non-linear bonus.
    score -= 12.0 * (-post / 18.0) * (-post / 18.0);

    // Penalize filling a mostly-empty bin with a small item (wasteful packing).
    let fill_ratio = item / cap;
    score += 20.0 * fill_ratio * (1.0 - fill_ratio) * (1.0 - fill_ratio);

    // Smooth interaction: large residual + small item is bad.
    let res_ratio = bin_residual as f64 / cap;
    score += 6.0 * res_ratio * res_ratio * (1.0 - fill_ratio);

    // Lookahead: bonus if next item fits exactly in the post-residual (chained fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 8.0 * (-gap / 15.0) * (-gap / 15.0);
        // Penalize if post-residual is just barely unusable for the next item.
        if post < nxt && post > 0.0 {
            score += 4.0 * (post / nxt);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Slight penalty when many bins fit, to encourage consolidation.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Nudge toward bins with residuals below the mean (use up tighter bins first).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when residual is full (empty) and the item
    // is large; otherwise keep it slightly penalized so open bins get used.
    if bin_residual == bin_capacity {
        score += 10.0 - 14.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leftover after that matters too.
            let two_step_left = post_residual - next_item_size;
            score -= 100.0 - (two_step_left as f64);
            if two_step_left == 0 {
                score -= 200.0;
            }
        } else {
            // Next item does NOT fit here: penalize creating residual smaller than next item.
            let dead = post_residual as f64;
            score += 40.0 + dead * 0.5;
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 50.0;
    }

    // Compare against mean residual: bins with residual far above mean waste capacity.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += 0.3 * (residual_f - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - residual_f);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive when current bins are bad fits
    // or the stream is early with room to consolidate later.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of opening a new bin, reduced when few bins fit the item.
        let mut new_bin_score = bin_capacity as f64 - 80.0;
        if fitting_bins_count == 0 {
            new_bin_score -= 400.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            // New bin can host both current and next item comfortably.
            new_bin_score -= 30.0;
        }
        if progress < 0.3 {
            new_bin_score += 50.0 * (1.0 - progress * 3.3);
        }
        score = score.max(0.0) * 0.0 + new_bin_score.max(score - 500.0);
        // Ensure new bin loses to genuine good fits but wins over bad fits.
        if post_residual == 0 {
            score = 10_000.0; // never open new bin when a perfect fit exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item still fits comfortably in the post residual.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 * next_item_size as f64;
    }
    // Next item cannot use the leftover: penalize dead space proportionally.
    else if next_item_size > 0 {
        score += 2.0 * next_item_size as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins tighter than the mean residual (good fits).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when it is genuinely the best option,
    // i.e. item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / (bin_capacity as f64);
        // Opening a new bin is penalized mildly; it wins only when existing
        // bins would leave huge unusable gaps.
        score += 20.0 - 30.0 * tightness;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0; // fresh bin can absorb the next item too
        }
    }

    // Slight late-stream bias toward consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (small gaps that few future items can fill) are heavily penalized.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits generally: small waste relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when the current item leaves a
    // large residual (good for future items) and open bins are numerous.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64;
        score -= 5.0 * (open_bins_count as f64);
        // Lookahead: if next item fits the new bin's residual, favor it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // Pressure from number of open bins: prefer filling existing bins
        // when many are open; penalize bins whose residual is far above mean
        // (they are less likely to be consolidated).
        score += 0.5 * (open_bins_count as f64);
        if (bin_residual as f64) > mean_residual {
            score += (bin_residual as f64 - mean_residual) * 0.3;
        }
    }

    // Lookahead synergy: if the next item exactly fits the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for stranding space.
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect 2-step match (bin will be exactly filled after next item).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Reward: post_residual can accommodate next item exactly or leave small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.6 * (post_residual as f64 - next_item_size as f64).min(30.0);
    } else if next_item_size > 0 {
        // Penalize dead space below next item size (wasted residual).
        score += 2.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Penalize creating very small unusable slivers relative to mean residual.
    if post_residual < 10 {
        score += 120.0;
    }

    // Prefer bins tighter than the mean residual (good fits).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 150.0 - 100.0 * progress;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 50.0; // pairing two identical items in a fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly hold the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 4.0 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            // Perfect match for the next item: strong reward.
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0; // base cost of opening a new bin
        // Cheaper to open a new bin when few open bins or late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        if open_bins_count == 0 {
            score -= 40.0;
        }
        // If the item fits poorly anywhere (huge item), opening a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        // If lookahead won't fit post-placement in a typical bin, fresh bin helps.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Slight preference for bins with residuals below the mean (consolidating space).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 0.5 * diff.min(20.0);
        } else {
            score += 0.3 * (-diff).min(20.0);
        }
    }

    // Prefer filling bins with larger residuals early on (keep small residual bins flexible).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score += (1.0 - progress) * (bin_residual as f64) * 0.05;
    }

    // Gentle tie-breaker: spread load across many open bins.
    score += 0.02 * open_bins_count as f64;

