    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strongly discourage opening a new bin when an open bin can fit.
            score += 60.0 + (fitting_bins_count as f64 * 5.0);
            // Less punitive if the item would leave a very awkward residual everywhere.
            if post_residual as f64 > mean_residual * 1.5 {
                score -= 20.0;
            }
        } else {
            // Forced to open a new bin: slight reward.
            score -= 10.0;
        }
        return score;
    }

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            // Perfect match: next item exactly fills this bin.
            score -= 45.0;
        } else if post_residual as f64 >= nxt {
            // Next item can fit here afterwards: reward proportionally to tightness.
            let gap = post_residual as f64 - nxt;
            if gap <= 10.0 {
                score -= 30.0 - gap * 1.5;
            } else {
                score -= 15.0 * (1.0 - gap / (bin_capacity as f64));
            }
        } else {
            // Next item won't fit here: penalize by how much it overshoots.
            let over = nxt - post_residual as f64;
            score += over * 0.6;
        }
    } else {
        // Last item: prefer minimal residual.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residuals below mean are "tighter",
    // favor filling them to keep many mid-size residuals available.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.25;
    } else {
        score += (pr - mean_residual) * 0.15;
    }

    // Dead-space penalty: very small residuals that likely can't fit future items
    // (items >= 10 in classic streams; use a soft threshold).
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 2.0;
    }

    // Last-chance bonus: this is the only bin that fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early-stream exploration: be slightly less greedy about tight fits early on.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (0..1).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Detect brand-new empty bin candidate.
    let is_new_bin = bin_residual == bin_capacity;

    // Tight fit reward: strongly favor placements that nearly fill the bin.
    // post_residual in [0..100]; a residual of 0 is a perfect fill.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Dead-space penalty: tiny unusable leftovers (can't fit min item of 1)
    // are only bad if they are small but nonzero; exact zero is ideal.
    if post_residual > 0 {
        score += 6.0 * (1.0 - post_residual as f64 / 10.0_f64.min(bin_capacity as f64)).max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Lookahead (k=2): reward if the next item can also fit in the post residual,
    // penalize if next item is large and would be stranded.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        } else {
            // Next item won't fit here; mild penalty proportional to how much
            // would be left stranded relative to mean residual.
            score += 4.0 * (post_residual as f64 / (mean_residual.max(1.0)));
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // discourage opening yet another bin; when few bins or low mean residual,
    // a new bin is more acceptable for large items.
    if is_new_bin {
        let crowd = (open_bins_count as f64).ln().max(0.0);
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Base penalty for opening a new bin when others could fit.
        score += 30.0 + 10.0 * crowd * mean_fill;
        // Late in the stream, opening new bins is more wasteful.
        score += 12.0 * progress;
        // Very large items deserve fresh bins more readily.
        score -= 0.25 * item_size as f64;
    }

    // Mild preference to fill bins that are already quite full (consolidation).
    let pre_fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * pre_fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let mean_res = mean_residual.clamp(0.0, cap);

    // Base: prefer tight fits (small post_residual), non-linearly.
    let x = pr / cap; // normalized post-residual in [0,1]
    let mut score = pr as f64;

    // Non-linear tightness reward: quadratic + cubic coupling with stream progress.
    // Late in the stream, tight fits matter more (less future to amortize waste).
    let tightness = (1.0 - x) * (1.0 - x) - 0.5 * x * (1.0 - x);
    score -= 60.0 * tightness * (0.6 + 0.8 * progress);

    // Penalize dead space relative to the mean residual of open bins:
    // a bin whose post-residual deviates strongly from the fleet mean creates
    // awkward leftovers; smooth quadratic deviation penalty.
    let dev = pr - mean_res;
    score += 0.35 * dev * dev / cap;

    // Lookahead coupling: reward leaving exactly enough room for the next item,
    // penalize leaving a gap the next item can't use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            // Next item fits: reward proportionally to how snugly it will fit.
            let snug = 1.0 - (gap / cap);
            score -= 25.0 * snug * snug * (1.0 - progress);
        } else {
            // Next item won't fit here: penalize proportional to unusable space.
            score += 12.0 * (-gap / cap) * cap * 0.01 * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (smoothly scaled by fill ratio of the bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill = 1.0 - br / cap;
        score -= 40.0 * (0.5 + fill);
    }

    // New-bin candidate handling: an empty bin gets a moderate baseline score.
    // It should win only when no open bin offers a decent fit; we bias it with
    // a smooth penalty that grows with the number of fitting alternatives and
    // with how much residual capacity the fleet already holds.
    if bin_residual == bin_capacity {
        let fleet_res = open_bins_count as f64 * mean_res;
        score += 30.0
            + 8.0 * (fitting_bins_count as f64)
            + 0.05 * fleet_res
            + 20.0 * (1.0 - progress);
    } else {
        // Slight preference for filling already-open bins as stream progresses.
        score += 5.0 * (1.0 - progress) * (br / cap);
    }

    // Mild penalty for proliferation of open bins late in the stream.
    score += 0.5 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify by integer division into bands of 10.
    let band = post_residual / 10;
    // Residuals that are small-but-nonzero are dead space; residuals that are
    // multiples of 10 (or zero) are "harmonic" and reusable. Reward harmonic classes.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 6.0 + (band as f64) * 0.5;
    } else {
        // Penalize off-class residuals, worse when far from a class boundary.
        let frac = (post_residual % 10) as f64;
        score += (10.0 - frac) * 0.4;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Fits, but leaves another residual: mild reward scaled by leftover class.
            let nxt_post = post_residual - next_item_size;
            score -= 8.0 - (nxt_post % 10) as f64 * 0.3;
        } else {
            // Next item won't fit here: penalize, scaled by overshoot magnitude.
            let over = (next_item_size - post_residual) as f64;
            score += 3.0 + over * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible (tiny post_residual that is off-harmonic).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual > 0 && post_residual < 10 {
            score += 10.0; // near-dead space: reconsider new bin
        }
    }

    // Perfect fit is always excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should win only when all open bins
    // would leave badly fragmented state. Base new-bin score near mean residual.
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.3 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Mild late-stream tightening: prefer compacting into few bins early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that are too small to
    // hold even the smallest plausible item (1..10) are pure waste.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit is maximally desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual can still host the lookahead item,
    // penalize placements that strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> favor consolidating into
    // existing bins over opening yet another one.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure,
        // but relax late in the stream when consolidation is less valuable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 25.0 * pressure * (1.0 - 0.5 * progress);
    } else {
        score -= 3.0 * pressure;
    }

    // Slight preference for filling bins below mean residual (tighter bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Partial lookahead: next item still fits after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Dead space penalty: tiny unusable leftovers.
    if post_residual < 10 {
        score += 20.0 - 2.0 * post_residual as f64;
    }

    // Reward tight fits (small post_residual, but usable).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 6.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Relative to mean residual: prefer bins below-average residual (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Penalize new bin opening when reasonable alternatives exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 12.0;
            // Extra penalty early/mid stream when many bins are open.
            score += 0.5 * open_bins_count as f64;
            // If next item would fit perfectly in the fresh bin too, soften penalty.
            if next_item_size > 0 && next_item_size >= item_size {
                score -= 4.0;
            }
        } else {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins tighter as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small, hard-to-use residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 4.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Bonus if post-residual is a snug home for the next item.
            let snug = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 4.0 * (1.0 - snug);
        } else {
            // Penalize creating a residual that the next item cannot use.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // fits poorly everywhere else (large residual waste potential) or the stream
    // is early and we can afford spreading.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 14.0;
        // Early in the stream, spreading is slightly cheaper.
        new_bin_penalty -= 6.0 * (1.0 - progress);
        // If many bins are open with high mean residual, spreading is less costly.
        new_bin_penalty -= 0.15 * (open_bins_count as f64).sqrt();
        new_bin_penalty -= (mean_residual / bin_capacity as f64).min(1.0) * 4.0;
        // A new bin gives perfect post-residual for large future items.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty -= 5.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for filling bins that are already relatively full.
    let used_fraction = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 3.0 * used_fraction;

    // Global balance: slightly discourage bins far below the mean residual
    // (they are "wasteful" outliers) unless the fit is very tight.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 2.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, but with a non-linear (quartic) penalty on small residuals
    // so that near-perfect fits are strongly favored over moderate ones.
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, moderate residuals are acceptable (bins stay flexible);
    // late in the stream, only tiny residuals should win.
    let flexibility = (1.0 - progress) * (1.0 - progress);
    score += 60.0 * norm_pr * norm_pr * progress;
    score -= 40.0 * norm_pr * flexibility;

    // Smooth dead-space penalty: residual too small for the smallest plausible item (<=10)
    // is wasted space; penalize via a smooth sigmoid-like ramp around the threshold.
    let dead = (10.0 - pr).max(0.0) / 10.0;
    score += 90.0 * dead * dead;

    // Lookahead coupling: reward residuals that can still hold the next item,
    // penalize residuals that can hold it only barely (creating fragmentation risk).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 25.0 * (1.0 - slack * slack);
        } else {
            let miss = (ni - pr) / cap;
            score += 35.0 * miss;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (smooth ramp on scarcity).
    if fitting_bins_count <= 1 {
        score -= 45.0;
    } else {
        score += 6.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Mild pressure to consolidate when many bins are open (non-linear in count).
    let density = open_bins_count as f64;
    score += 4.0 * (density / (density + 10.0)) * norm_pr * cap;

    // Nudge toward bins whose residual deviates from the mean (harmonization),
    // using a smooth quadratic coupling.
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev - 10.0 * dev;

    // Small smooth bonus for larger fill fraction (item_size relative to residual).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill * fill * (1.0 - progress * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: post_residual in small harmonic classes
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    } else if post_residual <= 30 {
        score -= 10.0;
    }

    // Harmonic class of post_residual modulo 10: prefer residuals that small items can fill
    let cls = post_residual % 10;
    if cls == 0 {
        score -= 6.0;
    } else if cls >= 5 {
        score += 2.0;
    }

    // Lookahead: if next item fits the post residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 8.0 + (10 - slack.min(10)) as f64;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins far below mean residual (avoid wasting space in nearly-full bins mismatch)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // New-bin candidate: penalize mildly, but allow it when residual waste would be large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = post_residual as f64;
        let base = 18.0 - 10.0 * progress;
        score += base + 0.15 * waste;
        // If no open bin fits tightly, new bin looks better when waste is small
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Small bonus for filling larger bins first (best-fit by residual already primary)
    score += 0.02 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to current residual (fill ratio of this placement).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin offers a good fit
    // (i.e., this bin's residual is large and item leaves a useful gap).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 20.0 + 2.5 * open_bins_count as f64;
        // But if existing bins would leave tiny dead space, a fresh bin is better.
        if post_residual >= 10 || post_residual == 0 {
            score -= 30.0;
        }
        // Lookahead: if next item fits in the fresh residual, boost new bin appeal.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0;
        }
    } else {
        // Existing bin: reward if it can also host the next item after this placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 {
            score += 8.0; // would strand the next item
        }
    }

    // Prefer placing large items into bins with small residuals (avoid wasting big gaps).
    if item_size as f64 > 0.6 * bin_capacity as f64 && bin_residual < bin_capacity as f64 * 0.85 {
        score -= 10.0;
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - fill_ratio);

    // Mean residual coupling: when open bins are mostly empty, prefer filling them.
    if mean_residual > 0.5 * bin_capacity as f64 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 / (1.0 + diff * diff);
        // Partial reward when next item fits comfortably (<= 60% of post residual).
        if post_residual >= next_item_size {
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill;
        } else {
            // Next item cannot use this residual: penalize dead space.
            score += 0.35 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fit (small post residual).
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it's genuinely needed.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0 * fitting_bins_count as f64;
        }
    }

    // Mild tie-break: prefer bins with residual below mean (concentrating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Prefer tighter relative fit overall.
    score += 0.15 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- New empty bin candidate ---
    if bin_residual == bin_capacity {
        // Baseline: a fresh bin is worse than any decent fit (post < 62 beats it),
        // but better than leaving big dead space (post > 62 loses to it).
        let mut s = cap * 0.62;
        // Large current items are more "bin-worthy" (a fresh bin gives them room);
        // small items should prefer squeezing into open bins.
        s += (item / cap) * 6.0;
        // Lookahead: if the next item is small, a fresh bin can absorb it too — slight bonus.
        if nxt > 0.0 && nxt <= cap - item {
            s -= 4.0 * (1.0 - nxt / cap);
        }
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        s *= 1.0 - 0.10 * t;
        return s;
    }

    // --- Existing open bin ---
    let mut score = post;

    // Tightness reward: the fuller the bin becomes relative to its residual, the better.
    score -= (1.0 - post / res) * 10.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Lookahead coupling: reward if the next item exactly fills this bin's post-residual,
    // penalize if the next item won't fit anywhere in the leftover space.
    if nxt > 0.0 {
        if nxt <= post {
            score -= 7.0 * (1.0 - nxt / post.max(1.0));
        } else {
            score += 4.0;
        }
    }

    // Global pressure: if open bins are generally full (low mean residual),
    // slightly favor using any fitting bin; if bins are loose, be pickier.
    score += (mean_residual - res) * 0.06;

    // Dead-space penalty for very small leftovers that likely become unusable.
    if post > 0.0 && post < 10.0 {
        score += 2.0;
    }

    // Mild time-horizon scaling: late in the stream, tighten selection.
    score *= 1.0 + 0.08 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let res_frac = pr / cap;

    // Base: penalize leftover space non-linearly (waste grows superlinearly).
    let mut score = pr as f64 * (1.0 + 1.5 * res_frac * res_frac);

    // Reward tight fits: subtract for small relative residual, smooth quadratic coupling with progress.
    score -= 30.0 * (1.0 - res_frac) * (1.0 - res_frac) * (1.0 + progress);

    // Non-linear coupling of item size with progress: large items early -> prefer filling existing bins.
    score -= 8.0 * fit_frac * fit_frac * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 + 25.0 * progress;
    }

    // Mean residual coupling: prefer bins deviating from mean (consolidate residuals).
    score += 0.35 * (pr - mean_residual).abs();

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (1.0 - gap / cap).max(0.0);
        // Penalize leaving residual that is too small for the next item (dead space).
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 10.0 * (1.0 - pr / cap);
        }
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are all poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = pr > cap * 0.55; // item leaves lots of space in any bin
        score = if poor_fit { 25.0 - 20.0 * progress } else { 60.0 + 40.0 * progress + 0.5 * open_bins_count as f64 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space quantization.
    // Residuals that are "useless" for typical items (1..100) get penalized
    // more when they fall into awkward classes (e.g. 1..9, non-round numbers).
    let pr = post_residual;
    if pr > 0 {
        // Small residuals are likely dead space: penalize mildly.
        if pr < 10 {
            score += 12.0;
        }
        // Round harmonic classes (multiples of 5, 10, 20, 25) remain usable
        // by a wide family of item sizes: reward them.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Integer-division thresholds: classify residual into harmonic bands.
        let band = pr / 20; // 0: tiny, 1: small, 2: medium, 3: large, 4+: near-full
        match band {
            0 => score += 8.0,   // tiny leftover, likely dead
            1 => score += 2.0,
            2 => score -= 2.0,   // medium residual ~40-59: versatile
            3 => score -= 4.0,   // large residual: very versatile
            _ => score -= 1.0,
        }
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this is a great chaining placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportional to how snugly the next item will fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack.min(10.0) * 0.5;
            // Harmonic bonus: post_residual == next_item_size exactly.
            if post_residual == next_item_size {
                score -= 25.0;
            }
            // Reward when post residual lands in a harmonic class matching
            // the next item's class (same decade / same mod-5 bucket).
            if pr / 10 == next_item_size as u32 / 10 {
                score -= 4.0;
            }
        } else {
            // Next item cannot fit here: the leftover becomes dead space
            // unless it is a standard small class.
            if pr < 10 && pr > 0 {
                score += 6.0;
            }
        }
    }

    // Last chance: this is the only bin that fits the item. Strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): only attractive when no good fit exists
    // among open bins. Penalize mildly so we prefer filling open bins unless
    // the fit would be terrible, but reward when current fit leaves a tiny
    // awkward residual and a fresh bin can host future large items.
    if bin_residual == bin_capacity {
        // Base penalty: opening new bins is generally costly.
        score += 15.0;
        // But if the stream is early, opening bins spreads load.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If the best alternative would leave a tiny dead residual,
        // a fresh bin is better (handled implicitly: other bins got the
        // small-residual penalty; add extra when next item is large).
        if next_item_size >= 60 {
            score -= 10.0;
        }
        // Many open bins with low mean residual: consolidation phase, avoid new bins.
        if mean_residual < 25.0 && open_bins_count > 3 {
            score += 20.0;
        }
    }

    // Prefer bins whose residual deviates strongly from the mean residual
    // in the tight direction (consolidate nearly-full bins).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    } else {
        score += (-dev) * 0.15;
    }

    // Mild pressure to reduce open bin count as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are wasted capacity.
    // A residual gap is "dead" if it is too small to hold even the
    // smallest plausible item, or too small for the lookahead item.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 120.0; // completely dead gap: worst outcome
        } else if next_item_size > 0 && post_residual < next_item_size {
            // gap cannot host the next item: likely dead space
            let gap_deficit = (next_item_size - post_residual) as f64;
            score += 40.0 + gap_deficit * 0.8;
        } else {
            // usable gap: mild reward proportional to how well the
            // next item would fit into the remaining space
            if next_item_size > 0 {
                let next_fit = 1.0 - ((post_residual - next_item_size) as f64 / cap);
                score -= 6.0 * next_fit;
            }
        }
    }

    // Tight-fit reward: filling the bin almost exactly is excellent.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 35.0 * (fill_ratio - 0.85) / 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer
    // using it over opening a new bin (unless dead space results).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: the empty bin should only win when
    // every open placement would create severe dead space. Give the
    // empty bin a moderate baseline so good fits in existing bins win.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, modulated by stream
        // progress and how many bins are already open
        score = 55.0 + 0.35 * open_bins_count as f64
            + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // if the next item is large, a fresh bin preserves big space
        if next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Open-bin pressure: mildly discourage scattering across many bins
    // by penalizing placements that leave large residual spread.
    let residual_dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * residual_dev;

    // Late-stream consolidation: as the stream nears its end, favor
    // filling existing bins tightly rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: leaving near-zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item, or can tightly chain-pack it.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score -= 400.0 / (1.0 + diff as f64);
        if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 300.0;
        }
        // Penalize residual that is too small for the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are preferred.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it enables
    // a perfect lookahead chain or existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64).abs() <= 2 {
            score -= 200.0;
        }
        if post_residual > 60 {
            score += 50.0;
        }
    }

    // Late-stream tightening: as the stream progresses, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize creating dead space too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: reward bins whose post residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Bin closes after this item; only good if the fit was tight.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be picky (penalize mediocre fits);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - tightness);

    // Global state coupling: when many bins are open with high mean residual,
    // prefer filling existing bins over opening new ones.
    if open_bins_count > 0 {
        score -= 0.5 * (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: make empty bins moderately attractive only when the
    // item is large or existing fits are poor; otherwise discourage opening.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 35.0 - 30.0 * large_item;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can host a chain of large items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with a quadratic sharpening term
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling of post-residual with stream progress:
    // early on, tight fills matter slightly less; late, dead space is costly
    let progress_coupling = 60.0 * norm_pr * (0.5 + progress * progress);
    score += progress_coupling;

    // Penalize leaving residual that cannot fit the next item (lookahead),
    // smoothly weighted by how "wasted" the gap is
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 25.0 * gap * (1.0 + progress);
        } else {
            // reward residual that still accommodates the next item
            let slack = (pr - nxt) / cap;
            score -= 10.0 * slack * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 - norm_pr);
    } else if fitting_bins_count > 1 {
        // slight penalty when many bins compete, encouraging tighter competition
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mean-residual interaction: if this bin's residual deviates from the mean,
    // prefer consolidating into larger-residual bins (smooth term)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 15.0 * dev * (0.3 + 0.7 * progress);

    // New-bin candidate handling: make empty bins mildly unattractive unless
    // no good fit exists (post_residual == capacity means brand-new bin)
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / cap;
        // new bin is fine for large items or when few bins are open
        score = pr - 30.0 * tightness - 5.0 * (open_bins_count as f64).ln().max(0.0);
        // late in the stream, opening new bins is worse
        score += 35.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    // Class 1: post_residual in 1..=10 (dead space) -> penalize.
    // Class 2: post_residual in 11..=30 (small item could land) -> mild reward.
    // Class 3: post_residual > 30 (flexible) -> reward proportional to fit density.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score += 18.0;
    } else if post_residual <= 30 {
        score -= 6.0;
    } else {
        score -= 10.0;
    }

    // Integer-division thresholds on post_residual relative to typical small items.
    let quarter = bin_capacity / 4; // 25
    let eighth = bin_capacity / 8;  // 12
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 8.0; // leftover exactly divisible into quarter chunks
    }
    if post_residual % eighth == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 14.0; // chain placement possible
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 6.0; // chaining nearly fills bin
            }
        } else if next_item_size <= bin_residual {
            // next item fits current bin but only before this placement
            score += 5.0;
        }
        // modulo harmony between next item and post residual
        if post_residual > 0 && next_item_size % post_residual.max(1) == 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin must not win unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening early when few bins are open is cheaper
        if open_bins_count <= 2 {
            score -= 20.0;
        }
        // If no open bin can fit, new bin is the only option
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Prefer tighter bins overall (closest fit logic via residual normalization)
    score += (bin_residual as f64 / cap) * 6.0;

    // Slight preference to balance against mean residual: avoid bins far above mean
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Reward good fits (tight packing) non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual cannot serve the next item: penalize as dead space.
        score += 8.0;
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64).ln() * (6.0 + 10.0 * progress);

    // New-bin candidate: make it unattractive unless residuals across bins are all poor
    // (i.e., item fits badly everywhere) or the fit here is genuinely tight.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fit_ratio > 0.85 || (fitting_bins_count == 0) {
            score -= 70.0;
        }
    } else {
        // Mild bonus for bins below mean residual (filling emptier bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead matching: reward post_residual that exactly fits next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 == nxt {
            // Perfect 2-step chain: consume the bin completely over two items
            score -= 60.0;
        } else if (post_residual as f64) < nxt {
            // Dead space relative to next item: penalize proportionally to how unusable it is
            let unusable = (nxt - post_residual as f64) / bin_capacity as f64;
            score += 40.0 * unusable;
        } else {
            // post_residual >= next item: small penalty grows with slack after next item
            score += 0.3 * (post_residual as f64 - nxt);
        }
    } else {
        // Last item: prefer filling as tightly as possible
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // --- Relative-to-mean-residual coupling ---
    // Prefer bins whose residual deviates below the mean (tighter, more exhausted bins)
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    // --- Last-chance bonus: if this is the only fitting bin, strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the current item is huge
        // relative to what open bins can absorb, or no bins fit well.
        // Penalize mildly so we prefer existing bins unless lookahead says otherwise.
        score += 15.0;
        if item_size >= 70 {
            score -= 10.0; // large items pair well with a fresh bin
        }
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            score -= 20.0; // fresh bin can host a near-perfect 2-item chain
        }
    }

    // --- Mild stream-progression pressure: late in the stream, tighten packing ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // --- Tie-break toward fewer open bins (consolidation) ---
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness: strongly reward small post residual (non-linear).
    let tightness = 1.0 - (post / cap);
    score -= 35.0 * tightness * tightness;

    // Penalize dead space that can't fit typical small items (<= 10 threshold).
    if post > 0.0 && post < 10.0 {
        score += 12.0; // wasted sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild penalty when many alternatives exist, favoring diversity of choice.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // Lookahead: if next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * ((nxt - post) / cap);
        }
    }

    // Prefer fuller bins relative to the fleet's mean residual.
    score += 0.35 * (mean_residual - post).max(0.0);

    // New-bin candidate logic: empty bin gets a base penalty so we only open
    // when no decent existing fit exists; discount late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 20.0;
        // Opening a bin is cheaper late in the stream (less residual to waste).
        new_bin_penalty *= 1.0 - 0.5 * progress;
        // If the item is large and would leave a big hole in an existing bin,
        // a fresh bin is relatively more attractive.
        new_bin_penalty -= 0.05 * item_size as f64;
        // If few bins can fit, opening is less costly.
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // Time horizon: early stream, be conservative with near-full bins (keep
    // flexibility); late stream, squeeze hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score -= 6.0 * tightness;
    } else if post > 0.0 && post < 20.0 && fitting_bins_count > 1 {
        score += 3.0; // keep flexible bins early
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_norm = item_size as f64 / cap;

    let mut score = post;

    // Smooth non-linear coupling: post_residual weighted by progress-dependent factor.
    // Late in the stream, waste matters more -> penalize large post_residual more.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += 0.8 * (post / cap) * (post / cap) * cap * progress_weight;

    // Reward tight fits: small post_residual relative to item size, smoothed polynomial.
    let tightness = 1.0 - post / cap;
    score -= 6.0 * tightness * tightness * fit_norm;

    // Dead-space penalty: residuals too small for any plausible item (smooth via tanh-like poly).
    let dead = (cap - post - 10.0).max(0.0);
    let dead_norm = 1.0 - (dead / cap).min(1.0);
    score += 4.0 * dead_norm * dead_norm * dead_norm;

    // Lookahead: bonus if next item can fit into this bin's post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let slack = (post - nx) / cap;
            score -= 3.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Penalize leaving post_residual that strands the next item.
            score += 2.0 * (nx - post) / cap;
        }
    }

    // New-bin candidate handling: penalize opening a new bin when alternatives exist,
    // unless the fit into existing bins would be poor.
    if bin_residual == bin_capacity {
        let alt_fit_exists = fitting_bins_count > 0;
        if alt_fit_exists {
            // Cost of a new bin decreases as stream progresses (fewer future items affected).
            let new_bin_cost = 30.0 * (1.0 - progress);
            // If the item fits very poorly everywhere (huge item), opening may be fine.
            let escape = 20.0 * fit_norm * fit_norm;
            score += new_bin_cost - escape;
        } else {
            score -= 5.0; // no alternative: new bin is the natural choice
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to use it rather than open a new bin.
        score -= 8.0;
    }

    // Mild pressure to consolidate: prefer bins whose residual deviates below mean
    // (fills fuller bins first), smooth quadratic coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // Slight preference for more crowded states late in stream.
    score -= 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: which quarter of capacity it occupies.
    let item_class = (item_size * 4 / bin_capacity.max(1)) as f64;
    let next_class = if next_item_size > 0 { (next_item_size * 4 / bin_capacity.max(1)) as f64 } else { 0.0 };

    // Reward filling a bin to near-exact harmonic boundaries (post_residual small or ~25/50/75).
    let post = post_residual as f64;
    let boundary_bonus = (post % 25.0).min(25.0 - post % 25.0);
    score -= 6.0 * (1.0 - boundary_bonus / 12.5); // tight or boundary-aligned fits rewarded

    // Dead space penalty: residuals below the smallest item (1) are impossible, but
    // residuals too small to host the next item are wasteful.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0 * (next_item_size - post_residual) as f64 / cap;
    }

    // If next item's harmonic class is compatible with the leftover, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 + 1.5 * next_class;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to typical
    // residuals or many bins are already open and mean residual is small.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap - 0.5).max(0.0);
        let crowded = (open_bins_count as f64 / 8.0).min(1.0);
        score -= 5.0 * pressure * crowded;
        score += 10.0; // base cost of opening a new bin
        if item_class >= 3.0 {
            score -= 6.0; // big items justify fresh bins
        }
    }

    // Prefer tighter bins overall (small residual before placement).
    score += 0.5 * (bin_residual as f64 / cap);

    // Early in the stream, be more willing to spread items (keeps future flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * (1.0 - progress) * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is ideal
    if post_residual == 0 {
        score -= 30.0;
    }

    // Strict dead-space avoidance: leftover gap smaller than the lookahead item
    // is likely wasted space -> penalize proportionally to the wasted amount.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0 + (next_item_size - post_residual) as f64 * 0.6;
    }

    // Reward bins that are already substantially filled (consolidation).
    if bin_residual < bin_capacity {
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Pressure from number of open bins: many open bins -> discourage new bins,
    // mildly favor reusing existing ones.
    score += open_bins_count as f64 * 0.15;

    // New-bin candidate penalty: only chosen when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0;
        // A new bin is attractive if the item is large (little dead space risk)
        score -= item_size as f64 * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();

        // Perfect 2-step fill: post_residual == next_item_size -> huge reward.
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Reward closeness of next item to remaining space.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        }

        // Penalize dead space that next item cannot use at all.
        if post_residual < next_item_size {
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }

        // If next item is large and this bin would be nearly full, that's fine (tight packing).
        if nxt >= 60.0 && post_residual < 10.0 {
            score -= 5.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins with residual below mean (tighter bins).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (pr - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size && post_residual < 10);
        if poor_fit {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    }

    // Small absolute dead-space shaping: nonlinear penalty for awkward residuals.
    if post_residual > 0 {
        let awkward = (post_residual as f64).ln();
        score += 2.0 * awkward;
    } else {
        // Perfect fill of the bin.
        score -= 40.0;
    }

    // Slight progression pressure: later in stream, prefer consolidating into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already base), amplify fit quality.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that likely cannot be reused by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 6.0; // still reusable for small items
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            if waste < 10 {
                score -= 15.0;
            } else {
                score -= 5.0 * (1.0 - waste as f64 / bin_capacity as f64);
            }
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 3.0;
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // More alternatives -> mild penalty for consuming a scarce good bin
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate logic: only attractive when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 35.0;
        // If mean residual is high, open bins have room; penalize new bin more.
        score += 0.3 * mean_residual;
        // If item barely fits anywhere (item close to capacity), new bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 25.0;
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Many open bins: discourage adding more.
        score += 1.5 * open_bins_count as f64;
    }

    // Global state: when mean residual is low, squeeze harder into remaining space.
    score -= 0.05 * mean_residual * fit_ratio;

    // Time horizon: early stream, be conservative (penalize waste more); late, just pack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: prefer tight fits (low post_residual), with smooth non-linear shaping.
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space is costlier, so amplify small residuals less
    // and heavily penalize large ones via a cubic term.
    let tightness = 1.0 - fit_frac;
    score += progress * tightness * tightness * tightness * 40.0;

    // Smooth reward for near-exact fits (post_residual close to 0), stronger early.
    let exactness = (-fit_frac * 6.0).exp();
    score -= exactness * (30.0 + 40.0 * (1.0 - progress));

    // Penalize leaving residuals that no plausible next item can use:
    // dead space whose size is below the minimum plausible item.
    let dead = (fit_frac * cap - 1.0).max(0.0);
    score += (dead / cap).powi(2) * 60.0;

    // Lookahead coupling: reward residuals that still fit the next item,
    // smoothly scaled by how much slack remains.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { (pr / nx).max(0.0) };
        score -= fits_next * 15.0 * (1.0 - 0.5 * progress);
        // Penalize consuming space the next item would have needed elsewhere.
        if pr < nx {
            score += (nx - pr) / cap * 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 25.0 * (1.0 - progress);
    }

    // New-bin candidate: generally penalize, but relax smoothly when the item
    // fits poorly everywhere (large item relative to mean residual) or late stream.
    if is_new_bin {
        let poor_fit = (item_size as f64 / mean_residual.max(1.0)).min(1.0);
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
        score += 35.0 - 30.0 * poor_fit - 10.0 * progress - 8.0 * pressure;
        // Slight bonus for a fresh bin when the item is large.
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Mild penalty for many open bins to encourage consolidation, smooth.
    score += (open_bins_count as f64).ln() * 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is best.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Harmonic class of post_residual: residuals divisible by common small
    // item sizes (10, 20, 25, 50) remain "usable" later; odd/prime-like
    // residuals become dead space.
    let harmonic = |r: u32| -> f64 {
        let mut h = 0.0;
        for &d in &[10u32, 20, 25, 50] {
            if r % d == 0 && r > 0 {
                h += 8.0;
            }
        }
        h
    };
    score -= harmonic(post_residual);

    // Penalize residuals in awkward ranges (just above typical minimum item size)
    if post_residual > 10 && post_residual < 20 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= harmonic(post_residual - next_item_size);
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a fresh bin is chosen only when open-bin fits are bad.
        score += 15.0;
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // If many open bins with large mean residual, a new bin is fine.
        if mean_residual > 50.0 {
            score -= 5.0;
        }
        // Penalize new bin more if an existing bin would leave tiny dead space.
        if post_residual >= bin_capacity.saturating_sub(item_size) && item_size <= 50 && fitting_bins_count > 1 {
            score += 10.0;
        }
    } else {
        // Mild preference for filling bins that are already well used.
        let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * used_frac;
    }

    // Slight penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead space avoidance ---
    // Space below the minimum possible item (1) is pure dead space; space that
    // cannot fit the known next item is likely to become dead space too.
    if post_residual == 0 {
        // Perfect fill: strongly reward.
        score -= 1000.0;
    } else {
        // Penalize residuals too small to ever be useful again (hard dead zone).
        if post_residual < 10 {
            score += 60.0 + (10 - post_residual) as f64 * 4.0;
        }
        // If lookahead exists and this residual cannot host it, the gap is
        // at risk of being stranded: penalize proportionally.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Conversely, if the next item fits exactly-ish, reward keeping this bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
            if post_residual == next_item_size {
                score -= 40.0; // exact lookahead fit: excellent packing
            }
        }
    }

    // --- Tight fit reward: small usable residual is good ---
    if post_residual > 0 && post_residual < item_size {
        score -= 8.0; // bin was more than half consumed by this item
    }

    // --- Last chance pressure ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // Only this bin can host the item; opening a new bin would waste
        // this residual entirely. Strongly favor using it.
        score -= 25.0;
    }

    // --- Open bins pressure: with many open bins, prefer consolidation ---
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        // Reward using existing bins, scaled by how many are already open.
        score -= 3.0 + open_pressure * 2.0;
    } else {
        // New-bin candidate: penalize when open bins are plentiful or carry
        // large mean residual (capacity available elsewhere).
        score += 2.0 + open_pressure * 1.5 + (mean_residual / 10.0).min(15.0);
    }

    // Slight early-stream tolerance for opening bins (build a diverse pool),
    // late-stream strictness (consolidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, penalize non-zero waste nonlinearly.
    if post_residual > 0 {
        let waste = post_residual as f64;
        score += (waste / bin_capacity as f64).powi(3) * 120.0;
    } else {
        score -= 60.0; // perfect fill bonus
    }

    // Lookahead: if next item fits exactly in the post residual, reward this bin strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            score -= (1.0 - gap / bin_capacity as f64) * 45.0;
        } else {
            // next item cannot use this bin's leftovers; penalize dead space a bit
            score += pr * 0.15;
        }
    }

    // Last-chance dynamics: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = 1.0 - post_residual as f64 / bin_residual as f64;
        score -= 30.0 * fit_quality;
    }

    // Time horizon: early in the stream, be more willing to open new bins (keep options
    // open); late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 25.0 + 55.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a bin is more attractive when many items are still coming and open
        // bins are crowded (high mean residual means little room anywhere).
        let crowd = mean_residual / bin_capacity as f64;
        score -= (1.0 - crowd) * 20.0 * (1.0 - progress);
    } else {
        // Existing bins with residual far below mean are "odd" bins; slight penalty
        // unless the fit is tight.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05 * progress;
    }

    // Prefer filling bins that already have many siblings (reduce open-bin sprawl).
    score += open_bins_count as f64 * 0.8 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: reward tight fits (small post_residual), non-linearly.
    let mut score = pr * (1.0 + 0.8 * pr / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (no future items to fill it).
    let progress_coupling = 1.0 + 1.5 * progress * progress * (pr / cap);
    score *= progress_coupling;

    // Penalize leaving residuals that no plausible next item can use,
    // with a smooth interaction between post_residual and lookahead size.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.35 * gap * gap / cap;
    } else {
        // Last item: dead space is permanent, penalize quadratically.
        score += 0.6 * pr * pr / cap;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Mild crowding penalty: prefer spreading across many open bins
    // only when residuals are large; smooth in mean_residual.
    let mean_norm = mean_residual / cap;
    score += 0.5 * mean_norm * mean_norm * (open_bins_count as f64).ln().max(0.0);

    // Reward using a well-filled bin (large fit fraction) smoothly.
    score -= 4.0 * fit_ratio * fit_ratio;

    // New-bin candidate: keep it mildly unattractive unless forced,
    // with a smooth decay over the stream (early bins are cheap).
    if bin_residual == bin_capacity {
        score += 10.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "reusable" classes (multiples of 10, or large enough for typical items)
    // are favored; awkward leftovers are penalized.
    let pr = post_residual;
    let class_mod = pr % 10;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else if class_mod == 0 {
        score -= 6.0; // clean harmonic leftover
    } else {
        // penalize dead space proportional to awkwardness
        score += (10 - class_mod) as f64 * 0.8;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item exactly or well
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // chain fit
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
            if (pr - next_item_size) % 10 == 0 {
                score -= 4.0; // harmonic chain
            }
        } else {
            score += 5.0; // next item won't fit here; slight penalty
        }
    }

    // Last chance: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate logic: opening a new bin is discouraged early and
    // when open bins fit reasonably; encouraged when mean residual is small.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0
            + 10.0 * (1.0 - progress)
            + 0.3 * mean_residual
            + 0.2 * open_bins_count as f64;
        // allow opening a new bin if current item is large and mean residual small
        if item_size as f64 > 0.6 * cap && mean_residual < item_size as f64 {
            score -= 25.0;
        }
    } else {
        // favor fuller bins (best-fit flavor): smaller residual -> lower score
        score += 0.1 * (bin_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is small enough that typical items (>= ~1/3 bin)
    // cannot use it, but nonzero.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 33.0 {
        // Dead space: quadratic penalty, worse for smaller gaps.
        score += (33.0 - gap) * (33.0 - gap) * 0.9;
    }

    // Reward leaving a gap that can accommodate the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 250.0;
    }
    // Penalize if the gap cannot fit the next item (potential future dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 120.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 180.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate (residual == capacity) gets a rising penalty.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64) * 12.0
            + (mean_residual / bin_capacity as f64).max(0.0) * 60.0;
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= (open_bins_count as f64).min(20.0) * 4.0;
    }

    // Mild preference for tighter fits overall (relative fill).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Early in the stream, allow slightly more freedom to open bins;
    // late in the stream, be stricter about consolidating.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching: reward exact fit for the next item ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: good chain continuation.
            let slack_after_next = post_residual - next_item_size;
            score -= 20.0;
            // Penalize remaining slack that is unlikely to be usable later
            // (small dead space below the minimum plausible item size).
            if slack_after_next < 10 {
                score += (10 - slack_after_next) as f64 * 1.5;
            }
        } else {
            // Next item cannot fit here: dead space is created.
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // --- Last-chance bin: strongly prefer using it before opening a new bin ---
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0;
    }

    // --- Penalize new-bin opening unless it is genuinely useful ---
    if is_new_bin {
        // Opening a new bin is bad when other bins can fit the item.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
        // Late in the stream, avoid opening bins that will stay mostly empty.
        if progress > 0.8 {
            score += 10.0 * progress;
        }
        // Early on, new bins are cheaper (more items remain to fill them).
        score -= 10.0 * (1.0 - progress);
    }

    // --- Mean residual coupling: prefer bins whose residual deviates ---
    // toward being consumed (tight packing), avoid outliers with huge slack.
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    // --- Mild preference for tighter fits overall (small post_residual) ---
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Small tie-breaker: prefer bins with more residual used by this item.
    score -= item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but discount tiny unusable slivers less
    // than medium dead space. A post_residual that can never fit anything
    // (post_residual < 1 handled naturally since sizes >= 1) is "locked in",
    // so weight it slightly less than a wasteful mid-range gap.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score *= 0.55; // sealed bin: dead space is cheap
    } else if pr >= 10.0 && pr <= 30.0 {
        score *= 1.25; // awkward gap zone: penalize
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it packs
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 8.0 * (over / bin_capacity as f64).min(1.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when the item is large relative to
    // any residual and open bins are numerous / residuals fragmented.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin: high unless justified
        score = bin_capacity as f64 * 0.9;
        // if item is huge, fresh bin is natural
        score -= 0.35 * item_size as f64;
        // penalize opening new bins when many bins are open with slack
        score += 2.0 * open_bins_count as f64;
        // if mean residual is large, prefer using existing bins
        score += 0.5 * mean_residual;
        // early in the stream, opening bins is cheaper (future flexibility)
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - t);
        // if the only alternative is a bad fit, allow the new bin
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Global fragmentation pressure: when open bins have high mean residual,
    // favor packing into existing space more aggressively.
    score -= 0.05 * mean_residual;

    // Time horizon: late in the stream, consolidation matters more (fewer
    // chances to fix fragmentation), so tighten fit preference.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * t;

    // Many open bins: discourage spreading items across bins; reward tight fits.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress and fill ratio, smooth non-linear couplings.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - (post_residual as f64 / cap);

    // Core non-linear polynomial coupling: reward high fill with superlinear term,
    // modulated by stream progress (late items reward tight packing more).
    let fill2 = fill * fill;
    let fill3 = fill2 * fill;
    let progress_term = 0.5 + 0.5 * progress;
    score -= (2.0 + 3.0 * progress) * (fill2 + 0.5 * fill3) * cap * 0.1;

    // Dead-space penalty: very small post_residual is good; mid-size residuals are wasteful.
    let pr = post_residual as f64;
    let dead = pr / cap;
    score += 4.0 * dead * (1.0 - dead) * (1.0 - progress_term); // penalize middling waste early

    // Exact / near-exact fit bonus (smooth, no hard threshold).
    let tightness = 1.0 - pr / cap;
    score -= 6.0 * tightness * tightness;

    // Lookahead: if next item fits in post_residual, reward; else mild penalty.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 1.5 + 1.5 * progress;
    } else if next_item_size > 0 {
        score += 0.5 * (1.0 - (next_item_size as i64 - post_residual as i64).unsigned_abs() as f64 / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else {
        // More competing bins -> slight penalty for wasting this one's space.
        score += 0.2 * (fitting_bins_count as f64).min(10.0);
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // (consume outliers, keep a balanced pool of large residuals).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.0 * dev * dev * cap * 0.05 - 0.5 * dev;

    // New empty bin candidate: default penalty so we prefer existing bins,
    // but relax late in the stream or when the fit in this bin is poor.
    if bin_residual == bin_capacity {
        let poor_fit = fill < 0.5;
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score += 12.0 - (4.0 * progress) - if poor_fit { 6.0 } else { 0.0 } - 0.5 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Base: prefer tight fits (small post_residual), mildly superlinear.
    let mut score = post_f * (1.0 + 0.5 * (post_f / cap_f));

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (divisible by small denominators) get rewarded.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 2 == 0 { bonus += 1.5; }
        if pr % 5 == 0 { bonus += 2.0; }
        if pr % 10 == 0 { bonus += 2.5; }
        if pr % 20 == 0 { bonus += 3.0; }
        if pr % 25 == 0 { bonus += 2.0; }
        if pr % 50 == 0 { bonus += 4.0; }
        // Integer-division thresholds: leftover in [1..=10] is near-dead space
        // unless it matches a common small item size.
        let dead = pr / 10; // 0 => tiny leftover, 1 => small, larger => usable
        score += (dead as f64) * -1.0; // usable leftovers rewarded
        score -= bonus;
        if pr <= 10 && pr % 5 != 0 && pr % 2 != 0 {
            score += 6.0; // awkward dead sliver
        }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap_f);
        } else {
            score += 2.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // are crowded and mean residual is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0) as f64;
        let crowding = open_bins_count as f64 / (8.0 + 4.0 * progress);
        let squeeze = (mean_residual / cap_f).min(1.0);
        score = cap_f * 1.2 - 15.0 * crowding.min(1.5) - 20.0 * (1.0 - squeeze);
        if fitting_bins_count == 0 {
            score -= 10.0; // no alternative anyway
        }
    }

    // Mild diversity: discourage many near-identical residual levels.
    let diff = (mean_residual - post_f).abs();
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.84;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: this bin becomes perfectly full after next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Residual left over after the next item would also fit; mild reward proportional to leftover.
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space: post_residual too small for the next item -> penalize heavily.
            let waste = (next_item_size - post_residual) as f64;
            score += 2.0 * waste;
        }

        // Chain fit: post_residual could hold next item and still leave room.
        if post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next == 0 {
                score -= 300.0;
            } else if after_next < 10 {
                score -= 100.0; // near-perfect packing
            }
        }
    } else {
        // Last item: just minimize leftover.
        score -= 50.0;
    }

    // Prefer tighter bins relative to the mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when it enables a much better future fit
    // (empty bin gives post_residual = capacity - item_size, rarely matching next item),
    // otherwise keep it unattractive via its naturally large post_residual plus a penalty.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.2 * open_bins_count as f64;
        // Exception: a fresh bin perfectly fits a huge item leaving no dead space risk.
        if item_size >= 80 {
            score -= 200.0;
        }
    }

    // Late in the stream, be extra conservative: squeeze existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin: it should lose against decent fits.
        let mut new_bin_score = bin_capacity as f64 * 1.5;

        // If this item fits nowhere else, opening a new bin is mandatory anyway;
        // make the new-bin candidate clearly the best choice.
        if fitting_bins_count == 0 {
            new_bin_score = -1000.0;
        } else if fitting_bins_count == 1 {
            // Last-chance bin: compare with the lone fitting bin's expected post residual.
            // If the item would leave a very tight residual in that bin, opening fresh
            // may be better only when the lookahead also fits the fresh residual.
            let lone_post = (bin_capacity as f64) - item_size as f64;
            let dead_space_penalty = (lone_post as f64) * 0.5;
            new_bin_score = bin_capacity as f64 * 1.5 - 60.0 + dead_space_penalty;

            // Lookahead synergy: if next item fits the fresh bin's residual, boost new bin.
            if next_item_size > 0 && next_item_size <= post_residual {
                new_bin_score -= 40.0;
            }
        } else {
            // Multiple fitting bins exist: strongly discourage new bin unless
            // the mean residual across open bins is very large (fragmented state)
            // and we are early in the stream (room to consolidate later).
            let fragmentation = (mean_residual - post_residual as f64).max(0.0);
            new_bin_score -= fragmentation * 0.3 * (1.0 - progress);
        }

        // Late in the stream, avoid opening new bins even more.
        new_bin_score += progress * 30.0;

        return new_bin_score;
    }

    // ---- Regular open-bin scoring ----

    // Reward tight fits: smaller post_residual is better (already the base term).

    // Penalize leaving residuals that are too small to fit typical future items
    // (dead space). Residuals in (0, 10) are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item exactly fits the resulting residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here after placement: slight penalty,
            // stronger when this bin is the item's last chance.
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor),
    // scaled by how many alternatives exist.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05 * (fitting_bins_count as f64).min(5.0) * 0.2;

    // Mild preference to fill bins that deviate above the mean residual
    // (drain the largest holes first) early in the stream.
    let deviation = bin_residual as f64 - mean_residual;
    score -= deviation * 0.1 * (1.0 - progress);

    // Late in the stream: be greedy, minimize post residual more aggressively
    // and discourage leaving many half-empty bins.
    score += post_residual as f64 * 0.3 * progress;

    // Slight penalty when many bins are open (encourage consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base cost: normalized wasted space, with convex (cubic) penalty so
    // large dead space is disproportionately punished.
    let x = post / cap;
    let mut score = x * (1.0 + 1.6 * x * x);

    // Smooth polynomial coupling with stream progress: late in the stream
    // waste becomes more costly, but the effect saturates.
    let prog_term = progress * (1.0 - 0.5 * progress);
    score += 0.9 * prog_term * x * (1.0 + x);

    // Reward tight fits (small post_residual) with a smooth bonus.
    score -= 1.2 * (1.0 - x) * (1.0 - x);

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward; if it barely misses, penalize creating near-useless space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 0.7 * (1.0 - slack) * (1.0 - slack);
        } else {
            let miss = (nxt - post) / cap;
            score += 0.8 * miss * (2.0 - miss);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 2.0;
    } else if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Contextual pressure: many open bins with low mean residual means
    // fragmentation; prefer consolidating into bins below the mean.
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 0.3 * dev;
        score += 0.02 * open_bins_count as f64 * x;
    }

    // New-bin candidate: neutral-ish baseline so it wins only when all
    // open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        score = 1.35 + 0.6 * progress - 0.15 * (1.0 - x);
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward filling the bin: lower score for larger placements (best-fit bias).
    score -= 0.35 * item_size as f64;

    // Perfect fit: heavily favored.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes of post_residual (decade buckets): residual that is a
    // multiple of 10 aligns with the small-item classes (10..80 stream),
    // making it more reusable than odd scraps.
    match post_residual % 10 {
        0 => score -= 4.0,
        1..=5 => score += 2.0, // tiny scraps are near-dead space
        6..=9 => score += 1.0,
        _ => {}
    }

    // Lookahead coupling: dead space if the next item cannot fit the remainder.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Waste proportional to unusable leftover, but a small scrap (<10)
            // is less costly than a mid-range orphan (e.g. 30..60 wasted).
            let orphan = post_residual as f64;
            score += if post_residual < 10 { 0.4 * orphan } else { 0.9 * orphan };
        } else if post_residual >= next_item_size {
            // This bin remains useful for the lookahead item.
            score -= 6.0;
            // Extra reward if next item fills it nearly perfectly.
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only open bin that fits, using it avoids
    // opening a new bin — strongly favor it unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual > 40 {
            score += 20.0; // bad fit on last chance: dampen the reward
        }
    }

    // New-bin candidate (empty bin): penalize opening a new bin when decent
    // alternatives exist; allow it when few/no bins fit or the item is large.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.15 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            score -= 30.0; // only one poor alternative
        }
        if item_size >= 60 {
            score -= 10.0; // big items keep fresh bins flexible
        }
    }

    // Stream-phase modulation: late in the stream, consolidation matters more;
    // mildly favor reusing bins over proliferation.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * phase * (post_residual as f64 / bin_capacity as f64);

    // Spread pressure: many open bins with high mean residual -> prefer the
    // bin whose use reduces dispersion (post_residual far from mean residual).
    if open_bins_count > 1 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score -= 0.1 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins, escalating with open bin pressure.
    if bin_residual == bin_capacity {
        score += 35.0 + 3.0 * open_bins_count as f64;
        // Only allow a new bin if the current bin would leave a truly bad gap.
        if post_residual < 10 && post_residual > 0 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits the post residual, reward leaving that space.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // Penalize leaving a gap that the next item almost but does not fit.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 8.0;
    }

    // Bin pressure: discourage scattering across many open bins slightly.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Early in the stream, allow more exploration of new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fit (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 400.0;
    } else if post_residual < 20 {
        score -= 150.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect chaining
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64); // tighter slack = better
        } else {
            // Next item won't fit here; penalize proportionally to wasted lookahead space.
            let gap = (next_item_size - post_residual) as f64;
            score += 60.0 * (gap / 100.0);
        }
    }

    // Penalize leaving residuals that are generally hard to fill (small awkward gaps)
    // relative to the mean residual across open bins.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < mean_residual * 0.5 {
        score += 30.0; // creating a below-average tiny residual = dead space risk
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only allow opening a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 200.0;
        // Cheaper to open a new bin when many bins are open (dispersion is fine)
        // and when the current item is large (poor fit candidates likely).
        score -= 1.5 * open_bins_count as f64;
        if item_size > 60 {
            score -= 80.0;
        }
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 50.0;
        }
    } else {
        // Mild preference for tighter existing bins (best-fit flavor) as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 0.5 * progress * (bin_capacity - bin_residual) as f64 / 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills: squared tightness term.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 30.0;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 25.0; // perfect closure
        } else if next_item_size == post_residual {
            score -= 40.0; // chain fill: reserve this bin for the pair
        } else if next_item_size <= post_residual {
            // mild reward proportional to how well next item consumes the leftover
            let chain = (next_item_size as f64) / (post_residual as f64);
            score -= 12.0 * chain;
        } else {
            // next item won't fit here: penalize leaving dead space if residual is small
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's the only option.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (item_size as f64) / (bin_capacity as f64);
        score += 60.0 + pressure;
        // Early in the stream, opening bins is cheaper; late, be conservative.
        let progress = (step_index as f64) / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Global state coupling: prefer bins whose residual deviates from the mean
    // (consolidate fragmentation into similar residual classes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer filling bins with larger residuals when many bins are open (reduce spread).
    score -= 0.05 * (bin_residual as f64) * (open_bins_count as f64).ln().max(0.0);

    // Slight preference for larger items in emptier bins.
    score -= 0.1 * (item_size as f64) * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post-residual, with a non-linear (quadratic) coupling
    // that increasingly punishes large leftover space as the stream progresses.
    let mut score = post * (1.0 + 1.5 * progress * progress);

    // Smooth waste penalty: cubic in normalized post-residual.
    let norm_post = post / cap;
    score += 40.0 * norm_post * norm_post * norm_post;

    // Reward tight fits: item filling most of the bin (smooth exponential term).
    let fill_ratio = item / res.max(1.0);
    score -= 25.0 * (fill_ratio * fill_ratio).tanh();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (scaled by remaining stream length).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate: empty bin should be chosen only when no good fit exists.
    // Penalize it mildly at baseline, more when open bins already fit well.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
        score += 15.0 + 10.0 * openness + 20.0 * (1.0 - progress);
        // If the next item is large, a fresh bin may be attractive: reduce penalty
        let nxt = next_item_size as f64;
        if nxt > 0.0 {
            score -= 12.0 * (nxt / cap) * (nxt / cap);
        }
    }

    // Lookahead coupling: penalize leaving post-residual that neither fits the
    // next item nor is near zero (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // residual can host next item: mild reward proportional to usefulness
            score -= 8.0 * (nxt / cap);
        } else {
            // dead space relative to next item: penalize the shortfall smoothly
            let gap = (nxt - post) / cap;
            score += 18.0 * gap * gap;
        }
    }

    // Mean-residual context: when mean residual is small, waste is costlier.
    let mean_norm = mean_residual / cap;
    score += 10.0 * (1.0 - mean_norm) * norm_post;

    // Small tie-breaker on exact fit.
    if post == 0.0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual in {0, cap/4, cap/2, 3cap/4} boundaries -> highly reusable
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let threeq = 3 * quarter;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual == quarter || post_residual == half || post_residual == threeq {
        score -= 12.0;
    }

    // Integer-division threshold classes on post_residual
    let cls = post_residual / 10; // decade class
    score -= match cls {
        0 => 25.0,          // 0..9: nearly full, great
        1 => 15.0,          // 10..19
        2 => 8.0,           // 20..29
        3 => 2.0,           // 30..39
        4 => -2.0,          // 40..49
        _ => 0.0,
    } as f64;

    // Penalize residual classes that are hard to fill: odd/dead zones
    // Residuals in (0,10) already rewarded; residuals in 51..=59 are awkward
    if post_residual >= 51 && post_residual <= 59 {
        score += 6.0;
    }
    // Harmonic trap: residual just above next_item is ideal for lookahead
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size as u32;
        if slack == 0 {
            score -= 30.0; // lookahead fits perfectly
        } else if slack <= 5 {
            score -= 18.0;
        } else if slack <= 15 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // lookahead cannot fit: dead space risk
        score += 8.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer fresh bin if current residual is very small
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score = cap * 0.85;
        if post_residual as f64 > cap * 0.6 {
            score += 10.0;
        }
        // if current bin would leave tiny unusable residue, new bin is fine
        if next_item_size > 0 && post_residual < next_item_size as u32 && post_residual < 10 {
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64) * 0.05;

    // Progress-based tie-break: later in stream, prefer tighter fills
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= post * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space: tiny gap nothing can fill (min item ~1..10 range, but small gaps attract small items poorly)
            score += 25.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual < 20 {
            // Semi-dead zone: only very small items fit; penalize moderately
            score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
        }
    }

    // Perfect fit gets strong reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when fit is loose
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - fill_ratio);

    // Lookahead: if next item fits into the resulting residual, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // residual becomes useless for the known next item
        score += 8.0;
    }

    // New-bin candidate calibration: empty bin should only win when the
    // best open-bin placement is genuinely poor. Anchor its score near the
    // mean residual so only bad fits (high score) trigger opening a new bin.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 35.0
            + open_bins_count as f64 * 0.5
            - (mean_residual / bin_capacity as f64) * 10.0;
        // Late in stream, avoid spawning bins for small items
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer bins whose post-residual tightly matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect chain: next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 30.0;
    }

    // Penalize dead space that is too small for the smallest possible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: filling a bin below-average residual is good.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance: strongly favor using the only fitting bin instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless the item is large relative to capacity
    // and current bins are crowded (high mean residual).
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let pressure = (item_size as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(1.0);
        score = bin_capacity as f64 + 80.0 - 60.0 * pressure * crowding;
        // If the next item is small, opening a fresh bin wastes capacity; penalize more.
        if next_item_size > 0 && next_item_size < item_size / 2 {
            score += 20.0;
        }
    }

    // Mild stream-progression term: later in the stream, be more conservative with new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (small post_residual), but shape the
    // preference non-linearly so near-zero dead space is heavily rewarded.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64) * (1.0 - pr / bin_capacity as f64) * 100.0;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead item: penalize.
        score += 0.25 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0 + 0.10 * item_size as f64;
    }

    // When many bins fit the item, prefer the tightest: add small penalty
    // scaled by fitting count so ties break toward low post_residual.
    if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: if mean residual is large, bins are fragmented —
    // prefer filling existing bins rather than opening new ones.
    score -= 0.03 * mean_residual;

    // Time horizon: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - pr / bin_capacity as f64);

    // New-bin candidate handling: an empty bin is a costly luxury; only
    // make it attractive when it beats poor fits (large post_residual
    // elsewhere) — penalize it moderately so tight fits win.
    if bin_residual == bin_capacity {
        let new_bin_base = bin_capacity as f64 * 0.55;
        // Early stream: opening bins is cheap-ish; late stream: expensive.
        score = new_bin_base + 8.0 * (1.0 - progress) + 14.0 * progress;
        // If no existing bin fits (this call is the only candidate), the
        // penalty is irrelevant — new bin gets opened anyway.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If lookahead item is huge, a fresh bin preserves flexibility.
        if next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Slight preference for bins that are already partially filled
    // (reduces bin count pressure) when residuals are comparable.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 2.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog_poly = 0.35 + 0.4 * progress - 0.25 * progress * progress;

    // Penalize large residuals more as stream advances (dead space matters more later)
    let mut score = pr * (1.0 + prog_poly * fit_ratio);

    // Smooth tight-fit reward: gaussian-like bump around small residuals
    let tightness = (-fit_ratio * fit_ratio * 6.0).exp();
    score -= 14.0 * tightness;

    // Last-chance bonus (smoothly scaled by scarcity of fitting bins)
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can fit the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 0.05 * (next_item_size as f64 - pr).min(40.0);
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += 0.15 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    // New-bin candidate: neutral-ish baseline, slightly penalized so it's chosen
    // only when open bins give a poor fit
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "dead" classes (very small leftovers) are penalized, while leftovers
    // that match likely future item sizes are rewarded.
    let cls = post_residual / 10; // integer-division threshold classes
    match cls {
        0 => score += 60.0,                 // dead space (<10): nearly unusable
        1 => score += 25.0,                 // 10..19: only tiny items fit
        2 => score += 8.0,                  // 20..29
        3 => score -= 6.0,                  // 30..39: common item band
        4 => score -= 10.0,                 // 40..49
        5 => score -= 12.0,                 // 50..59
        6 => score -= 8.0,                  // 60..69
        _ => score -= 2.0,                  // 70+: loose but flexible
    }

    // Exact-fit reward: leftover zero is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a golden chain placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but not exactly: mild reward scaled by slack waste.
        score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual cannot host the next item: penalize proportionally.
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap when many bins are open (fragmentation
        // risk low) and expensive when few are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64;
        score += 45.0 - 2.5 * openness - 20.0 * progress;
        // If the item fills the fresh bin exactly, opening is great.
        if item_size == bin_capacity {
            score -= 120.0;
        }
    }

    // Mean-residual context: when average residual is high, wasting space in
    // this bin matters less; when low, be frugal.
    score -= 0.15 * mean_residual;

    // Slight preference for packing tighter bins first (best-fit flavor).
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1..10)
    // are unusable; penalize them heavily, scaled by how "wasted" they are.
    let dead_threshold: u32 = 9;
    if post_residual <= dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Small risky gaps: next items (10..80) rarely fit; mild penalty.
        score += 8.0 + (20 - post_residual) as f64 * 0.5;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next <= dead_threshold {
            score -= 22.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap; if gap is small, this bin is a dead end.
        if post_residual < 20 {
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin tendency); with few bins, allow spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mean-residual coupling: when average residual is large, avoid leaving
    // mid-size gaps that fragment the fleet; when small, tight fits dominate.
    if mean_residual > 50.0 && post_residual > 30 && post_residual < 60 {
        score += 6.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its raw post_residual (= capacity - item) is already large; add explicit
    // penalty so new bins are only chosen when all open bins create dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.5 * (open_bins_count as f64).ln().max(0.0);
        // Early in the stream, opening bins is cheap and useful.
        if progress < 0.15 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match of next item into post-residual is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        score += 0.5 * dead * dead / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins would leave big dead space
    // or there are no fitting alternatives.
    if bin_residual == bin_capacity {
        score = 100.0 + post_residual as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        } else if fitting_bins_count == 1 {
            score += 60.0; // discourage abandoning the sole fitting bin
        }
        // Early stream: keep bins open longer.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
    }

    // Mild tie-break: prefer bins tighter than the mean residual.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small dead space).
    if post_residual < 10 {
        score -= 60.0;
    } else if post_residual < 25 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize leaving dead space the next item can't use,
            // scaled by how much is wasted.
            let dead = post_residual as f64 - (next_item_size as i64).max(0) as f64;
            if post_residual < next_item_size {
                score += 0.10 * (post_residual as f64);
            }
            let _ = dead;
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 15.0;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 40.0 * (fitting_bins_count as f64);
        }
        // Early in the stream, be more willing to open bins (build a portfolio).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        // If mean residual is large, existing bins are roomy -> avoid new bin.
        score += 0.20 * mean_residual;
    }

    // Mild penalty for spreading across many open bins when this fit is loose.
    if open_bins_count > 4 && post_residual > 40 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual (tight fit).
    let mut score = pr;

    // Smooth non-linear coupling: post residual normalized and squared,
    // penalizing large dead space increasingly (quadratic dead-space term).
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * cap * 0.05;

    // Reward tight fits with a smooth saturating term (tanh-like coupling).
    let fit_tightness = 1.0 - pr_norm;
    score -= 10.0 * fit_tightness * fit_tightness;

    // Last-chance bonus: only one bin can fit the item -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many bins fit, to break ties by tightness only.
        score += 2.0 * (fitting_bins_count as f64).ln().min(3.0);
    }

    // Stream-progress coupling: later in the stream, waste matters more.
    score += 8.0 * progress * pr_norm;

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = 1.0 - (next_item_size as f64 / pr);
        score -= 6.0 * slack;
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty proportional to residual.
        score += 3.0 * pr_norm;
    }

    // New-bin candidate handling: bin_residual == bin_capacity means brand-new bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin, but less when current fit is terrible
        // (post_residual huge relative to capacity) or late in stream with many bins.
        let badness = fit_tightness; // high when placement leaves much space
        score += 18.0 - 14.0 * badness * badness - 5.0 * progress;
        // If no existing bin fits (this is the only candidate), new bin is unavoidable.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's a
    // good "filler" bin; normalize deviation smoothly.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev;

    // Open-bin pressure: many open bins -> favor consolidating into existing bins.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse granularity classes (capacity/4 buckets)
    let item_class = item_size / (bin_capacity / 4 + 1);
    let next_class = next_item_size / (bin_capacity / 4 + 1);

    // Reward tight fits strongly (dead space minimization)
    score -= (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class pairing: reward when next item's class complements post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        // Reward if next item leaves another small gap (chain of tight fits)
        score -= (gap as f64 / bin_capacity as f64).powi(2) * 40.0;
        // Extra reward when classes chain nicely (large+small, medium+medium)
        if next_class >= item_class {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the gap: penalize dead space more
        score += 15.0;
    }

    // Dead-space threshold penalties via integer division thresholds on post_residual
    // Gaps of 1..=10 are nearly unusable for items >= 10 in classic packing,
    // but with sizes 1..100 they may still matter; use graded penalty.
    let dead_band = post_residual / 10; // 0..=10 harmonic band
    score += dead_band as f64 * 6.0;

    // Very small residual (< half of min plausible next item) is dead space
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 * 0.9;
        // Attractive if no good fit exists among open bins
        if fitting_bins_count == 0 {
            score -= 150.0;
        } else if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // If mean residual across open bins is large, reuse them instead
        if mean_residual > item_size as f64 * 1.5 {
            score += 40.0;
        }
    }

    // Mild penalty for proliferating open bins
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residual close to item (best-fit flavor) modulated by class
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

