    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer reusing existing bins
    // (penalize the new-bin candidate, whose residual == capacity).
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 8.0; // gap too small for next item -> mild dead-space penalty
        }
    }

    // Mean-residual coupling: prefer bins close to the mean residual
    // (balanced packing keeps future options open).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Early stream: be slightly more selective; late stream: close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

