        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // Many open bins with slack: discourage another one.
        score += 0.5 * open_bins_count as f64;
    } else {
        // Existing bin: reward using bins with larger residuals when they fit well
        // (keep small residuals for small items).
        let residual_frac = bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * residual_frac;
    }

    // Global slack awareness: if mean residual is high, prefer consolidating
    // into existing bins.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Mild penalty for creating residuals that are awkward (small but nonzero),
    // scaled by stream progress (late stream, dead space matters more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;

    // Base: reward small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.6 * fit * fit);

    // Polynomial coupling of fit with stream progress:
    // early on, prefer tight fits mildly; later, punish residual waste quadratically
    let coupling = 0.5 + 2.0 * progress * progress;
    score += coupling * pr * (1.0 - fit) * fit;

    // Penalize bins whose residual deviates from mean residual (fragmentation signal)
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * dev * cap * (0.3 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: bonus if next item can fit the post-residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (1.0 - ni / cap) * (1.0 - 0.5 * progress);
        } else {
            // dead space for the known next item: penalize smoothly
            score += 6.0 * (ni - pr) / cap * cap;
        }
    }

    // Mild penalty for spreading across too many open bins late in the stream
    score += (open_bins_count as f64).ln() * (1.0 + 2.0 * progress) * 0.5;

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let new_bin_bonus = 25.0 * (1.0 - progress) + 10.0;
        // If item would leave a tiny unusable sliver in existing bins, prefer new bin
        let sliver = if pr > 0.0 && pr < 10.0 { 40.0 } else { 0.0 };
        score = pr + new_bin_bonus - sliver + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fill is perfect.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space: sliver that likely nothing (min size 1..10) can use well.
        score += 25.0;
    } else {
        // Modulo-10 harmonic band: reward residuals in friendly classes (multiples of 10).
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        // Reward if the lookahead item fits into the remaining space.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else if next_item_size > 0 {
            // Post-residual too small for next item: penalize proportionally.
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a new bin is usually wasteful unless the fit
    // into every open bin would be terrible (huge leftover) or dead space.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count == 0;
        let bad_leftover = post_residual > 60; // item tiny relative to fresh bin
        score += 45.0;
        if poor_fit_everywhere {
            score -= 55.0; // no alternative: new bin is fine
        } else if bad_leftover && next_item_size > 0 && next_item_size >= bin_residual - item_size {
            // keep new-bin option alive when existing bins would strand the next item
            score -= 10.0;
        }
        // Early stream: fewer open bins -> slightly discourage bin proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Tie-break: prefer bins whose residual is close to the mean (balance).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (items can be as small as 1) are pure waste; the smaller the gap band,
    // the harsher the penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // moderate risk zone
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 3 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits into the post residual, reward keeping
    // this bin alive for a good follow-up placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack.min(10.0) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit would create severe dead space.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones (penalize the new-bin candidate).
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; favor bins closer to (or below) the mean.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    }

    // New-bin candidate handling: an empty bin is attractive only when the
    // item is large relative to capacity or no good fit exists. Penalize it
    // moderately so tight fits in open bins win, but allow it when the item
    // would leave a bad gap everywhere.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 20.0 - fill_ratio * 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    // Late-stream consolidation: as the stream progresses, tighten up by
    // favoring bins with less remaining residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward proportional to how snug it is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit: dead space penalty, worse when post_residual is small.
            let dead = post_residual as f64;
            score += 20.0 * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: penalize so it's chosen only when open bins give bad fits.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if current fit is poor and lookahead is poor, new bin becomes attractive.
        if post_residual > 0 && next_item_size > post_residual {
            score -= 100.0;
        }
    }

    // Slight preference for filling larger residual bins early in the stream.
    score -= 0.1 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits. Reward small post_residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0; // tiny dead space is wasted capacity
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // fits badly everywhere else or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins when existing bins have plenty of room and fit well.
        score += 55.0;
        score -= 45.0 * (1.0 - pressure); // more penalty when mean residual is high? no: invert
        score += 45.0 * pressure; // high mean residual (full bins) makes new bin more attractive
        // Lookahead: if next item is large, a fresh bin may be valuable.
        if next_item_size > 0 {
            let next_big = next_item_size as f64 / bin_capacity as f64;
            score -= 30.0 * next_big * (1.0 - fit_ratio);
        }
        // Early in stream: allow opening bins more freely; late: consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // Few open bins: opening one is cheap.
        score -= 3.0 * (open_bins_count as f64).sqrt().recip().min(1.0) * 10.0;
    }

    // Lookahead coupling for existing bins: if the leftover after placement
    // can still hold the next item, this is a good sequencing choice.
    if next_item_size > 0 && bin_residual < bin_capacity {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // slightly, to avoid leaving many nearly-full stragglers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild global consolidation pressure as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in the stream, penalize larger residuals more
    score += 20.0 * progress * norm_pr * (1.0 - progress) * 4.0;

    // Reward tight fits (small post residual) with a smooth quadratic bonus
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bin: strongly favor using it (smooth exponential-style reward)
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - norm_pr);
    }

    // Mean-residual coupling: penalize bins far below mean residual (fragmentation signal)
    score += 0.15 * (mean_residual - pr).abs();

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap);
    }

    // Penalize opening new bins as open bin count grows
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64).sqrt() * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual (mod-10 granularity) ----
    let pr = post_residual;
    let class = pr % 10; // harmonic residue class
    match class {
        0 => {
            // Perfectly divisible residual: highly reusable
            score -= 18.0;
        }
        1..=4 => {
            // Small sliver: near-dead space, penalize proportionally
            score += 6.0 + (4 - class) as f64 * 3.0;
        }
        5..=9 => {
            // Mid-range residual: mildly usable
            score -= 2.0 + (class - 5) as f64 * 1.5;
        }
        _ => {}
    }

    // ---- Integer-division threshold: "usable chunk" classes ----
    // How many items of the *next* size fit in the post residual?
    if next_item_size > 0 {
        let fits_next = (pr / next_item_size.max(1)) as f64;
        if fits_next >= 1.0 {
            // Next item can follow: strong reward, scaled by how cleanly it divides
            let slack = (pr % next_item_size) as f64;
            score -= 12.0 + fits_next * 4.0 - slack * 0.3;
        } else {
            // Next item won't fit here: mild penalty, worse if residual is tiny
            score += (next_item_size as f64 - pr as f64) * 0.25;
        }
    }

    // ---- Dead-space zone: post_residual in (0, 10) is nearly unusable ----
    if pr > 0 && pr < 10 {
        score += 22.0;
    }

    // ---- Last-chance bin: only one bin can fit this item ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // ---- Crowding: many open bins => prefer consolidation ----
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += crowding * 0.6 * (0.5 + 0.5 * progress);

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is generally costly; make it attractive ONLY when
        // the resulting post_residual is large and cleanly classed (mod 10 == 0),
        // or when existing bins are all poor fits (few fitting bins).
        let clean_class = if pr % 10 == 0 { 10.0 } else { 0.0 };
        let scarcity_bonus = if fitting_bins_count <= 1 { 30.0 } else { 0.0 };
        let big_room = if pr >= 40 { 8.0 } else { 0.0 };
        score -= clean_class + scarcity_bonus + big_room;
        // Base tax on opening new bins, softened late in the stream
        score += 14.0 * (1.0 - 0.4 * progress);
    }

    // ---- Mean-residual coupling: keep scores comparable across bins ----
    score += (mean_residual - pr as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for typical items) are heavily penalized.
    let dead_zone_low = 1.0f64;
    let dead_zone_high = 20.0f64;
    let pr = post_residual as f64;
    if pr > dead_zone_low && pr < dead_zone_high {
        // Peak penalty at the middle of the dead zone (worst wasted space).
        let center = (dead_zone_low + dead_zone_high) / 2.0;
        let width = dead_zone_high - dead_zone_low;
        let bump = 1.0 - ((pr - center).abs() / (width / 2.0));
        score += 45.0 * bump.max(0.0);
    }

    // Reward very tight fits (near-perfect packing).
    if pr == 0 {
        score -= 30.0;
    } else if pr <= 5 {
        score -= 12.0;
    } else if pr <= 10 {
        score -= 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many
    // bins are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - 0.5 * progress);

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // New-bin candidate handling: an empty bin gets a moderate baseline.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if no open bin fits well
        // (large dead-space risk) or many bins fit poorly.
        let poor_fit = pr > dead_zone_low && pr < dead_zone_high;
        if poor_fit && fitting_bins_count <= 2 {
            score -= 40.0; // prefer fresh bin over creating dead space
        } else {
            score += 15.0; // default: prefer filling existing bins
        }
        // Slight new-bin discount early in the stream (room to consolidate later).
        score -= 10.0 * (1.0 - progress);
    }

    // Mild alignment with mean residual: prefer bins close to the mean
    // (keeps residual distribution balanced).
    score += (mean_residual - pr).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already encoded).

    // 2-step lookahead: penalize post_residual that is dead space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: next item can still land here.
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            // Dead space penalty scaled by how unusable the leftover is.
            let waste = post_residual as f64;
            score += 6.0 + 0.35 * waste;
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean are less attractive
    // unless the fit is tight (post_residual small).
    let pr = post_residual as f64;
    let mean_gap = mean_residual - pr;
    if mean_gap > 0.0 {
        score -= 0.25 * mean_gap; // tighter than average -> reward
    } else {
        score += 0.15 * (-mean_gap); // looser than average -> mild penalty
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is pure dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0; // soften if it creates dead space
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Neutral-ish default; made worse if open bins exist that fit.
        score = 55.0 + 3.0 * open_bins_count as f64;
        if next_item_size > 0 {
            // A fresh bin leaves 100 - item_size for next item; reward if roomy.
            if post_residual >= next_item_size {
                score -= 8.0;
            } else {
                score += 5.0;
            }
        }
        // Late in the stream, avoid opening bins for marginal gains.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
