pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: quadratic penalty on post residual (dead space), weighted by progress
    let mut score = post * (1.0 + 1.5 * progress) + 0.004 * post * post;

    // Reward tight fits: normalized fill ratio, smooth cubic reward
    let fill = item / cap;
    score -= 18.0 * fill * fill * fill;

    // Penalize residuals that are too small to be useful for typical future items
    // smooth sigmoid-like term around residual ~ item_size scale
    let usability = post / (post + 25.0);
    score += 10.0 * (1.0 - usability);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= 12.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            score += 4.0 * ((nxt - post) / cap);
        }
    }

    // Interaction: relative to mean residual — favor bins tighter than average
    let rel = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * rel * rel.abs() + 3.0 * rel;

    // Slight preference to keep open bin count low early on
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate (bin_residual == bin_capacity) gets a mild opening cost
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // "usable bands" via integer division on capacity fractions.
    let pr = post_residual as u32;
    let band = pr / 10; // bands of width 10 (harmonic classes of capacity)
    let band_center = (band * 10 + 5) as f64;
    let band_offset = (pr as f64 - band_center).abs();

    // Reward residuals that sit exactly on harmonic class boundaries
    // (perfectly packable leftovers: 0, 10, 20, ... are ideal dead space).
    score -= 12.0 * (1.0 - band_offset / 5.0).max(0.0);

    // Penalize residuals that are too small to ever fit another item
    // (min item size 1, but typical items are >= 10): dead space < 10 is waste.
    if pr < 10 && pr > 0 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a harmonic match — strongly reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits but leaves a new residual; reward proportional fit
            let nr = pr - next_item_size;
            let nr_band = (nr / 10) as f64;
            score -= 15.0 + 2.0 * nr_band;
        } else {
            // next item will NOT fit here: penalize slightly, this bin is a dead end
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make opening a new bin costly unless the item is large relative to capacity
    // (large items justify fresh bins) or no good fit exists.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score += 45.0 - 30.0 * frac; // large items -> cheaper to open new bin
        if next_item_size > 0 && (next_item_size as i64 - pr as i64).abs() <= 5 {
            score -= 20.0; // fresh bin pairs well with upcoming item
        }
    }

    // Tight fit reward: near-perfect packing of the current item.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 10.0 * tightness * tightness;

    // Modulo harmonic bonus: residuals divisible by 5 pack better with
    // typical item size distributions.
    if pr % 5 == 0 {
        score -= 6.0;
    }
    if pr % 20 == 0 {
        score -= 6.0; // super-harmonic class
    }

    // Mild pressure against bin proliferation late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0)) * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero post-residuals are wasted space.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavy penalty scaled by how tiny the gap is.
            score += (10 - post_residual) as f64 * 6.0;
        } else if post_residual < 25 {
            // Moderately hard to fill: strong penalty.
            score += (25 - post_residual) as f64 * 2.5;
        } else {
            // Larger gaps are more reusable: mild penalty that decays with gap size.
            score += (post_residual as f64 - 25.0) * 0.25;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: mildly prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.6;

    // Compare residual to mean residual across open bins: prefer bins below-average residual
    // (tighter bins) so loose bins stay loose for larger future items.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else if slack < 10 {
            score -= 8.0;
        }
    }

    // New-bin candidate: empty bin should only win when the fit is terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 15.0 * progress;
        // If a fitting bin exists and would leave a perfect or near-perfect state,
        // the new bin loses; if the best alternative wastes much space, it wins.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the less space wasted, the better.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // 2-step lookahead: reward post_residual that exactly (or nearly) matches next_item_size,
    // so the next item can fill this bin perfectly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 * (-diff / 12.0).exp(); // strong bonus for near-exact match
        // Penalize leaving a residual that is too small for the next item (dead space)
        if (post_residual as u64) < (next_item_size as u64) {
            score += 8.0;
        }
    } else {
        // Last item: pure tightness matters most
        score -= 10.0;
    }

    // Relative-to-mean coupling: prefer bins whose post_residual stays near mean residual,
    // avoiding creation of outlier small residuals that become dead space.
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * mean_diff;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current open bins fit poorly.
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            // Opening a new bin is reasonable; give it a moderate score.
            score -= 5.0;
        } else {
            // Discourage opening a new bin when good existing fits exist.
            score += 30.0;
        }
    }

    // Slight preference for filling bins that are already mostly full
    // (keeps number of active bins low).
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: strongly prefer minimal post residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize unusable dead space: if post_residual is small but nonzero and
    // cannot fit typical small items, it's wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead (k=2): if the next item fits exactly into the post residual,
    // heavily reward this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item uses leftover space
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else if next_item_size > bin_residual {
            // next item can't fit in this bin at all; keeping residual large is fine
            score -= 5.0;
        }
        // If next item fits current residual but not post residual, this placement
        // destroys a future option: mild penalty scaled by wasted opportunity.
        if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when the item is large relative
    // to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin for a large item is reasonable; for small items it wastes space.
        if load_frac > 0.5 {
            score -= 15.0 * (load_frac - 0.5);
        } else {
            score += 20.0 * (0.5 - load_frac);
        }
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // If many bins already open, discourage another.
        score += 2.0 * open_bins_count as f64;
        // If other bins fit, opening new is worse.
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Global state coupling: prefer bins whose residual is below the mean
    // (concentrate filling into emptier-relative bins keeps tight bins tight).
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 0.05 * (mean_residual - resid);
    } else {
        score += 0.05 * (resid - mean_residual);
    }

    // Early stream: keep residuals flexible (prefer balanced fills).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        score += 0.1 * (post_residual as f64 - 25.0).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Core: quadratic coupling of post_residual with stream progress.
    // Later in the stream, leaving residual is more costly -> steeper penalty.
    let mut score = post * (1.0 + 0.9 * progress * progress) + 0.004 * post * post;

    // Reward tight fits (small post_residual) with a smooth non-linear bonus.
    score -= 12.0 * (-post / 18.0) * (-post / 18.0);

    // Penalize filling a mostly-empty bin with a small item (wasteful packing).
    let fill_ratio = item / cap;
    score += 20.0 * fill_ratio * (1.0 - fill_ratio) * (1.0 - fill_ratio);

    // Smooth interaction: large residual + small item is bad.
    let res_ratio = bin_residual as f64 / cap;
    score += 6.0 * res_ratio * res_ratio * (1.0 - fill_ratio);

    // Lookahead: bonus if next item fits exactly in the post-residual (chained fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 8.0 * (-gap / 15.0) * (-gap / 15.0);
        // Penalize if post-residual is just barely unusable for the next item.
        if post < nxt && post > 0.0 {
            score += 4.0 * (post / nxt);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Slight penalty when many bins fit, to encourage consolidation.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Nudge toward bins with residuals below the mean (use up tighter bins first).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when residual is full (empty) and the item
    // is large; otherwise keep it slightly penalized so open bins get used.
    if bin_residual == bin_capacity {
        score += 10.0 - 14.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual), harmonic in scale.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 90.0 * tight * tight;

    // Harmonic class of post_residual: reward residuals in "usable" classes.
    // Residuals that are exact multiples of small harmonics (e.g. mod 10 == 0)
    // pair well with typical item sizes.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus: f64 = match pr % 10 {
            0 => 30.0,
            5 => 18.0,
            2 | 8 => 10.0,
            _ => 0.0,
        };
        // Only worth it if a plausible next item (>= ~10) could use it.
        if pr >= 10 {
            score -= class_bonus;
        }
    }

    // Penalize dead space: residuals too small for any item (1..10 unusable).
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 && next_item_size <= pr {
        let exact = (next_item_size == pr) as f64;
        let fits = (next_item_size as f64) / (pr.max(1) as f64);
        score -= 25.0 * exact + 20.0 * fits;
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here; penalize creating a stranded bin.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Prefer denser bins when many bins are open (consolidation pressure).
    let density = 1.0 - (bin_residual as f64) / cap;
    score -= 10.0 * density * (open_bins_count.min(64) as f64).ln().max(0.0);

    // Mild stream-phase modulation: early on, be picky about near-perfect fits.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * tight * (1.0 - phase);

    // New-bin candidate: neutral-ish baseline; only attractive if this is a
    // genuinely bad fit into existing bins (post_residual huge waste).
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 20.0 * (1.0 - tight);
        // Opening a new bin is fine when open-bin fits would strand lots of space.
        if post_residual >= 0 {
            score -= (item_size as f64) * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any small unusable gap is heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(10) {
        score += 1000.0; // dead space: gap too small for any realistic item
    }
    if post_residual == 0 {
        score -= 50.0; // perfect fill is excellent
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: penalize creating more bins when many are open.
    score += (open_bins_count as f64) * 2.0;

    // New-bin candidate: only attractive when the current item is large
    // and would leave a very tight fit in any existing bin anyway.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.9
            + (open_bins_count as f64) * 3.0
            - (item_size as f64) * 0.5
            - progress * 5.0;
        // Lookahead: if next item is small, an existing bin is preferable.
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 40.0;
        }
    }

    // Slight preference for bins below mean residual (balancing).
    if (bin_residual as f64) > mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled against mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // 2-step lookahead: reward bins whose post_residual closely matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + gap);
        // Perfect chain: post_residual exactly equals next item size -> strong reward.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual too small for next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.2 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Less penalty early in stream (more room to build good bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If next item is small, a fresh bin wastes capacity; if large, fresh bin helps.
        if next_item_size > 0 && next_item_size > item_size {
            score -= 15.0;
        }
    }

    // Mild preference for bins already tighter than average (fragmentation control).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to ever fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            let slack_ratio = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 8.0 * slack_ratio;
        } else {
            // Next item won't fit here; mild penalty proportional to wasted lookahead potential.
            let gap = next_item_size as f64 - post_residual as f64;
            score += 2.0 * (gap / bin_capacity as f64);
        }
    }

    // New-bin candidate logic: empty bin gets a base penalty so we prefer existing bins,
    // but the penalty shrinks when open bins are fragmented (high mean residual spread)
    // or when few bins fit the item.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 * 0.5)).abs();
        let pressure = (fitting_bins_count as f64).recip();
        let progress = step_index as f64 / (total_items as f64 + 1.0);
        let new_bin_penalty = 20.0 + 15.0 * (1.0 - pressure) - 6.0 * (fragmentation / bin_capacity as f64) - 5.0 * progress;
        score = new_bin_penalty;
    } else {
        // Mild penalty for using bins with large residuals when many bins fit (save big bins).
        let big_bin_saving = (bin_residual as f64 / bin_capacity as f64) * 4.0 * (fitting_bins_count as f64).ln();
        score += big_bin_saving;
    }

    // Time horizon: early in the stream, be slightly more conservative (keep bins flexible);
    // late in the stream, pack aggressively.
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    score -= 6.0 * progress * tightness;

    // Crowding effect: many open bins -> prefer filling existing ones further.
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base: penalize wasted space quadratically (smooth coupling)
    let mut score = post * post / cap;

    // Reward tight fits: small post_residual relative to item size
    let tightness = post / (item_size as f64 + 1.0);
    score -= 12.0 * (-tightness * 4.0).exp();

    // Dead-space penalty: residuals too small for typical future items
    let small_frac = post / cap;
    score += 20.0 * small_frac * small_frac * (small_frac - 0.35).abs();

    // Stream progress coupling: early on, prefer flexibility (larger residuals ok);
    // late, pack tightly and avoid opening bins
    score *= 0.6 + 0.8 * progress;
    score -= 6.0 * progress * (1.0 - small_frac);

    // New-bin candidate: penalize opening a new bin, unless current bins fit badly
    let is_new_bin = (bin_residual as u32 == bin_capacity) && (item_size as f64 <= cap);
    if is_new_bin {
        let urgency = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base cost of a fresh bin
        score += 15.0 + 25.0 * progress;
        // If item fits poorly everywhere else, allow new bin
        let fit_quality = 1.0 - (item_size as f64 / cap);
        score -= 40.0 * urgency * (1.0 - fit_quality);
        // Lookahead: if next item is large, a fresh bin is attractive
        if next_item_size > 0 {
            let next_big = next_item_size as f64 / cap;
            score -= 10.0 * next_big * next_big;
        }
    } else {
        // Last-chance bonus: only one fitting bin -> strong reward to use it
        if fitting_bins_count == 1 {
            score -= 18.0;
        }
        // Prefer fuller bins among many open bins
        score -= 3.0 * (res / cap);
        // Lookahead synergy: leftover should fit the next item if possible
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / cap);
        }
    }

    // Mild preference to reduce number of open bins when mean residual is low
    if mean_residual < (item_size as f64) * 0.5 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Tight-fit reward: fill fraction of the bin ---
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // --- Harmonic class of post_residual: dead space analysis ---
    // Class A: residual too small to be useful later (dead space) -> penalize
    if post_residual > 0 {
        let dead_threshold = 12u32; // small unusable sliver
        if post_residual < dead_threshold {
            score += 20.0 * (dead_threshold - post_residual) as f64;
        }
    }

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 50.0;
    }

    // --- Modulo / integer-division classes on post_residual ---
    // Residuals that are multiples of small common sizes (10, 20, 25, 50)
    // are more likely to be reused by future items -> reward them.
    let reusable = (post_residual % 10 == 0 && post_residual >= 10)
        || (post_residual % 25 == 0 && post_residual >= 25)
        || post_residual == 50;
    if reusable {
        score -= 6.0;
    }
    // Odd, awkward residuals are less reusable -> mild penalty
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 2.0;
    }

    // --- Lookahead coupling: does next item fit the post residual? ---
    if next_item_size > 0 && post_residual >= next_item_size {
        // Keeping room for the next item is valuable
        score -= 4.0 + 0.05 * next_item_size as f64;
        // Bonus if next item exactly consumes the remainder
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; residual becomes dead weight
        score += 0.1 * post_residual as f64;
    }

    // --- Last-chance bin: avoid opening a new bin unnecessarily ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate: penalize opening a bin unless current fit is bad ---
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        score += 55.0;
        // It's more acceptable to open a new bin when:
        //  - the item is large (few bins can hold it anyway)
        //  - many bins are open but none fit well
        if item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // --- Spread awareness: if this bin's residual deviates from mean, mild nudge ---
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits (waste <= 5 is excellent).
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Prefer bins whose residual was already fragmented (tight fill tendency).
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += tightness * 10.0;

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty scaled by open bins.
        score += 20.0 + open_bins_count as f64 * 4.0;
        // But if this is the last fitting bin, opening a new bin is acceptable.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // If next item is large and mean residual is small, a fresh bin is attractive.
        if next_item_size as f64 > mean_residual + 5.0 && next_item_size > 0 {
            score -= 12.0;
        }
    } else if fitting_bins_count == 1 {
        // This bin is the only chance: strongly favor using it.
        score -= 35.0;
    }

    // Lookahead: if the post residual exactly accommodates the next item, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here after placement: penalize dead space.
        score += 6.0;
    }

    // Exact/near-exact fit of current item.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Relative tightness vs mean residual across open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
        // But if next item is large and post_residual here would be ideal, new bin is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Late-stream bias: prefer closing bins tightly as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: reward leaving a gap that fits the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        score -= 18.0 * (1.0 - (next_gap as f64 / bin_capacity as f64));
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty if this bin becomes stranded.
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless current fit is poor
    // or many bins are open and mean residual is high (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Base cost of a fresh bin.
        score += 70.0;
        // But if the item fits badly anywhere else, new bin looks better.
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if poor_fit < 0.35 {
            score -= 40.0;
        }
        if fragmentation > 0.5 && open_bins_count > 3 {
            score -= 20.0 * (fragmentation - 0.5);
        }
        // Late in the stream, avoid opening bins for small potential gains.
        score += 15.0 * progress;
    }

    // Mild preference for bins below mean residual (consolidate emptier space).
    if bin_residual as f64 > mean_residual {
        score += 6.0;
    } else {
        score -= 4.0;
    }

    // Reward using bins that are already fairly full (reduce bin count pressure).
    let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * used;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), non-linearly.
    let mut score = x * x * (2.0 - x); // smooth cubic: penalizes large leftover space

    // Smooth coupling with stream progress: as stream advances, demand tighter fits.
    let tightness = 1.0 + 3.0 * progress;
    score *= tightness;

    // Reward bins whose residual is "just right" for the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = x - nx;
        // If post residual closely matches next item, reward (subtract); mismatch penalized smoothly.
        let match_term = -4.0 * (-gap * gap * 40.0).exp();
        score += match_term;
        // Penalize leaving residual that is too small for the next item (dead space).
        if gap < 0.0 {
            score += -gap * cap * (0.02 + 0.05 * progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 2.0 + 2.0 * progress;
    }

    // Mild penalty when many bins are open and this bin's residual deviates from mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev * (open_bins_count as f64).sqrt() * (0.5 + progress);

    // Slight preference to keep filling already-open bins vs opening new ones.
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Small absolute tie-breaker on post residual.
    score += 0.01 * post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible into capacity
    // fractions are "harmonic" and easy to fill later; prime-ish residues are dead space.
    let post = post_residual;
    if post > 0 {
        // Class 1: post-residual is a clean capacity fraction (25/50/20/10 etc.)
        if post % 25 == 0 || post % 20 == 0 || post % 50 == 0 {
            score -= 6.0;
        }
        // Class 2: post-residual is small enough to be near-unfillable (dead space)
        if post < 10 {
            score += 12.0;
        } else if post <= 15 {
            score += 4.0;
        }
        // Modulo-10 harmonic banding: smoother residuals score better
        score -= ((post % 10) as f64) * 0.3;
    } else {
        // Perfect fit: strongly reward
        score -= 30.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 && post >= next_item_size {
        // Next item fits: reward, more if fit is tight (harmonic pairing)
        let slack = (post - next_item_size) as f64;
        score -= 10.0 - slack.min(10.0) * 0.5;
        // Harmonic pair: post and next item sum to a clean fraction
        if (post + next_item_size) % 25 == 0 || (post + next_item_size) % 50 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post > 0 && post < next_item_size {
        // Next item won't fit here: penalize small leftovers mildly
        if post < next_item_size && post < 20 {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many options, prefer tighter fits (smaller post already does this)
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        let base_penalty = 18.0;
        // Early in the stream, opening bins is cheaper (future items unknown)
        let progress = step_index as f64 / total_items.max(1) as f64;
        let decay = 6.0 * (1.0 - progress);
        // If mean residual across open bins is large, opening a new bin wastes potential
        let waste = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 10.0;
        score += base_penalty + waste - decay;
        // If next item is huge, a fresh bin is more valuable
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Prefer filling bins with high residual when open-bin count is large
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).min(8.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: heavily favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 24.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: post_residual gaps that are too small for typical
    // future items (and too small for the lookahead item) are "unusable".
    let dead_threshold = next_item_size.max(10) as f64;
    if (post_residual as f64) < dead_threshold {
        // Gap is unusable for the lookahead item: penalize proportionally.
        let unusable = dead_threshold - post_residual as f64;
        score += 6.0 + 0.35 * unusable;
    }
    if post_residual > 0 && post_residual < 10 {
        // Tiny sliver: near-total waste of the remaining space.
        score += 18.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this is a perfect chain placement — reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spreading out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 1.5 * pressure * (1.0 - progress * 0.5);

    // Relative fit vs. mean residual: bins already tighter than average
    // are good consolidation targets.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly awful.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has zero dead space now,
    // but opening it wastes the residual of existing bins. Penalize it
    // mildly so it only wins when no open bin offers a decent fit;
    // relax the penalty late in the stream when consolidation matters less.
    if bin_residual == bin_capacity {
        score += 14.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Empty new-bin candidate: penalize unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: full capacity of fresh residual.
        score = bin_capacity as f64 * 0.75;
        // Discount the new bin if the item leaves a huge dead space in existing bins
        // or if no bin fits (fitting_bins_count == 0 handled by caller, but be safe).
        let tight_fit = (bin_residual - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 1000.0;
        } else if tight_fit > 50.0 {
            // item would leave big hole in existing bins -> new bin more attractive
            score -= 20.0;
        }
        // Lookahead: if next item could combine with leftover in a fresh bin, mild discount
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) >= next_item_size as f64 {
            score -= 5.0;
        }
        return score;
    }

    // Core: reward exact 2-step lookahead match — post_residual equals next item size.
    if next_item_size > 0 {
        let match_gap = (post_residual as f64 - next_item_size as f64).abs();
        if match_gap < 0.5 {
            // Perfect chaining: item + next item exactly fill this bin.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement: reward proportionally.
            score -= 25.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space relative to mean residual.
            let dead = post_residual as f64;
            score += dead * 0.3;
            if dead > mean_residual {
                score += (dead - mean_residual) * 0.5;
            }
        }
    } else {
        // Last item: pure best-fit, minimal post residual.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild preference for tighter fits among comparable bins (best-fit flavor).
    score -= (item_size as f64 / bin_residual as f64) * 5.0;

    // Early in stream, keep bins open and flexible: slight penalty for very small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 && progress < 0.9 {
        score += 8.0; // avoid stranding tiny unusable slivers early
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), used to modulate exploration.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin before placing the item.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize dead space: very small post_residual that nothing (min size ~1..10) can use,
    // but reward perfect closure.
    if post_residual == 0 {
        score -= 30.0; // perfect fit, excellent
    } else if post_residual < 10 {
        score += 6.0; // tiny unusable gap (items >= 10 classically, but unknown dist: mild penalty)
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // reward proportional to how well next item would fill the remainder
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * next_fit;
        } else {
            // next item won't fit here; penalize leaving large stranded space
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate logic: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: prefer existing bins by default.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if existing fit is terrible (item much smaller than residual of alternatives),
        // opening a fresh bin is attractive: emulate by rewarding when item is large.
        // Large items (near half capacity or more) benefit from a fresh bin.
        if item_size as f64 >= 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Early in the stream, allow more exploration/opening.
        score -= 8.0 * (1.0 - progress);
        // If many bins are open and mean residual is high, discourage more bins.
        score += 0.3 * mean_residual * (open_bins_count as f64).sqrt() * 0.1;
    }

    // Encourage packing into bins that are already fairly full (best-fit flavor),
    // scaled by stream progress (more greedy later).
    score -= progress * 5.0 * fill;

    // Mild penalty for scattering across many open bins when this bin is nearly empty.
    if fill < 0.1 && open_bins_count > 3 {
        score += 2.0;
    }

    // Global balance: prefer bins whose residual is below mean (denser bins).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear dead-space penalty: quadratic coupling with stream progress.
    // Small residuals become increasingly wasteful as the stream progresses.
    let dead = (1.0 - norm_post).powi(2);
    score -= 12.0 * dead * (0.4 + 0.6 * progress);

    // Penalize residuals too small for the minimum item (unusable gap),
    // smoothly scaled by how close to unusable it is.
    if post > 0.0 && post < 1.0 {
        score += 0.0;
    }
    let min_item = 1.0f64;
    let unusable = ((min_item - post) / min_item).clamp(0.0, 1.0);
    score += 8.0 * unusable * unusable;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && (next_item_size as f64) == post {
        score -= 15.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        // Partial reward proportional to how well next item fills the gap.
        let fill = (next_item_size as f64) / post.max(1.0);
        score -= 6.0 * fill * fill;
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty, stronger late in stream.
        score += 3.0 * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Discourage spreading across too many open bins relative to mean residual:
    // prefer bins tighter than the mean (best-fit-like behavior).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate (residual == capacity): penalize so new bins are only
    // opened when no good fit exists; relax penalty as stream progresses so
    // late poor fits prefer fresh bins over fragmenting old ones.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 20.0 - 8.0 * progress;
        // If item is huge relative to capacity, opening a fresh bin is fine.
        let big_item_bonus = (item_size as f64 / cap) * 6.0;
        score += new_bin_penalty - big_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    // Residuals that are "nice" (divisible into common small sizes) are less wasteful.
    let cap_frac = bin_capacity / 4; // 25
    let mut class_penalty = 0.0;
    if post_residual == 0 {
        class_penalty -= 60.0; // perfect fit: best possible
    } else if post_residual < 10 {
        class_penalty += 25.0; // dead space below smallest item size
    } else if post_residual % cap_frac == 0 {
        class_penalty -= 20.0; // residual is a clean quarter-capacity multiple
    } else if post_residual % 10 == 0 {
        class_penalty -= 10.0; // residual aligns with common item granularity
    } else {
        class_penalty += (post_residual % 10) as f64 * 1.5; // jagged remainder penalty
    }
    score += class_penalty;

    // Integer-division threshold on post_residual relative to next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item also fits here: strong reward, scaled by tightness
            let slack = post_residual - next_item_size;
            score -= 30.0 + (post_residual - slack) as f64 * 0.4;
        } else {
            // next item won't fit: penalize proportionally to wasted opportunity
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // harmonic class of next_item_size vs post_residual (mod alignment)
        if post_residual > 0 && next_item_size % post_residual.max(1) == 0 && post_residual >= 10 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are all poor fits (harmonic threshold on mean residual).
    if bin_residual == bin_capacity {
        let poor_residuals = mean_residual < (bin_capacity as f64 * 0.2);
        let late_stream = step_index as f64 / (total_items.max(1) as f64) > 0.7;
        if poor_residuals || (late_stream && open_bins_count > 2) {
            score -= 5.0; // allow opening when open bins are fragmented
        } else {
            score += 80.0; // discourage opening when good bins exist
        }
    }

    // Mild preference for tighter bins overall (relative to mean residual).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late-stream consolidation: push toward filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // gap too small for any item (min size 1..100 => treat <10 as near-dead)
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // marginal gap, only very small items can use it
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize a gap that is just barely too small for the next item (would become dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 25 {
        score += 18.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of bins; mild per-bin penalty
    // applied to the brand-new-bin candidate (residual == capacity) so that
    // open bins are generally preferred, but a new bin beats a bad fit.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.35 * open_bins_count as f64;
        // Opening a new bin is attractive when the item is large relative to capacity
        // and no bin fits well (post_residual in the new bin is capacity - item).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= 60 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Deviation from mean residual: prefer bins that are already relatively full
    // (small residual) to consolidate packing.
    score += 0.05 * (mean_residual - bin_residual as f64).abs() * (bin_residual as f64 - mean_residual).signum().max(0.0);

    // Slight preference for tighter fits overall (non-linear in post_residual).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post residual can still hold the next item: keep the bin attractive
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }
    // Next item cannot fit here; penalize dead space more when it is small
    else if next_item_size > 0 {
        score += 10.0 + 0.5 * next_item_size as f64;
    }

    // Reward tight fits (small post residual) generally
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize bins with residual far from the mean (outliers)
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        score += desperation + 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Late in the stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual).
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 40.0 * fit_ratio * fit_ratio;

    // Lookahead: if next item fits exactly in post_residual, big reward for this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * chain_tightness;
    }
    // Penalize leaving post_residual too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // When several bins fit, mild penalty proportional to choice richness to spread load.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented
    // or this is a very poor fit for existing bins.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let poor_fit = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
        // New bin is penalized normally, but discount when open bins are few and mean
        // residual is small (nothing useful to place into).
        let desperation = (1.0 - mean_residual / bin_capacity as f64).max(0.0);
        score += 30.0 - 20.0 * desperation - 10.0 * poor_fit - 0.5 * fragmentation.min(50.0);
    }

    // Global state: many open bins with large mean residual -> encourage consolidating
    // into already-open bins rather than spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * crowding * (1.0 - progress);

    // Late in the stream: be more conservative, prefer filling existing bins tightly.
    score -= 10.0 * progress * fit_ratio;

    // Prefer bins whose residual is close to item size (near-exact fit bonus).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score -= 8.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Core: prefer small post-residual, with smooth polynomial shaping.
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Stream-progress coupling: late in the stream, dead space hurts more,
    // so amplify the penalty on large post-residuals smoothly.
    let progress_coupling = 1.0 + 1.5 * progress * norm_post;
    score *= progress_coupling;

    // Interaction with mean residual: if the fleet is already fragmented
    // (high mean residual), penalize leaving more dead space.
    score += 0.35 * (mean_residual / cap) * post;

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item cannot fit in post-residual, mildly penalize big leftovers.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 4.0 * (1.0 - (nxt / post.max(1.0)).abs() - 0.5).abs().min(1.0);
        } else {
            score += 0.08 * (nxt - post);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mild penalty for many open bins (consolidation pressure), scaled smoothly.
    score += 0.15 * (open_bins_count as f64).sqrt() * norm_post;

    // New-bin candidate handling: residual == capacity means an empty bin.
    // Base it slightly above a perfect fit in an existing bin, but let it win
    // when the item would leave a very awkward remainder (smooth threshold).
    if bin_residual == bin_capacity {
        let awkward = 1.0 - (-2.5 * (norm_post - 0.35) * (norm_post - 0.35));
        score += cap * (0.10 + 0.5 * awkward.max(0.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: mod-10 residue classes ---
    // Residuals that are "harmonically useful" (multiples of 10, small residues)
    // are less dead space; odd/awkward residues are penalized.
    let pr = post_residual;
    let residue = (pr % 10) as f64;
    if pr > 0 {
        score += residue * 0.6; // penalize non-aligned dead space
    }
    // Perfect-fit class: residual exactly 0 is ideal
    if pr == 0 {
        score -= 40.0;
    }
    // Small-but-alive residuals (1..=9) are near-dead space: heavy penalty
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Harmonic sweet spots: residuals that are multiples of 25 or 50 can host
    // common item classes
    if pr % 50 == 0 && pr > 0 {
        score -= 12.0;
    } else if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Integer-division thresholds on post_residual: which item classes still fit
    // next (next_item_size lookahead, k=2)
    if next_item_size > 0 {
        if next_item_size <= pr {
            // This bin can also host the next item: strong reward, especially
            // when post_residual is close to next_item_size (tight chain)
            let tightness = 1.0 - (pr - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 + 10.0 * tightness;
        } else {
            // Next item cannot fit here: this bin becomes dead after this placement
            score += 10.0;
            // If the leftover is also below the minimum observed item scale (~10),
            // it is truly dead space
            if pr < 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling fuller bins: normalize fill fraction
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Discourage opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost, plus penalty if open bins fit well
        score += 8.0;
        if fitting_bins_count > 0 {
            // Only open a new bin if existing fits are bad (large post_residual elsewhere)
            let best_else = mean_residual.min(bin_capacity as f64);
            if best_else > (bin_capacity as f64) * 0.5 {
                score -= 6.0; // existing bins are roomy; opening new is less costly
            } else {
                score += 12.0;
            }
        }
        // Early in stream: slightly favor opening bins to build diversity
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * (1.0 - progress);
    }

    // Mild penalty for bin sprawl
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste. Penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits (post_residual very small relative to item).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual as f64 <= 0.05 * bin_capacity as f64 {
        score -= 40.0;
    } else if post_residual as f64 <= 0.15 * bin_capacity as f64 {
        score -= 15.0 * fill_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading items,
    // prefer keeping fill concentrated; few open bins -> opening new bins is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item could exactly use the post_residual,
    // reward leaving that gap; if next item is large and wouldn't fit anyway,
    // dead space matters less.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual {
            // gap unusable for next item: slight penalty scaled by gap size
            score += 0.2 * (post_residual as f64);
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (fill the emptier-relative bins less; prefer tighter bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate handling: an empty bin has large post_residual, which
    // already scores high; add a mild fixed cost so it is only chosen when
    // open bins have poor fits (their bonuses/penalties dominate).
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64).min(1.0);
        }
        // Penalize post_residual just below next_item_size (near-miss dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: tightest fit wins
        score -= 20.0;
    }

    // Reward tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when it enables a perfect next match
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        } else {
            score += 40.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) but avoid near-zero dead space
    // that the lookahead item cannot use.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if post residual is stranded (too small for next item
    // and below the minimum item size), penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // stranded space relative to next item
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize leaving tiny unusable slivers (< typical min size 10)
    if post_residual < 10 && post_residual > 0 {
        score += 12.0 * (10.0 - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Global state: many open bins with large mean residual -> prefer
    // consolidating into existing bins; few open bins -> new bin is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.35 * crowding * (0.5 + 0.5 * progress);

    // New-bin candidate handling: empty bin should only win when existing
    // fits are poor or bin set is crowded.
    if bin_residual == bin_capacity {
        score += 22.0;
        if open_bins_count == 0 {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // late in the stream, opening fresh bins is more wasteful
        score += 15.0 * progress;
    }

    // Mild preference for filling larger-residual bins when mean residual is low
    score += 0.08 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Core: prefer tight fits (small post_residual), with polynomial shaping.
    let x = pr / cap; // normalized post residual in [0,1)
    let mut score = x * x * (3.0 - 2.0 * x); // smoothstep: strongly penalize large leftover

    // Non-linear coupling with stream progress: early on, tolerate loose fits
    // (keep bins flexible); late, demand tight packing.
    let tight_bias = 1.0 + 2.0 * progress * progress;
    score *= tight_bias;

    // Interaction: post_residual vs mean residual — avoid making a bin far
    // tighter than the fleet average (wasted flexibility), smooth cubic term.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 0.5 * dev * dev * dev.abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // unless post residual is huge.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - x * x);
    }

    // Lookahead: reward leaving room for the next item (smooth logistic coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let room = x - nx; // how much slack remains for next item after this
        let s = 1.0 / (1.0 + (-6.0 * room).exp());
        score += 2.0 * (1.0 - s); // penalize when next item won't fit here
    }

    // New-bin candidate handling: empty bin should only win when current bins
    // are poor fits. Penalize opening new bins progressively with stream length.
    if bin_residual == bin_capacity {
        let fleet_pressure = (open / (open + 4.0)) * (0.5 + 0.5 * progress);
        score += 6.0 * (1.0 - fleet_pressure);
        // but if many bins already fit the item, opening new is clearly worse
        score += 1.5 * fit;
    }

    // Mild penalty for very small unusable slivers (dead space), smooth.
    if pr > 0 && pr < 10 {
        score += 1.0 - (pr as f64) / 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap_f = bin_capacity as f64;

    // ---- New-bin candidate ----
    if bin_residual == bin_capacity {
        let mut s = cap_f * 0.85 + post_residual as f64;
        // If no open bin can fit the item, opening a bin is necessary.
        if fitting_bins_count == 0 {
            s -= 60.0;
        }
        // If the next item cannot fit a fresh bin either, slightly discourage opening now.
        if next_item_size > 0 && next_item_size > bin_residual {
            s += 15.0;
        }
        // Late in the stream, closing out with new bins is cheaper.
        s -= progress * 10.0;
        return s;
    }

    // ---- Existing-bin scoring ----
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Harmonic classes: bucket post_residual into capacity quarters.
        let quarter = (bin_capacity / 4).max(1);
        let class = post_residual / quarter;
        score += class as f64 * 6.0;

        // Near-perfect residual (very small dead space).
        if post_residual < 10 {
            score -= 15.0;
        }
        // Decimal-aligned residuals pair well with typical item sizes.
        if post_residual % 10 == 0 {
            score -= 4.0;
        }
        // Residuals in the awkward middle band (just above half) are flexible; slight reward.
        if post_residual > bin_capacity / 2 && post_residual <= bin_capacity / 2 + 10 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item also fits in the leftover space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual {
        // Penalize leaving residual the next item cannot use, proportional to wasted space.
        score += 5.0 * (post_residual as f64 / cap_f);
    }

    // Prefer fuller bins (less residual before placement).
    score -= (bin_capacity - bin_residual) as f64 * 0.2;

    // Mild tie-breaker toward bins below the mean residual (consolidate emptier space).
    score -= mean_residual.min(cap_f) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1) can ever
    // fill usefully are heavily penalized; gaps below the typical item floor
    // (10) are semi-dead.
    if post_residual == 0 {
        score -= 60.0; // perfect fill, best possible outcome
    } else if post_residual < 10 {
        score += 45.0; // unusable dead space
    } else if post_residual < 20 {
        score += 18.0; // risky gap
    }

    // Reward tight fits: small fraction of residual consumed as waste.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item cannot go here; the gap becomes dead unless another bin helps
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: prefer reusing bins when many are already open,
    // but allow new-bin escape when pressure is low and fit is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when the current fit is bad
    // (large post residual waste) or residual is already fragmented.
    if bin_residual == bin_capacity {
        // baseline score equals full capacity; adjust so a new bin wins
        // only when existing bins would waste a lot of space.
        score -= 5.0;
        if mean_residual < 30.0 {
            score -= 10.0; // open bins are nearly full anyway
        }
        if item_size >= bin_capacity / 2 {
            score -= 15.0; // big items deserve fresh bins
        }
    }

    // Mild preference to pack into below-mean-residual bins (balance load).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (smaller post_residual) is better.
    // Reward perfect-ish fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item's size (chain packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        // Exact chain match is highly desirable.
        if post_residual == next_item_size {
            score -= 45.0;
        }
        // Penalize leaving residual that no small future item can use
        // if it is far from next_item_size and small.
        if post_residual < 10 && post_residual != next_item_size {
            score += 25.0;
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Compare against mean residual: bins with residual well below the mean
    // are "tight" bins; placing here consolidates near-full bins.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.6 * (mean_residual - residual_f);
    } else {
        score += 0.3 * (residual_f - mean_residual);
    }

    // New-bin candidate handling: an empty bin is a fallback.
    // Only attractive when the item is huge relative to capacity or
    // when no open bin offers a decent fit (high post_residual everywhere).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Big items fill a fresh bin well; small items should go into open bins.
        score += 35.0 * (1.0 - fill_ratio);
        // If stream is late, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many bins are already open, discourage another one.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild penalty for wasting a large-residual bin on a tiny item
    // when the fit leaves a big awkward gap relative to capacity.
    let gap_ratio = post_residual as f64 / bin_capacity as f64;
    if gap_ratio > 0.5 && gap_ratio < 0.9 {
        score += 10.0 * gap_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // Penalize if next item cannot fit here anyway (wasted pairing opportunity).
            score += 3.0;
        }
        // Perfect chain: next item exactly fills remaining space.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: opening a new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Cheaper to open new bins early in the stream (more future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // If many bins are open and none fit well, new bin is more acceptable.
        score -= 2.0 * open_bins_count as f64;
        // If mean residual is high, existing bins have room; discourage new bin.
        score += 0.3 * mean_residual;
    }

    // Prefer bins below mean residual (smaller bins absorb items, keeping large gaps free).
    if bin_residual != bin_capacity {
        score += 0.1 * ((bin_residual as f64) - mean_residual);
    }

    // Mild penalty for spreading across many open bins late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    let mut score = pr;

    // Non-linear coupling: post_residual scaled by stream progress (later items tolerate larger leftovers less)
    score += 8.0 * pr * progress * (1.0 - progress);

    // Penalize dead space quadratically when it can't fit the next item
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0);
        score += 0.05 * waste * waste / cap;
    } else {
        // End of stream: strongly prefer minimal leftover
        score += 0.2 * pr * pr / cap;
    }

    // Smooth interaction between residual fraction and progress
    let res_frac = bin_residual as f64 / cap;
    score -= 6.0 * res_frac * (1.0 - res_frac) * (1.0 - progress);

    // Last-chance bonus: only one bin fits, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin candidate, more so early in the stream
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (balancing)
    score += 0.3 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize large dead space quadratically
    score += 0.012 * (post_residual as f64).powi(2) / cap_f;

    // Harmonic class of post_residual: residuals divisible by common class
    // sizes (10, 20, 25, 50) are "harmonic" and more reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        60.0 // perfect fill: best possible
    } else if pr % 50 == 0 {
        25.0
    } else if pr % 25 == 0 {
        18.0
    } else if pr % 20 == 0 {
        14.0
    } else if pr % 10 == 0 {
        10.0
    } else if pr % 5 == 0 {
        5.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize odd/non-harmonic residuals scaled by size (dead space that
    // cannot be exactly filled by typical class sizes).
    let nonharmonic = if pr % 10 != 0 { pr % 10 } else { 0 };
    score += 0.6 * nonharmonic as f64;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item fits: reward harmonic post_residual classes
            if pr % next_item_size == 0 {
                score -= 20.0;
            }
            let npr = pr - next_item_size;
            if npr % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual: penalize large residuals wasted
            score += 0.05 * pr as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more when many bins
    // are open and stream is progressing (waste accumulates).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap_f + 40.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
        // but if the item is huge relative to mean residual space, opening
        // a fresh bin may be right: soften penalty
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
        // exact-capacity item: new bin is perfect
        if item_size == bin_capacity {
            score = -100.0;
        }
    }

    // Integer-division threshold: bins whose residual class matches item's
    // capacity-fraction class get preference.
    let item_class = bin_capacity / item_size.max(1);
    let resid_class = if pr > 0 { pr / item_size.max(1) } else { 0 };
    if resid_class > 0 {
        score -= 3.0 * resid_class.min(item_class) as f64;
    }

    // Slight preference for bins below mean residual (consolidate emptier bins)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 - 2.5 * post_residual as f64; // tiny gaps heavily penalized
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins whose residual is just above the item (snug fit).
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score -= 12.0 / (1.0 + snug);

    // Coupling: dead space is worse when few bins fit the item (last chance).
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: prefer consolidating into existing bins.
    score += 0.35 * open_bins_count as f64;

    // Penalize bins far from mean residual (encourage homogeneity of fills).
    score += 0.08 * (post_residual as f64 - mean_residual).abs();

    // Lookahead: if next item could exactly use the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0; // post residual useless for next item
    }

    // Late in the stream, be more tolerant of opening new bins with clean residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = 60.0 - 25.0 * progress + 0.5 * item_size as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post_residual as f64 - nx).abs();
        if post_residual as u32 == next_item_size {
            score -= 800.0; // chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            score -= 150.0 * (nx / (post_residual as f64 + 1.0)); // next item fits well
        } else {
            score += 120.0 * (nx / (post_residual as f64 + 1.0)); // dead space vs lookahead
        }
        // Gentle bonus for small |post_residual - next|
        score += 0.4 * diff;
    } else {
        // Last item: prefer tightest fit
        score -= 300.0;
    }

    // Relative to mean residual: prefer bins with residual near item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Penalize leaving large unusable slivers (below typical small item size)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0; // tiny dead space
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // New empty bin candidate: strongly discourage unless few fitting bins
    if bin_residual == bin_capacity {
        score += 250.0 + 30.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 350.0; // opening a bin is fine when no good alternatives
        }
    }

    // Prefer fuller bins (low residual) generally
    score -= 0.5 * (bin_capacity as f64 - bin_residual as f64);

    // Slight preference for using fewer bins early vs late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver is wasted capacity
    } else if post_residual >= 10 {
        // post_residual that can still hold items is fine; slight reward for medium leftovers
        score -= 3.0 * ((post_residual as f64) / 100.0).min(1.0);
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is expensive; penalize unless current bin is a poor fit
        // or this is the last fitting bin.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0
            - 20.0 * (1.0 - fit_ratio)
            - 15.0 * progress;
        // If many bins are open and mean residual is large, prefer reusing open bins.
        score += 0.5 * open_bins_count as f64;
        score += 0.2 * mean_residual;
        // If no other bin fits well (fitting_bins_count == 1 means only this choice among open),
        // new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Existing bin: reward being the last chance (avoid opening a new bin).
        if fitting_bins_count == 1 {
            score -= 35.0;
        } else {
            score -= 5.0 * (fitting_bins_count as f64).recip();
        }

        // Lookahead: if next item could use the post_residual, reward this placement.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 10.0; // chain-friendly placement
            } else if (bin_residual >= item_size + next_item_size) == false && post_residual < next_item_size {
                score += 4.0; // leaving space too small for next item
            }
            // Perfect pair: item + next fills bin exactly
            if item_size + next_item_size == bin_residual {
                score -= 20.0;
            }
        }
    }

    // Slight global balance: prefer bins with residual below mean (consolidate fullness).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild time-horizon scaling: later in stream, tighten more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) - prn * progress;
    score += 40.0 * poly;

    // Reward near-perfect fits, stronger late in stream
    let fit = (prn - 0.05).abs();
    score -= (1.0 - fit.min(1.0)) * (10.0 + 30.0 * progress);

    // Penalize waste relative to mean residual
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: favor residuals that can still host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        score += 5.0 * prn;
    }

    // New-bin candidate: mildly penalize so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction buckets. Leftovers that fall into small "dead zone"
    // classes (cannot fit even the smallest plausible item) are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement.
    let post_frac = post / cap;

    // Dead-space penalty: residual below the minimum item size is pure waste.
    if post_residual < 10 && bin_residual != bin_capacity {
        score += 60.0 * (10.0 - post) / 10.0;
    }

    // Harmonic class via integer division thresholds on post_residual.
    // Classes: [0,9), [10,24), [25,49), [50,74), [75,100]
    let class = post_residual / 25; // 0..=4
    let class_bias = match class {
        0 => 25.0,                      // tiny leftover, likely dead space
        1 => 5.0,                       // awkward mid-small leftover
        2 => -8.0,                      // ~half-full bin, good packing
        3 => -12.0,                     // leaves room for mid items
        _ => -15.0,                     // large residual, flexible bin
    };
    score += class_bias;

    // Modulo harmonic: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) pair well with typical item quantization.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack.min(10.0);
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how far off it is, using modulo classes of the mismatch.
            let mismatch = next_item_size - post_residual;
            score += (mismatch % 20) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a
    // new bin when the fit is reasonable.
    if fitting_bins_count == 1 && post_frac >= 0.0 {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin gets a neutral baseline so it
    // only wins when open bins would create bad fits.
    if bin_residual == bin_capacity {
        score = 55.0
            + post_frac * 10.0
            - if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        // Late in the stream, opening new bins is less attractive if mean
        // residual across open bins is still large.
        score += mean_residual * 0.1;
        // Early stream: new bins are cheap, slightly favor them.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        return score;
    }

    // Prefer tight fits: reward small post residual relative to item size.
    score -= (item_size as f64) * 0.15;

    // Spread pressure: with many open bins, prefer filling existing ones
    // rather than leaving many half-empty bins.
    if open_bins_count > 2 {
        score -= 2.0 * (open_bins_count.min(20) as f64).ln();
    }

    // Mean residual coupling: if this bin is below mean residual (tighter
    // than average), it is a good consolidation target.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to plausibly fit a future item are wasted.
    // Treat gaps < 10 (min item) as total loss, and gaps just above the minimum as risky.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 18.0;
    } else if post_residual <= 35 {
        score += 6.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another one
    // (applies to the new-bin candidate whose residual == capacity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 8.0 + 30.0 * progress + 0.6 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += pressure;
    }

    // Lookahead: if the next item can use the post residual, reward leaving it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Slight preference for bins tighter than the mean (better consolidation).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: perfect match with next item is golden.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 120.0; // exact two-item completion
        } else if post_residual > next_item_size {
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize dead space proportional to gap
            score += 0.5 * diff;
        }
    } else {
        // last item: just minimize post_residual
        score -= 30.0 * tightness;
    }

    // Relative to mean residual: bins already fragmented are less attractive.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when it genuinely beats squeezing in.
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can host the next item too
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // opening a bin is reasonable when alternatives are scarce
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize large dead space if post_residual is small-but-unusable
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 5.0 + 0.05 * next_item_size as f64;
    }
    // If next item cannot fit in post_residual but would fit a fresh bin, penalize slightly
    if next_item_size > post_residual && next_item_size > 0 {
        score += 2.0;
    }

    // New-bin candidate handling: empty bin gets a mild default preference
    if bin_residual == bin_capacity {
        // Prefer new bin when existing bins fit poorly
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score += 12.0 - 20.0 * (1.0 - poor_fit);
        // Early in stream, opening bins is cheap; late, avoid proliferation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 * progress;
        // If many bins already open, discourage opening more
        score += 0.4 * open_bins_count as f64;
    }

    // Global state coupling: high mean residual suggests slack exists; prefer bins below mean
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score += 1.5;
    } else if bin_residual < bin_capacity {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear shaping
    let mut score = x * (1.0 + 0.6 * x * (1.0 - x)) * cap;

    // Smooth polynomial coupling with stream progress:
    // late in stream, tighten further (penalize waste more)
    let late = progress * progress;
    score += 8.0 * late * x * (1.0 - x) * 4.0;

    // Reward tight fits (post residual near zero) more strongly as stream advances
    score -= 12.0 * (1.0 - x) * (1.0 - x) * (0.5 + progress);

    // Lookahead coupling: if next item fits the post residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - progress) * (next_item_size as f64 / cap);
    }

    // Last-chance bin bonus: only one bin fits -> strong reward
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins far from mean residual (fragmentation aversion), smooth in progress
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * (0.5 + progress);

    // New-bin candidate handling: empty bin gets a smooth adaptive penalty,
    // relaxed when current fit is poor or item is large
    if bin_residual == bin_capacity {
        let tightness = 1.0 - x; // for empty bin post_residual = cap - item => x = item/cap
        let fit_quality = tightness * tightness; // large item -> better "fit" into new bin
        score += 20.0 - 14.0 * fit_quality - 8.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 25.0; // nothing else fits well: allow new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Perfect-fit classes: reward residuals that are harmonic divisors of capacity
    // (these are the most reusable "slots" for future items).
    let harmonic_bonus = if pr == 0 {
        60.0
    } else if pr == half {
        30.0
    } else if pr == third {
        22.0
    } else if pr == quarter {
        14.0
    } else if pr % 10 == 0 && pr <= bin_capacity / 2 {
        8.0
    } else {
        0.0
    };
    score -= harmonic_bonus as f64;

    // Dead-space penalty: small odd residuals are hard to fill (items >= 1 but
    // typically chunky). Penalize non-harmonic tiny residuals.
    if pr > 0 && pr < quarter {
        let oddness = (pr % 2) as f64 + (pr % 3 == 0) as u32 as f64;
        score += 12.0 + (quarter - pr) as f64 * 0.6 + oddness * 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            let gap_quality = if gap == half as u32 { 18.0 }
                else if gap == third as u32 { 12.0 }
                else if gap % 10 == 0 { 7.0 }
                else { 0.0 };
            score -= 10.0 + gap_quality;
        } else {
            // Next item cannot follow here; penalize slightly more for wasted slot.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current fit is poor. Penalize the fresh bin mildly so decent fits win.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0
            + open_bins_count as f64 * 0.5
            + mean_residual * 0.15
            + progress * 5.0;
        // But if current item leaves a bad residual everywhere, fresh bin is attractive:
        if post_residual > 0 && post_residual < quarter {
            score -= 18.0;
        }
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 40.0; // next item is full-bin size, save space
        }
    }

    // Mild preference for tighter bins overall (best-fit core), modulated by
    // harmonic class of bin_residual.
    score += (bin_residual as f64) * 0.05;
    if bin_residual % 10 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small leftover gaps (1..=9) are nearly unusable.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual > 9 && post_residual <= 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Tight fit reward: leftover smaller than half of min item size.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 && post_residual > 0 {
        score -= 40.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open bins pressure: penalize spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins whose residual is close to the item (best-fit coupling).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 30.0;

    // Lookahead: avoid leaving a gap that barely fails the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }

    // New-bin candidate: only open a new bin when current bin fits are poor.
    if bin_residual == bin_capacity {
        score = 150.0 + open_bins_count as f64 * 3.0 - mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score = -50.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Aggressive 2-step lookahead matching:
    // reward bins whose post_residual exactly matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match gets a strong discount; near matches get graded discount.
        if diff == 0.0 {
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else if diff <= 10.0 {
            score -= 30.0 - 2.0 * diff;
        } else {
            // Penalize leaving a gap that neither fits nor matches next item well.
            score += 0.5 * diff;
        }
    } else {
        // Last item: prefer tightest fit (smallest post_residual), base score already does this.
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins with below-average residual (tighter bins)
    // so we keep larger residual bins flexible for larger future items.
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= 0.4 * (mean_residual - resid_f);
    } else {
        score += 0.6 * (resid_f - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize opening a new bin unless the item is large
    // relative to the bin and no good fit exists (encourage consolidation).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is attractive mainly for big items or late in the stream.
        score += 35.0 - 25.0 * fill_ratio - 10.0 * progress;
        // If many open bins already exist, discourage spreading further.
        score += 0.5 * open_bins_count as f64;
        // But if the next item is huge and won't fit anywhere after placement,
        // opening a fresh bin may be wise: soften the penalty.
        if next_item_size > post_residual && next_item_size > 0 {
            score -= 15.0;
        }
    }

    // Penalize very small dead space that is likely unusable (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small slivers are fine to leave
    } else if post_residual >= 10 && post_residual < 40 {
        score += 6.0 * (1.0 - (post_residual as f64) / 40.0); // mid-range leftover is awkward
    } else {
        score -= 4.0; // large leftover keeps bin usable
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly after this placement -> big reward
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // New-bin candidate handling: opening a new bin wastes capacity; penalize
    // unless the current fit is poor or bin is nearly full.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 50.0;
        if poor_fit && fitting_bins_count > 0 {
            score -= 10.0; // open a fresh bin for a big item rather than fragmenting
        } else {
            score += 20.0 + 0.5 * open_bins_count as f64; // prefer existing bins
        }
    }

    // Global state coupling: when many bins are open with large mean residual,
    // favor consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual / (bin_capacity as f64)) * (1.0 + progress);
    score -= 5.0 * consolidation;

    // Mild preference for fuller bins as stream progresses.
    score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: prefer tight fits (small post_residual), non-linearly amplified.
    let mut score = pr * (1.0 + 0.8 * pr / cap);

    // Dead-space penalty: residuals too small to ever fit future items (items >= 1).
    if pr > 0.0 && pr < 1.0 {
        score += 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 6.0 * progress;
    }

    // Penalty for wasting a nearly-empty bin when many bins fit the item anyway
    // (preserve big-residual bins for awkward items).
    let waste = (bin_residual as f64 - item_size as f64) / cap;
    if fitting_bins_count > 1 {
        score += 3.0 * waste * waste * (fitting_bins_count as f64 - 1.0);
    }

    // Coupling with stream progress: later in stream, value tight packing more,
    // and penalize opening new bins.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let urgency = (next_item_size as f64 / cap).max(0.0);
        // New bin attractive only if item is large or no alternative; penalize otherwise.
        score += 8.0 * (1.0 - progress) + 6.0 * open_bins_count as f64 * 0.1;
        if next_item_size > 0 && urgency > 0.5 {
            score -= 4.0; // large next item: fresh bin useful
        }
        if fitting_bins_count >= 1 {
            score += 10.0; // existing bins can take it; avoid spreading
        }
    }

    // Mean residual coupling: when average residual is low, tight fits matter more.
    score += 0.05 * (mean_residual - pr).abs() * (0.5 + progress);

    // Lookahead: reward leaving post_residual that can host the next item.
    if next_item_size > 0 {
        if pr >= next_item_size as f64 && pr > 0.0 {
            score -= 3.0 * (pr / cap) * (1.0 - (pr - next_item_size as f64) / cap);
        } else if pr > 0.0 {
            score += 2.0 * progress; // stranded residual late in stream is costly
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled softly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * pr;

    // Harmonic class of post_residual: residues mod small divisors.
    // Residue 0 classes (post_residual divisible by 10/20/25) are "cleaner"
    // dead space for future items drawn from typical size lattices.
    let post = post_residual;
    let residue10 = (post % 10) as f64;
    let residue20 = (post % 20) as f64;
    let residue25 = (post % 25) as f64;
    score += 1.2 * residue10 + 0.8 * residue20 + 0.6 * residue25;

    // Integer-division thresholds: reward post_residual falling into
    // "usable" bands where a next item likely fits.
    if next_item_size > 0 {
        let nx = next_item_size;
        if post >= nx {
            // Perfect harmonic match: next item exactly fills this bin.
            if post == nx {
                score -= 60.0;
            } else {
                score -= 12.0;
            }
            // Class match on modulo 10: next item's residue aligns with post.
            if post % 10 == nx % 10 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += 4.0 + 0.15 * ((nx - post) as f64);
        }
        // If next item is large, prefer leaving large residuals.
        if nx > 50 && post < nx {
            score += 3.0;
        }
    } else {
        // Last item: any residual is pure waste; minimize it hard.
        score += 2.0 * pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so it is
    // only chosen when no open bin offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But if the item is huge relative to mean residual, opening fresh
        // is reasonable — soften the penalty.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - pr / cap);

    // Tie-break toward bins with low residual relative to fleet mean
    // (keeps mean residual low, avoids many half-empty bins).
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any future item are pure waste. Penalize them heavily.
    let min_item = 1u32;
    if post_residual < min_item {
        // Perfect fit: zero residual is ideal.
        score -= 25.0;
    } else if post_residual <= 10 {
        // Small dead space below the minimum item size is unusable.
        score += 20.0;
    } else if post_residual <= 20 {
        // Tight residual band: only small items can use it, mildly risky.
        score += 6.0;
    } else {
        // Usable residual: gently reward keeping room for the next item.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let next_fits = next_item_size > 0 && post_residual >= next_item_size;
        if next_fits {
            score -= 4.0 * (1.0 - progress);
        } else if next_item_size > 0 {
            score += 3.0;
        }
    }

    // Reward filling the bin tightly relative to capacity.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Last chance: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins over spreading out.
    let pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);
    if bin_residual != bin_capacity {
        score -= 5.0 * pressure;
    } else {
        // New-bin candidate: only attractive when the item is large and
        // no existing bin fits well (post_residual small in a fresh bin
        // means a big item -> a fresh bin dedicated to it).
        score += 12.0 + 8.0 * pressure;
        // If lookahead item would also fit the fresh bin comfortably,
        // opening a new bin becomes more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is an outlier worth emptying out (closing small bins first).
    let resid = post_residual as f64;
    if bin_residual != bin_capacity && resid < mean_residual - 15.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score -= 20.0 * (-post_residual as f64 / 10.0).exp();

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space penalty: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (post_residual as f64 - next_item_size as f64 + 1.0).ln().max(0.0);
        } else {
            // Next item won't fit here; penalize leaving medium dead space.
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins already below-average residual (well-filled).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count <= 1 {
            score -= 70.0; // no real alternative: open new bin
        } else if post_residual as f64 > mean_residual {
            score -= 10.0; // current bins are quite empty, new bin is fine
        }
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Base penalty for opening a new bin; grows with number of open bins.
        score += 35.0 + 2.5 * open_bins_count as f64;
        // Large items justify a fresh bin; small items should squeeze into open bins.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score -= 45.0 * fill_frac * fill_frac;
        // If this item barely fits anywhere, a new bin is legitimate.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        } else if fitting_bins_count <= 3 {
            score -= 20.0;
        }
        // Early in the stream, tolerate more bins (future items can fill them).
        score -= 15.0 * (1.0 - t);
        // Lookahead: if the next item would fit into a fresh bin's leftover, boost appeal.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 10.0;
        }
    } else {
        // Last-chance bin: strongly reward using it to avoid opening a bin later.
        if fitting_bins_count == 1 {
            score -= 28.0;
        } else {
            // Among multiple candidates, prefer bins whose residual is already small (tight fit).
            score += 0.2 * (mean_residual - post_residual as f64).max(0.0);
        }
        // Lookahead coupling: reward when next item nests in the leftover space.
        if next_item_size > 0 {
            if (next_item_size as f64) <= post_residual as f64 {
                score -= 12.0;
            } else if next_item_size <= bin_residual {
                // Next item fits this bin now but would be blocked by current item.
                score += 7.0;
            }
        }
        // Penalize creating tiny dead space that nothing (min size 1..100) can use later.
        if post_residual > 0 && post_residual < 10 {
            score += 6.0;
        }
        // Slight preference for keeping very large residuals intact for big future items.
        if post_residual > 70 {
            score += 4.0;
        }
    }

    // Mild time-horizon drift: late in the stream, consolidation matters more.
    score += 3.0 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post-residual (tight packing), normalized.
    let mut score = post / cap;

    // Smooth polynomial coupling of tightness with stream progress:
    // tight fits matter more as the stream matures.
    let tightness = 1.0 - post / cap; // 1 = perfect fit
    score -= tightness * tightness * (0.5 + 2.0 * progress);

    // Penalize leaving dead space that is too small for typical items
    // (non-linear: unusable slivers cost disproportionately more).
    let dead = post / cap;
    score += dead * dead * dead * 3.0;

    // Lookahead: reward bins whose post-residual can still host the next item,
    // penalize near-misses smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 0.35 * (1.0 - (post - nxt) / cap);
        } else {
            let miss = (nxt - post) / cap;
            score += 0.25 * miss * miss;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - progress);
    } else {
        // Mild penalty proportional to number of alternatives (prefer scarce space).
        score += 0.02 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current residuals are large relative to the item (poor fits everywhere).
    let is_new_bin = (bin_residual as u32 == bin_capacity) && post_residual == bin_capacity - item_size;
    if is_new_bin {
        let avg_waste = mean_residual / cap;
        // New bin penalized normally, discounted when open bins are all "full-ish".
        score += 0.6 + 1.5 * (1.0 - avg_waste) * (1.0 - avg_waste);
        // Late in the stream, slightly discourage opening extra bins.
        score += 0.4 * progress;
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= 0.1 * (open_bins_count as f64).sqrt() / (1.0 + cap / res.max(1.0));
    }

    // Smooth interaction: item size vs residual fill level.
    let fill = 1.0 - res / cap;
    score -= 0.15 * (item / cap) * fill * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space below smallest item (1) is worst,
    // but with unknown distribution penalize very small unusable slivers.
    if post_residual > 0 {
        // Fractional fill of the bin after placement (capacity fractions logic).
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 8.0 * fill;

        // Modulo-class penalty: residuals in awkward classes (e.g. 1..9, 51..59)
        // are less reusable across typical size classes.
        let m = post_residual % 50;
        if m < 10 && m > 0 {
            score += 6.0;
        }
        let q = post_residual / 25; // quarter classes: 0,1,2,3
        score -= match q {
            0 => 4.0,        // tiny residual, likely dead space
            1 => -2.0,       // ~25-49 residual: very reusable
            2 => -3.0,       // ~50-74: highly reusable
            _ => -1.0,       // 75-99: large
        };

        // Integer-division threshold on next_item_size vs post_residual:
        // lookahead item fits exactly -> big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 60.0;
            } else if next_item_size <= post_residual {
                // how many of next item could still fit (integer division)
                let k = post_residual / next_item_size.max(1);
                score -= 3.0 * k as f64;
                let rem = post_residual % next_item_size.max(1);
                if rem < 5 && rem > 0 {
                    score += 2.5; // near-exact chain, slight nudge
                }
            } else {
                // next item cannot use this bin's residual at all: penalize
                // leaving residual that nothing planned can consume.
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so we only open when placements are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if no open bin fits well (item large relative to mean residual),
        // relax the penalty: opening fresh may be better.
        if item_size as f64 > mean_residual {
            score -= 14.0;
        }
        // Late in stream, opening a bin is cheaper (fewer future items to place).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
    }

    // Prefer filling bins that are already relatively full (tight packing).
    let pre_fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * pre_fill;

    // Waste relative to mean residual: placing into a below-average residual bin
    // is efficient consolidation.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (< 10, min item size) are pure waste.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        // Gaps in the awkward 11..=20 range are hard to fill later.
        score += 8.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits: item filling most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading further
    // unless the fit is excellent; with few bins, consolidation is fine.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (1.0 - fill_ratio) * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= post_residual + 9 {
        // Next item nearly fits the gap; mild reward.
        score -= 5.0;
    }

    // Mean residual coupling: prefer bins close to the mean residual to keep
    // the bin portfolio balanced (avoids many near-full bins + one huge gap).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate (empty bin): penalize so it is only chosen when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in the stream, opening bins is cheaper.
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer smallest post-residual (tightest fit).

    // Aggressive 2-step lookahead: strongly reward a post_residual that exactly
    // matches the next item size (perfect chained fit).
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        let diff = (pr - ni).abs();
        if diff == 0.0 {
            score -= 40.0; // exact lookahead match: excellent
        } else if diff <= 5.0 {
            score -= 15.0 * (1.0 - diff / 6.0);
        } else {
            // penalize post-residuals that are slightly too small for the next item
            // (dead space the next item can't use)
            if pr < ni && pr > 0.0 {
                score += 4.0 * (1.0 - pr / ni);
            }
        }
    }

    // Relative-to-mean coupling: a bin with residual far above the mean is a
    // "loose" bin; using it for a small item wastes its capacity. Favor bins
    // whose residual is near/below the mean.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap.max(0.0) - 0.05 * (-residual_gap).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; make the empty
    // bin attractive only when the item is large relative to capacity or no
    // good fit exists.
    if bin_residual == bin_capacity {
        // Penalize new bins mildly so existing reasonable fits win.
        score += 10.0;
        // But large items (relative to capacity) justify a fresh bin.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 18.0 * fill_ratio;
        // If the next item also fits into the leftover of a fresh bin, opening
        // now is less costly (lookahead-aware new-bin discount).
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 6.0;
        }
        // Many open bins with slack: discourage yet another bin.
        if open_bins_count > 3 && mean_residual > 30.0 {
            score += 8.0;
        }
    }

    // Late-stream consolidation: near the end, prefer filling existing bins
    // tightly to avoid leaving many half-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below the
    // smallest plausible item (<=10) is worthless, so it counts extra.
    if post_residual < 10 {
        score -= 12.0; // effectively sealed bin: excellent outcome
    } else {
        // Penalize residual that is unlikely to be usable by future items.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * waste * waste;
    }

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, this is a
    // valuable pairing; reward proportionally to how snugly the next item fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 10.0 + 8.0 * snug;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for the next item: mild penalty unless bin is sealed.
        if post_residual >= 10 {
            score += 4.0;
        }
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding: with many open bins, prefer filling existing ones rather than
    // spreading; with few open bins, new-bin candidate is less penalized.
    let crowding = open_bins_count as f64;
    score -= (2.0 * crowding).ln().max(0.0) * 1.5;

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the item fits poorly everywhere else or the stream
    // is early and future capacity is valuable.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // Early in the stream, keep a fresh bin cheap (flexibility for future items).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 14.0 * (1.0 - progress);
        // If open bins are already crowded/fragmented, new bin is fine.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 6.0;
    } else {
        // Existing-bin bonus: using what we have is generally good.
        score -= 3.0;
        // Prefer bins whose residual is close to the mean (keep homogeneity),
        // penalize outliers that create fragmented state.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Time-horizon modulation: late in the stream, consolidation matters more;
    // slightly boost any bin that can absorb the item now.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic coupling of post residual with stream progress.
    // Late in the stream, tight fills matter more (progressive tightening).
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr);

    // Reward using large fraction of the bin (small post_residual) with smooth saturation.
    let fill = 1.0 - norm_pr;
    score -= 0.8 * fill * fill * (1.0 + 0.5 * progress);

    // Penalize dead space: residuals too small for likely future items.
    let dead = if norm_pr > 0.0 && norm_pr < 0.1 { (0.1 - norm_pr) * 10.0 } else { 0.0 };
    score += dead * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count <= 1 {
        score -= 1.5;
    }

    // Lookahead coupling: if next item fits exactly in post residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 0.6 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to leftover.
        score += 0.3 * norm_pr * (1.0 - progress);
    }

    // New-bin candidate handling: empty bin should be chosen only when
    // no good fit exists; make it mediocre by default.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 0.9 - 0.4 * progress;
        // If many bins are open, slightly discourage hoarding new bins.
        score += 0.05 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Coupling with mean residual: prefer bins below mean residual (tighter bins).
        let dev = (mean_residual - bin_residual as f64) / cap;
        score -= 0.4 * dev;
    }

    // Smooth global regularization to keep scores bounded.
    score += 0.1 * norm_item * norm_item;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by 10 (or by 20)
    // align with the common item-size grid and are more reusable.
    let class10 = (post_residual % 10) as f64;
    let class20 = (post_residual % 20) as f64;
    score += class10 * 0.35 + class20 * 0.25;

    // Integer-division thresholds on post_residual: classify leftover space.
    let q = post_residual / 10; // 0..10
    match q {
        0 => score -= 55.0,                 // near-perfect fill (dead space ~0)
        1 => score -= 30.0,                 // very good fill
        2 => score -= 15.0,
        3 => score -= 5.0,
        6 | 7 => score += 8.0,              // awkward mid leftover
        8 => score += 20.0,                 // large leftover: wasted capacity
        9 => score += 30.0,                 // barely used bin
        _ => {}
    }

    // Reward bins that can also host the lookahead item (chaining fits).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // post-residual too small for next item: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    } else {
        // Last item: maximize fill, minimize leftover.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // the item is large (small post_residual) and many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 >= 0.6 * bin_capacity as f64;
        if large_item && open_bins_count > 3 && post_residual >= next_item_size.max(1) {
            score -= 12.0 + 20.0 * progress;
        } else {
            score += 60.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Prefer bins below the mean residual (pack tight bins first, leave
    // roomy bins flexible for future items).
    score += 0.20 * ((post_residual as f64) - mean_residual);

    // Mild tie-break toward earlier-created (tighter) bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any plausible item (>=10)
    // are almost worthless, so penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small gap: only valuable if the lookahead item can use it.
        if next_item_size == 0 || next_item_size > post_residual {
            score += 25.0;
        } else {
            score -= 15.0; // lookahead fits exactly into the leftover gap
        }
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: prefer bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
    }

    // Last-chance pressure: if this is the only bin that fits, using it avoids
    // opening a new bin; but only when the fit is not terrible.
    if fitting_bins_count == 1 && post_residual < item_size as f64 as u32 + 30 {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new
    // partial fills; with few open bins, consolidation is cheaper anyway.
    let pressure = (open_bins_count as f64).ln() * 4.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: an empty bin should only win when no open bin gives a
    // decent fit (i.e. all fits would create big dead space).
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: nothing fits anywhere
        } else if next_item_size > 0 && item_size as f64 > 0.6 * bin_capacity as f64 {
            // Large item: pairing with the next item in a fresh bin can be good.
            if item_size + next_item_size <= bin_capacity {
                score -= 35.0;
            }
        }
    }

    // Slight late-stream tightening: waste matters more as stream nears end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild preference toward bins below-average fullness for balance.
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Reward near matches with lookahead item (tight 2-step fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize creating tiny unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Penalize residuals that no plausible item (1..=100) can use well:
    // dead space that is small relative to capacity.
    if post_residual > 0 && post_residual < item_size {
        score += 5.0;
    }

    // Prefer tighter fits relative to the mean residual of open bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If lookahead matches a fresh bin perfectly (item + next fill a bin), allow it.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 60.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 10.0;
        }
    }

    // Late in the stream, consolidate: slightly favor filling existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.2;

    // With many open bins, discourage spreading; prefer tightest fills.
    if open_bins_count > 4 {
        score += (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only bin that can fit, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits perfectly into the post-residual, reward.
    if next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item could fit here later; penalize wasting this residual now.
            score += 8.0 * (1.0 - gap / bin_capacity as f64);
        }
        if next_item_size == post_residual {
            score -= 35.0; // perfect chaining
        }
    }

    // New-bin candidate handling: penalize opening a new bin, but allow it
    // when the item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // new bin can host the next item too
        }
    }

    // Global state coupling: many open bins with high mean residual
    // suggests fragmentation -> prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * mean_residual * (1.0 - progress) * 0.05;
    score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio);

    // Penalize leaving dead space that no plausible item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post residual, with polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear waste term: penalize residuals that are hard to fill later.
    let x = pr / cap; // normalized post residual
    score += cap * (x * x * x) * (0.5 + 0.5 * progress);

    // Reward tight fits (small post residual) more strongly as stream progresses.
    score -= (1.0 - x) * (1.0 - x) * 10.0 * (0.3 + 0.7 * progress);

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        score += 2.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mild penalty so we prefer existing bins unless fit is bad.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean (balanced use).
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: tight fit reward (small post_residual is good)
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Harmonic class of post_residual: modulo classes on capacity
    let class = post_residual % 20;
    // Class 0 (residual multiple of 20) is highly reusable -> strong reward
    match class {
        0 => score -= 18.0,
        5 => score -= 6.0,
        10 => score -= 12.0,
        15 => score -= 4.0,
        _ => {}
    }

    // Integer division thresholds: small residuals are dead space
    if post_residual <= 10 {
        score += 25.0; // nearly unusable
    } else if post_residual <= 20 {
        score += 10.0;
    } else if post_residual <= 30 {
        score += 3.0;
    }

    // Lookahead coupling: does next item fit exactly / well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect follow-up fill
        } else if next_item_size < post_residual {
            let nxt_class = (post_residual - next_item_size) % 20;
            if nxt_class == 0 {
                score -= 14.0;
            }
            score -= 4.0; // next item fits, mild reward
        } else {
            score += 6.0; // next item won't fit here; residual may become dead
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // options are bad (poor fits / many fitting bins exist).
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        // If several bins fit the item, opening a new bin is rarely worth it
        let crowd = (fitting_bins_count as f64).min(6.0);
        // If this is a large item and mean residual is small, new bin is attractive
        let big_item = (item_size as f64 / cap_f) > 0.6;
        let tight_world = mean_residual < (item_size as f64);
        let mut penalty = base_penalty + crowd * 5.0;
        if big_item && tight_world {
            penalty -= 20.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            penalty -= 10.0; // room for a paired fill in fresh bin
        }
        score += penalty;
    }

    // Mild progression term: late in stream, consolidation matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (or too small to be useful) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward very tight fits (post_residual near zero but not a dead gap).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many bins open, avoid spreading; with few bins,
    // be more tolerant of imperfect fits.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64) * 0.15;

    // Lookahead coupling: if the next item fits the post residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Mean residual alignment: prefer bins close to the mean residual
    // (keeps residual distribution balanced).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.1;

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (large item, poor fits elsewhere, or this item nearly fills a fresh bin).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 || fill_ratio > 0.7 {
            score -= 30.0;
        } else {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: huge reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Item can follow: reward proportional to closeness.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space created.
            score += 0.5 * diff as f64;
        }
        // Chain bonus: post_residual could hold next item split into two parts
        if post_residual >= next_item_size * 2 {
            score -= 5.0;
        }
    }

    // Penalize new-bin opening unless this is a last-chance situation or fit is poor.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin gets a base penalty; relax it when few fitting bins exist or fit is very tight.
        let mut penalty = 25.0;
        if fitting_bins_count <= 1 {
            penalty -= 30.0; // last chance: allow new bin
        }
        if post_residual <= 10 {
            penalty -= 10.0; // near-perfect fit, worth opening
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            penalty -= 8.0; // new bin will also serve next item
        }
        penalty += 10.0 * (1.0 - progress); // early stream: prefer reusing bins
        score += penalty;
    }

    // Last-chance bonus for existing bins: using the only fitting bin avoids a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Relative to mean residual: prefer bins tighter than average (good packing),
    // penalize leaving residual far above mean (fragmentation).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Mild penalty for very small residuals that become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual so small leftovers dominate.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * (1.0 - (-6.0 * tightness).exp());

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that can never fit a plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead coupling: reward bins whose post_residual can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Chain fit: current + next leaves a clean residual
        if post_residual == next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, be pickier: prefer the best fit more strongly.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: when open bins have large mean residual, prefer filling them.
    score -= 0.3 * mean_residual;

    // Time horizon: late in stream, consolidate aggressively into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // New-bin candidate: only attractive if item is huge and residual waste unavoidable.
    if bin_residual == bin_capacity {
        score += 35.0; // default penalty for opening new bin
        let fill_ratio = (item_size as f64) / (bin_capacity as f64);
        if fill_ratio > 0.9 {
            score -= 30.0; // big items deserve a fresh bin
        }
        if next_item_size > 0 && next_item_size >= bin_residual - item_size.min(bin_residual) && next_item_size > 0 && item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild penalty for many open bins already (encourage consolidation).
    score += 0.5 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tighter fits (small post_residual) rewarded non-linearly.
    let fit_ratio = 1.0 - pr / cap; // 0..1, high when tight fit
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later, smoothly.
    let dead = pr / cap;
    if dead > 0.0 {
        score += 8.0 * dead * (1.0 - dead) * (1.0 - dead);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if next item can use the post residual, reward leaving exactly that space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - gap * gap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance fitting: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Stream progress coupling: late in stream, be greedier (prefer tight fits, avoid new bins).
    score -= 6.0 * progress * fit_ratio;

    // Penalize opening a new bin when open bins exist, more so late in the stream.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).min(5.0);
        score += 10.0 + 3.0 * progress + 1.5 * crowding;
        // Allow new bin only if it would be nearly filled by this item.
        let fill = item_size as f64 / cap;
        if fill > 0.8 {
            score -= 14.0 * fill;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic classes on post_residual (modulo 10 buckets):
    // residuals that are multiples of 10 are "clean" and reusable -> reward.
    // Odd/prime-ish tiny residuals tend to become dead space -> penalize.
    if post_residual > 0 {
        let cls = (post_residual % 10) as f64;
        score += match post_residual % 10 {
            0 => -8.0,
            5 => -2.0,
            1 => 6.0,
            7 => 4.0,
            _ => cls * 0.4,
        };
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: leftover too small for anything (min item is ~1,
    // but sub-threshold slivers are rarely usable).
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this bin; scale reward by how snugly the next item nests.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize slightly if we also strand space.
        score += 3.0;
    }

    // Last-chance bin: if this is the only open bin that fits the item,
    // using it avoids opening a new bin -> reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate (bin_residual == bin_capacity):
    // prefer opening a fresh bin when existing fits are scarce or the
    // open-bin pool already has plenty of usable residual space.
    if bin_residual == bin_capacity {
        // Cost of carrying an extra open bin.
        score += open_bins_count as f64 * 0.6;
        // If no other bin can fit the item, a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if fitting_bins_count <= 1 {
            score -= 6.0;
        }
        // If mean residual across open bins is large, reuse them instead.
        score += mean_residual * 0.12;
        // Early in the stream, consolidating is cheaper than sprawling.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 4.0;
        // Exact half-fill new bin is attractive for future pairing.
        if (post_residual as f64 - cap * 0.5).abs() < 1.0 {
            score -= 3.0;
        }
    }

    // Mild penalty for very loose fits (wasting more than half the bin).
    if post_residual > item_size && post_residual > bin_capacity / 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..=10 range guard) are pure waste; penalize them hard.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Reward near-exact fits (small post_residual is good, but with
    // diminishing returns so tiny gaps don't dominate).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // open-bin pressure is high. Make empty bins moderately costly.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If the next item is small, a fresh bin is less appealing since
        // existing residual space likely suffices later.
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score += 15.0;
        }
        // Late in the stream, avoid opening bins that will stay mostly empty.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 20.0 * progress;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit flavor)
    // beyond raw post_residual ordering.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Slight preference for filling bins with larger residuals when many
    // bins are open, to consolidate load.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space for the known next item.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves a new residual: mild reward scaled
            // by how tight the chained fit is.
            let chain_residual = (post_residual - next_item_size) as f64;
            score -= 20.0 - chain_residual * 0.3;
        }
        // If next item is bigger than post_residual, we create dead space
        // relative to the lookahead: penalize proportionally.
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Penalize leaving residuals too small to ever be useful
    // (items are >= 1, but very small slivers are hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Compare against mean residual: filling a bin well below the mean
    // residual (i.e., a large bin) is less valuable than using a tight bin.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + item_size as f64 * 0.1;
    }

    // New empty bin candidate: penalize so it is only chosen when no open
    // bin gives a decent fit; relax penalty late in the stream.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 70.0 - 20.0 * progress;
        // If the item is large relative to capacity, opening fresh is safer.
        if item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Mild preference for consolidating when many bins are open.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scaled waste relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Lookahead: penalize if the next item could have fit in the residual we leave behind.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score += 8.0; // we consumed space the next item needed
        } else if (bin_residual as i64) >= (next_item_size as i64) && (post_residual as i64) < (next_item_size as i64) {
            score -= 3.0; // we block the next item cleanly; mild reward
        }
        // Exact-pair bonus: item + next item fill this bin almost perfectly.
        let pair_waste = (bin_capacity as i64) - (item_size as i64) - (next_item_size as i64);
        if pair_waste >= 0 && (bin_residual as i64) >= (item_size as i64 + next_item_size as i64) {
            score -= 6.0 + pair_waste as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (future items may pair well).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        // If the item is large, a fresh bin gives flexibility.
        score -= 0.05 * item_size as f64;
    } else {
        // Slight preference for bins with residuals below the mean (consolidate small leftovers).
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        } else {
            score += 1.0;
        }
    }

    // Global pressure: when many bins are open, discourage adding more, encourage filling.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 0.5 * open_bins_count as f64 * (1.0 - tightness);
    }

    // Avoid leaving tiny unusable slivers unless the item nearly fills the bin.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }
    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: waste from post residual, with non-linear (quadratic) growth
    let mut score = pr + 18.0 * norm_pr * norm_pr * cap;

    // Smooth stream-progress coupling: late in the stream, waste is costlier
    score *= 1.0 + 0.8 * progress * norm_pr;

    // Reward tight fits (small post residual) with a saturating term
    score -= 25.0 * (-norm_pr * 6.0).exp();

    // Lookahead: if next item fits into post residual, reward this placement smoothly
    let next_fits = (norm_next <= norm_pr) as i32 as f64;
    score -= 14.0 * next_fits * (1.0 - (norm_pr - norm_next).abs());

    // Penalize when post residual is too small for the next item (dead space)
    let next_fits_not = (norm_next > norm_pr) as i32 as f64;
    score += 10.0 * next_fits_not * (norm_next - norm_pr) * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_item);
    }

    // Mild penalty when many bins are open relative to stream length (encourage consolidation)
    score += 2.0 * (open_bins_count as f64) / (total_items.max(1) as f64).sqrt();

    // Pull toward mean residual: prefer bins whose resulting residual is near the mean
    let mean_norm = mean_residual / cap;
    score += 4.0 * (norm_pr - mean_norm).abs();

    // New-bin candidate handling: empty bin gets neutral-to-slightly-high score,
    // only attractive when no good fit exists (large item, poor fits)
    if bin_residual == bin_capacity {
        score = 55.0 + 40.0 * norm_item * (1.0 - progress) - 20.0 * norm_item * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality classes via integer division.
    let class = post_residual / 10;
    // Penalize awkward classes (small unusable slivers) more than linear.
    score += match class {
        0 => 0.0,                       // residual < 10: essentially perfect fill
        1 => 2.0,                       // 10..19: tight but usable
        2 => 4.5,                       // 20..29
        3 => 6.0,                       // 30..39
        4 => 6.5,                       // 40..49
        _ => 8.0,                       // large leftover: wasteful placement
    };

    // Modulo-5 harmonic: residuals divisible by 5 pair better with typical item sizes.
    if post_residual % 5 == 0 {
        score -= 1.5;
    }
    if post_residual % 3 == 0 {
        score -= 0.5;
    }

    // Lookahead coupling: reward if next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize small post residuals (dead space).
            if post_residual < next_item_size && post_residual < 20 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: make it moderately unattractive unless open bins are crowded.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) + 5.0;
        // If few bins can fit the item, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score = 0.0;
        }
        // Late in stream with many open bins, prefer reusing.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.5 && open_bins_count > 4 {
            score += 10.0;
        }
    }

    // Prefer filling bins below the mean residual (denser bins first).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Tie-break: prefer tighter fit (small post residual relative to item size).
    score += (item_size as f64) / (bin_capacity as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Minimum item size seen in stream; treat 10 as conservative floor.
    let min_item = 10u32;

    // Dead-space penalty: post_residual below the smallest possible item
    // is pure waste -> heavy penalty.
    if post_residual < min_item && post_residual > 0 {
        score += 60.0 + (min_item - post_residual) as f64 * 2.0;
    }

    // Quasi-dead space: gap too small for the lookahead item (when known)
    // and unlikely to fit anything useful relative to mean residual.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones,
    // penalize the new-bin candidate more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline high, softened only if it enables a perfect
        // future pairing with the lookahead item.
        score = bin_capacity as f64 + pressure * 2.0;
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 10.0;
        }
    } else {
        score += pressure * 0.3;
    }

    // Slight preference for bins below mean residual (balancing residuals).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near matches: reward post_residual close to next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 / (1.0 + diff);
    }

    // Penalize dead space that is too small for any plausible item (sizes >= 1),
    // but especially below the minimum plausible size (10 in classic regime).
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins that are already well-filled
    // (small residual relative to the mean keeps fragmentation concentrated).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: only attractive when the fit here is terrible.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if bin_residual == bin_capacity {
        // Empty bin baseline: moderate score so it wins only over bad fits.
        score = 55.0 + fit_ratio * 0.0;
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64).abs() < 5 {
            score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 45.0; // no real alternative -> new bin is fine
        }
    } else if fit_ratio < 0.35 && post_residual > 60 {
        // Very poor fill of a large bin: encourage opening a fresh bin instead.
        score += 30.0;
    }

    // Late in the stream, consolidate: avoid leaving many scattered open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score -= 8.0 * progress * (open_bins_count as f64).sqrt().recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is already the base).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward gaps: residuals that can only fit very small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty
    }

    // Lookahead coupling: if the next item fits the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; mild penalty proportional to waste.
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // current fits are poor or the stream is early with few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = fitting_bins_count == 0
            || (fitting_bins_count == 1 && fit_ratio < 0.35);
        if poor_fits {
            score -= 22.0 + 15.0 * (1.0 - progress);
        } else {
            score += 35.0 + 10.0 * open_bins_count as f64;
        }
    }

    // Global state: prefer filling bins with large residuals when mean residual is high.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Prefer bins that are already partially filled (avoid scattering).
    if bin_residual < bin_capacity {
        score -= 8.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;
    let mut score = r;

    // Smooth polynomial coupling: post_residual warped by stream progress
    let warp = 1.0 + 0.8 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score = r * warp;

    // Reward tight fits with a smooth non-linear term
    let tight = 1.0 - norm_r;
    score -= 25.0 * tight * tight * (1.0 + progress);

    // Penalize residual near the awkward zone via smooth bump
    let center = 0.5;
    let width = 0.25;
    let bump = (-((norm_r - center) * (norm_r - center)) / (2.0 * width * width)).exp();
    score += 18.0 * bump;

    // Lookahead: reward bins that can also fit next item (smooth gate)
    if next_item_size > 0 {
        let fits_next = (r >= next_item_size as f64) as f64;
        let closeness = 1.0 - (r - next_item_size as f64).abs() / cap;
        score -= 12.0 * fits_next * closeness * (0.5 + progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Pressure from many open bins: mild penalty scaled by mean residual deviation
    let dev = (mean_residual - r).abs();
    score += 0.05 * open_bins_count as f64 + 0.03 * dev;

    // Late-stream smoothing: encourage consolidation
    score *= 1.0 + 0.1 * progress * (open_bins_count as f64 / 10.0).min(2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "dead" (too small for
    // smallest plausible future item) are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 30.0 + (dead_threshold - post_residual) as f64 * 3.0;
    } else {
        // Reward post_residuals in useful harmonic classes: multiples of 10/20
        // pack well with typical item sizes.
        if post_residual % 20 == 0 {
            score -= 8.0;
        } else if post_residual % 10 == 0 {
            score -= 4.0;
        }
        // Penalize awkward mid-band residues (just below half capacity)
        let half = bin_capacity / 2;
        if post_residual > half && post_residual < half + 15 {
            score += 6.0;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 25.0;
        } else {
            score -= 5.0;
            // reward if next item lands in a good harmonic class too
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here: mild penalty if this residual becomes waste
        if post_residual < 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: it's only attractive when open bins are few
    // or current fits are poor. Penalize it by default via open_bins_count.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        // But if the item is huge (harmonic top class) and few bins exist,
        // opening fresh is fine.
        if item_size > bin_capacity * 3 / 4 && open_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // Progress-scaled tightness: as the stream advances, prefer filling bins
    // tightly (lower post_residual relative to capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / cap) * 10.0;

    // Prefer bins with residuals below the mean (consolidate small spaces).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(30.0) * 0.4;
    } else {
        score += (pr - mean_residual).min(30.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits after this placement: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack.min(60.0);
        } else {
            // Next item won't fit here: penalize leaving a gap that is too small
            // to be useful (dead space) relative to typical item sizes.
            if post_residual < 10 {
                score += 150.0;
            } else {
                score += 20.0;
            }
        }
    }

    // Compare post residual against mean residual: prefer bins that end up
    // tighter than average (concentrate packing into nearly-full bins).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Penalize the new-bin candidate slightly so it is chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 80.0;
    }

    // Early in the stream, allow more bins to open (keeps future flexibility);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post_residual, super-linearly.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving dead space that likely can't fit future items.
    // If next item cannot fit in the post-residual, this placement is risky
    // unless the bin is nearly full anyway.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 12.0;
    } else if next_item_size > 0 {
        // Reward leaving just enough room for the lookahead item.
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible (large post_residual).
    if fitting_bins_count == 1 {
        score -= 30.0;
        // But if the leftover would be tiny dead space, that's still fine.
        if post_residual < 10 {
            score -= 10.0;
        }
    } else {
        // Many alternatives: prefer bins that would become "complete" (residual < 10).
        if post_residual < 10 {
            score -= 15.0;
        }
    }

    // Compare against mean residual: placing into a below-average-residual bin
    // (i.e., fuller bin) preserves large residuals elsewhere for big items.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 6.0 * ((bin_residual as f64) - mean_residual) / (bin_capacity as f64);
    }

    // New-bin candidate: empty bin has bin_residual == bin_capacity.
    // Opening a new bin is attractive only when the item is large and would
    // leave awkward space in any existing bin, or when the stream is early
    // and items are big (likely many large items ahead).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins mildly; stronger when item is small.
        let mut new_bin_score = 25.0 + 0.5 * (100.0 - item_size as f64);
        // Early in the stream with large items, new bins are cheap insurance.
        if item_size >= 60 && progress < 0.3 {
            new_bin_score -= 20.0;
        }
        // If no open bin can fit at all (fitting_bins_count == 0 semantics not
        // distinguishable here), rely on residual: only called for empty bin
        // when alternatives exist too, so keep it moderately high.
        score += new_bin_score;
    }

    // Mild preference for filling bins when many are open (bin-count pressure).
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time-horizon coupling: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = post * (1.0 + 0.9 * fit_ratio * fit_ratio);

    // Reward near-perfect fits more aggressively (quartic coupling)
    score -= 30.0 * (1.0 - fit_ratio).powi(4);

    // Stream-progress coupling: later in the stream, tolerate larger residuals less
    score += 12.0 * progress * fit_ratio * (1.0 - progress).max(0.05);

    // Dead-space penalty: residual too small to matter (below typical item scale)
    let dead = (20.0 - post).max(0.0) / 20.0;
    score += 8.0 * dead * dead;

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 10.0 * (next_item_size as f64 / post.max(1.0));
    } else if next_item_size > 0 {
        score += 5.0 * ((next_item_size as f64 - post) / cap);
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with below-mean residual (denser bins first)
    score += 0.05 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin, scaled by how many bins already fit the item
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        let fit_pressure = (fitting_bins_count as f64).powi(2);
        score += 35.0 + 6.0 * openness + 4.0 * fit_pressure;
        // Allow opening a new bin late in the stream if item is large
        score -= 20.0 * progress * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward small post_residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Harmonic class of post_residual: bins whose residual falls into
    // "usable" classes (multiples of small denominators) are more valuable.
    let pr = post_residual;
    if pr > 0 {
        let mut class_bonus = 0.0;
        if pr % 2 == 0 { class_bonus += 3.0; }
        if pr % 5 == 0 { class_bonus += 4.0; }
        if pr % 10 == 0 { class_bonus += 5.0; }
        if pr % 20 == 0 { class_bonus += 4.0; }
        if pr % 25 == 0 { class_bonus += 3.0; }
        if pr % 50 == 0 { class_bonus += 3.0; }
        score -= class_bonus;
    } else {
        // Perfect fill: strongly favored.
        score -= 60.0;
    }

    // Penalize dead space that no future item can plausibly use.
    // Items are 1..100; residuals below ~10 are nearly dead.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Mid-range awkward residuals (just above common item sizes).
    if pr > 10 && pr < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly prefer this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.2;
        } else {
            // Next item won't fit here; slightly penalize leaving large gap.
            score += (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it
    // unless the fit is tight; otherwise favor using it to keep bin count down.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: brand-new empty bin should only win when open bins
    // offer poor fits. Penalize opening a new bin progressively with stream
    // length and number of open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + open_bins_count as f64 * 2.0 + progress * 10.0;
        // But if mean residual across open bins is too small to fit item,
        // opening new bin becomes attractive: subtract based on mean residual.
        if (mean_residual < item_size as f64) && mean_residual > 0.0 {
            score -= 40.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 10.0; // room for lookahead pairing in fresh bin
        }
    }

    // Mild preference for consolidating into bins with low residual overall.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // plausible future item (min item = 1, but realistically small gaps)
    // are penalized heavily in a non-linear way.
    if post_residual > 0 {
        // dead-space penalty grows sharply as gap shrinks below threshold
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += (10.0 - gap) * 6.0; // unusable sliver -> strong penalty
        } else if gap < 20.0 {
            score += (20.0 - gap) * 2.0;
        }
    } else {
        // perfect fill: big reward
        score -= 40.0;
    }

    // Reward tight fits relative to item size
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, slightly favor consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * 3.0;
    if bin_residual != bin_capacity {
        score -= pressure * (0.5 + 0.5 * progress);
    } else {
        // New-bin candidate: penalize opening bins, more so as stream progresses
        score += 8.0 + 10.0 * progress + pressure;
        // But if next item is large and this item would leave a matching gap,
        // opening a new bin can pair items nicely: mild bonus
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (i.e., nearly full bins) to consolidate filling.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid).min(30.0) * 0.4;
    } else {
        score += (resid - mean_residual).min(30.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly matches post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual as i64 - next_item_size as i64) as f64;
        // Exact match with next item => chain of perfect fills
        if diff == 0.0 {
            score -= 500.0;
        } else {
            // Reward tight fits for the next item; penalize leaving awkward gaps
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: penalize dead space proportionally
        let waste = post_residual as f64;
        score += 0.5 * waste;
        // If leftover is small but unusable, extra penalty
        if waste < next_item_size as f64 && waste <= 10.0 {
            score += 20.0;
        }
    }

    // Prefer tighter bins relative to the mean residual of open bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Mild pressure to consolidate when many bins are open
    score -= 0.1 * open_bins_count as f64;

    // Slight preference for using already-open bins over the new-bin candidate
    if bin_residual < bin_capacity {
        score -= 5.0;
    } else {
        // New empty bin: penalty so it's only chosen when open bins fit poorly
        score += 30.0;
        // Opening a new bin is more acceptable early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 8.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            score += 5.0 + 0.1 * nxt;
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is usually bad unless the fit
    // elsewhere would be terrible or many bins are already open with low residuals.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln() * 4.0;
        let mean_tightness = 1.0 - mean_residual / cap;
        // Penalize new bins, but less when the stream is early or mean residuals are large.
        score += 18.0 + open_pressure - 10.0 * mean_tightness - 8.0 * (1.0 - progress);
        // A new bin is attractive if the item is huge relative to typical residuals.
        if (item_size as f64) > mean_residual {
            score -= 6.0;
        }
    }

    // Mild preference for packing into bins whose residual deviates from the mean
    // (consolidate fragmented space early, use outliers late).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * if progress > 0.5 { 1.0 } else { -0.5 };

    // Slight time drift: later in the stream, prefer tighter packing overall.
    score -= 4.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let coupling = norm_post * norm_post * (1.0 + 3.0 * progress) + norm_post * progress * progress;
    score += 12.0 * coupling;

    // Reward tight fits (small post_residual) more strongly later in the stream.
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize creating dead space that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 {
        let waste = (next_item_size as f64 - post_residual as f64).max(0.0) / bin_capacity as f64;
        score += 10.0 * waste * waste;
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty when bin residual deviates from the mean residual (balance pressure).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 2.0 * dev * dev;

    // Slight penalty for opening new bins when many are already open.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (4.0 + 6.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always excellent.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the post residual relative to capacity.
    // Class 0: post_residual == 0 (handled). Class 1: tiny dead space (bad).
    // Class 2: post_residual is a "nice" fraction of capacity (good, reusable).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize unusable dead space strongly: residuals < 10 can never fit any item.
    if post_residual < 10 {
        score += 500.0;
    } else if post_residual < 20 {
        score += 120.0;
    } else if post_residual < 30 {
        score += 40.0;
    }

    // Reward residuals that are "harmonic" fractions of capacity (25, 50, 75, etc.)
    // since future items drawn from many distributions align with them.
    let harmonic_bonus = if post_residual % 25 == 0 {
        60.0
    } else if post_residual % 10 == 0 {
        35.0
    } else if post_residual % 5 == 0 {
        15.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement sets up a perfect fit — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits; small post_residual after that is fine
            let npr = post_residual - next_item_size;
            score -= (npr as f64) * 0.5;
            if npr < 10 {
                score += 60.0; // but leaves dead space after next
            }
        } else {
            // next item won't fit here; a larger residual is more valuable
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 150.0;
        if post_residual < 10 {
            score += 250.0; // unless it creates dead space anyway
        }
    }

    // New-bin candidate handling: bin_residual == bin_capacity means empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: only worth it when existing bins fit poorly.
        score += 200.0;
        // Scale new-bin cost by stream progress: early on, prefer consolidating;
        // late in the stream, opening fresh bins is safer for large future items.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 80.0;
        // If many bins are open with slack, discourage another one.
        score += (open_bins_count as f64) * 4.0;
        // If mean residual across open bins is small, new bin is more attractive.
        score -= (mean_residual.max(0.0)).min(100.0) * 1.5;
        // Big items: opening a fresh bin for a large item is natural.
        if item_size > 50 {
            score -= 60.0;
        }
        // Lookahead: if next item is large and this item is large, a fresh bin
        // preserves flexibility.
        if next_item_size > 50 && item_size > 50 {
            score -= 40.0;
        }
    } else {
        // Mild preference for tighter existing bins (best-fit flavor already in
        // the base post_residual term); add small penalty for very loose fits.
        let waste_ratio = pr / (bin_residual as f64).max(1.0);
        score += waste_ratio * 20.0;
        // Prefer bins whose residual is close to item size (tight packing).
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.1;
    }

    // Slight global pressure to keep the number of open bins low.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // minimum plausible item are "dead". Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 45.0; // perfect fill: strongly reward
    }

    // Moderate dead space (small but potentially usable) gets graded penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward tightness relative to bin capacity.
    score -= 0.6 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.9 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when this bin would leave
    // a large dead gap and the next item is small enough to use a fresh bin.
    if bin_residual == bin_capacity {
        let tight_here = post_residual == 0 || post_residual >= item_size;
        if post_residual < 10 || (!tight_here && next_item_size > post_residual && next_item_size > 0) {
            score -= 18.0; // opening fresh bin is better than trapping space
        } else {
            score += 30.0; // prefer existing bins with decent fits
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item can't use this gap -> mild penalty
    }

    // Early stream: be slightly more conservative with open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * (1.0 - progress);

    // Mean residual coupling: bins far below mean residual are underfilled.
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual as i64 - next_item_size as i64) as f64;
        // Perfect next-item match is a huge win; degrade smoothly with mismatch
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).powi(3);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here: mild penalty scaled by how far off we are
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Penalize unusable dead space (very small post_residual that likely fits nothing)
    if post_residual < 10 {
        score += 18.0;
    }

    // Reward tight fits relative to the mean residual of open bins
    if (post_residual as f64) < mean_residual {
        score -= 8.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 4.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage opening a new bin when open bins give a decent fit
    if bin_residual == bin_capacity {
        score += 20.0;
        // But allow a new bin if current fit is very poor (large dead space left)
        if post_residual < 10 {
            score -= 30.0;
        }
        // Late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: strongly reward closing a bin completely.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead (k=2): reward leaving room for the next item, penalize dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // Chainable residual: the space left is still usable.
            score -= 8.0 + 0.06 * pr;
        } else if pr > 0.0 {
            // Dead space: too small for the next item; penalize proportionally.
            score += 5.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: if this is the only open bin that fits, using it
    // avoids opening a new bin. Strong reward (unless it's the fresh-bin candidate).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Brand-new empty bin candidate: default penalty so we prefer existing bins,
    // but relax the penalty late in the stream (consolidation phase).
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * t;
    }

    // Mild attraction toward bins with above-average residual (use fuller bins first).
    score -= 0.08 * (bin_residual as f64 - mean_residual);

    // When many bins are open, prefer placements that leave small residuals
    // to consolidate the open-bin population.
    score += 0.25 * (open_bins_count as f64) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_norm = item_size as f64 / cap;
    let res_norm = bin_residual as f64 / cap;

    // Base: penalize wasted post residual, non-linearly (dead space grows worse quadratically).
    let mut score = pr + 8.0 * (pr / cap).powi(2) * cap;

    // Smooth coupling: tight fits (small post_residual relative to item) are rewarded.
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * fit_norm * cap;

    // Stream-progress coupling: early on, prefer filling bins loosely (keep flexibility);
    // later, squeeze residual space harder via a smooth polynomial weight.
    let urgency = progress * progress * (3.0 - 2.0 * progress);
    score -= urgency * pr * 0.6;
    score += (1.0 - urgency) * pr * 0.15;

    // Lookahead coupling: if next item fits into post_residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack) * (nx / cap);
        } else {
            // Next item won't fit here: mildly penalize leaving a tempting-but-useless gap.
            score += 3.0 * (pr / cap) * (nx / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 10.0 + 5.0 * (1.0 - fit_norm);
    }

    // New-bin candidate handling: it is only attractive when the item leaves a very
    // clean residual there (e.g., near-perfect fill) or existing fits are terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying with stream progress and open-bin load.
        let mut new_bin_score = 18.0 * (1.0 - urgency) + 4.0;
        // Reward a fresh bin when the item fills it almost exactly (smooth term).
        new_bin_score -= 14.0 * (fit_norm * fit_norm);
        // Penalize new bins when mean residual of open bins is already large.
        new_bin_score += 0.05 * mean_residual;
        // Late in the stream, prefer consolidating into open bins.
        new_bin_score += 10.0 * urgency;
        score = new_bin_score;
    } else {
        // Mild penalty if many bins are open and this one is only loosely related to mean state.
        score += 0.02 * ((bin_residual as f64) - mean_residual).abs() * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" modulo classes are still useful; large awkward chunks are dead space.
    let pr = post_residual;
    let class = pr % 10; // decimal harmonic class
    let dead_penalty = match pr {
        0 => -40.0,                     // perfect fit: strongly reward
        1..=5 => -18.0,                 // near-perfect: still excellent
        6..=10 => -8.0,                 // good
        11..=20 => 0.0,                 // neutral
        21..=49 => (pr as f64) * 0.25,  // growing waste
        _ => (pr as f64) * 0.35,        // big chunk: heavy penalty
    };
    score += dead_penalty;

    // Class-based micro-adjustment: residuals congruent to small mod-10 classes
    // pair well with typical item sizes (multiples of 10 dominate many streams).
    if class <= 2 && pr > 0 {
        score -= 4.0;
    } else if class >= 8 && pr < bin_capacity {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily; if it cannot fit, mildly penalize (bin becomes dead after this).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            score += 5.0;
        }
    } else {
        // Last item: only perfect fits matter.
        score += (pr as f64) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large (poor fit anywhere) or the stream is early (many items to come).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        let pressure = (mean_residual - item_size as f64).max(0.0) / cap;
        let new_bin_bonus = 30.0 * item_frac * (1.0 - progress) + 12.0 * pressure;
        score += 55.0 - new_bin_bonus; // base handicap so open bins win by default
    }

    // Spread-aware adjustment: when mean residual is high, prefer filling the
    // emptiest bins (post residual small relative to mean).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Mild coupling with occupancy: more open bins -> tighter packing preferred.
    score += (open_bins_count as f64) * (post_residual as f64 / cap) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    } else {
        // Larger usable gaps get a mild reward for being flexible.
        score -= 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    }

    // Mean-residual coupling: if this bin is far below average residual, it's tighter than the rest -> prefer it.
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: only attractive when it can absorb future items well
    // (i.e., current item is small relative to capacity and few bins are open).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let phase = step_index as f64 / total_items.max(1) as f64;
        if fill_ratio > 0.6 || (open_bins_count > 0 && fill_ratio < 0.35) {
            score += 80.0; // avoid opening new bin for big items or when existing bins barely used
        } else {
            score += 20.0 - 15.0 * (1.0 - phase);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post residual, or at least fits comfortably into it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt == post {
            score -= 80.0; // perfect chained fit
        } else if nxt < post {
            let slack = post - nxt;
            if slack <= 5.0 {
                score -= 45.0;
            } else {
                score -= 20.0 * (1.0 - slack / 100.0);
            }
        } else {
            // Next item cannot fit: post residual becomes dead space risk.
            score += 15.0 + (nxt - post) / 10.0;
        }
    } else {
        // Last item: only the immediate fit matters; reward tight fits hard.
        score -= 30.0;
    }

    // Compare against mean residual across open bins:
    // prefer bins with residual below average (tighter bins get emptied first),
    // penalize dipping into unusually roomy bins for small items.
    if (bin_residual as f64) > mean_residual + 20.0 && item_size < 40 {
        score += 10.0;
    } else if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: keep it unattractive unless the current item is large
    // and no tight fit exists (score naturally high via post_residual == capacity).
    if bin_residual == bin_capacity {
        score += 40.0;
        // If the item is huge, a fresh bin is actually reasonable.
        if item_size >= 70 {
            score -= 45.0;
        }
    }

    // Slight late-stream conservatism: consolidate more as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64 / bin_residual as f64).max(0.0);
    score -= 8.0 * tightness * (item_size as f64);

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves a gap: mild reward proportional to fill.
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item will NOT fit: penalize small dead space more.
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 0.35 * (waste.max(0.0));
            }
        }
    } else {
        // Last item: any residual is pure waste; prefer max fill.
        score += 0.5 * post_residual as f64;
    }

    // Last chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly,
        // i.e., post_residual here is small relative to what open bins offer.
        // Base cost of a fresh bin:
        score += 45.0;
        // More open bins with slack => discourage new bins.
        score += 1.5 * open_bins_count as f64;
        // High mean residual => plenty of room already; discourage new bin.
        score += 0.4 * mean_residual;
        // But if the current item is large and post_residual would be tiny,
        // a fresh bin is actually a great full placement.
        if post_residual <= 10 {
            score -= 40.0;
        }
        // Early in the stream, allow more bins (future items may pair with the rest).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // If next item is large, a fresh bin with big post_residual can host it.
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 10.0;
        }
    } else {
        // Existing bin: prefer bins whose post_residual remains useful for typical items.
        // Penalize leaving residuals in the awkward 1..10 range (hard to fill).
        if post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        // Prefer keeping residuals that common next items can use.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
        // Slight preference to spread load when many bins are open.
        if (post_residual as f64) > mean_residual {
            score += 0.1 * (post_residual as f64 - mean_residual);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    // Early in the stream, tolerate slack; late, demand tight packing.
    let tightness = 1.0 + 2.5 * progress * progress;
    score += (post / cap) * (post / cap) * cap * 0.5 * tightness;

    // Reward using most of the bin (low post_residual) with a smooth cubic reward.
    score -= (1.0 - post / cap).powi(3) * 12.0;

    // Penalize creating dead space that is too small for typical future items,
    // smoothly varying with progress.
    let dead_zone = (post / cap - 0.25).powi(2);
    score += dead_zone * 8.0 * (0.5 + progress);

    // Last-chance bonus: strongly favor this bin if it is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 * (1.0 - progress * 0.5);
    }

    // Penalize opening a new bin, more so as the stream progresses.
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress;
    }

    // Mild penalty when many bins are open relative to progress (encourages consolidation).
    score += open_bins_count as f64 * 0.15 * (0.5 + progress);

    // Discourage placements far from the mean residual (smooth dispersion penalty).
    score += ((post - mean_residual) / cap).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward near-perfect fits (class 0 of small moduli),
    // penalize awkward dead space classes.
    let pr = post_residual as i64;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // modulo classes: 0 mod 10 = "harmonic" leftover that pairs well with small items
        let m10 = pr % 10;
        let m25 = pr % 25;
        if m10 == 0 { score -= 8.0; }
        if m25 == 0 { score -= 6.0; }
        if m10 == 5 { score += 4.0; }
        // dead space: residual too small to ever fit another item (min size 1..10 typical)
        if pr < 10 {
            score += 25.0 - pr as f64 * 2.0; // unusable sliver penalty
        }
    }

    // Lookahead harmony: does the next item fit in the resulting residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 5.0; // next item won't reuse this bin
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Crowding: when many bins are open, prefer consolidating into tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (open_bins_count as f64).ln() * 0.8 * (1.0 - progress * 0.5);

    // Pull toward the mean residual: prefer bins with less remaining space than average
    // (best-fit flavor), scaled by how tight the bin currently is.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: residual == capacity. Score it as the waste it would create,
    // with a mild discount early in the stream or when no bin fits decently.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste;
        // allow new bins more readily early on
        score -= 15.0 * (1.0 - progress);
        // if this bin is the only candidate, opening new is fine
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        // penalize opening bins for tiny items (huge waste class)
        if item_size < 30 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste; punish them quadratically.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 12.0;
    }
    // "Awkward zone": residuals in [10, 30) only fit small items; penalize
    // proportionally so near-full packing is preferred over leaving gaps.
    else if post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (post_residual small relative to capacity).
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 25.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling: an empty bin should only win when the
    // item fits poorly everywhere else. Give it a moderate baseline so
    // decent fits into open bins always beat it.
    if bin_residual == bin_capacity {
        score += 70.0;
        // Early in the stream, opening bins is cheaper; relax the penalty.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 30.0;
        // Large next item makes a fresh bin more attractive for pairing.
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, reward this placement strongly (perfect pairing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates
    // favorably from the mean (consolidate space into fewer bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64);
        // Exact 2-chain fit: strong reward
        if post_residual == next_item_size {
            score -= 250.0;
        }
    }

    // Penalize large dead space relative to mean residual (wasted capacity)
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.8 * (pr - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - pr);
    }

    // Dead space threshold: residuals too small to fit anything (min item = 1)
    if pr > 0 && pr < 10.0 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 180.0;
        // But if lookahead chains perfectly into a fresh bin, ease the penalty
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 200.0;
        }
    }

    // Early stream: be slightly more conservative with bin openings
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness * tightness).max(0.0);

    // Penalize creating dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    // Lookahead coupling: perfect post-residual match for next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; slight penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: discourage spreading; prefer filling existing ones.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.5 * crowding;

    // Time-horizon effect: early on, keep bins flexible (avoid near-full);
    // late in stream, prioritize consolidation aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when existing bins are all poor fits.
    if bin_residual == bin_capacity && bin_capacity == 100 {
        // Neutral baseline plus cost of opening a new bin,
        // waived when current bin would leave a very large gap.
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if gap_ratio > 0.5 {
            score -= 35.0; // this placement wastes half a bin; prefer new bin
        } else {
            score += 12.0;
        }
    }

    // Mild preference for bins with residual close to item (best-fit flavor).
    let pre_fit = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * pre_fit;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / c;
    let norm_item = item_size as f64 / c;
    let norm_next = next_item_size as f64 / c;

    // Base: prefer small post-residual, with a smooth polynomial shaping term
    let mut score = pr as f64;
    let poly = norm_pr * (1.0 - norm_pr) * 4.0; // peaks at half-full residual
    score += 30.0 * poly * poly;

    // Reward tight fits (low post-residual) more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 40.0 * progress * tightness * tightness;

    // Dead-space penalty: residuals too small for the typical next item
    if next_item_size > 0 {
        let waste = (norm_next - norm_pr).max(0.0);
        score += 25.0 * waste * waste;
        // Bonus if next item exactly fits the post-residual
        let gap = (pr - next_item_size as f64).abs() / c;
        score -= 15.0 * (-gap * 10.0).exp() * progress;
    } else {
        // End of stream: strongly minimize leftover space
        score -= 20.0 * tightness * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 50.0 + 30.0 * progress;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    let dev = (bin_residual as f64 - mean_residual).abs() / c;
    score += 8.0 * dev * (open_bins_count as f64 / (open_bins_count as f64 + 10.0));

    // Discard nearly-full bins early in the stream (keep flexibility)
    score += 12.0 * (1.0 - progress) * norm_pr * norm_pr;

    // New-bin candidate: penalize opening a bin unless current bin would leave large waste
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * (1.0 - tightness) * progress;
        if fitting_bins_count == 0 { score -= 100.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible into coarse classes.
    // Small leftovers (dead space) are penalized super-linearly.
    if post_residual == 0 {
        // Perfect fit — heavily reward.
        score -= 200.0;
    } else {
        let pr = post_residual;
        // Class boundaries via integer division on capacity fractions.
        let cls = pr / 10; // 0..=9 harmonic class
        match cls {
            0 => score -= 60.0,          // 1..9: nearly perfect, very usable
            1 => score -= 30.0,          // 10..19
            2 => score -= 10.0,          // 20..29
            3 => score -= 2.0,           // 30..39
            4 => score += 0.0,           // 40..49 neutral
            5 => score += 5.0,           // 50..59: half-empty bin
            _ => score += 15.0,          // 60+: large waste
        }
        // Dead-space penalty: leftover smaller than the minimum plausible item (1..100 unknown,
        // use small threshold) that nothing typical can fill.
        if pr < 10 {
            score += 40.0; // unusable sliver
        }
    }

    // Lookahead coupling: reward if the next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot class.
            let over = next_item_size - post_residual;
            score += (over / 20) as f64 * 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: mild, so it beats only bad fits (large post_residual).
        score = 55.0 + post_residual as f64 * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A new bin always fits the next item too; small bonus.
            score -= 5.0;
        }
    }

    // Stream progression: later in the stream, be more conservative about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // Crowding: with many open bins, prefer tightening existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean residual context: if the average bin is loose, prefer tight placements.
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are useless.
    let min_item = 1.0f64;
    let dead_threshold = 10.0f64; // typical smallest item; small gaps are likely dead
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: fraction of residual consumed
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Penalize leaving a gap that next item cannot use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation (higher post_residual penalty)
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 2.0;

    // Prefer bins with residual below mean (fill fuller bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin, reduced when current bin fit is poor
        let poor_fit = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
        score += 45.0 - poor_fit * 20.0;
        // late in stream, opening a fresh bin is cheaper than scattering
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // Next item fits exactly afterwards: bonus scaled by tightness.
            score -= 400.0 / (1.0 + diff / 10.0);
        } else {
            // Next item would not fit here: penalize leaving a tempting-but-too-small gap.
            score += 60.0 * (1.0 - diff / (bin_capacity as f64));
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 50.0 * (0.5 - rel);
        } else if rel > 1.5 {
            score += 30.0 * (rel - 1.5);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize creating large dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Mild preference for filling bins more as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty when many bins are open: encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Penalize dead space: residuals too small for any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item cannot use leftover space; penalize wasted remainder
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless fits are terrible
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin still useful for lookahead
        }
    }

    // Global state: many open bins -> prefer consolidating into existing ones
    score += mean_residual * 0.05;
    score -= open_bins_count as f64 * 0.3;

    // Time horizon: late in the stream, be more conservative (favor tight existing fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: prefer tight fits (small post_residual), with mild non-linear shaping.
    let mut score = post + 0.15 * (post / cap) * post;

    // Reward using the bin when the NEXT item can also fit into the resulting
    // post_residual (lookahead synergy), smoothly scaled by lookahead size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let synergy = (nxt / cap) * (1.0 - post / cap);
            score -= 6.0 * synergy;
        } else {
            // Post-residual too small for the next item: penalize dead space,
            // more strongly for large wasted fractions.
            let waste = (nxt - post) / cap;
            score += 8.0 * waste * waste;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count <= 1 && !is_new_bin {
        score -= 12.0;
    }

    // Mean-residual coupling: if this bin's residual deviates badly from the
    // mean, apply a smooth quadratic penalty to encourage balanced packing.
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate handling: penalize opening a new bin, with a smooth
    // penalty that decays with progress and grows with the residual it leaves.
    if is_new_bin {
        let residual_frac = post / cap;
        let pressure = 1.0 - (fitting_bins_count.max(1) as f64).recip().sqrt();
        let penalty = 18.0
            + 10.0 * residual_frac * residual_frac
            + 14.0 * (1.0 - progress) * pressure;
        score += penalty;
        // If no open bin fits, opening is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 22.0;
        }
    } else {
        // Mild preference for reusing bins early in the stream.
        score -= 3.0 * (1.0 - progress) * (item_size as f64 / cap);
    }

    // Open-bin count pressure: many open bins -> favor consolidation.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction buckets. Leftovers in "dead" classes (too small for
    // typical items) are penalized; leftovers in "usable" classes are rewarded.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let dead_zone = post_residual < eighth as u32;
    let sweet_zone = post_residual >= eighth as u32 && post_residual <= quarter as u32;

    if dead_zone {
        score += 12.0; // nearly-unusable sliver
    } else if sweet_zone {
        score -= 6.0; // leftover that can still host a mid-size item
    }

    // Integer-division harmonic class: post_residual mod (capacity/16)
    // measures how "aligned" the leftover is with common item granularity.
    let grain = (bin_capacity / 16).max(1) as u32;
    let misalignment = post_residual % grain;
    score += misalignment as f64 * 0.35;

    // Lookahead coupling: if the next item fits into the post-residual,
    // strongly favor this bin (chaining two items).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Perfect chain: next item exactly fills the leftover
        if next_item_size == post_residual {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; leftover likely becomes dead space
        score += (post_residual as f64) * 0.25;
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate detection: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is wasteful when other bins fit; penalize it
        // proportionally to how many alternatives exist and how good the
        // mean residual is.
        if fitting_bins_count > 0 {
            score += 25.0 + 5.0 * (open_bins_count as f64).min(10.0);
        }
        // But allow a new bin if the item is huge relative to capacity and
        // would leave a very tight squeeze elsewhere (post_residual tiny).
        if post_residual == 0 {
            score -= 30.0; // perfect fill anywhere is great; new bin fine
        }
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Perfect fill is always the best outcome.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Mild preference to spread load when many bins are open with slack.
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (0..=15) are nearly unusable
    // for future items (min item 10, typically larger). Penalize them hard,
    // but a residual of exactly 0 is perfect.
    if post_residual > 0 && post_residual <= 15 {
        score += 45.0;
    } else if post_residual > 15 && post_residual <= 25 {
        score += 18.0;
    } else if post_residual > 25 && post_residual <= 40 {
        score -= 6.0; // medium gaps still usable for small items
    } else if post_residual > 40 {
        score -= 10.0; // large residual keeps the bin flexible
    }

    // Reward very tight fits (post_residual below the smallest item).
    if post_residual < 10 {
        score -= 30.0;
    }

    // Last chance: if this is the only bin that fits, prefer it strongly
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into fresh bins; with few open bins, allow opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when open bins are few,
        // penalized when many bins are already open.
        score += 12.0 + 8.0 * pressure;
        // If no open bin fits (fitting count reflects only this candidate),
        // opening a new bin is the only real option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Filling an existing bin reduces fragmentation slightly.
        score -= 4.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly (chaining placements).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight bonus for using this bin now.
        score -= 3.0;
    }

    // Mean-residual coupling: if this bin is below average residual,
    // it is the "driest" bin — prefer draining it to consolidate bins.
    let residual = bin_residual as f64;
    if residual < mean_residual {
        score -= (mean_residual - residual) * 0.4;
    } else {
        score += (residual - mean_residual) * 0.2;
    }

    // Late in the stream, tighten up: avoid any waste at all.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step lookahead match:
    // post_residual exactly equals the next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial credit: next item fits with little slack left afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space that the next item cannot use at all.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Make the brand-new empty bin slightly unattractive unless it is the only option.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
        // But a new bin is fine if the current item is huge relative to residual needs
        // and nothing else fits well (post_residual small means good fill).
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    // Late in the stream, consolidate: prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Exact or near-exact fill is gold.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 55.0;
        // If decent fits exist elsewhere, penalize more.
        if fitting_bins_count > 0 {
            let best_possible = post_residual as f64; // post_residual == 100 - item
            // If an open bin could leave less dead space than a fresh bin, avoid new bin.
            score += 20.0 * (1.0 - best_possible / bin_capacity as f64);
        }
        // Late in the stream, opening new bins is cheap (few future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * progress;
        // Many open bins: avoid adding more fragmentation.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Using an existing bin reduces fragmentation; reward it.
        score -= 5.0;
        // Reward bins whose residual is far below mean (consolidating scarce space usage).
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Lookahead: if next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here anyway; slight penalty for leaving large gap.
            score += 0.02 * post_residual as f64;
        }
    } else {
        // Last item: any placement works; prefer filling existing bins.
        if !is_new_bin {
            score -= 50.0;
        }
    }

    // Time horizon: early in stream, keep residuals flexible (avoid tiny residuals
    // that can't host future items); late in stream, prioritize filling tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.5 && post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - 2.0 * progress);
    }

    // Mild preference for bins with larger residual among equals (use fullest bins first
    // is captured by small post_residual already); tie-break with residual.
    score += 0.001 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    let mut score = norm_pr * (1.0 + 0.8 * progress) + 0.6 * norm_pr * norm_pr;

    // Dead-space penalty: residuals too small for any plausible item (min size 1, but typical items larger).
    let dead_threshold = 0.05 * cap;
    if pr > 0.0 && pr < dead_threshold {
        score += 2.0 * (dead_threshold - pr) / cap;
    }

    // Lookahead: reward if next item fits snugly into the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 0.9 * snug * (1.0 - progress);
        } else {
            // Next item won't fit here: slight penalty proportional to overflow gap.
            score += 0.3 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.5 + 0.5 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so when other bins fit.
    if bin_residual == bin_capacity {
        score += 1.2 + 0.4 * (open_bins_count as f64).ln1p();
        if fitting_bins_count > 0 {
            score += 0.8;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 0.5 * progress;
    }

    // Mild preference for bins below mean residual (balance load across open bins).
    score += 0.15 * (pr - mean_residual) / cap;

    // Tiny tie-break favoring fuller bins.
    score -= 0.01 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue
    // classes modulo a small quantum. Residuals in "useful" classes (that a
    // typical next item could still fill) get a subtraction; unusable
    // tiny residuals get penalized.
    let q = 10u32;
    let class = post_residual / q; // integer division threshold class
    match class {
        0 => score += 25.0,           // 0..9 : nearly dead space, bad
        1 => score -= 2.0,            // 10..19: fits small items, ok
        2 => score -= 6.0,            // 20..29: good target zone
        3 => score -= 8.0,            // 30..39: sweet spot
        4 => score -= 5.0,            // 40..49
        5 => score -= 2.0,            // 50..59
        _ => score -= 1.0,            // large residual: bin barely used
    }

    // Coupling with lookahead: if the next item exactly fits the post
    // residual, strongly reward this bin (perfect chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // harmonic classes of chained slack
            if slack < 10 {
                score -= 12.0;
            } else if slack < 20 {
                score -= 8.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by
            // how far off it is
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 * 0.75 + 20.0;
        // more attractive late in the stream when open bins are fragmented
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // if many open bins exist, opening yet another is worse early on
        score += open_bins_count as f64 * 1.5;
    }

    // Prefer packing into bins whose residual is below the mean (tightening
    // nearly-full bins first).
    let mean_diff = mean_residual - bin_residual as f64;
    score += mean_diff * 0.3;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical items (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 18.0 * tightness;

    // Penalize when this bin is the only fitting bin and post residual is dead space
    if fitting_bins_count == 1 {
        score -= 8.0;
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Open bins pressure: discourage opening new bins when many bins open
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * (open_bins_count as f64).sqrt();
        // but if next item is large and this bin would leave bad gap, allow
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 3.0;
        }
    } else {
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.15 * (mean_residual - post_residual as f64);

    // Late stream: prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a bin unless it is unavoidable or clearly better.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 25.0 + 5.0 * fitting_bins_count as f64 };
        score += 40.0 + pressure;
    } else {
        // Last-chance bonus: strongly favor using the only bin that fits.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // 2-step lookahead: reward when post_residual matches the next item exactly.
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).abs();
            if gap == 0 {
                score -= 45.0; // perfect chain fit
            } else {
                score += gap as f64 * 0.6; // penalize mismatched leftover vs next need
                // soft reward if next item still fits after this placement
                if next_item_size <= post_residual {
                    score -= 8.0;
                }
            }
        }

        // Penalize creating small unusable dead space (waste < typical min item).
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }

        // Tie-break toward bins with residuals below mean (pack tight bins first).
        score += (mean_residual - bin_residual as f64) * 0.15;

        // Mild pressure to consolidate when many bins are open.
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 40.0;

    // Reward exact fill strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize dead space that is too small for the minimum item size (1..100 unknown,
    // but typical streams have small items; penalize residuals below a soft threshold).
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let next_leftover = post_residual as f64 - next_item_size as f64;
            score += next_leftover * 0.8;
        } else {
            // Next item won't fit here; slight penalty for wasting large residual.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: empty bin should generally lose unless all open fits are bad.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened frivolously.
        score += 35.0;
        // But if the current item is large relative to mean residual of open bins,
        // opening fresh may be reasonable — soften the penalty.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 15.0 * (frac - 0.5) * 2.0;
        }
        // Early in the stream, having few bins open makes a new bin cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins with residual near mean (avoid fragmenting).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Prefer bins whose residual is close to item size (minimize slack directly).
    let slack = (bin_residual as f64 - item_size as f64);
    score += slack * 0.35;

    // Slight preference for reusing bins over creating new ones as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_res = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: quadratic waste term, amplified with progress
    score += (norm_res * norm_res) * bin_capacity as f64 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    } else if fitting_bins_count > 2 {
        // Many alternatives: penalize slightly to encourage spreading
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Lookahead coupling: reward if the post-residual can host the next item
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let fit_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 10.0 + 15.0 * fit_quality;
    }

    // New-bin candidate: penalize opening a bin unless residuals elsewhere are tight
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 25.0 + 50.0 * pressure * (1.0 - progress);
        if fitting_bins_count == 1 {
            score -= 70.0; // still allow escape hatch when it's the only option
        }
    }

    // Mild preference for filling bins that are already small relative to mean
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Class A: perfect fit (post_residual == 0) -> massive reward
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Class B: dead space — post_residual too small for ANY future item (min size 1..10 band).
    // Anything below 10 is likely unusable; below 5 is almost certainly waste.
    if post_residual < 10 {
        score -= 60.0; // closing the bin tightly is good; waste is "locked in" harmlessly
        if post_residual < 5 {
            score -= 40.0;
        }
    } else if post_residual < 20 {
        // Small pocket: only usable by tiny items; mildly penalize
        score += 15.0;
    }

    // Class C: harmonic match — next item exactly fills the remainder.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chain of perfect fits
        } else if post_residual >= next_item_size {
            // Next item fits here too: residual remains "productive"
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item CANNOT use this leftover: leftover risks becoming dead space
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 2.0;
            // Harsh if leftover is in the awkward 10..30 harmonic band
            if post_residual >= 10 && post_residual < 30 {
                score += gap * 1.5;
            }
        }

        // Modulo-class coupling: if post_residual and next_item_size share a
        // divisor class w.r.t. capacity (e.g., both multiples of 25), future
        // tiling is more likely — reward.
        let cap = bin_capacity as u32;
        for &d in &[25u32, 20u32, 10u32] {
            if post_residual % d == 0 && next_item_size % d == 0 && next_item_size <= post_residual {
                score -= d as f64 * 0.3;
                break;
            }
        }
    }

    // Class D: integer-division threshold on residual fraction of capacity.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    // Prefer placing into bins that are already substantially filled.
    let quarters = (fill_ratio * 4.0).floor() as i32; // 0..3
    score -= quarters as f64 * 8.0;

    // Class E: last-chance bin — if this is the only bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; waived when no open bin fits.
        let mut penalty = 180.0;
        if fitting_bins_count == 0 {
            penalty = -50.0; // forced: no alternative
        } else if next_item_size > 0 && next_item_size >= bin_residual {
            // Next item could go in the fresh bin: opening may still be wise
            penalty -= 40.0;
        }
        // Late in the stream, avoid inflating bin count
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += progress * 60.0;
        score += penalty;
    }

    // Mild dispersion term: prefer bins whose residual is far from the mean
    // (consolidates waste into few bins, keeps others tight).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Small nudge toward tighter fits overall
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that can never fit even the
    // smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 {
        let dead_threshold = 20u32; // gaps <= 20 are nearly unusable
        if post_residual <= dead_threshold {
            score += (dead_threshold - post_residual + 1) as f64 * 6.0;
        }
        // Mid-size gaps: mild quadratic penalty to prefer even packing.
        score += (post_residual as f64) * (post_residual as f64) * 0.01;
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty per competing bin: prefer bins with tighter fits,
        // tie-break by residual ordering is already in base score.
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // Open-bin pressure: when many bins are open, discourage opening more;
    // when few bins are open, opening is cheaper.
    let open_pressure = (open_bins_count as f64).ln() * 2.0;
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base cost plus pressure.
        score += 15.0 + open_pressure;
        // Early in the stream, new bins are acceptable; late, they are costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // If next item is large and no open bin likely fits both, opening
        // fresh can still be reasonable: small discount.
        if next_item_size > item_size && next_item_size >= bin_residual.saturating_sub(item_size) {
            score -= 5.0;
        }
    } else {
        // Reward using existing bins, scaled by how full the bin already is.
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fill_ratio * 12.0;
        // Mean residual coupling: if this bin's residual is far below the
        // mean, it is a tight-fit candidate -> reward.
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= dev * 0.3;
        } else {
            score += (-dev) * 0.1;
        }
    }

    // Lookahead: if post_residual exactly fits the next item, big reward
    // (chains two items perfectly).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 20 {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Next item cannot use the gap; slight extra penalty.
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space minimization).
    let pr = post_residual as f64;
    score -= (1.0 - pr / bin_capacity as f64) * 20.0;
    if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack.min(15.0) * 0.5;
    }
    // Penalize creating residual that is too small for the next item (wasted space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Relative to mean residual: prefer filling below-average-residual bins.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: penalize opening a new bin unless it gives
    // an excellent fit or no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 12.0 + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // Opening a fresh bin that also hosts the next item is attractive.
            score -= base_penalty;
        } else {
            score += base_penalty;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild tie-break: prefer tighter bins overall.
    score += (bin_capacity as f64 - bin_residual as f64).recip() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that can likely never be reused (items >= 1... keep
    // residual small but nonzero is bad; zero residual is perfect).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }
    if post_residual == 0 {
        score -= 12.0;
    }

    // Lookahead: if the next item could use this bin's post-residual, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0; // dead space the known next item cannot use
        }
        // Coupling: residual exactly matching next item is ideal
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Time horizon: later in the stream, prefer consolidating into open bins
    // (avoid scattering) — penalize opening new bins late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus late-stream penalty, reduced when
        // open bins are all crowded (mean residual low).
        score += 10.0 + 30.0 * progress;
        if mean_residual < item_size as f64 {
            score -= 8.0; // no open bin is roomy; new bin is justified
        }
        if fitting_bins_count == 0 {
            score -= 25.0; // nothing fits elsewhere; must open new bin
        }
    } else {
        // Reward using bins with residual above the mean (drain the roomy bins first).
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        }
        // Many open bins: encourage filling existing ones.
        score -= (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;

    // Base: prefer small post-residual, with non-linear amplification of tight fits.
    let mut score = pr * (1.0 + 0.9 * fill * fill);

    // Smooth stream-progress coupling: tighten packing as stream advances.
    score *= 1.0 + 0.35 * progress * fill;

    // Dead-space penalty: residual too small to hold the smallest plausible item.
    let dead = ((30.0 - pr) / 30.0).max(0.0);
    score += 25.0 * dead * dead * (1.0 + 0.5 * progress);

    // Lookahead coupling: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let d = (pr - nx) / cap;
        score -= 6.0 * (-d * d * 8.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize opening a new bin unless the fit is genuinely tight elsewhere:
    // new-bin candidate has bin_residual == cap; make its score track item size
    // and mildly discourage it while open bins with slack exist.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.25 * open_bins_count as f64 + 8.0 * (1.0 - fill);
        // Allow new bin late in stream or for large items that would leave big residuals elsewhere.
        score -= 10.0 * progress * (it / cap);
    } else {
        // Slight preference for bins tighter than the mean residual (best-fit flavor).
        score += 0.15 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: tiny leftovers are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class thresholds via integer division on capacity fractions.
    let class = post_residual / (bin_capacity / 10).max(1); // 0..=10 harmonic class
    match class {
        0 => score -= 40.0,                 // near-perfect fit
        1 => score -= 25.0,                 // excellent
        2 => score -= 12.0,                 // good
        3 => score -= 4.0,                  // ok
        4 => { /* neutral */ }
        5 => score += 3.0,                  // half-full leftover
        6 => score += 5.0,
        7 => score += 8.0,
        8 => score += 12.0,
        9 => score += 16.0,
        _ => {}
    }

    // Big leftover is only fine if the NEXT item can use it (harmonic pairing).
    if next_item_size > 0 {
        let fits_next = next_item_size <= post_residual;
        if fits_next {
            // Reward a pairing where next item nearly fills the remainder.
            let fill_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 10.0 * fill_ratio;
            if next_item_size == post_residual {
                score -= 30.0; // perfect harmonic pair
            }
        } else {
            // Leftover cannot host the next item: penalize proportionally.
            score += 6.0 + 0.1 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when all open bins are nearly full
    // or this is a large item that would wreck a good bin.
    if bin_residual == bin_capacity {
        let avg_open_fullness = mean_residual / cap;
        // Opening a bin is good when open bins are tight (low mean residual)
        // and current fit is poor (high post_residual elsewhere).
        let poor_fit = pr / cap;
        let urgency = (1.0 - avg_open_fullness).clamp(0.0, 1.0);
        let base = 55.0 - 30.0 * urgency + 20.0 * poor_fit;
        // Early stream: prefer consolidation; late stream: opening is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = base - 10.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 15.0; // large items deserve fresh bins
        }
    }

    // Mild preference for tighter bins overall.
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    // Penalize leaving residual far from a harmonic class boundary (mid-band waste).
    let frac = pr % (bin_capacity / 10).max(1) as u32;
    let band = (bin_capacity / 10).max(1) as f64;
    let mid_dist = ((frac as f64 / band) - 0.5).abs();
    score += 4.0 * mid_dist;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item can use are pure waste.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // A gap is "dead" if it's smaller than the next item (or tiny in absolute terms).
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 8 };
    if post_residual < dead_threshold && post_residual > 0 {
        // Heavy penalty scaled by how close we are to a perfect fill.
        let waste_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score += 40.0 * waste_ratio * (1.0 + progress);
    }

    // Perfect or near-perfect fills are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= 15.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so add a penalty there).
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        // But if the new bin would give a much better residual than the mean, soften it.
        let post = (bin_capacity - item_size) as f64;
        if post < mean_residual {
            score -= 0.5 * (mean_residual - post);
        }
    } else {
        // Mild bonus for placing into bins already below-average residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Lookahead coupling: if the next item exactly matches the resulting gap,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward bins whose post_residual closely matches the next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post_residual as f64 - next).abs();
        if post_residual as u32 >= next_item_size {
            // next item can also fit here: reward exact match strongly
            score -= 45.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize leftover dead space
            score += 0.35 * post_residual as f64;
        }
        // mild reward if post_residual is a "perfect" complement pair
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // last item: purely minimize waste
        score -= 10.0;
    }

    // Relative-to-mean-residual coupling: prefer bins that are already below-average full
    // (concentrate filling), but avoid leaving outliers of huge residual vs mean
    let res = post_residual as f64;
    if res > mean_residual {
        score += 0.25 * (res - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - res);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the fit is bad
    // elsewhere or the item is large (poor fit potential in partially-filled bins)
    if bin_residual == bin_capacity {
        // default neutral cost of opening a new bin
        score = 55.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 <= bin_capacity as f64 {
            // pair fits together in fresh bin: slightly cheaper
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            // no open bin fits: must open anyway
            score = 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post_residual, reward leaving that space
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.25 * next_item_size as f64;
    }
    // If next item won't fit here, mildly penalize wasting space
    if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // Last chance: this is the only fitting bin — strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when fit is poor
    // or many bins are already open with high mean residual
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.35;
        let crowded = open_bins_count as f64 > 3.0 && mean_residual > 40.0;
        let mut new_bin_penalty = 55.0;
        if poor_fit { new_bin_penalty -= 20.0; }
        if crowded { new_bin_penalty -= 15.0; }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += progress * 10.0;
        score += new_bin_penalty;
    }

    // Prefer bins with residual close to item (best-fit style)
    let gap = (bin_residual as i64 - item_size as i64) as f64;
    score += gap.abs() * 0.2;

    // Mild preference for filling bins with low residual among open bins
    if bin_residual < bin_capacity {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap; // 0..1 residual fraction
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * (1.0 + 0.9 * progress) + 0.35 * norm_post * norm_post * (1.0 - progress);

    let mut score = poly * cap;

    // Tight fits are good; penalize dead space quadratically
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Last chance bin: reward strongly to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0 + 4.0 * progress;
    }

    // New bin candidate: penalize mildly early, more when open bins exist and fit poorly
    if is_new_bin {
        score += 2.0 + 6.0 * (1.0 - progress) + 0.15 * open_bins_count as f64;
        // If lookahead item could use this fresh bin, soften penalty
        if next_item_size > 0 && next_item_size as f64 <= cap {
            score -= 1.5;
        }
    }

    // Lookahead synergy: prefer bins whose post residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 2.5 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 1.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Mean residual coupling: avoid leaving this bin far above mean residual
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Dead-space penalty: small post_residuals are wasteful unless perfectly tight.
    if post_residual > 0 {
        score += 12.0 / (post_residual as f64).powf(0.7);
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Harmonic class reward: residual aligned to multiples of 10 (common item granularity)
    // leaves a "usable class" of space for future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Quasi-harmonic: residuals in {5,15,25,...} can pair with odd-half items.
    if post_residual % 10 == 5 && post_residual > 0 {
        score -= 2.0;
    }
    // Penalize awkward classes (1..4, 6..9 mod 10) proportionally to how small they are.
    let cls = post_residual % 10;
    if cls >= 1 && cls <= 4 {
        score += (5 - cls) as f64 * 1.5;
    } else if cls >= 6 && cls <= 9 {
        score += (cls - 5) as f64 * 1.5;
    }

    // Lookahead: reward bins whose post_residual can still host the next item,
    // especially when that next item fits a harmonic class of the residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            if post_residual % next_item_size.max(1) == 0 {
                score -= 4.0; // exact harmonic tiling possible
            }
        } else {
            score += 3.0; // bin becomes dead after this placement
        }
    }

    // Congestion pressure: many open bins with slack -> prefer reusing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if !is_new_bin {
        score -= (open_bins_count as f64).sqrt() * 0.8;
        score -= mean_residual * 0.05;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a new bin is attractive when the item is large
    // (leaving a large, well-classed residual) or when few bins fit and congestion is low.
    if is_new_bin {
        let large_item_bonus = (item_size as f64) * 0.35;
        score -= large_item_bonus;
        // If next item is small, a fresh 100-residual bin is valuable for it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        score += progress * 10.0;
        // If several bins already fit, discourage opening yet another one.
        if fitting_bins_count >= 2 {
            score += 8.0 * (fitting_bins_count as f64).min(4.0);
        }
        // Discourage new bins that would leave tiny dead space immediately.
        if post_residual > 0 && post_residual < 20 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so it's only chosen when all open bins
    // would create dead space; boost pressure when open bin count is high.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 + (open_bins_count as f64) * 1.5;
        // If this is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual gap, reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size > 0 {
        // Gap likely dead for the next item; penalize moderately.
        score += 3.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into fuller bins.
    score += (open_bins_count as f64) * 0.3 + (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)) * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 50.0; // perfect two-step chain: fill completely next step
        }
        // Penalize leaving dead space the next item cannot use
        if post_residual < next_item_size {
            score += 10.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Compare post_residual against mean residual: prefer bins whose remaining space
    // stays near the mean (balanced packing), penalize extreme outliers.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Tight fits are good: small post_residual is naturally favored by base term.
    // Reward near-full utilization quadratically.
    let utilization = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * utilization * utilization;

    // Early in the stream, be more willing to open bins for large items
    // (keeps flexibility); late in the stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if item is large or progress is early.
        score += 25.0 * (1.0 - progress);
        score += 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * fill_ratio * fill_ratio * (item_size as f64);

    // Penalize dead space: small post_residual relative to item size is good,
    // but a large post_residual that no future item can use is bad.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && (next_item_size as u32) <= post_residual { 0.0 } else { post_residual as f64 };
        score += 0.6 * dead;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        // Next item still fits: mild reward proportional to leftover after both.
        let chain_left = post_residual - next_item_size as u32;
        score -= 6.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize this bin slightly to save room.
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // mean residual across open bins is small (fragmented state) or few bins fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = 1.0 - mean_residual / (bin_capacity as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let open_penalty = (open_bins_count as f64).ln() * 3.0;
        score += 40.0 - 35.0 * fragmentation - 15.0 * scarcity - 10.0 * progress + open_penalty;
        // Never open a new bin early when plenty of space exists.
        if mean_residual > (item_size as f64) * 1.5 {
            score += 20.0;
        }
    }

    // Global state: prefer filling bins with below-average residual (balance reduction).
    if bin_residual < bin_capacity {
        let diff = (bin_residual as f64) - mean_residual;
        score += 0.15 * diff;
    }

    // Slight preference for using already-open bins as stream progresses.
    if bin_residual < bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post_residual) with a non-linear quadratic shaping.
    let mut score = post * (1.0 + 0.015 * post / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late, squeeze hard.
    let tight_bias = 2.0 * progress * (1.0 - progress); // peaks mid-stream
    score += post * post / (cap * cap) * (18.0 + 40.0 * progress) - tight_bias * 6.0;

    // Reward filling a bin nearly exactly (post near 0) super-linearly.
    let fill_frac = 1.0 - post / cap;
    score -= fill_frac * fill_frac * 12.0;

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: mildly penalize opening a new bin so that
    // decent fits into open bins win, but if this item would leave a very
    // large dead space in every bin (large post_residual relative to cap),
    // the empty bin (post = cap - item) can win.
    if bin_residual == bin_capacity {
        let new_bin_dead = post / cap;
        score += 30.0 - 55.0 * new_bin_dead * new_bin_dead;
        // Early stream: opening bins is cheap-ish; late stream: discourage.
        score += 10.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack_after_next = post - nxt;
            score -= 10.0 * (1.0 - slack_after_next / cap);
        } else {
            // next item can't follow here; slight penalty proportional to gap
            score += 2.0 * ((nxt - post) / cap);
        }
    }

    // Prefer balancing residuals toward the mean (avoid many tiny slacks).
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Slight penalty for proliferating bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which quarter of the bin remains.
    let quarter = cap / 4.0;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Reward residuals that match a harmonic class boundary (post == 0, 25, 50, 75)
    let harmonic = [
        (post - 0.0).abs(),
        (post - quarter).abs(),
        (post - 2.0 * quarter).abs(),
        (post - 3.0 * quarter).abs(),
    ];
    let best_h = harmonic.iter().cloned().fold(f64::INFINITY, f64::min);
    score -= 18.0 * (1.0 - best_h / quarter).max(0.0);

    // If the next item fits exactly into the post residual, big reward.
    if next > 0.0 && next <= post {
        if (post - next).abs() < 1.0 {
            score -= 30.0; // perfect pairing
        } else {
            // next item fits with a decent leftover
            let leftover = post - next;
            if leftover <= quarter {
                score -= 12.0;
            } else {
                score += 4.0; // wastes space for a small next item
            }
        }
    } else if next > 0.0 {
        // next item cannot fit in this bin's residual: penalize large residuals
        score += 0.08 * (post - 10.0).max(0.0);
    }

    // Integer-division threshold: post_residual / 10 class
    let class = post_residual / 10;
    match class {
        0 => score -= 15.0,           // near-perfect fill (0-9 left)
        1 => score -= 8.0,            // good fill
        2 => score -= 2.0,            // ok
        3 => score += 3.0,            // mediocre
        4 => score += 6.0,            // half empty
        _ => score += 8.0,            // mostly empty
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit is terrible.
    if bin_residual == bin_capacity {
        score = cap * 0.85; // baseline: prefer existing bins by default
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        // open new bin if mean residual is low (bins are full) or fit is bad
        if mean_residual < 25.0 || (next > 0.0 && next as u32 > post_residual && post_residual < item_size / 2) {
            score -= 20.0 + 10.0 * progress;
        }
        if crowded > 8.0 {
            score -= 5.0;
        }
    }

    // Mild penalty for tight fits that create dead space below the smallest item.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Small bonus for compacting when many bins are open.
    score -= 0.3 * open_bins_count as f64 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (small gaps that few future items can fill) are heavily penalized.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits generally: small waste relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when the current item leaves a
    // large residual (good for future items) and open bins are numerous.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64;
        score -= 5.0 * (open_bins_count as f64);
        // Lookahead: if next item fits the new bin's residual, favor it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // Pressure from number of open bins: prefer filling existing bins
        // when many are open; penalize bins whose residual is far above mean
        // (they are less likely to be consolidated).
        score += 0.5 * (open_bins_count as f64);
        if (bin_residual as f64) > mean_residual {
            score += (bin_residual as f64 - mean_residual) * 0.3;
        }
    }

    // Lookahead synergy: if the next item exactly fits the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for stranding space.
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post_residual against capacity.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tight * tight * (item_size as f64);

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 {
        let dead = (bin_capacity as f64) * 0.12;
        if (post_residual as f64) < dead {
            score += 6.0 * (dead - post_residual as f64) / dead;
        }
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 / (1.0 + slack);
        } else {
            // next item cannot use this residual; penalize wasted space
            score += 0.5 * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
        if post_residual as f64 > (bin_capacity as f64) * 0.5 {
            score += 4.0; // poor fit, soften the bonus
        }
    }

    // New-bin candidate handling: penalize opening a new bin when good fits exist,
    // but allow it when the item fits poorly everywhere or bins are crowded.
    if bin_residual == bin_capacity {
        score += 15.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (item_size as f64) > mean_residual;
        if poor_fit || fitting_bins_count == 0 {
            score -= 12.0;
        }
        if open_bins_count > 4 && !poor_fit {
            score += 5.0;
        }
        score += 3.0 * (1.0 - progress);
    }

    // Mild preference for bins already below mean residual (consolidate slack).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    // Late-stream consolidation: prefer filling existing bins near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post residual), with mild non-linear emphasis.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth polynomial coupling of tightness with stream progress:
    // later in the stream, dead space matters more.
    let tightness = 1.0 - pr / cap;
    score -= progress * tightness * tightness * 12.0;

    // Reward filling bins deeply (non-linear in fill fraction).
    let fill = item / cap;
    score -= 8.0 * fill * fill;

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize bins whose residual deviates from mean (harmonize residuals),
    // smooth quadratic term.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Lookahead coupling: reward leaving residual that can host the next item,
    // penalize residuals that are awkwardly small but nonzero.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else if pr > 0.0 {
            score += 4.0 * (1.0 - pr / nxt.min(cap));
        }
    }

    // New-bin candidate: penalize opening a new bin, scaled by how many
    // open bins could fit the item and by stream progress.
    if bin_residual == bin_capacity {
        let escape = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 25.0 + 10.0 * progress + 5.0 / escape;
    }

    // Slight penalty for accumulating many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues divisible by common
    // item sizes (10/20/25/50) are more reusable than "dead" residues.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit is best possible
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 20 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -7.0
    } else if pr < 10 {
        25.0 // dead space below minimum item size
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Tightness: reward filling a large fraction of the bin.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill;

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this bin becomes a two-item chain — strongly reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let nxt_pr = pr - next_item_size;
            if nxt_pr % 10 == 0 || nxt_pr == 0 {
                score -= 8.0;
            }
        } else if pr > 0 && next_item_size % pr == 0 {
            // next item is a multiple of residual: residual is a useful divisor
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * (post_residual as f64).min(60.0);
    }

    // New-bin candidate handling: an empty bin has full residual. Prefer
    // keeping it pristine unless no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Neutral base; slightly penalize so tight existing fits win,
        // but with lookahead synergy it can win.
        score += 12.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // reserve for a clean two-item pairing
        }
        // Late in the stream, opening fresh bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Many open bins with high mean residual: encourage consolidation
    // into emptier bins to avoid fragmentation.
    if open_bins_count > 3 && mean_residual > 40.0 {
        score += 4.0;
    }

    // Small nudge toward bins whose residual is close to item size
    // (near-perfect fits among non-empty bins).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score -= 10.0 / (1.0 + gap / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (1..=15) are heavily penalized: they waste capacity.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (1.0 - (post_residual as f64) / 15.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fills generally: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // --- Next-item lookahead coupling ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin remains useful for the next item.
            score -= 12.0;
            // Extra reward if post_residual exactly accommodates next item.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else if post_residual > 0 {
            // Post-residual too small for next item: dead space penalty scaled by gap size.
            let gap = next_item_size - post_residual;
            if gap <= 20 {
                score += 18.0 * (1.0 - gap as f64 / 20.0);
            }
        }
    }

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // Only this open bin fits; strongly prefer it over opening a new bin.
        score -= 45.0;
    }

    // --- Open-bins pressure ---
    // More open bins -> favor consolidation into existing bins.
    let pressure = open_bins_count as f64;
    if bin_residual < bin_capacity {
        score -= pressure * 0.8;
    } else {
        // New-bin candidate: penalize mildly so we only open when fits are poor.
        score += 30.0 + pressure * 0.3;
        // But if item is large and mean residual across open bins is small,
        // opening a new bin is fine (few good hosts exist).
        if (mean_residual < item_size as f64) && item_size >= 50 {
            score -= 55.0;
        }
    }

    // --- Stream progression ---
    // Late in the stream, be more conservative: keep existing bins usable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward an exact match: this bin becomes perfect for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial reward when the next item still fits here afterwards.
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit in the leftover: penalize dead space, more so if small.
        score += 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize waste relative to the mean residual across open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if current bin fits are poor (large leftover).
    if bin_residual == bin_capacity {
        let best_possible = 100.0 - item_size as f64;
        score = 100.0 - 0.5 * best_possible;
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 40.0;
        }
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 + next_item_size as f64 {
            score += 25.0; // an open bin can host both items; discourage new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Reward tight fits: strongly favor small post_residual (dead space penalty, superlinear)
    score += (post * post) / cap;

    // Reward filling bins completely
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Lookahead: if next item fits into post_residual, this placement is valuable
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // post_residual too small for next item: penalize proportionally to wasted space
            score += (post / cap) * 10.0;
        }
    }

    // Last chance bin: strongly prefer using the only fitting bin before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when mean residual is high
    score += mean_residual * 0.05;

    // New bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 60.0;
        // Cheaper to open new bin late in stream? No: early bins amortize more, so penalize early
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
        // If next item is large and current item is small, new bin may be fine
        if next_item_size >= item_size && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Slight preference for bins with smaller residual among equals (pack tight first)
    score += (bin_residual as f64) * 0.02;

    // Penalize very low utilization placements
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.5 && bin_residual < bin_capacity {
        score += (0.5 - fill_ratio) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), with smooth non-linear shaping
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, penalize waste more aggressively
    score += pr_norm * (1.0 + 2.0 * progress * progress) * 10.0;

    // Non-linear interaction between post-residual and mean residual across open bins
    let mr = mean_residual / cap;
    score += 8.0 * pr_norm * mr * (1.0 - mr);

    // Lookahead: reward bins whose post-residual can still hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            // dead space relative to lookahead item
            let gap = (nxt - pr) / cap;
            score += 15.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is huge
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill = item_size as f64 / cap;
        // Opening a fresh bin is attractive only for large items (poor fits elsewhere)
        score = 60.0 - 40.0 * fill * fill - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative
        }
    } else {
        // Reward using existing bins, more so when many are open
        score -= 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Mild penalty for leaving residuals in the awkward 20-40 zone (hard to fill later)
    let awkward = ((pr - 30.0) / 30.0).powi(2);
    score += 6.0 * (-awkward).exp() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: the smaller the post_residual relative to capacity, the better.
    score -= (bin_capacity - post_residual) as f64 * 0.5;

    // Harmonic class of post_residual: dead space classes are penalized.
    // Class boundaries at multiples of 10 (smallest item size granularity).
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // Unusable sliver: dead space that likely nothing (min size 1..10) can use.
        score += 25.0;
    } else if pr < 20 {
        score += 8.0;
    } else if pr < 30 {
        score += 2.0;
    }

    // Lookahead coupling: reward if next item fits exactly-ish into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect chain
        } else if next_item_size <= pr {
            let gap = (pr - next_item_size) as f64;
            // reward decays with gap, harmonic in (gap+1)
            score -= 20.0 / (1.0 + gap / 10.0);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly prefer using it
    // (avoids opening a new bin) — unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity means brand-new bin.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual we abandon elsewhere.
        // Penalize mildly so it only wins when all open bins fit badly.
        score += 18.0;
        // But if item is huge relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Early in stream, prefer consolidating into open bins less strongly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    }

    // Prefer filling bins whose residual deviates below the mean (tighten scattered bins).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    // Mild pressure to reduce number of open bins late in the stream.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized
    // (unless post_residual == 0, a perfect fill, which gets a big reward).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score += 60.0; // creates dead space below the smallest item
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; scale penalty on the base score.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.3 + 0.5 * progress);
    score *= 1.0 + pressure / 100.0;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin best consumed now.
    let res_diff = mean_residual - bin_residual as f64;
    if res_diff > 0.0 {
        score -= 0.5 * res_diff;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item would fit exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use the gap; penalize leaving medium gaps
        score += 0.1 * (post_residual as f64);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no open bin fits well;
        // make the empty bin moderately expensive so tight fits win.
        score += 30.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    score += 30.0 * (1.0 - fit_ratio);

    // Two-step lookahead: reward if the next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item completion
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack as f64 / post_residual as f64);
        } else {
            // Next item cannot follow: post_residual becomes dead space.
            let dead = post_residual as f64;
            score += 0.5 * dead;
        }
    }

    // Penalize post_residual smaller than the minimum possible item (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // Compare against mean residual: prefer bins already below-average residual
    // (larger fill fraction) to close them out.
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        if rel < 1.0 {
            score -= 15.0 * (1.0 - rel);
        } else {
            score += 10.0 * (rel - 1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: make empty bins unattractive unless the item
    // fits poorly everywhere (implicit via above bonuses) or stream is early
    // and building a diverse pool is cheap.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early on, allow new bins; later, discourage strongly.
        score += 25.0 + 60.0 * progress;
        // But if next item is large, a fresh bin is useful.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Slight preference to spread load when many bins are open with high mean residual.
    if open_bins_count > 4 && mean_residual > 50.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_tight = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - next_tight / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual becomes dead space if next item can't use it.
        score += 8.0 * tightness;
    }

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening new bins when decent alternatives exist,
    // unless the item fits very snugly into the fresh bin.
    if bin_residual == bin_capacity {
        let snug = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        let early = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 15.0 * (1.0 - snug) - 10.0 * early;
        // If few bins fit the item, opening a new one is less bad.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    } else {
        // Mild preference for filling fuller bins among open bins.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 12.0 * fill;
    }

    // Global state coupling: when mean residual is high, prefer bins
    // that consume the common surplus; when low, be frugal.
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Slight time-horizon adaptation: later in the stream, tighten up.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let mut score = pr;

    // Polynomial coupling of post_residual with stream progress:
    // early on, slightly tolerate larger post residuals; later, penalize them strongly.
    let poly = x * x * (3.0 - 2.0 * progress) + x * x * x * progress * 2.0;
    score += poly * cap * 0.35;

    // Tight fit reward: quadratic bonus when post_residual is small
    score -= (1.0 - x) * (1.0 - x) * 8.0;

    // Last-chance bin: strong reward, modulated by progress
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 4.0;
        } else {
            score += (next_item_size - post_residual as u32) as f64 * 0.05 * progress;
        }
    }

    // Penalize bins far from mean residual (fragmentation avoidance)
    let dev = pr - mean_residual;
    score += 0.03 * dev * dev * (0.5 + progress);

    // Mild penalty for many open bins when residual is large (waste)
    score += (open_bins_count as f64).ln() * x * 2.0;

    // New-bin candidate: baseline score so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 15.0 * (1.0 - progress) - 4.0 * (1.0 - x);
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post_residual (small remainders favored superlinearly)
    if post_residual > 0 {
        // Dead-space classes: post_residual in {1..=9} is nearly unusable for items >=10
        if post_residual < 10 {
            score += 40.0; // useless sliver
        } else if post_residual <= 20 {
            score += 8.0;
        }
        score += (post_residual as f64).powf(1.25) * 0.15;
    } else {
        score -= 60.0; // perfect fill
    }

    // Lookahead: penalize if next item cannot fit in post_residual (would need new bin anyway)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward leaving room for the next item, scaled by how snugly it would fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 0.1 * slack;
            // harmonic class: post_residual % 10 small means next item pairs tightly
            if (post_residual % 10) < 3 { score -= 5.0; }
        } else {
            score += 10.0; // next item forced elsewhere; residual becomes dead space
        }
    } else {
        // last item: minimize waste aggressively
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        let poor_fit = (post_residual as f64) > 0.5 * bin_capacity as f64;
        if poor_fit && next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 30.0; // fresh bin can host item + next item
        } else if poor_fit && fitting_bins_count <= 1 {
            score -= 5.0;
        } else {
            score += 50.0; // keep using existing open bins when fit is decent
        }
    }

    // Stream progression: early on, be pickier (keep bins flexible); later, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;
    score += (open_bins_count as f64) * 0.5;

    // Mean residual coupling: if this bin is far below mean residual, it's a good closer
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 { score -= 0.2 * dev; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Any post_residual in (0, 10) is unusable dead space: heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 120.0;
    }
    // Post residual exactly matching next item's size: excellent lookahead fit.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }
    // Post residual large enough for the next item: mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual as f64 - next_item_size as f64).min(20.0);
    }
    // Post residual too small for next item but above dead-space zone: slight penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // --- Tightness reward: reward filling a large fraction of the bin ---
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // --- Open bins pressure: penalize opening new bins when many are open ---
    let is_new_bin_candidate = bin_residual == bin_capacity;
    if is_new_bin_candidate {
        // New bin starts with residual = capacity; make it unattractive unless
        // nothing else fits well. Base penalty grows with open_bins_count.
        score += 25.0 + 3.0 * open_bins_count as f64;
        // If item is small relative to capacity, opening a new bin is wasteful.
        if item_size < bin_capacity / 2 {
            score += 30.0;
        }
        // Last-chance pressure: if only this (new) bin "fits", allow it.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    } else {
        // Reward using existing bins, especially last-chance bins.
        if fitting_bins_count == 1 {
            score -= 70.0;
        }
        // Slight preference for bins tighter than the mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // --- Stream progression: early on, be conservative with new bins;
    // late in the stream, avoid leaving dead space even more strongly. ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * progress;
    }
    if is_new_bin_candidate && progress > 0.8 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: penalize proportionally to wasted potential.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize very small dead space (unusable slivers) relative to item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare residual against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless post-fit residual is large
    // or no real bin offers a decent fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 20.0 * progress;
        if post_residual >= 70 {
            score -= 20.0; // big item leaving big residual: fresh bin is fine
        }
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Mild preference for tighter existing bins late in the stream.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared post-residual penalizes large leftover space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, unless it's genuinely useful
    // (many open bins with small residuals and the item is large).
    if bin_residual == bin_capacity {
        score += 30.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        // Late in the stream with big items, opening a fresh bin is less bad.
        score -= progress * 20.0 * large_item;
        // If current open bins are nearly full on average, new bin is attractive.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 15.0;
    }

    // Lookahead: reward if next item can fit into the post-residual (keeps chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // Extra reward when next item is a good fit for the leftover.
        let next_fit_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 8.0 * next_fit_tightness;
    }
    // Penalize leaving a residual that is too small for the next item (dead space).
    else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Prefer filling bins with larger residuals relative to the fleet average
    // (balance: avoid many half-empty bins).
    if bin_residual != bin_capacity {
        let rel = bin_residual as f64 / (mean_residual.max(1.0));
        if rel > 1.2 {
            score -= 5.0 * (rel - 1.2).min(2.0);
        }
    }

    // Early stream: be conservative, keep bins flexible (avoid creating tiny residuals).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        score += 12.0 * (1.0 - progress); // dead space worse early on
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling: residual value decays with stream progress
    let residual_decay = (1.0 - progress * 0.5).max(0.5);
    score *= residual_decay;

    // Penalize dead space relative to capacity, non-quadratically
    let dead = pr / cap;
    score += 12.0 * dead * dead * (1.0 + 0.5 * progress);

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - ((pr - nxt) / cap);
            score -= 8.0 * snug * snug;
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 * (1.0 - dead);
    }

    // Slight preference for tight fit relative to item size
    let fill = item_size as f64 / cap;
    score -= 5.0 * fill * (1.0 - dead);

    // Mean residual alignment: prefer bins near the mean
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev;

    // New-bin candidate: penalize opening unless residuals are very tight
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress) - 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: small post_residual (tight fit).
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of small sizes) are less penalized.
    let pr = post_residual;
    if pr > 0 {
        // dead-space penalty grows super-linearly for small, awkward leftovers
        let class = pr % 10;
        let awkward = match class {
            1..=3 => 6.0,   // hardest to fill later
            4..=6 => 3.0,
            7..=9 => 1.0,
            _ => 0.0,       // class 0 (multiple of 10) is friendly
        };
        score += awkward * (1.0 + (pr as f64 / cap).exp() * 0.5);
    }

    // Perfect fit: strong reward.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && pr > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            // next item fits: leftover remains but still useful
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot fit here: this bin becomes frozen dead space
            score += (next_item_size - pr) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that shrinks
    // when many items remain (opening early is fine) and when open bins are
    // already congested / mean residual is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let congestion = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap as f64 * 0.55
            + 30.0 * progress                      // late stream: avoid new bins
            + 10.0 * (1.0 - congestion)            // if open bins are full, new bin is OK
            - 8.0 * (open_bins_count as f64).ln().max(0.0);
        // If nothing else fits well, new bin should still lose to terrible fits:
        // handled by awkward penalties above.
    }

    // Mild global regularization: prefer bins with residual below mean
    // (consolidate space into few bins).
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    // Integer-division threshold: post_residual >= half capacity means we
    // wasted a big bin on a small item; penalize.
    if pr * 2 >= bin_capacity && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small for the next item are likely wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Absolute dead space: tiny gaps nothing (min size 1..) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage consolidation when few bins exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are plentiful.
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if current bin's post-fit residual is unusable dead space,
        // a new bin becomes attractive.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
    } else {
        // Slight bonus for reusing bins when bin count is high.
        score -= 0.3 * open_bins_count as f64;
    }

    // Mean residual coupling: bins far below mean residual are good targets
    // for balancing space usage.
    score -= 0.2 * ((bin_residual as f64) - mean_residual);

    // Late-stream tightening: as the stream progresses, prioritize compact fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer bins whose post_residual exactly matches the next item size (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 18.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);

        // Perfect 2-chain: post_residual == next_item_size exactly.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Near-perfect: next item leaves a tiny unusable remainder afterwards.
        if next_item_size <= post_residual && (post_residual - next_item_size) < 10 {
            score -= 12.0;
        }
        // If next item cannot fit in this bin's post_residual, penalize large wasted space
        // unless it's still large enough to be generally useful.
        if next_item_size > post_residual {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * tightness * tightness;

    // Penalize creating dead space smaller than the minimum item size (unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins with less residual than average
    // (consolidate fullness), penalize using the emptiest bins for small items.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Early in the stream, be more conservative about leaving large residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual more than linearly.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward using bins with small residuals (efficient packing).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.15;

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty unless post residual is small (dead space anyway).
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Avoid wasting a nearly-full bin on a small item if many bins can fit the item.
    if fitting_bins_count > 1 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: opening a new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 35.0;
        // More open bins => cheaper to reuse; opening a bin when many are open is penalized.
        score += open_bins_count as f64 * 1.5;
        // Late in the stream, opening new bins is less attractive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // If current bin would leave a tight fit, opening a new bin is less needed.
        if post_residual <= 5 {
            score += 25.0;
        }
        // If mean residual across bins is large, prefer reusing existing bins.
        score += mean_residual * 0.3;
    }

    // Global state: if many open bins have large mean residual, encourage consolidating into them.
    if bin_residual != bin_capacity && mean_residual > 30.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item / cap;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;

    // Base: prefer tight fits via smooth non-linear decay on post_residual.
    let mut score = 1.0 - (-4.0 * norm_post).exp();

    // Non-linear polynomial coupling of post_residual with stream progress.
    let coupling = norm_post * norm_post * (1.0 + 2.0 * progress) + norm_post * norm_item * progress;
    score += 3.0 * coupling;

    // Penalize new bins progressively as the stream advances (smooth in progress).
    if is_new_bin {
        score += 2.0 + 6.0 * progress * (1.0 - norm_item * norm_item);
    }

    // Last-chance bonus: if this is the only fitting bin, reward using it strongly.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 4.0 + 3.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    let nxt = next_item_size as f64 / cap;
    if nxt > 0.0 {
        let gap = (norm_post - nxt).abs();
        score += 1.5 * gap * gap - 0.8 * nxt * (1.0 - norm_post);
    }

    // Mild pressure to consolidate: reward bins tighter than the mean residual.
    let mean_norm = mean_residual / cap;
    score += 0.5 * (mean_norm - norm_post) * (1.0 + progress);

    // Slight preference for fuller bins among many open bins.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item granularities) are preferred.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Reward post-residuals that are "reusable" sizes: divisible by 10, 20, 25, 50.
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit: strongly favored
    } else {
        let mut hb = 0.0;
        if pr % 10 == 0 { hb -= 8.0; }
        if pr % 20 == 0 { hb -= 6.0; }
        if pr % 25 == 0 { hb -= 5.0; }
        if pr % 50 == 0 { hb -= 7.0; }
        // Dead-space penalty for tiny unusable leftovers (1..10)
        if pr < 10 { hb += 25.0; }
        else if pr < 20 { hb += 8.0; }
        hb
    };
    score += harmonic_bonus;

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // Reward closeness of next item fit; penalize if slack becomes dead space
            score -= 15.0 * (1.0 - slack / cap);
            if slack < 10.0 { score += 10.0; }
        } else {
            // Next item won't fit here: mild penalty, this bin is a dead end
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate handling: penalize opening a new bin when decent fits exist,
    // but allow it when open bins are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: proportional to progress through the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 20.0 * progress;
        // If many open bins are fragmented (mean residual large), new bin is fine.
        if mean_residual > 0.5 * cap {
            score -= 15.0;
        }
        // If next item is large and won't pair with typical residuals, new bin attractive
        if next_item_size >= 60 { score -= 10.0; }
    }

    // Prefer tighter existing bins: smaller residual before placement is better.
    score += 0.1 * (bin_residual as f64 - post_residual as f64);

    // Mild penalty for proliferating bins late in the stream.
    score += 0.05 * open_bins_count as f64;

    // Nudge toward bins whose residual is close to mean (keep bin states uniform),
    // which preserves future pairing options.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: overwhelmingly favored.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits generally (small post_residual relative to capacity).
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 120.0;
        } else if gap < 10 {
            score += 20.0; // next item would create dead space here
        }
    }

    // Last chance: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // already-open bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 2.0 * (1.0 - progress);

    // New-bin candidate: penalize it so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 150.0;
    }

    // Mild preference for bins with below-mean residual (fill emptier bins less,
    // keep tight bins tight).
    if bin_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.14;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer minimal post residual (tight fits).
    let mut score = post;

    // Fraction of the bin left after placement.
    let post_frac = post / cap;

    // Dead-space penalty: residuals too small for typical future items are waste.
    // Non-linear: quadratic ramp once post_residual drops below the item-size floor.
    if post_residual > 0 {
        let waste = (cap * 0.20 - post).max(0.0);
        score += 0.35 * waste * waste / cap;
    } else {
        // Perfect closure: strong reward.
        score -= 40.0;
    }

    // Lookahead coupling: reward if the next item fits into post_residual,
    // penalize if it almost fits but misses (creates regret).
    if next > 0.0 {
        if next <= post {
            score -= 18.0 * (1.0 - next / cap);
        } else if next <= post + 12.0 {
            score += 12.0 * (next - post) / 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 0.5 * item;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, scaled by competition.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: if mean residual is high, prefer consolidating into fuller bins
    // (i.e., bins with lower post residual relative to mean).
    score += 0.15 * (mean_residual - post).max(0.0) * (mean_residual / cap.max(1.0));

    // Time horizon: early in the stream, tolerate opening new bins (future flexibility);
    // late in the stream, aggressively close out existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - post_frac);

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized by default, but the penalty shrinks when
        // the item is large (few future chances to use a fresh bin efficiently)
        // and when many bins are already open (fragmentation already high).
        let new_bin_penalty = 30.0
            - 0.25 * item
            - 1.5 * (open_bins_count as f64).min(20.0)
            - 15.0 * progress;
        // If no existing bin would leave a usable residual, allow the new bin.
        let poor_fit_elsewhere = fitting_bins_count == 0 || post_frac < 0.10;
        score += if poor_fit_elsewhere { new_bin_penalty.max(-10.0) } else { new_bin_penalty.max(8.0) };
    }

    // Small tie-breaker favoring bins whose residual is closest below the mean
    // (keeps residual distribution tight).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = fitting_bins_count as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits (low post residual)
    let mut score = post;

    // Non-linear waste coupling: small post-residuals are valuable dead space sinks
    let waste_term = (norm_post * norm_post) * cap * 0.35;
    score += waste_term;

    // Last-chance bonus: strongly reward using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 18.0 + 12.0 * (1.0 - progress);
    } else {
        // Mild crowding penalty as many bins compete
        score += (fit / (fit + 3.0)) * 4.0;
    }

    // Lookahead: reward leaving room for the next item; penalize blocking it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            // smooth reward when next item still fits, stronger near-exact matches
            let coupling = (gap / cap);
            score -= 10.0 * (-((gap - 0.0) * (gap - 0.0)) / (2.0 * 25.0)).exp() * (1.0 - coupling * coupling);
        } else {
            // penalize creating residual that cannot host next item
            score += 6.0 * (1.0 - progress) * (-gap / cap).min(1.0);
        }
    }

    // Mean-residual deviation: prefer bins below mean residual (consolidate emptier space)
    let dev = (mean_residual - post) / cap;
    score += 5.0 * dev * dev * (if dev < 0.0 { 1.0 } else { -1.0 });

    // New-bin candidate handling: bin_residual == bin_capacity means empty bin
    if bin_residual == bin_capacity {
        // discourage opening a new bin generally; allow it only for poor fits elsewhere
        let desperation = if fitting_bins_count <= 1 { 0.0 } else { 1.0 };
        score += 30.0 * desperation + 10.0 * (1.0 - progress);
        // but if item is large relative to capacity, new bin is fine
        score -= (item_size as f64 / cap) * 12.0;
    }

    // Late-stream tightening: as stream ends, avoid leaving large residuals anywhere
    score += progress * norm_post * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size buckets (integer division thresholds)
    let item_class = item_size / 10;                       // 1..=10
    let next_class = next_item_size / 10;                  // 0..=10 (0 = lookahead absent)

    // Fraction of bin consumed by placing item here
    let fill_frac = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: post_residual near 0 is desirable
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 30.0;

    // Penalize dead space: small post_residual classes are fine, mid-range waste is bad
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score -= 5.0; // near-perfect fit bonus
    } else if dead >= 10.0 && dead < 25.0 {
        // classic "waste" zone: residual too small for most items
        score += 8.0 * (1.0 - fill_frac);
    }

    // Modulo coupling: if next item exactly divides the post-residual class, favor
    let post_class = post_residual / 10;
    if next_item_size > 0 && post_class > 0 {
        if next_item_size <= post_residual {
            // next item fits in the leftover: reward keeping a usable remainder
            score -= 6.0;
            if post_residual % next_item_size == 0 {
                score -= 4.0; // perfect modular packing opportunity
            }
        } else {
            // next item cannot use the remainder: penalize stranded space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // with many candidates, prefer bins whose residual class matches item class
        let bin_class = bin_residual / 10;
        if bin_class == item_class {
            score -= 3.0;
        }
    }

    // New-bin candidate logic: only open a new bin when the item is large
    // or all existing fits are terrible
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / bin_capacity as f64) * 40.0;
        score -= pressure;
        // opening a new bin is attractive for big items (>= half capacity)
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        // late in the stream, discourage bin proliferation slightly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 5.0;
        // many open bins already: mild penalty for one more
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Harmonic penalty on post_residual: prefer residuals in friendly classes
    // (multiples of 10 leave room for the common size classes)
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 0.3;

    // Global residual balance: prefer bins near the mean residual (keeps pool uniform)
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..10) are wasted capacity -> heavy penalty band.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // risky gap, only fits tiny items
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: only one open bin can fit this item -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But if the next item would fit in the residual this placement creates,
        // a fresh bin keeps flexibility.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Placing into an open bin reduces pressure; reward slightly.
        score -= 2.0;
        // If next item still fits after placement, this is doubly good.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > 0 {
            // Creating a gap the next item cannot use is dead space.
            score += 4.0;
        }
    }

    // Mean-residual coupling: prefer bins close to the mean residual
    // (keeps the bin pool homogeneous and predictable).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * diff;

    // Late in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item still fits comfortably in the post residual.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 * next_item_size as f64;
    }
    // Next item cannot use the leftover: penalize dead space proportionally.
    else if next_item_size > 0 {
        score += 2.0 * next_item_size as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins tighter than the mean residual (good fits).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when it is genuinely the best option,
    // i.e. item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / (bin_capacity as f64);
        // Opening a new bin is penalized mildly; it wins only when existing
        // bins would leave huge unusable gaps.
        score += 20.0 - 30.0 * tightness;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0; // fresh bin can absorb the next item too
        }
    }

    // Slight late-stream bias toward consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared residual penalty grows superlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Exact fit is extremely desirable.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 25.0 * (1.0 - gap as f64 / bin_capacity as f64);
        if gap == 0 {
            score -= 40.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving awkward small residual.
        if post_residual > 0 && post_residual < 15 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin is attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins early and when good fits exist; discount late when fragmentation is high.
        let mut new_bin_score = 55.0 - 45.0 * pressure;
        if mean_residual < 20.0 && open_bins_count > 2 {
            new_bin_score -= 30.0; // fragmented state: prefer fresh bin
        }
        if progress > 0.8 {
            new_bin_score += 15.0; // late stream: avoid opening bins that may go unused
        }
        score += new_bin_score;
    } else {
        // Reward using existing bins, more so when mean residual is high (bins are loose).
        score -= 8.0 + mean_residual * 0.15;
    }

    // Discourage spreading across too many open bins when residuals are already small.
    if open_bins_count > 4 && bin_residual != bin_capacity && post_residual < next_item_size as u32 {
        score += 5.0;
    }

    // Mild time-dependent tightening: as stream progresses, waste becomes costlier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling: residual utility decays non-linearly with progress
    let tightness = 1.0 - (pr / cap);
    score -= 30.0 * tightness * tightness * (1.0 + progress);

    // Reward near-exact fits more aggressively over time
    score -= 20.0 * (1.0 - tightness).powi(3) * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 - tightness);
    }

    // Lookahead: discourage leaving residual that next item can't use
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 12.0 * (ni - pr) / cap * (0.5 + progress);
        } else {
            score -= 8.0 * (1.0 - ((pr - ni) / cap).min(1.0)) * progress;
        }
    }

    // New-bin candidate: penalize mildly unless current fit is poor
    if bin_residual == bin_capacity {
        score += 25.0 - 30.0 * (1.0 - (item_size as f64 / cap)).powi(2);
    }

    // Deter bin proliferation late in stream
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already does this).

    // Harmonic class of post_residual: residues modulo 10 create
    // "dead space classes". Penalize awkward residues (1..9 small remainders
    // are hard to fill later), reward multiples of 10.
    let post = post_residual as u32;
    if post > 0 {
        let r = post % 10;
        let dead_penalty = match r {
            0 => -6.0,
            1 | 9 => 8.0,
            2 | 8 => 6.0,
            3 | 7 => 4.0,
            4 | 6 => 2.0,
            _ => 0.0,
        };
        score += dead_penalty as f64;
    }

    // Perfect fill is ideal.
    if post == 0 {
        score -= 25.0;
    }

    // Fraction of capacity wasted: quadratic coupling on post_residual/capacity.
    let frac = post as f64 / cap;
    score += 20.0 * frac * frac;

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward this placement (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 18.0;
        } else if next_item_size <= post {
            // Next item fits: reward proportional to how snugly.
            let nr = post - next_item_size;
            let nr_res = nr % 10;
            score -= 6.0 - 0.5 * (nr_res as f64);
        } else {
            // Next item won't fit here: slight penalty, worse for small post.
            score += 3.0 * (next_item_size - post) as f64 / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.15 * open_bins_count as f64;

    // Mean residual context: bins with residual far below mean are "odd ones
    // out" — filling them normalizes the pool.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // New-bin candidate: bin_residual == bin_capacity (empty bin).
    // Give it a moderate score: chosen only when all existing fits are bad.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * item_size as f64;
        // Late in stream, slightly discourage new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If next item is large and this bin would be opened anyway, ok.
        if next_item_size >= 60 && item_size <= 40 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. A gap is "dead" if it is below a small-item floor.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to residual (high fill ratio of the gap).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Penalize if next item cannot fit into post residual but bin_residual was large.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate more strongly).
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; rises as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + progress * 20.0;
        // But if no open bin fits well (item large relative to mean residual),
        // opening a new bin becomes more attractive.
        if (item_size as f64) > mean_residual {
            score -= 35.0;
        }
        // If next item is huge, a fresh bin is valuable for it.
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild preference toward bins with below-average residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item's size (perfect chain fill).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual as f64 - next_item_size as f64).abs();
        score -= 30.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > post_residual {
        // Next item cannot follow into this bin: penalize proportionally.
        score += 0.35 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits relative to mean residual across open bins.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Penalize bins with residuals far below the mean (fragmented bins),
    // unless this is a last-chance bin.
    let dev = post_residual as f64 - mean_residual;
    if fitting_bins_count > 1 {
        score += 0.25 * dev.max(0.0);
    } else {
        // Last chance before opening a new bin: strong bonus to use it.
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline; only preferred when open
    // bins would create large dead space. Slight penalty keeps it behind
    // good fits, but it beats bins leaving huge unusable residuals.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening new bins is more acceptable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    }

    // Mild penalty for accumulating many open bins (encourage compaction).
    score += 0.5 * open_bins_count as f64;

    // Discard tiny dead space: prefer post_residual either 0 or >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual relative to item size.
    let tightness = if item_size > 0 { 1.0 - (post_residual as f64) / (bin_residual as f64) } else { 0.0 };
    score -= 2.5 * tightness * item_size as f64;

    // Penalize dead space: gaps too small for any plausible item (min size 1, but
    // practically items ~10+), scaled by how "stuck" the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let waste_after_next = post_residual - next_item_size;
            if waste_after_next < 10 {
                score -= 15.0;
            } else {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += 3.0;
        }
    } else {
        // Last item: just minimize leftover space.
        score -= 5.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when there are
    // already many open bins or good alternatives exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (exploration).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is high, we shouldn't need a new bin.
        score += 0.1 * mean_residual;
    } else {
        // Slight preference for bins with larger residual (fill emptier bins first
        // keeps tight bins for tight items) — mild Best-Fit-against-mean coupling.
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap; // normalized post residual in [0,1)
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr;

    // Smooth polynomial coupling: penalize mid-range leftover space (dead space)
    // quadratically around a "sweet spot" that shrinks as the stream progresses.
    let sweet = (1.0 - progress) * 0.35 * cap;
    let dev = fit_norm * cap - sweet;
    score += 0.9 * dev * dev / cap;

    // Cubic coupling of post-residual with progress: late in the stream,
    // small leftovers become more valuable (pack tighter).
    score += (0.5 + 1.5 * progress) * (fit_norm * fit_norm * fit_norm) * cap * 0.4;

    // Last-chance bonus: if this is the only bin that fits, reward strongly.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - fit_norm);
    } else {
        // Slight penalty when many alternatives exist; encourage spreading wisely.
        score += (fitting_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * progress);
    }

    // Lookahead: if the next item fits into the post-residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * (0.5 + 0.5 * (1.0 - progress));
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when good alternatives exist.
        score += 45.0 + 3.0 * (open_bins_count as f64);
        // But if no open bin fits (fitting_bins_count refers to open bins only),
        // the new bin is the only viable option: make it attractive.
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 1 {
            // Still likely worse than using the last-chance bin unless it's a very poor fit.
            let waste = bin_residual as f64 - item_size as f64;
            if waste > 0.6 * cap {
                score -= 120.0;
            }
        }
    }

    // Mild interaction with mean residual: prefer bins below mean residual
    // (i.e., tighter bins get slight preference), smooth term.
    score += 0.15 * (mean_residual - pr).tanh() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Harmonic class of post_residual: modulo-10 bands model dead-space usability.
    let pr = post_residual;
    let class = pr % 10;
    // Residuals in [0..10] are near-dead; residuals that are multiples of 5/10 stay reusable.
    match class {
        0 => score -= 12.0,               // perfectly reusable class
        5 => score -= 6.0,                // half-class, still useful
        1 | 9 => score += 8.0,            // awkward slivers
        2 | 8 => score += 4.0,
        3 | 7 => score += 1.0,
        4 | 6 => score -= 2.0,
        _ => {}
    }

    // Integer-division thresholds: residual buckets by size of item that could still fit.
    // If next item fits exactly, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0 + (pr - next_item_size) as f64 * 0.05;
        if pr == next_item_size {
            score -= 15.0; // perfect lookahead match
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here: mildly penalize leaving a bin that strands the lookahead
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // New-bin candidate: residual == capacity. Only attractive when no open bin fits well
    // (post_residual would be huge waste elsewhere) or stream is late and consolidation is done.
    if bin_residual == bin_capacity {
        // Opening a new bin costs ~capacity of potential; penalize unless item is huge.
        let waste_penalty = (bin_capacity - item_size) as f64;
        score += 25.0 + 0.5 * waste_penalty;
        // If item is very large relative to capacity, new bin is fine.
        if item_size * 4 >= bin_capacity * 3 {
            score -= 30.0;
        }
        // Early stream: opening bins is cheaper (more future items to fill them).
        score -= 15.0 * (1.0 - progress);
    }

    // Coupling with mean residual: if this bin's residual is far below mean, it's a
    // "harmonically small" bin — using it consolidates waste.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.15; // prefer small-residual (nearly full) bins
    } else {
        score += (-dev) * 0.05; // mild penalty for using large-residual bins
    }

    // Many open bins: encourage filling existing ones to allow closing streams.
    score -= 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Tiny exact-fill bonus.
    if pr == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward exact/near match between post_residual
    // and the next item size (perfect chain), penalize mismatched dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if post >= nxt {
            // Next item fits here: reward closeness of match.
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 25.0; // perfect chain bonus
            }
        } else {
            // Next item won't fit: penalize proportionally to wasted residual.
            score += 4.0 * (post / nxt).min(2.0);
        }
    }

    // Relative-to-mean-residual coupling: prefer bins whose residual deviates
    // favorably (smaller residual than mean = tighter bin).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only allow opening a fresh bin when the item
    // is large relative to current residuals or fits are scarce.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / bin_capacity as f64;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_cost = 20.0 + 8.0 * (open_bins_count as f64).ln().max(0.0);
        // Discount new-bin cost when item is big, bins are scarce, or late in stream.
        score += open_cost * (1.0 - 0.4 * pressure) * (1.0 - 0.3 * scarcity) * (1.0 - 0.2 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic penalty on remaining space after placement
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;
    score += tightness;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Exact fit for the lookahead item: this residual is gold
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Penalize bins whose residual would still fit the next item comfortably
    // (waste a big hole when the next item could use it)
    if next_item_size > 0 && post_residual >= next_item_size {
        score += 8.0 + 0.25 * (post_residual - next_item_size) as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Compare residual against the global mean residual: prefer bins that are
    // already "used up" relative to the fleet average
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Penalize creating tiny dead space (< smallest plausible item, use 5)
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // New-bin candidate handling: brand-new empty bin should only win when
    // no open bin offers a decent fit. Give it a mild penalty that shrinks
    // as the stream progresses and open bins accumulate fragmentation.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else { 0.0 };
        score += 20.0 + 30.0 * fragmentation + 10.0 * progress;
        // If next item is huge relative to a fresh bin, opening is more attractive
        if next_item_size > 0 && next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Late-stream consolidation: as we approach the end, avoid leaving many
    // half-empty bins; favor bins with small residual even more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 0.5 * post_residual as f64;

    // Mild penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual (tight fit), non-linearly scaled.
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Progress coupling: late in the stream, tighten more aggressively.
    score *= 1.0 + 0.8 * progress * (1.0 - norm_post);

    // Penalize dead space relative to the mean residual across open bins.
    score += 0.3 * (post - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post);
    }

    // Lookahead: favor leaving room for the next item if it fits snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 15.0 * (1.0 - slack * slack) * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many open bins; encourages consolidation.
    score += 0.5 * open_bins_count as f64 * norm_post;

    // New-bin candidate: make empty bins moderately attractive only for large items.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small,
    // "dead" residue classes (can host almost nothing) should be strongly
    // penalized, while leftovers in reusable classes are rewarded.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / c;

    // Dead-space penalty: leftover < 10 is unusable (min item is 1..100 here,
    // but tiny leftovers waste little; big dead chunks near half capacity are
    // the worst when they can't fit the lookahead item).
    if post_residual == 0 {
        score -= 30.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect fit
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item doesn't fit at all, penalize mildly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            // Reward closeness of the fit for the next item.
            score -= 10.0 * (1.0 - (pr - ni) / c);
            if pr == ni {
                score -= 15.0; // chain of perfect fits
            }
        } else {
            score += 5.0 + 5.0 * frac; // leftover will be stranded
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: empty bin should only win when no open bin offers a
    // decent fit. Penalize opening a new bin while mean residual is large.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * mean_residual;
        // Late in the stream, opening fresh bins is more wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Modulo/harmonic classes on post_residual: leftovers that are multiples
    // of common item sizes (divisible by 10 or 25) remain reusable.
    let pr_u = post_residual;
    if pr_u % 10 == 0 && pr_u > 0 {
        score -= 4.0;
    }
    if pr_u % 25 == 0 && pr_u > 0 {
        score -= 3.0;
    }
    // Odd-ish leftovers in awkward bands (just above small item sizes) are dead.
    if pr_u >= 1 && pr_u < 10 {
        score += 0.0; // already handled
    } else if pr_u > 50 {
        score += 0.5 * frac * 10.0; // large leftovers are less urgent to fill tightly
    }

    // Prefer tighter fills: subtract proportional to how much of the bin the
    // current item consumes.
    score -= (item_size as f64 / c) * 5.0;

    // Many open bins: discourage spreading; prefer bins below mean residual
    // (fill the emptiest-feeling tight bins first keeps mean low).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it's smaller than the smallest plausible item (treat 10 as floor, but scale with capacity).
    let min_gap = (bin_capacity as f64 * 0.10).min(10.0);
    if (post_residual as f64) < min_gap && post_residual > 0 {
        score += (min_gap - post_residual as f64) * 6.0; // wasted space penalty
    }

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual as f64 <= bin_capacity as f64 * 0.05 {
        score -= 20.0;
    }

    // Reward bins whose residual closely matches item size (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= 12.0 / (1.0 + tightness);

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * (0.5 + progress) * 2.0;

    // New-bin candidate handling: opening a new bin is only attractive if no tight fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when current bins are very fragmented
        // (mean residual small relative to item size) or this bin would be the only option.
        let fragmentation = (mean_residual / item_size.max(1) as f64).min(3.0);
        score += 18.0 - fragmentation * 5.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin anyway
        }
        // Late in the stream, prefer consolidating into existing bins.
        score += progress * 10.0;
    }

    // Lookahead: if next item could exactly fill this bin's post_residual, bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // If next item fits in post_residual, mild bonus; if it would be wasted, mild penalty.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-perfect match: next item fits with small leftover afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let second_leftover = post_residual - next_item_size;
        if second_leftover <= 5 {
            score -= 25.0;
        } else if second_leftover <= 10 {
            score -= 12.0;
        }
        // Penalize wasting a large residual when the next item barely fits
        // but leaves a big unusable gap afterwards.
        if second_leftover > 20 {
            score += 5.0;
        }
    }

    // Next item does NOT fit in the leftover: penalize proportionally to
    // how stranded the residual is relative to mean residual.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.6;
    }

    // Dead-space penalty: tiny residuals are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    // Penalize opening a new bin while good fits exist.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if no existing bin can fit the item, opening is necessary:
        // partially neutralize via lookahead alignment.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            let pr = bin_capacity - item_size;
            if pr == next_item_size {
                score -= 45.0;
            }
        }
        // As stream progresses, prefer closing out open bins less aggressively.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Mild coupling with mean residual: prefer bins whose fit tightens
    // the spread of residuals across open bins.
    let post_f = post_residual as f64;
    score += (post_f - mean_residual).abs() * 0.15;

    // Encourage filling bins tightly as more bins accumulate.
    score -= 0.05 * open_bins_count as f64 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if the next item fits in the post residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 9.0;
        } else if next_item_size > bin_residual {
            // Next item won't fit here anyway; residual choice matters less.
            score += 2.0;
        } else {
            // Placing here strands space the next item could have used.
            score += 7.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full / poor fits.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / (bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early; relax later when fragmentation dominates.
        let new_bin_penalty = 30.0 * (1.0 - 0.6 * progress) * (1.0 - avg_fill);
        score += 20.0 + new_bin_penalty;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 12.0;
        }
    }

    // Mild preference for bins below average residual (keeps emptier bins flexible).
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score += 3.0;
    }

    // Encourage consolidation when many bins are open.
    score -= 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Slight time-varying tie-break to diversify exploration across the stream.
    let phase = ((step_index as f64) * 0.37).sin();
    score += 0.8 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Core: quadratic dead-space penalty, amplified as the stream matures.
    let mut score = post + 18.0 * norm_post * norm_post * (0.4 + 0.6 * progress) * cap;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (item / cap);

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize post_residual that can never accept the next item (wasted lookahead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual < next_item_size {
            score += 8.0 + 6.0 * (1.0 - nxt / cap);
        } else {
            // Reward leaving exactly enough room for the next item.
            let gap = (post - nxt) / cap;
            score -= 6.0 * (1.0 - gap).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize opening a fresh bin when open bins exist,
    // unless it's early or the stream is very crowded.
    let is_new_bin = bin_residual as f64 == cap;
    if is_new_bin {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
        score += 22.0 - 10.0 * progress - 4.0 * crowd.min(3.0);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual
    // (consolidate into emptier bins, keep high-residual bins flexible).
    let dev = (mean_residual - post) / cap;
    score += 5.0 * dev * dev - 4.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals divisible by 10 are
    // "usable slots" for typical item sizes; odd residuals create dead space.
    let r = post_residual;
    let class = r % 10;
    if class == 0 {
        score -= 6.0; // perfectly harmonic residual, very reusable
    } else if class <= 3 {
        score += 4.0; // small sliver, near-dead space
    }

    // Integer-division threshold: residual in [0,10) is essentially wasted,
    // penalize heavily unless it exactly fits known small classes.
    if r < 10 && r > 0 {
        score += 12.0;
    }
    if r == 0 {
        score -= 15.0; // perfect closure of the bin
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward; if next item cannot use the residual at all, penalize.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 20.0;
        } else if next_item_size > r {
            score += 5.0;
        } else {
            let gap = r - next_item_size;
            score += (gap % 10) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // residual (poor fit) or when many bins are open with low mean residual.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity as f64);
        score = 30.0 + 40.0 * (1.0 - tight);
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // pairing potential in a fresh bin
        }
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 15.0; // an open bin could take it instead
        }
    }

    // Slight preference for tighter (fuller) bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let r = post_residual as f64;
    let n = open_bins_count as f64;
    let ns = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Last item: post_residual is permanent waste -> pure minimization.
    if next_item_size == 0 {
        return r - if post_residual == 0 { 10.0 } else { 0.0 };
    }

    // Perfect fit: the bin is closed, zero final waste. Reward grows with
    // open-bin pressure (consolidation is most valuable when many bins exist).
    if post_residual == 0 {
        return -(25.0 + 0.6 * n);
    }

    let mut score = r;

    // Strict dead-space avoidance: small nonzero residuals are unlikely to ever
    // be filled and become permanent waste. Quadratic sting just above zero.
    let dead_t: f64 = 14.0;
    if r < dead_t {
        // Pickiness relaxes when many bins are open: fill what exists instead
        // of proliferating bins.
        let picky = 1.0 / (1.0 + 0.03 * n);
        score += 30.0 * (1.0 - r / dead_t).powi(2) * picky;
        // Residual cannot even hold the lookahead item: dead for >= 1 more step.
        if r < ns {
            score += 6.0;
        }
    } else if r >= ns {
        // Residual stays alive for the next item: mild flexibility bonus.
        score -= 3.0;
    }

    // Lookahead perfect closure: the next item will exactly zero this bin.
    if ns == r {
        score -= 12.0;
    }

    if is_new_bin {
        // Opening penalty: bin proliferation pressure grows with open_bins_count,
        // stream progress, and existing slack pooled in open bins.
        let mut open_pen = 6.0 + 0.4 * n + 8.0 * progress + 0.04 * mean_residual;
        if fitting_bins_count == 0 {
            open_pen = 0.0; // forced open: no open bin can fit the item
        }
        score += open_pen;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: using it avoids opening a new bin; bonus scales with
        // open-bin pressure.
        score -= 6.0 + 0.3 * n;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 40.0 + 60.0 * tightness;
    } else if next_item_size > 0 {
        // Penalize dead space that cannot fit the next item, scaled by how close it is to being useless.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 15.0 * (1.0 - waste);
    }

    // Prefer tightest relative fit vs mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing residuals are poor
    // or too fragmented to fit the item.
    if bin_residual == bin_capacity {
        let usable = if next_item_size > 0 { post_residual >= next_item_size } else { post_residual == 0 };
        let poor_open = mean_residual < item_size as f64 * 1.1 || fitting_bins_count == 0;
        if usable && !poor_open {
            score += 250.0; // keep using open bins when they work
        } else {
            score -= 60.0;  // open a new bin when open bins are hopeless
        }
    }

    // Mild penalty for wasting space in bins with large residual (avoid squandering flexible bins).
    if bin_residual >= bin_capacity * 3 / 4 && bin_residual < bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that is small but unusable is fine,
    // large post_residual wastes capacity.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score -= 5.0; // near-perfect fill
    } else if pr >= 10.0 {
        score += 0.15 * (pr - 10.0);
    }

    // Lookahead: reward if next item fits into post_residual (chained packing).
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else if (next_item_size as f64) <= pr + 10.0 {
            score += 2.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation by penalizing spread.
    score += 0.5 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual deviates below mean
    // (filling the emptiest-but-usable bins first keeps tight bins tight).
    let dev = mean_residual - bin_residual as f64;
    score += 0.1 * dev;

    // Time horizon: later in the stream, be more conservative about leaving slack.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * t * (pr / 100.0);

    // New-bin candidate: only attractive when no open bin fits well
    // (large item, few fitting bins) or stream is early.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits elsewhere: open new bin
        } else if item_size >= 60 && fitting_bins_count <= 2 {
            score -= 6.0; // big item, poor alternatives
        } else {
            score += 20.0 + 10.0 * (1.0 - t); // discourage wasteful new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize post_residual, but non-linearly (dead space matters more when small)
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress
    let prog_sq = progress * progress;
    let prog_cu = prog_sq * progress;
    score += pr * (0.5 * prog_sq - 0.35 * prog_cu) * 2.0;

    // Interaction: post_residual vs mean residual (waste relative to average)
    let dev = mean_residual - pr;
    score += 0.25 * dev * (1.0 - norm_pr);

    // Tight-fit reward: smooth function of fill ratio
    let fill = item_size as f64 / cap;
    score -= 12.0 * fill * fill * (1.0 - norm_pr);

    // Lookahead: reward if next item fits the post-residual (smooth term)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (1.0 - (nx / (pr + 1.0)).min(2.0)).max(0.0);
        score -= 6.0 * fits * (1.0 - progress);
    }

    // Last-chance bonus: penalize opening new bins when few fitting bins exist
    if fitting_bins_count <= 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: smooth penalty scaled by number of open bins and progress
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post_residual mod 10
    let pr_class = post_residual % 10;
    score -= match pr_class {
        0 => 12.0,          // perfectly divisible residual (e.g. 0,10,...) — great state
        5 => 6.0,           // half-class residual still very usable
        _ => 0.0,
    };

    // Penalize awkward dead space: post_residual in (0,10) is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Mid-range awkward residuals (11..19) are poor for items >=10
    if post_residual >= 11 && post_residual <= 19 {
        score += 8.0;
    }

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 30.0;
    }

    // Harmonic coupling with next item: reward residuals that can host next_item_size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // integer-division threshold: how many future items fit
            let fits = post_residual / next_item_size.max(1);
            score -= 4.0 * fits as f64;
        } else {
            // next item cannot use this residual — dead space relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when fit quality elsewhere is bad
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // opening a new bin is attractive for large items (poor fit anywhere)
        score = score * 0.5 + (1.0 - tightness) * 40.0;
        // late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // if many bins fit the item, opening new bin is wasteful
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    // Mild penalty for leaving residual far from mean (imbalance)
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // are fine, but residuals in the "unusable small gap" band (1..=15)
    // create dead space. Penalize them heavily.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 - (post_residual as f64) * 3.0;
    }

    // Perfect or near-perfect fits are highly rewarded.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Prefer bins whose residual tightly matches the item (low slack ratio).
    let slack_ratio = post_residual as f64 / bin_capacity as f64;
    score += slack_ratio * 40.0;

    // Reward using bins that are already mostly full (low residual before placement).
    let fill_before = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_before * 20.0;

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // and encourage consolidating into existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin count.
        score += 30.0 + open_bins_count as f64 * 5.0;
        // But if no open bin fits well (high mean residual mismatch), allow it.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor placing here to avoid a new bin.
        score -= 35.0;
    }

    // Lookahead coupling: if the next item can use the resulting post_residual,
    // reward this placement (leaving a useful gap).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for next item: mild penalty (potential dead space).
        score += 8.0;
    }

    // Mean residual coupling: placing into a bin far below the mean residual
    // (i.e., unusually full bin) is good consolidation.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    // Slight stream-progression term: later in the stream, be greedier about
    // tight fits to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is inherently favored by base term,
    // but amplify the effect for near-perfect packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // this is a perfect chain placement — heavily reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits after this placement: mildly reward.
        score -= 6.0;
        // Extra reward if post_residual - next_item_size leaves a small remainder.
        let after_next = post_residual - next_item_size;
        if after_next <= 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit in the leftover: penalize proportional to wasted lookahead.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.3 * gap;
    }

    // Penalize creating dead space relative to the mean residual of open bins.
    if post_residual as f64 > mean_residual + 20.0 {
        score += 0.4 * (post_residual as f64 - mean_residual - 20.0);
    }

    // Last-chance bonus: if this is the only bin that fits the item, prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when open bins
    // would be badly fragmented. Penalize the fresh bin mildly by default so we
    // prefer filling existing bins, unless residuals are all small.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin becomes attractive: reduce its score.
        score -= 40.0 * pressure;
        // Progress-based: later in the stream, be more conservative about new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins are open, discourage spreading items thin.
        score += 0.5 * open_bins_count as f64;
    }

    // Small penalty for very large items in bins with lots of residual
    // (avoid wasting a big residual on a big item when a small one could use it).
    if item_size > 50 && post_residual > 40 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Reward creating residual that can still host the next item (lookahead k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if the next item would fit snugly afterwards too.
        let next_tight = next_item_size as f64 / post_residual as f64;
        score -= 6.0 * next_tight;
    } else if next_item_size > 0 {
        // Penalize leaving a dead gap smaller than the next item.
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Last chance: this is the only bin that fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count >= 2 {
        // Mild penalty when many alternatives exist; keep options open.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: only attractive when open bins are nearly full
    // or the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // But if all open bins have low residual (poor hosts), opening is fine.
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 40.0 * mean_fill * mean_fill;
        // Late in the stream, prefer consolidating into open bins less.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If no open bin can even fit the item, opening is mandatory-ish.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild global pressure: many open bins -> prefer packing existing ones tighter.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins whose residual deviates favorably from the mean (use fuller bins).
    score += 0.10 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: prefer small post_residual (tight fit), with a mild non-linear
    // quadratic coupling so very tight fits are disproportionately favored.
    let mut score = pr + 0.35 * (pr / cap) * pr;

    // Stream-progress coupling: early in the stream, tolerate slack (bins may
    // still receive more items); late in the stream, push toward tight packing.
    let progress_weight = 0.4 * (1.0 - progress) + 0.9 * progress;
    score += progress_weight * (pr / cap) * cap * 0.25;

    // Smooth non-linear interaction: residual vs mean residual of open bins.
    // Placing into a bin whose residual is far below mean concentrates slack.
    let mean_c = mean_residual.max(0.0);
    let ratio = (bin_residual as f64) / cap;
    score += 0.3 * (1.0 - ratio) * (mean_c / cap).tanh() * 10.0;

    // New-bin penalty: opening a bin wastes capacity unless the item is huge
    // relative to all fitting options (handled by fitting_bins_count term).
    if is_new_bin {
        score += 30.0 + 20.0 * progress;
        // If this bin is the only option, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0;
    }

    // Lookahead coupling: reward leaving post_residual that can accommodate
    // the next item; penalize post_residual that is small but nonzero
    // (unusable dead space).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 6.0 * (1.0 - (pr - ni) / cap) * (ni / cap);
        } else if pr > 0 {
            // dead space penalty, smooth quadratic ramp
            score += 8.0 * (pr / cap) * (1.0 - pr / cap) * (ni / cap);
        }
    }

    // Mild penalty for large open-bins count to discourage bin proliferation.
    score += (open_bins_count as f64).ln().max(0.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes of 10 units.
    let cap_f = bin_capacity as f64;
    let post_class = (post_residual * 10 / bin_capacity.max(1)) as u32; // 0..10

    // Dead-space penalty: residuals below half capacity are hard to fill.
    if post_residual < bin_capacity / 2 {
        let depth = (bin_capacity / 2 - post_residual) as f64;
        score += 0.6 * depth;
    }

    // Perfect / near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Class-based bonus: residuals that remain in a "useful" class (>= 30)
    // can still host typical items; residuals in tiny classes 1..=2 are risky.
    match post_class {
        0 => score -= 40.0,          // sealed bin, great
        1 | 2 => score += 45.0,      // dead space of 10-20
        3 | 4 => score += 15.0,      // marginal
        _ => {}
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
            // Harmonic match: next item leaves a residual in the same class family.
            let next_post = post_residual - next_item_size;
            let next_class = (next_post * 10 / bin_capacity.max(1)) as u32;
            if next_class == post_class {
                score -= 10.0;
            }
            if next_post == 0 {
                score -= 60.0;
            }
        } else {
            // Next item cannot use this bin's leftover: slight penalty if leftover is small.
            if post_residual < 25 {
                score += 12.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin is not chosen unless existing fits are bad.
        score += 55.0;
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // If many bins are open, discourage one more.
        score += 2.5 * open_bins_count as f64;
    }

    // Tie-break toward bins with small residual relative to the mean (tight packing).
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Mild penalty for very large items leaving large residuals mismatched.
    if item_size >= 60 && post_residual >= 40 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are highly penalized.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr <= 5.0 {
            score += 60.0; // nearly-full bin: excellent, heavily reward
        } else if pr < 15.0 {
            score += 12.0 * (15.0 - pr); // unusable sliver: strong penalty
        } else {
            // larger gaps: mild quadratic waste penalty
            let frac = pr / bin_capacity as f64;
            score += 8.0 * frac * frac * 100.0;
        }
    }

    // Reward tight fit relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 30.0 + 6.0 * open_bins_count as f64;
        // But if the new bin would keep large residual for future big items, soften.
        score -= 0.1 * post_residual as f64;
    }

    // Lookahead: favor bins whose post_residual accommodates next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 35.0; // perfect two-item closure
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // next item cannot use this gap: dead space likely
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    let dev = mean_residual - bin_residual as f64;
    score -= 0.05 * dev;

    // Slight late-stream tightening: conserve bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // 2-step lookahead coupling with the next item
    if next_item_size > 0 {
        if pr == next_item_size {
            // Perfect match: this bin will be exactly filled by the next item
            score -= 18.0;
        } else if pr >= next_item_size {
            // Next item still fits afterwards
            score -= 4.0;
        } else {
            // Next item cannot use the leftover: dead-space risk
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // Penalize unusable slivers
    if pr > 0 && pr < 5 {
        score += 6.0;
    }

    // New empty bin candidate: only attractive when it enables a clean lookahead fit
    if bin_residual == bin_capacity {
        score += 14.0;
        if next_item_size > 0 && pr >= next_item_size {
            score -= 6.0;
        }
        if pr == next_item_size {
            score -= 8.0;
        }
    }

    // Mild alignment with global residual state
    score += 0.03 * (mean_residual - pr as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post-residuals.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space that likely can't be reused later.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 {
        let usable = if next_item_size > 0 && (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        score += (post_residual as f64) * (0.25 + 0.45 * (1.0 - usable)) * (0.6 + 0.8 * progress);
    }

    // Lookahead coupling: reward leaving exactly the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.6;
        if post_residual as u32 == next_item_size {
            score -= 18.0;
        }
        if (post_residual as u32) < next_item_size {
            score += (next_item_size - post_residual as u32) as f64 * 0.9;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 12.0 * progress;
    }

    // Crowding pressure: with many open bins, prefer consolidating into emptier bins.
    if open_bins_count > 1 {
        score += (mean_residual - post_residual as f64) * 0.15;
    }

    // Prefer filling bins with small residual relative to mean (harmonize loads).
    score += ((post_residual as f64) - mean_residual).abs() * 0.08;

    // New-bin candidate: only attractive when current bin leaves unusable sliver
    // or item barely fits nowhere well.
    if bin_residual == bin_capacity {
        let sliver_elsewhere = fitting_bins_count > 0 && post_residual < 10 && next_item_size > post_residual;
        if sliver_elsewhere {
            score -= 10.0;
        } else {
            score += 30.0 + 40.0 * (1.0 - progress);
        }
    }

    // Mild bonus for exact fills.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (keep bins flexible);
    // late in the stream, penalize wasted space more aggressively.
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += norm_pr * norm_pr * cap * progress_weight * 0.15;

    // Smooth interaction: residual vs mean residual (avoid leaving bins far above/below mean)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
        score -= 10.0;
    }

    // Lookahead coupling: reward bins whose post-residual can still host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            // next item won't fit here; penalize proportionally to the shortfall
            let shortfall = (ni - pr) / cap;
            score += 15.0 * shortfall * shortfall;
        }
    }

    // Slight preference to fill bins among many open ones (bin consolidation)
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - norm_pr);

    // New-bin candidate: keep it mildly attractive only for very poor fits late in stream
    if bin_residual == bin_capacity {
        let poor_fit = 1.0 - (item_size as f64 / cap);
        score += 6.0 - 10.0 * progress * poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tight * tight;

    // Harmonic class of post_residual: mod-10 buckets penalize "awkward" leftovers.
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 {
        // leftovers in [1..9] are hard to fill; 0 is perfect; multiples of 10 are friendly.
        score += (9 - class) as f64 * 1.5;
        if class == 0 && pr > 0 {
            score -= 6.0;
        }
        // Very small dead space (< 10) is nearly unusable given min item size 1..100 unknown
        if pr < 10 {
            score += 12.0;
        }
    } else {
        score -= 15.0; // perfect fill
    }

    // Integer-division thresholds: post_residual relative to typical item scales.
    let q = pr / 25; // 0..4 quarters
    score -= q as f64 * 3.0;

    // Lookahead coupling: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect chaining
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            score += slack as f64 * 0.4;
            if slack % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    } else {
        // Last item: strongly prefer exact fill
        score += 20.0 * (pr > 0) as i32 as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // with many options, prefer tightest fit (already captured) but damp spread
        score += 2.0;
    }

    // Mean residual coupling: if this bin is far below mean residual, it's "junkier" — prefer filling it.
    let dev = mean_residual - bin_residual as f64;
    score -= dev.max(0.0) * 0.5;
    score += (-dev).max(0.0) * 0.2;

    // Late in the stream, consolidate: prefer bins with small residual more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tight;

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and would leave open bins very fragmented.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let fragmentation = if fitting_bins_count > 0 {
            (post_residual as f64 / bin_capacity as f64) * (1.0 - large_item)
        } else {
            0.0
        };
        // Base cost of a new bin, discounted for large items / late stream.
        score = 55.0 - 30.0 * large_item - 15.0 * progress + fragmentation * 40.0;
        if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
            score -= 10.0; // fresh bin can chain next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold any
    // future item (min size 1, but practically small gaps) are pure waste.
    // Penalize gaps in the "unusable" band [1, 15] heavily.
    if post_residual > 0 && post_residual < 15 {
        score += (16 - post_residual as i32) as f64 * 12.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward fits that still leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating a gap just below the next item: dead space risk.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 6.0 * open_bins_count as f64;
        // Opening a bin is more acceptable early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    } else {
        // Prefer tighter bins among open ones (smaller residual = better fit).
        score += 0.15 * (bin_residual as f64 - mean_residual);
        // Mild penalty for spreading across many bins.
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but punish unusable dead space hard.
    if post_residual < 10 {
        // Post-residual below minimum item size is near-wasted; penalize proportionally.
        score += 12.0 * (10 - post_residual) as f64;
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual == next_item_size {
            // Perfect chain: next item exactly fills this bin afterwards.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: reward closeness of the match.
            score -= 25.0 * (1.0 - gap as f64 / 100.0);
        } else {
            // Next item cannot follow into this bin: penalize, worse when gap is large.
            score += 8.0 + 0.25 * gap as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual well above mean are "loose";
    // filling them with a big item is valuable; bins below mean are already tight.
    let res = post_residual as f64;
    let dev = res - mean_residual;
    score += 0.35 * dev; // prefer leaving residual below the mean (tighter overall)

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual by construction,
    // but we must decide explicitly. Opening a new bin is good when the current fit is
    // sloppy (large post_residual) and the next item is large too.
    if bin_residual == bin_capacity {
        // Cost of a fresh bin: base penalty that tight fits elsewhere must overcome.
        score = bin_capacity as f64 + 20.0;
        // If next item is large, a fresh bin is more attractive (keeps big space free).
        if next_item_size >= 50 {
            score -= 15.0;
        }
        // Late in the stream, avoid opening unnecessary bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins already: discourage one more unless necessary.
        score += 1.5 * open_bins_count as f64;
    }

    // Small global tie-breaker favoring earlier bins slightly (stability).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer small post-residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating unusable dead space (residual too small for the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 8.0;
        }
    } else {
        // Last item: purely minimize waste.
        score -= 5.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a decent fit
    // or the stream is early with room to grow.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) / (1.0 + mean_residual / 20.0);
        score += 40.0;               // base penalty for opening a new bin
        score -= 35.0 * progress;    // cheaper to open bins early in the stream
        score -= 10.0 * (1.0 - 1.0 / (1.0 + crowded)); // more acceptable when bins are crowded/full
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0; // fresh bin can host the current item and the next one
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits anywhere: must open a bin
        }
    }

    // Slight preference for bins with below-average residual (keep flexible bins free).
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.05 * diff;

    // Mild load-balancing pressure: many open bins -> fill emptier ones less eagerly.
    if open_bins_count > 1 {
        score += 0.02 * (open_bins_count as f64) * (bin_residual as f64) / (bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Smooth non-linear coupling: squared normalized post-residual, weighted by stream progress.
    // Late in the stream, leaving large residuals is increasingly penalized (waste compounds).
    let norm_pr = (pr / cap).clamp(0.0, 1.0);
    score += 12.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);

    // Smooth interaction with mean residual: bins in a fragmented fleet get a slight
    // quadratic nudge toward absorbing items (consolidation pressure).
    let norm_mean = (mean_residual / cap).clamp(0.0, 1.5);
    score -= 4.0 * norm_mean * norm_mean * (open_bins_count as f64).ln1p() * 0.35;

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // scaled smoothly by how snugly it fits.
    if next_item_size > 0 && (next_item_size as u64) <= (post_residual as u64) {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 3.0 + 4.0 * snug;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // Brand-new empty bin candidate: penalize mildly, scaled by item size
    // (small items in a fresh bin waste more capacity potential).
    if bin_residual == bin_capacity {
        score += 5.0 + 8.0 * (item_size as f64 / cap);
    }

    // Tiny tie-breaker preferring tighter fits, smooth in item size.
    score += 0.02 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 bands.
    // Small post_residuals are good (tight fit); reward them nonlinearly.
    let post_class = post_residual % 10;
    score -= (10 - post_class) as f64 * 0.6; // near-multiples of 10 rewarded

    // Dead-space penalty: residuals that are unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny slivers are dead space
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    // Harmonic coupling with next item: if next item fits exactly into
    // post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            // modulo-harmonic: gap that is a multiple of 10 leaves a nice class
            if gap % 10 == 0 {
                score -= 4.0 + (gap as f64).ln();
            }
            score += gap as f64 * 0.15;
        } else {
            // next item cannot fit here: mild penalty, larger if bin becomes dead
            if post_residual < 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new
    // bin by rewarding this one (otherwise we'd spawn bins too eagerly).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate (residual == capacity): only attractive when the item
    // is large relative to capacity or current bins are fragmented.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for big items; penalize for small items when open bins exist.
        score -= fill_frac * 10.0;
        if open_bins_count > 0 && item_size < bin_capacity / 4 {
            score += 14.0;
        }
        // If open bins are very full on average, a fresh bin is reasonable.
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        score -= mean_fill * 6.0;
        // Harmonic threshold: item size in upper harmonic class of capacity
        if item_size * 2 > bin_capacity {
            score -= 6.0;
        }
    }

    // Stream progression: early on, be conservative with tight fits;
    // later, exploit tight packing more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Slight preference to fill already-open bins vs spreading across many.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual gap is "dead" if no plausible future item (>=1) could ever
    // use it well; treat gaps below a small threshold as wasted capacity.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Mid-range dead space (hard to fill exactly) gets a softer penalty.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Perfect fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the leftover gap -> penalize proportional gap
        score += (post_residual as f64) * 0.4;
    }

    // New-bin candidate logic: only attractive when open bins are tight or
    // this placement would create severe dead space.
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        // With few bins and roomy residuals, opening a new bin is bad.
        score += 15.0;
        score -= tightness * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for tighter bins overall.
    score += (bin_capacity as f64 - bin_residual as f64) * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: place here if post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Partial lookahead benefit: next item fits comfortably (but not perfectly).
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward closeness of the follow-up fit.
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot follow into this bin: penalize proportionally to wasted potential.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Relative-to-mean residual coupling: leaving much more space than average wastes capacity.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.35 * (pr - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - pr);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when the item is large relative to capacity
    // (poor fit anywhere) or the stream is early and many bins will still be useful.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize opening a new bin for small items or late in the stream.
        score += 30.0 * (1.0 - fill_ratio) + 25.0 * progress;
        // If no open bin can fit at all, opening is inevitable: soften the penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor minimal post residual (non-linear).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 24.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty for burning a scarce residual here.
        score += 2.0;
    }

    // Lookahead: reward if the next item fits exactly-ish into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 14.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: slight penalty for leaving awkward space.
            score += 4.0;
        }
    }

    // Dead-space penalty: residuals too small to hold even the smallest item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 10.0 + 10.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing bins
    // rather than fragmenting; conversely few bins -> consolidation is cheap.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 3.0 * pressure * tightness;

    // Time horizon: late in the stream, avoid opening new bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * progress * tightness;

    // New-bin candidate: only attractive when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, discounted when item is large / many bins open.
        let mut new_bin_score = 55.0;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        new_bin_score -= 30.0 * fill_ratio;
        new_bin_score -= 6.0 * progress;
        if fitting_bins_count == 0 {
            new_bin_score -= 60.0; // must open a bin anyway
        }
        // If mean residual is large, reusing existing bins is likely better.
        new_bin_score += 0.4 * mean_residual;
        score = score.min(new_bin_score);
        score = new_bin_score.max(score.min(new_bin_score) * 0.0 + new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post residual, with a non-linear (quadratic) penalty
    // for leaving awkward mid-range dead space.
    let mut score = post + 40.0 * norm_post * (1.0 - norm_post);

    // Polynomial coupling with stream progress: early on, tighter packing
    // matters less (more future items to fill gaps); later, dead space is costly.
    score += 30.0 * progress * norm_post * norm_post;
    score -= 20.0 * progress * norm_post * (1.0 - norm_post);

    // Interaction with mean residual: if this bin's residual deviates strongly
    // from the fleet mean, penalize creating imbalance (cubic smooth term).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev * dev.abs().sqrt().max(0.0);

    // Lookahead coupling: reward leaving room for the next item (smooth gaussian-like term).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 25.0 * (-gap * gap / 900.0);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize mildly so it only wins when open bins fit poorly,
    // with the penalty decaying as the stream progresses.
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small remainder" classes are penalized (dead space), while leftovers
    // that can plausibly host a future item are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class boundaries via integer division thresholds on post_residual.
    let class = post_residual / 10; // 0..=10 harmonic buckets
    match class {
        0 => score += 25.0,                 // 0-9: nearly perfect fit, but tiny waste locked
        1 => score -= 8.0,                  // 10-19: usable small slot
        2 => score -= 12.0,                 // 20-29: good slot for small items
        3 => score -= 6.0,                  // 30-39: mediocre
        4 => score += 3.0,                  // 40-49: awkward zone
        5 => score += 6.0,                  // 50-59: half-empty bin
        6 => score += 4.0,                  // 60-69
        7 => score += 2.0,                  // 70-79
        8 => score -= 2.0,                  // 80-89: roomy bin, fine
        _ => {}                             // 90+: fresh-ish bin
    }

    // Pairing reward: if the next item fits exactly (or well) into the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = post - nxt;
            score -= 15.0 * (1.0 - slack / 40.0).max(0.0);
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by waste
            score += 0.08 * post;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer using it only
    // when no open bin offers a good fit. Penalize the fresh bin mildly so existing
    // decent fits win, but keep it competitive against terrible fits.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.05 * (open_bins_count as f64);
    }

    // Progress coupling: late in the stream, consolidate harder (avoid sprawl).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0 * ((post_residual as f64) / cap);

    // Mean residual coupling: when open bins are generally empty, prefer filling
    // the fullest ones (score already grows with post_residual, add coupling).
    score += 0.1 * (mean_residual - post).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are wasted.
    // Treat gaps below the minimum item size (1) as perfect, tiny gaps (1..=9) as dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fit reward
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0; // unusable sliver penalty
    }

    // Reward leaving a gap that can host the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // lookahead can't fit in the gap: mild penalty scaled by how close it was
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Tightness bonus: fraction of the bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, avoid spreading; prefer filling existing.
    let obp = open_bins_count as f64;
    if bin_residual != bin_capacity {
        score -= 2.0 * (obp / (obp + 5.0));
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): only attractive when current bin fit is bad
    // (large dead space) or no real alternative exists. Penalize by default.
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if all open bins would leave heavy dead space, allow opening
        let dead_elsewhere = (mean_residual - item_size as f64).max(0.0);
        if dead_elsewhere > 30.0 {
            score -= 40.0;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Slight stream-progression bias: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Perfect fit for the next item is highly desirable.
        if diff == 0.0 {
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else if diff <= 5.0 {
            score -= 35.0 - 3.0 * diff;
        } else if diff <= 10.0 {
            score -= 15.0 - 1.0 * diff;
        } else {
            // Post-residual far from next item: dead-space risk grows with smallness.
            if post_residual < next_item_size && post_residual > 0 {
                score += (next - post_residual as f64) * 0.5;
            }
        }
    }

    // Prefer bins whose residual is tighter than average (good fits).
    let mean_gap = mean_residual - bin_residual as f64;
    score += mean_gap * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 45.0;
    }

    // Penalize creating tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate handling: normally unattractive (post_residual = capacity already large),
    // but attractive when open bins fit poorly (large lookahead mismatch).
    if is_new_bin {
        let penalty = 70.0 + 0.5 * open_bins_count as f64;
        score += penalty;
        // If lookahead suggests no open bin will match well, ease opening a new bin.
        if next_item_size > 0 {
            let worst = (post_residual as f64 - next_item_size as f64).abs();
            let _ = worst;
        }
        if fitting_bins_count <= 1 {
            score -= 80.0;
        }
        // Late in stream, prefer closing out bins tightly rather than new ones.
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize tiny dead space asymmetrically: residuals that can never fit even the
    // smallest item (<= 1..10 range) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 12.0; // perfect closure is excellent
    }

    // Lookahead (k=2): if the next item fits exactly into the post residual, reward;
    // if the next item cannot fit but this bin could have held it after rearrangement,
    // mildly penalize creating a gap the future item can't use.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fit
        } else if next_item_size < post_residual {
            score -= 6.0;  // next item still fits here
        } else if next_item_size > bin_residual {
            // next item won't fit this bin either way; residual size matters less
            score += 2.0;
        } else {
            // next item fits current bin but not after this placement: bad ordering
            score += 8.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.15 * (bin_residual as f64 - post_residual as f64);
    }

    // Many open bins: discourage fragmentation; prefer consolidating into bins
    // whose residual is already below the mean (denser bins).
    let dev = mean_residual - bin_residual as f64;
    score -= 0.25 * dev;

    // Time horizon: early in the stream, be conservative with open bins (favor
    // filling existing ones); late in the stream, tightness dominates anyway.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are already open,
        // with slight relief as the stream progresses.
        score += 20.0 + 3.0 * (open_bins_count as f64) - 10.0 * progress;
        // Allow a new bin if the item is huge relative to capacity and no tight option exists.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 8.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild preference for larger residual bins when item is small (save big gaps for big items).
    if item_size <= 30 {
        score += 0.05 * (bin_capacity as f64 - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: tight fit preferred, with non-linear (quadratic) shaping of post residual.
    let mut score = norm_pr + 0.6 * norm_pr * norm_pr;

    // Smooth coupling of post-residual with stream progress:
    // late in stream, tighten further (penalize residual growth more).
    score += 1.2 * norm_pr * progress;

    // Cubic interaction: residual waste compounds over time.
    score += 0.8 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, reward strongly (subtract).
    if fitting_bins_count == 1 {
        score -= 2.0 + 3.0 * progress;
    } else {
        // Mild penalty when many bins fit: prefer dispersal less, keep tight fits.
        score += 0.15 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: if next item fits into post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 1.0 - slack; // best when next item fills the remainder
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to how close it was.
        let gap = (next_item_size as f64 - pr) / cap;
        score += 0.5 * gap;
    }

    // New-bin candidate handling: empty bin gets a smooth adaptive penalty,
    // shrinking as stream progresses or when few bins fit.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (fitting_bins_count as f64).recip()
        };
        score = cap * (0.6 - 0.35 * progress) * (0.5 + pressure) + 0.2 * (open_bins_count as f64).ln().max(0.0);
    }

    // Coupling with mean residual: avoid bins that deviate strongly toward waste.
    score += 0.1 * (mean_residual - pr).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining_stream = (total_items.saturating_sub(step_index)) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post_residual as f64;

    if is_new_bin {
        // Candidate for opening a fresh bin: neutral-to-slightly-poor baseline.
        // Only wins when every open bin would leave an awkward residual.
        score = 55.0 + 25.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0; // fresh bin keeps lookahead flexibility
        }
        return score;
    }

    // Perfect closure is excellent regardless of stream position.
    if post_residual == 0 {
        score -= 30.0 + 10.0 * progress;
        return score;
    }

    // Dead-space penalty grows with how much stream is left to pack.
    let waste_weight = 0.5 + 1.5 * (1.0 - progress);
    score += waste_weight * (post_residual as f64 / cap) * 20.0;

    // Harmonic classes on post_residual (mod-10 decile logic):
    // residuals in 1..=9 are likely dead space (items 1..100, but tight classes matter);
    // residuals in 10..=19 or 50..=59 are "reusable classes" for typical mid-size items.
    let class = post_residual % 10;
    match post_residual {
        1..=9 => score += 12.0 - (class as f64) * 0.5, // tiny slivers: penalize
        10..=19 => score -= 4.0,                        // useful class for small items
        20..=29 => score += 2.0,
        50..=59 => score -= 3.0,                        // half-capacity class: very reusable
        _ => {}
    }

    // Lookahead (k=2): reward if next item fits the post residual, scaled by tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 + 10.0 * tightness;
    } else if next_item_size > post_residual {
        // Next item cannot use this residual: residual likely becomes dead space.
        score += 6.0 + 0.1 * (post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Prefer bins whose residual is below the open-bin mean (consolidating waste).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Mild pressure to close bins when many are open.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin can fit the item: opening a new bin is mandatory.
            return -1000.0;
        }
        // Prefer opening a new bin only when the existing fit is very poor
        // (the item would leave a tiny unusable gap in every fitting bin)
        // or when the stream is early and consolidation is less critical.
        // Base cost of a fresh bin: high score so it loses against decent fits.
        let mut new_bin_score = bin_capacity as f64 * 1.5;
        // If this item is the last chance in the only fitting bin, strongly
        // discourage opening a new bin (avoid wasting the nearly-full bin).
        if fitting_bins_count == 1 {
            new_bin_score += 500.0;
        }
        // Late in the stream, keep bins consolidated.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 100.0;
        // Many open bins already: discourage proliferation.
        new_bin_score += open_bins_count as f64 * 5.0;
        return new_bin_score;
    }

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: post_residual in 1..=9 is unusable
    // (min item size is 1 under the interface note; treat <10 as risky gap).
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 10.0;
    } else if post_residual < 20 {
        // Moderately awkward gap: mild penalty.
        score += 15.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 200.0; // chain fit: next item seals this bin perfectly
        } else if slack < 10 {
            score -= 50.0;
        } else {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, using it
    // prevents opening a new bin — strong reward.
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else {
        // Open-bins pressure: with many open bins, prefer filling existing
        // bins tightly (scaled by mean residual as a congestion signal).
        score += open_bins_count as f64 * 2.0;
        score += (mean_residual - post_residual as f64) * 0.5;
    }

    // Slight preference for bins whose residual was already small
    // (best-fit flavor beyond raw post_residual).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.0;

    // Exact fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward post_residual matching next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score -= (100.0 - diff).max(0.0) * 0.6;
        // Perfect lookahead match: next item exactly fills this bin
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize if next item cannot fit into post_residual (dead space risk)
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Compare residual against mean residual: prefer bins with below-average residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last chance: strongly favor using this bin to avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist with reasonable fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // New bin only attractive if item is large relative to capacity and fits are poor
        let fit_quality = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 20.0 * fit_quality;
        // If next item is large too, chaining in one new bin is attractive
        if next_item_size > 0 && (item_size + next_item_size) as f64 >= bin_capacity as f64 * 0.9 {
            score -= 35.0;
        }
    }

    // Slight preference for filling bins earlier in the stream (consolidation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual (wasted space is bad, but exact fits are great).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Strong reward for exact fills (post_residual == 0).
    if post_residual == 0 {
        score -= 20.0;
    }

    // Penalize creating tiny dead space (1..=9) that nothing small can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement heavily (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 6.0 * next_fit;
        } else {
            // Next item cannot fit here; slight penalty for leaving large residual
            // that will likely become dead space.
            let waste = (post_residual as f64 - next_item_size as f64).abs();
            score += 0.05 * waste;
        }
    }

    // New-bin candidate handling: empty bin should only win when current open bins
    // are poor fits or already numerous relative to progress.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        // Base cost of a new bin; reduced when no bin fits or bins are fragmented.
        score += 30.0 - 25.0 * scarcity - 2.0 * crowding.min(5.0) + 5.0 * (1.0 - progress);
    } else {
        // Mild preference for using bins with larger residual relative to mean
        // (balance residual consumption across bins).
        let rel = bin_residual as f64 - mean_residual;
        score += 0.03 * rel;
    }

    // Penalize bins whose residual is much larger than the item (wasteful placement
    // when other tight options exist), scaled by how many alternatives exist.
    if fitting_bins_count > 1 {
        let slack = (bin_residual - item_size) as f64;
        score += 0.02 * slack * (fitting_bins_count as f64);
    }

    // Small time-horizon modulation: early in the stream, be more conservative
    // about fragmenting bins; late in the stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let fit_norm = (item_size as f64) / cap;

    // Base: prefer small post-residual (tight fit), with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Polynomial coupling of post-residual with stream progress:
    // early on, tolerate slack; late in stream, penalize dead space aggressively
    let progress_coupling = pr_norm * progress * progress * (2.0 + 3.0 * fit_norm);
    score += 30.0 * progress_coupling;

    // Smooth reward for near-perfect fits (post_residual close to 0), stronger later
    let tightness = (1.0 - pr_norm).powi(3);
    score -= 12.0 * tightness * (0.4 + 0.6 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        // plenty of alternatives: mild penalty for wasting a scarce residual
        score += 4.0 * pr_norm * (fitting_bins_count as f64).sqrt();
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let match_quality = 1.0 - (pr - nxt) / cap;
            score -= 18.0 * match_quality * match_quality;
        } else {
            // post-residual too small for next item: penalize dead space
            score += 10.0 * pr_norm * (nxt / cap);
        }
    } else {
        // last item: prefer minimal leftover
        score += 5.0 * pr_norm;
    }

    // Contextual term: relative residual vs mean residual across open bins
    let mean_norm = mean_residual / cap;
    score += 6.0 * (pr_norm - mean_norm) * (1.0 + progress);

    // Mild pressure against proliferating many open bins with large slack
    score += 2.0 * pr_norm * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: only attractive when current bin would leave an awkward
    // residual and alternatives exist; smooth logistic-like gate on pr_norm
    if bin_residual == bin_capacity {
        let awkward = 1.0 / (1.0 + (-12.0 * (pr_norm - 0.35)).exp());
        score += 20.0 * awkward * (0.3 + 0.7 * progress);
        // but never open a new bin for a trivially small item
        score += 15.0 * fit_norm * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    let class = pr / (bin_capacity / 4); // quarter-classes: 0,1,2,3,4
    score += match class {
        0 => -30.0, // near-perfect fit: strongly reward
        1 => -12.0, // usable small gap
        2 => 0.0,
        3 => 8.0,   // awkward mid gap
        _ => 14.0,  // mostly empty bin used poorly
    };

    // Modulo-10 dead-space penalty: residuals not expressible as typical item sums
    // (items 1..100; multiples of 10 are common anchors).
    if pr % 10 != 0 && pr > 0 {
        score += 3.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 && pr >= next_item_size {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - slack as f64 / cap_f);
        }
    } else if next_item_size > 0 {
        // next item can't fit here: mild penalty if this bin becomes stranded
        score += 5.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing residuals are large or
    // the item is big relative to remaining capacity.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap_f;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap_f * 0.35 + 25.0 * pressure - 15.0 * (item_size as f64 / cap_f) + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    // Small global tie-breaker favoring denser packing as stream progresses.
    score -= 0.01 * (step_index as f64 % 7.0);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are pure waste.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        // Perfect fill: strong reward.
        score -= 60.0;
    } else if post_residual <= 20 {
        // Small gap likely unusable: heavy penalty.
        score += 35.0;
    }

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: next item can still use this bin; reward proportional to usefulness.
            score -= 8.0;
        } else {
            // Gap stranded relative to lookahead: penalize the stranded amount.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage proliferation of open bins; favor consolidating
    // into existing bins, especially when many are open.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).sqrt() * 1.5;
    } else {
        // New-bin candidate: add a base opening cost so it only wins on good long-term
        // prospects (large residual preserved for future items).
        score += 12.0;
        // A fresh bin is more attractive early in the stream (more future items to fill it)
        // and when existing bins are quite full on average.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        score += (mean_residual / bin_capacity as f64).max(0.0) * 8.0;
        // If the current item nearly fills the fresh bin, that's a decent deal.
        if item_size >= bin_capacity * 7 / 10 {
            score -= 10.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (best-fit flavor).
    score += ((bin_residual - item_size) as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize brand-new bin candidate so existing bins are preferred,
    // unless this is a forced last-resort situation.
    if bin_residual == bin_capacity {
        score += 1000.0;
        if fitting_bins_count <= 1 {
            // No (or single) open bin fits: opening a new bin is acceptable,
            // reward a fresh bin that can still host the next item.
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 600.0;
            }
        }
        return score;
    }

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect match: bin is exactly consumed by the next item.
            score -= 250.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: good continuation.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.6 * slack.min(50.0);
        } else {
            // Dead space for the lookahead item: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.9 * gap;
        }
    }

    // Reward tight fits relative to current item.
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * 50.0;

    // Compare against mean residual: prefer bins that get closer to average fill.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 180.0;
        if post_residual < next_item_size && next_item_size > 0 {
            score += 40.0; // still creates dead space, soften the reward
        }
    }

    // Late in the stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 1 && progress > 0.7 {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize post residual that is too small to fit any plausible item (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins with residual below mean residual (fill emptier-of-space bins first)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Early in the stream: mildly discourage opening too many bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later; also penalize if open bins are few
        score += 18.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // Existing bins get a mild bonus that grows with stream progress (consolidation)
        score -= 4.0 * progress;
    }

    // Penalize very fragmented residuals (many open bins with mid-size residual)
    if bin_residual > 30 && bin_residual < 60 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);

    // Base: tight fits (small post_residual) are favored.
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes increasingly costly.
    let norm_post = post / cap;
    let prog2 = progress * progress;
    score += 18.0 * norm_post * norm_post * (0.4 + prog2) * cap * 0.05;

    // Reward near-perfect fills (post_residual small relative to capacity).
    if post == 0 {
        score -= 25.0;
    } else if norm_post < 0.1 {
        score -= 12.0 * (0.1 - norm_post) / 0.1;
    }

    // Penalize leaving residuals that are hard to reuse: compare against next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            // next item cannot fit here; this residual is likely dead space.
            score += 6.0 * (nxt - post) / cap * 10.0;
        } else if nxt <= post {
            // lookahead fits: reward keeping usable space.
            score -= 4.0 * (post - nxt) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded.
    let is_new_bin = (bin_residual as u32 == bin_capacity) && item_size <= bin_capacity;
    if is_new_bin {
        let crowding = mean_residual / cap;
        score = cap * 0.9 + 30.0 * (1.0 - crowding);
        // Early in stream, opening fresh bins is cheaper; late, avoid it.
        score += 20.0 * (1.0 - progress);
    }

    // Mild preference to spread load when many bins are open and residuals large.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: dead-space classes 1..9 (non-decade)
    // are hard to fill with items >= 10, so penalize them; decade residuals are reusable.
    let cls = post_residual % 10;
    if post_residual > 0 {
        if cls == 0 {
            score -= 6.0; // clean decade residual, very reusable
        } else if cls <= 4 {
            score += (5 - cls) as f64 * 2.0; // small dead space, nearly useless
        } else {
            score += (cls - 4) as f64 * 0.8; // larger awkward class, moderately bad
        }
    } else {
        score -= 15.0; // perfect closure of the bin
    }

    // Very tight fits (post_residual <= 5) are excellent: strong reward.
    if post_residual <= 5 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
        // Harmonic check: next item leaves a decade residual too
        let ncls = (post_residual - next_item_size) % 10;
        if ncls == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 2.0; // residual too small for lookahead: dead space likely
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (which would strand this residual forever).
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;
    if open_bins_count > 8 {
        score -= 1.5; // too many open bins: favor filling existing ones
    }

    // New-bin candidate detection: residual equals capacity means empty bin.
    // Give it a mild handicap so tight existing fits win, but it remains
    // attractive when every open bin would leave large awkward residuals.
    if bin_residual == bin_capacity {
        score += 6.0;
        // An empty bin is fine if the item is large (small post_residual)
        if post_residual <= 20 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any future item (min item size 1, but practically small gaps < 10)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        // Perfect fit is gold: reward strongly.
        score -= 60.0;
    }

    // Tight fit reward relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: discourage proliferation of bins, but only mildly so
    // it never overrides dead-space avoidance.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is large and would leave this bin wasted anyway, slight
    // preference to consume the bin now.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 5.0;
    }

    // New-bin candidate handling: only attractive when all open bins would
    // create bad dead space or the stream is early with few bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // If existing bins are fragmented (high mean residual spread vs fit),
        // opening a fresh bin becomes more attractive.
        let would_waste = fitting_bins_count == 0
            || (post_residual < 10 && fitting_bins_count <= 2);
        if would_waste {
            score -= 45.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild alignment with mean residual: prefer bins whose residual is below
    // average (they are the "tighter" bins).
    let residual_diff = mean_residual - bin_residual as f64;
    score += residual_diff * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer post_residual that exactly matches the next item (2-step lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (100.0 / (1.0 + diff)) * 0.5;
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize post_residual just below next item size (unusable for lookahead).
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // Last item: just minimize wasted space.
        score -= 10.0;
    }

    // Penalize large dead space relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - pr) * 0.1;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
        if post_residual <= 10 {
            score -= 20.0; // near-perfect fill
        }
    }

    // Reward tight fits overall.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 15.0;

    // New-bin candidate (empty bin): penalize so it is chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is huge and would leave tiny residue anywhere, opening fresh is fine.
        if item_size >= 80 {
            score -= 15.0;
        }
    }

    // Slight preference early in the stream to keep bins flexible (small post_residual is still primary).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that leave little waste.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating tiny unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover too small for next item: mild penalty scaled by progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
    }

    // Last-chance bonus: if this is the only bin that fits, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer reusing existing bins over opening new ones; scale with congestion.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 3.0;
    }

    // Global-state coupling: bins far below the mean residual are worth filling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Late-stream: consolidate into fewer bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: early on tolerate loose fits,
    // late in the stream penalize wasted space more aggressively.
    let prog_coupling = 0.5 * progress * (1.0 + norm_pr * (1.0 - progress));
    score += prog_coupling * pr;

    // Lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack) * (0.5 + 0.5 * progress);
        } else {
            // Post-residual too small for lookahead: dead-space penalty, smooth ramp.
            let dead = (nxt - pr) / nxt.max(1.0);
            score += 4.0 * dead * dead * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        // Mild penalty when many bins compete: prefer the tightest, already handled by base.
        score += 0.5 * (fitting_bins_count.min(10) as f64 - 1.0).ln().max(0.0);
    }

    // Mean-residual context: if this bin is far below mean residual, it's a good filler target.
    let dev = (mean_residual - pr) / cap;
    score -= 2.0 * dev * (1.0 - dev * dev).max(0.0);

    // New-bin candidate: penalize opening a new bin unless residuals are all tight.
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 5.0 * (1.0 - mean_norm * mean_norm) * (0.3 + 0.7 * progress);
        if next_item_size > 0 && post_residual >= next_item_size as f64 {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 bands (capacity fractions)
    let band = post_residual % 10;
    // Small leftover bands are "dead space" -> penalize
    if band > 0 && band < 5 {
        score += (5 - band) as f64 * 2.5;
    } else if band == 0 {
        // Perfect harmonic alignment: reward
        score -= 6.0;
    }

    // Reward filling bin so post_residual matches next item exactly (perfect chaining)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits: mild reward proportional to harmony
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= (10 - gap) as f64 * 0.6;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit after this placement: penalize dead space
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it's clearly better
    if bin_residual == bin_capacity {
        // Base penalty for new bin; reduce penalty if many bins and mean residual is fragmented
        let mut new_bin_penalty = 20.0;
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            // existing bins are too full on average -> opening new bin more acceptable
            new_bin_penalty -= 8.0;
        }
        if fitting_bins_count == 0 {
            new_bin_penalty -= 25.0; // no alternative
        }
        // Prefer new bin when post_residual of this placement would be tiny (tight fit elsewhere)
        score += new_bin_penalty;
        // Harmonic alignment of new bin with item: reward if item divides capacity nicely
        if bin_capacity % item_size.max(1) == 0 {
            score -= 4.0;
        }
    }

    // Tight fit reward: post_residual close to zero but nonzero
    if post_residual > 0 && post_residual <= 3 {
        score -= 5.0;
    }

    // Progress coupling: late in stream, consolidate harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Penalize bins whose residual is far above mean (keeps balance, saves tight bins)
    let diff = bin_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += diff * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit
    // even the smallest plausible item are wasted space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Partially usable gap: moderate penalty scaled by gap smallness
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 25.0 / (1.0 + fit_ratio * fit_ratio * 4.0);

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading
    // (favor consolidating into fewer bins); when few bins, opening is cheap.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer a new bin only when the current fit is bad and many bins exist.
    if bin_residual == bin_capacity {
        // Base new-bin score: neutral, slightly above a good fit
        let mut nb = 45.0 + open_bins_count as f64 * 0.3;
        // If lookahead item could pair with this new bin's residual,
        // opening is more attractive.
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            nb -= 12.0;
        }
        // Late in the stream, avoid opening new bins unnecessarily.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb += progress * 15.0;
        score = score.min(score) * 0.0 + score; // keep placeholder
        // Return new-bin score directly for this candidate
        return nb;
    }

    // Lookahead synergy: if the post_residual exactly matches the next
    // item size, this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 6.0;
    }

    // Prefer bins with below-mean residual (consolidate fullness)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step fit: post_residual exactly matches next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect fit for the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 5.0 {
            score -= 25.0 - 3.0 * gap;
        }
        // Penalize post_residual that is too small to ever fit the next item (dead space).
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    }

    // Prefer tight fits for the current item: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Compare against mean residual: filling a large-residual bin is cheap.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: mildly penalized so we prefer reusing open bins,
    // but attractive when the fit would create large dead space.
    if bin_residual == bin_capacity {
        score += 8.0;
        if post_residual > 40 {
            score += 0.2 * (post_residual as f64 - 40.0);
        }
    }

    // Early in the stream, be more willing to open bins for better structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // next item won't fit here; mild penalty for fragmenting
            score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in the stream, prefer opening new bins to keep flexibility;
    // late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream progresses and when many bins open.
        score += 30.0 + 50.0 * progress + 2.0 * open_bins_count as f64;
        // But if no open bin fits well, opening is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin: reward usage more later in the stream.
        score -= 20.0 * progress;
        // Prefer bins whose residual is close to the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    // Prefer filling larger-residual bins when item is large (avoid stranding big holes).
    if item_size > 50 {
        score -= 0.2 * bin_residual as f64;
    }

    // Slight preference for bins that fit the item among many (keep choices open).
    if fitting_bins_count > 1 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: post residual (waste) with non-linear quadratic/quartic shaping.
    let mut score = post + 0.008 * post * post;

    // Smooth polynomial coupling of waste with stream progress:
    // early on, waste is cheap; later, dead space becomes costly.
    let progress_coupling = (1.0 + 2.5 * progress) * (post / cap).powi(2) * cap * 0.6;
    score += progress_coupling;

    // Cubic interaction term: reward tight fits more strongly as stream advances.
    let tightness = 1.0 - (post / cap);
    score -= 30.0 * progress * tightness.powi(3);

    // Last-chance bin bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 20.0 * progress;
    }

    // Penalize bins far from mean residual (keeps bin states homogeneous).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 15.0 * (1.0 - ((post - nxt) / cap).abs());
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 0.02 * (nxt - post);
        }
    }

    // New-bin candidate: make it unattractive unless it is genuinely better.
    if bin_residual == bin_capacity {
        score += 55.0 + 45.0 * (1.0 - progress) + 0.1 * open_bins_count as f64;
        // Allow opening a new bin when post_residual would be very small in existing bins
        // is already handled by the waste terms above.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the residual space (capacity / 8 buckets).
    let class = post_residual / (bin_capacity / 8);
    score -= class as f64 * 3.0;

    // Penalize dead space that cannot hold the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if post_residual is exactly next_item_size (perfect chain).
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if the current item is huge relative to mean residual, opening fresh is fine.
        if (item_size as f64) > mean_residual + 5.0 {
            score -= 35.0;
        }
    }

    // Prefer filling bins with larger residual when many bins are open (bin consolidation).
    score += (bin_residual as f64) * 0.05;

    // Slight preference to use more-open-bins states efficiently early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // Modulo bonus: residuals that are multiples of common item sizes (10s) stay reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the minimum item (1..MIN_USABLE) are pure waste -> heavy penalty.
    const MIN_USABLE: u32 = 10;
    if post_residual > 0 && post_residual < MIN_USABLE {
        score += 60.0 + 8.0 * (MIN_USABLE - post_residual) as f64;
    }

    // Tight fit reward: the smaller the post_residual within usable range,
    // the better (perfect fills get big discount).
    if post_residual == 0 {
        score -= 55.0; // perfect fill
    } else {
        let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
        score -= 30.0 * fill_frac * fill_frac;
    }

    // Penalize creating a residual that cannot fit the lookahead item
    // if the next item could have fit here (wasted opportunity).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 12.0;
        }
        // Reward residual that still accommodates the next item nicely.
        if post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins; but when
    // many bins are open, avoid dumping into near-full bins unnecessarily.
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate handling: only attractive when the item is large
    // relative to capacity or existing fits are poor.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 - 40.0 * large;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
    }

    // Mild progression term: late in the stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next == 0 {
            score -= 90.0; // perfect 2-item chain fill
        } else {
            score -= 45.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use what's left; penalize proportionally.
        let wasted = post_residual as f64 / next_item_size.max(1) as f64;
        score += 25.0 * wasted.min(3.0);
    }

    // Prefer bins with residual below mean residual (denser bins stay dense).
    let mean_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 20.0 * mean_gap;

    // Last-chance bin: only open bin that fits -> strong preference to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when no good existing fit exists
    // (e.g., item is huge relative to mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (item_size as f64 / bin_residual as f64) > 0.9;
        let no_fits = fitting_bins_count == 0;
        if poor_fit || no_fits || (open_bins_count == 0) {
            score -= 70.0; // opening a fresh bin is fine
        } else {
            // Discourage wasting a fresh bin when open bins can absorb the item.
            score += 35.0 + 40.0 * (1.0 - progress);
        }
    }

    // Mild bonus for filling nearly-full bins completely.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild superlinear push.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    // Progress horizon: early on, keep bins flexible (avoid tiny residuals);
    // late in the stream, greedily fill bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * post_residual as f64 * 0.5;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 && post_residual < 10 {
            // small dead space: mildly penalize
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Crowding: with many open bins, encourage consolidation into existing bins.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin — prefer filling it to keep the pool uniform.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // New-bin candidate handling: an empty bin must not win unless existing
    // fits are bad. Penalize opening a new bin, more so early on and when
    // other bins fit.
    if bin_residual == bin_capacity {
        let base_penalty = 55.0 + (1.0 - progress) * 25.0;
        let crowd_penalty = if fitting_bins_count > 0 { fitting_bins_count as f64 * 6.0 } else { 0.0 };
        // If the item would leave a large awkward residual in any existing bin,
        // opening a fresh bin becomes more attractive (penalty shrinks).
        let awkward = (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;
        score += base_penalty + crowd_penalty - awkward;
        // Never open a new bin for a near-perfect fit situation elsewhere.
        if post_residual <= 5 && fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Exact fill is always ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; later, punish dead space quadratically.
    let pr_norm = pr / cap;
    score += pr_norm * pr_norm * cap * (0.5 + 1.5 * progress);

    // Smooth fill-ratio reward: item filling bin well is favored, scaled by progress
    let fill = it / r.max(1.0);
    score -= fill * fill * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead coupling: reward leaving room for the next item (smooth quadratic mismatch)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score -= (1.0 - diff * diff) * 2.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins vs mean residual
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);
    score += 0.02 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: heavily favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Harmonic class of post_residual: dead space that no plausible item (1..=100)
    // can use well. Penalize small unusable slivers, reward leaving "harmonic"
    // residuals (multiples of common item sizes).
    let pr = post_residual;
    if pr > 0 {
        // sliver penalty: residuals 1..=9 are nearly dead space
        if pr < 10 {
            score += 40.0 * (10 - pr) as f64;
        }
        // harmonic reward: post_residual divisible by 10 or 20 leaves reusable space
        if pr % 10 == 0 {
            score -= 15.0;
        }
        if pr % 25 == 0 {
            score -= 10.0;
        }
        // integer division threshold: residual in [10, 30] is a sweet spot
        // (fits half of small items) vs [31, 60] medium vs [61, 100] large
        let class = pr / 10;
        match class {
            1 => score -= 12.0,
            2 => score -= 8.0,
            3 => score -= 4.0,
            _ => {}
        }
    } else {
        // perfect fill
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly into the post_residual,
    // this is a great chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let npr = post_residual - next_item_size;
            if npr % 10 == 0 {
                score -= 20.0;
            }
            score -= 5.0 * (npr as f64 / cap);
        } else {
            // post_residual too small for next item: penalize proportionally
            score += 8.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no good
    // fit exists. Base new-bin penalty proportional to stream progress and
    // current bin count.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // allow new bin when item is huge relative to residual of typical bins
        if item_size >= 70 && fitting_bins_count <= 1 {
            score -= 70.0;
        }
    }

    // Mild preference to consolidate: bins with below-mean residual are more
    // "wasted" — placing there evens out residuals.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can't fit the smallest plausible item are worthless.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 4.0 } else if post_residual < item_size { 2.0 } else { 0.0 };
        score += dead * (post_residual as f64);
    }

    // Reward tight fits (near-zero post residual).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make it costly unless residual would be genuinely useful later.
    if bin_residual == bin_capacity {
        let base = 25.0 + 0.6 * open_bins_count as f64;
        // If next item would fit in the fresh bin too, opening is slightly better.
        let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual { 8.0 } else { 0.0 };
        score += base - lookahead_bonus;
    }

    // If the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // dead space for the known next item
    }

    // Slight preference for bins below mean residual (balance spreading).
    score -= 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect lookahead match (item fits with small slack for next item).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 40.0 - 3.0 * slack;
        } else {
            score -= (100.0 / (1.0 + slack)) * 0.5;
        }
    }

    // Penalize dead space: residuals too small to fit typical items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (tighter bins) so looser bins remain for larger future items.
    let diff = mean_residual - post_residual as f64;
    score += diff * 0.3;

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty discourages wasteful bin opening.
        score += 20.0;
        // But if this is the last fitting option (i.e., all open bins are poor),
        // allow opening a fresh bin.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // If next item is large, a fresh bin with full capacity is valuable.
        if next_item_size > 0 && next_item_size > item_size {
            score -= (next_item_size as f64 - item_size as f64) * 0.4;
        }
    }

    // Slight preference to fill bins with more items already (fewer open bins better).
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strong reward, zero dead space is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.6 * next_item_size as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Penalize "wasting" a large-residual bin on a small item (creates dead space
    // proportional to leftover potential weighted by item smallness).
    let slack = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.15 * slack * (item_size as f64 / bin_capacity as f64);

    // Time-horizon coupling: as the stream progresses, prefer placements that
    // leave compact residuals (fill bins tighter late in the stream).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global-state coupling: mildly prefer bins whose residual is below the mean
    // (consolidate fullness across open bins).
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: baseline score so a fresh bin is chosen only
    // when no open bin offers a decent fit; slight preference for larger items
    // to seed new bins with big pieces.
    if bin_residual == bin_capacity {
        score = 0.9 * bin_capacity as f64 - 0.3 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 10.0; // no alternative: opening a bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tight fit preferred (low post_residual).
    let mut score = post;

    // Non-linear coupling: quadratic dead-space penalty grows with stream progress
    // (late in the stream, wasted space is costlier to amortize).
    let tight = post / cap;
    score += tight * tight * cap * (0.5 + progress);

    // Reward placing into a bin when it is the last chance to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; keep flexibility.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit here: penalize residuals just below next size (dead space).
            let miss = (nxt - post) / cap;
            score += 6.0 * miss * miss * cap;
        }
    }

    // Prefer filling bins that are already relatively empty vs. the fleet mean:
    // steer consolidation toward low-residual bins.
    score += 0.15 * (mean_residual - post);

    // Slight preference to use more-open-bins states early (spread) and
    // consolidate later via progress-coupled term on bin count.
    score += 0.5 * open_bins_count as f64 * (0.2 + progress);

    // New-bin candidate (empty bin): only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral base plus penalty that shrinks as fits elsewhere get worse.
        // If item fits badly in existing bins (large post_residual elsewhere),
        // opening a new bin becomes competitive.
        score = 0.55 * cap + 0.25 * item_size as f64 - 0.1 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in stream, prefer reusing existing bins: raise new-bin cost.
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in "useful" classes
    // (multiples of 10 / half-classes) are preferred since future items (1..100) are
    // more likely to fit exactly into coarser residual classes.
    let pr = post_residual;
    let coarse = pr % 10 == 0;
    let half = pr % 5 == 0;
    if coarse {
        score -= 6.0;
    } else if half {
        score -= 2.5;
    } else {
        // penalize awkward residuals, worse for tiny odd leftovers
        score += ((pr % 5) as f64) * 0.8;
    }

    // Dead-space penalty: residuals too small to fit typical future items
    if pr < 10 && pr > 0 {
        score += 12.0;
    }
    if pr == 0 {
        score -= 15.0; // perfect packing is best
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match: next item's class vs residual class
            if pr % next_item_size.max(1) == 0 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; leftover smaller than next item is dead weight
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin is a fallback; make it attractive only
    // when the post_residual here would be a poor class (wasteful placement).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0;
        // but if placing here would leave an awkward residual, opening fresh is better
        if pr > 0 && pr < 10 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size > pr && pr > 0 && pr < next_item_size {
            score -= 5.0;
        }
    }

    // Stream progression: late in the stream, prefer tightening packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (pr as f64) * 0.05;

    // Prefer bins tighter than average (best-fit flavor with harmonic twist)
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Many open bins: encourage filling existing ones rather than spreading
    score += (open_bins_count as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Reward filling bins that are already mostly full.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: more open bins -> prefer using existing ones,
    // penalize keeping many bins open with large residual.
    score += 3.0 * open_bins_count as f64;
    score += 0.5 * mean_residual;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current bin
    // would leave a large unusable gap or fit is very poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 35.0;
        // If the item fits tightly in a fresh bin (near-perfect division),
        // opening a new bin can be attractive (e.g., item_size near capacity).
        if item_size >= bin_capacity * 3 / 4 {
            score -= 45.0;
        }
        // If the fit in existing bins is terrible (huge dead space), allow new bin.
        if post_residual < 10 && item_size > 50 {
            score -= 30.0;
        }
    }

    // Lookahead: if next item could exactly fill this bin's post_residual,
    // reward placing current item here.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // If next item would fit better in a fresh bin than in this bin's leftover,
    // mildly penalize leaving awkward gaps.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Early in the stream, be slightly more willing to open bins (build a pool).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post residual can at least accommodate the next item: good chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Post residual too small for next item: dead-space penalty scaled by how close it came.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 1.5 * waste;
    }

    // Penalize tiny unusable residuals (dead space), unless it's a perfect match already rewarded.
    if post_residual > 0 && post_residual < 10 && !(next_item_size > 0 && post_residual == next_item_size) {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: neutral baseline, only attractive when open bins are badly fragmented
    // or this is a large item better isolated.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 55.0 + 30.0 * fragmentation - 10.0 * progress;
        // Isolate large items into fresh bins.
        if item_size >= 70 { score -= 15.0; }
        // Avoid proliferating bins early when open bins fit reasonably.
        if next_item_size > 0 && post_residual >= next_item_size { score += 20.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 25.0 + 30.0 * (1.0 - t) - 10.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        return score;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tight * tight;

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            score -= 20.0 / (1.0 + gap / 10.0);
        } else {
            score += 5.0 * (1.0 - gap / (bin_capacity as f64));
        }
    } else {
        // Last item: just fill as much as possible.
        score -= item_size as f64 * 0.1;
    }

    // Prefer bins below mean residual (balance), scaled by stream progress.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev * (0.5 + 0.5 * t);

    // Slight preference for bins in crowded regimes.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress:
    // later in the stream, residual waste matters more (tighter packing).
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let poly = pr_norm * (1.0 + progress * pr_norm * 2.0 + progress * progress * pr_norm * 2.0);
    score += poly * 30.0;

    // Reward filling the bin almost completely (post_residual small relative to item)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * fill_ratio * 25.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when open bins fit well
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, scaled with number of open bins and mean residual
        let mut nb = 40.0 + open_bins_count as f64 * 3.0;
        // If mean residual is large, opening a new bin wastes existing space
        nb += mean_residual * 0.5;
        // Lookahead: if next item fits into typical residual, prefer using open bins
        if next_item_size > 0 {
            let n = next_item_size as f64;
            if n <= mean_residual {
                nb += 35.0 * (1.0 - progress * 0.5);
            } else {
                nb -= 10.0;
            }
        }
        // Early in stream, new bins are cheaper; late in stream, consolidate
        nb *= 1.0 - 0.3 * progress;
        score += nb;
    } else {
        // Lookahead synergy: reward leaving residual that exactly fits the next item
        if next_item_size > 0 {
            let diff = (pr as i64 - next_item_size as i64).abs() as f64;
            score -= 15.0 * (1.0 - diff / cap).max(0.0);
        }
        // Mild penalty when many bins fit (less urgency) — prefer tightest anyway via post_residual
        score += (fitting_bins_count as f64).min(5.0) * 2.0;
    }

    // Non-linear penalty for very small unusable residuals (dead space)
    if pr < 10.0 {
        score += (10.0 - pr as f64) * (10.0 - pr as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Harmonic class logic: classify post_residual into residue classes
    let pr = post_residual as i64;
    let nis = next_item_size as i64;

    // Reward when next item exactly fills the post residual (perfect chain)
    if nis > 0 && nis == pr {
        score -= 300.0;
    } else if nis > 0 && pr >= nis {
        // next item fits: reward proportionally to how much slack remains after
        let after_next = pr - nis;
        if after_next <= 10 {
            score -= 120.0;
        } else {
            score -= (after_next as f64) * 0.5;
        }
    } else if nis > 0 && pr < nis {
        // dead space for the next item: penalize based on modulo class of gap
        let gap = nis - pr;
        let gap_mod = gap % 10;
        let class_penalty = match gap_mod {
            0 => 40.0,   // gap is a multiple of 10: likely fillable later
            1..=3 => 70.0,
            4..=7 => 55.0,
            _ => 60.0,
        };
        score += class_penalty + (gap as f64) * 0.3;
    }

    // Integer-division thresholds on post_residual: small residuals are dead space
    if pr > 0 && pr <= (bin_capacity as i64) / 10 {
        score += 90.0; // residual below 10% capacity is nearly unusable
    } else if pr > (bin_capacity as i64) * 2 / 5 && pr < (bin_capacity as i64) * 3 / 5 {
        // mid-range residual: keep flexible, mild bonus
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 250.0;
        // but if no open bin fits, opening is fine
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        // lookahead: if next item is large, a fresh bin is valuable
        if nis >= 50 {
            score -= 60.0;
        }
    }

    // Prefer fuller bins overall: use mean residual as reference
    let mean_r = mean_residual;
    if (bin_residual as f64) < mean_r {
        score -= 20.0; // below-average residual => bin is fuller, favor it
    } else {
        score += 10.0;
    }

    // Slight preference for compact bin collections early in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver => heavy penalty
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward very tight fits (post_residual small relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 6.0 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item would fit the post residual exactly-ish, reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot use the gap: dead space likely
            score += 5.0;
        }
    }

    // New empty bin candidate: expensive, only attractive for large items
    // or when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.35 * (open_bins_count as f64);
        // large items pack cleanly into fresh bins
        let size_bonus = if item_size >= 70 { -20.0 } else if item_size >= 50 { -5.0 } else { 15.0 };
        // if existing bins fit poorly (large mean residual but item small), discourage new bin less
        let spread = (mean_residual - post_residual as f64).abs();
        score = base + size_bonus + 0.2 * spread;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small for typical items (1..100, min 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: brand-new empty bin must lose unless all
    // open bins give poor fits.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            post_residual as f64 - next_item_size as f64
        } else {
            post_residual as f64
        };
        // Base penalty: opening a new bin is discouraged.
        score += 35.0;
        // But if the fit here is actually cleaner than existing bins
        // (item nearly fills a fresh bin), allow it occasionally.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 50.0;
        }
        // Late in the stream, be more conservative about new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        let _ = poor_fit;
    }

    // Mild preference to fill already-open bins as stream progresses.
    score -= 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Perfect pairing: item + next item exactly fills residual.
        if item_size + next_item_size == bin_residual {
            score -= 35.0;
        }
    }

    // New-bin candidate logic: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening bins early in the stream when many bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // If this is the only fitting option, soften the penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Large items justify a fresh bin more readily.
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    // Prefer bins deviating favorably from the mean residual (fill fuller-than-average bins).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Mild preference for bins with small residual overall (best-fit flavor).
    score += 0.05 * bin_residual as f64;

    // Late in stream: consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    let mut score = pr * (1.0 + 0.8 * progress_poly);

    // Reward tight fits non-linearly
    score -= 30.0 * fill * fill * (1.0 + 0.5 * progress_poly);

    // Penalize dead space that is too small to be useful later (non-linear)
    let dead = pr / cap;
    score += 25.0 * dead * (1.0 - dead) * (1.0 - dead);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - fit_ratio);

    // New-bin candidate: penalize so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * (1.0 - fill) * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how it partitions capacity
    let post = post_residual;
    let class = if post == 0 { 0 } else { post % 10 };
    let div_class = if post == 0 { 0 } else { post / 10 };

    // Perfect fit: huge reward
    if post == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: post_residual too small for the smallest item (1)
    // but we still penalize tiny unusable slivers relative to typical min item
    if post > 0 && post < 10 {
        score += 60.0;
    }

    // Harmonic class bonus: post_residual divisible by common item classes
    if post > 0 && (post % 10 == 0 || post % 20 == 0 || post % 25 == 0 || post % 50 == 0) {
        score -= 12.0;
    } else if class <= 2 && div_class > 0 {
        score += 4.0; // awkward leftover
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post >= next_item_size {
        let slack = post - next_item_size;
        if slack == 0 {
            score -= 80.0;
        } else if slack < 10 {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post > 0 {
        // next item won't fit here; penalize leaving large stranded space
        if post >= 30 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): must be penalized so we only open when
    // existing fits are poor. Base penalty scaled by stream progress and load.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap * (0.6 + 0.4 * progress) + 50.0;
        // Allow opening a new bin if current item barely fits anywhere and
        // the next item is large (avoid trapping small residuals)
        if next_item_size > 0 && next_item_size >= 60 && item_size >= 50 {
            score -= 70.0;
        }
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Mild preference for tighter bins when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - (bin_residual as f64 / cap));

    // Mean residual alignment: prefer bins near the mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residual gaps that are too small
    // to be useful (likely below the minimum item size of 1..100 stream,
    // treat gaps < 20 as near-dead, gaps < 35 as risky).
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 200.0;
    } else if post_residual < 20 {
        // Unusable dead space: heavy penalty.
        score += 60.0 + pr;
    } else if post_residual < 35 {
        // Risky gap: moderate penalty.
        score += 15.0 + 0.5 * pr;
    } else {
        // Usable gap: mild reward for larger usable space.
        score -= 0.1 * pr;
    }

    // Reward tight fits relative to residual (small waste fraction).
    let waste_frac = pr / bin_residual.max(1) as f64;
    score += 30.0 * waste_frac;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, encourage filling rather than opening new.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score += 2.0 * (open_bins_count as f64).powf(1.1) * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless post_residual is dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make the empty bin attractive only when the item
    // is large or existing residuals are poor. Base penalty for opening new.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * (open_bins_count as f64);
        // If next item is large, keeping flexibility is valuable: reduce penalty.
        if next_item_size >= 50 {
            score -= 20.0;
        }
        // If mean residual across open bins is small, opening fresh is fine.
        if mean_residual < 25.0 {
            score -= 30.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement (sets up a perfect follow-up fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 40.0;
        } else if gap < 25.0 {
            score -= 15.0;
        }
    }
    // If next item would NOT fit here but fits nowhere else either,
    // keeping this bin tight is fine; slight penalty otherwise for
    // leaving a gap that blocks the lookahead item.
    else if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Perfect chain: next item exactly fills the remainder.
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
        // Avoid leaving residual the next item cannot use at all.
        if next_item_size > post_residual {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    } else {
        // Last item: prefer tightest fit, no lookahead needed.
        score -= 10.0;
    }

    // Penalize tiny dead space (unusable fragments).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last chance: this is the only bin that fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    // New empty bin candidate: penalize opening a new bin unless current
    // placement would create large dead space.
    if bin_residual == bin_capacity {
        score += 35.0;
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 20.0; // opening is fine if this bin would stay mostly empty anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-full packing
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize small dead space that is unlikely to fit typical future items.
    // Dead space in (0, 10) is almost unusable since min item is small but
    // fragmentation hurts; scale penalty by how "wasted" the gap is.
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        if waste < 0.10 {
            score += 8.0 * (0.10 - waste) * 10.0; // small gap: strongly penalize creating it
        } else {
            score += 2.0 * waste; // large leftover: mild penalty
        }
    } else {
        score -= 15.0; // perfect fit: strongly favored
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size {
            score -= 3.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here; mild penalty proportional to leftover
            score += 1.5;
        }
    }

    // New-bin candidate handling: opening a new bin wastes residual capacity
    // of existing bins. Penalize unless existing bins are poor fits or the
    // item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 10.0;
        if fitting_bins_count == 0 {
            new_bin_penalty -= 20.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            new_bin_penalty += 6.0; // last chance elsewhere: keep existing bin attractive
        }
        // If mean residual across open bins is large, we can absorb the item:
        // penalize new bin more.
        new_bin_penalty += 0.15 * mean_residual;
        // Large items late in stream: prefer consolidating into open bins.
        new_bin_penalty += 0.05 * item_size as f64 * (1.0 - progress);
        // Few open bins early: opening is cheaper.
        if open_bins_count > 4 {
            new_bin_penalty += 2.0;
        }
        score += new_bin_penalty;
    }

    // Time-horizon modulation: early on, be slightly greedy for tight fits;
    // late, prioritize minimizing bin count via last-chance usage.
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize leftover space, with non-linear (quartic) shaping
    let mut score = pr as f64 * (1.0 + 0.8 * x * x);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight packing matters more -> weight leftover more
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 2.0; // peaks mid-stream
    score *= 0.5 + 0.5 * progress_coupling * (1.0 + progress);

    // Reward near-perfect fits smoothly
    let tightness = 1.0 - x;
    score -= 30.0 * tightness * tightness * tightness;

    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize bins that deviate from mean residual (fragmentation avoidance)
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // Slight preference to fill already-open bins as count grows
    score += 0.05 * open_bins_count as f64 * x;

    // New-bin candidate: discourage opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 25.0 - 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo a base of 10: residuals that are
    // multiples of 10 are "harmonious" (likely reusable by future items).
    let harmonic = post_residual % 10;
    if harmonic == 0 {
        score -= 6.0; // perfectly aligned residual
    } else if harmonic <= 3 {
        score += 2.0 + harmonic as f64; // small dead-space slivers
    } else if harmonic >= 8 {
        score += 1.0; // nearly aligned but wasteful
    }

    // Integer-division thresholds: residual in "big half" vs "small half"
    if post_residual > bin_capacity / 2 {
        score -= 4.0; // bin still broadly usable
    } else if post_residual >= bin_capacity / 4 {
        score += 1.5; // mid-range residual, moderately useful
    } else {
        score += 5.0; // small residual, near-dead bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves a bad harmonic residue
        let next_post = post_residual - next_item_size;
        if next_post % 10 == 0 {
            score -= 8.0;
        } else if next_post > bin_capacity / 2 {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize leaving tight unusable gap less
        // if post_residual is large (bin stays attractive for later items)
        if post_residual >= next_item_size * 2 {
            score -= 2.0;
        } else if post_residual < 10 {
            score += 3.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin is a good harmonic fit.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.55 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin anyway
        } else if fitting_bins_count == 1 {
            score += 10.0; // keep the last-chance bin in play
        }
        // early stream: opening bins cheap is fine
        if (step_index as f64) / (total_items.max(1) as f64) < 0.3 {
            score -= 5.0;
        }
    }

    // Mild penalty for spreading across too many open bins
    score += (open_bins_count as f64) * 0.15;

    // Tie-break toward bins whose residual is closest to mean (balanced load)
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fitting the next item too (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item can't use the gap
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: more open bins -> prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * 0.8;

    // New empty bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual < 10 && post_residual > 0;
        if bad_fit {
            score -= 30.0; // opening a new bin beats creating dead space
        } else {
            score += 45.0; // prefer existing bins for decent fits
        }
    }

    // Late in stream: consolidate harder.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += post_residual as f64 * progress * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter residual fill is better (Best-Fit component)
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // ---- Aggressive 2-step lookahead matching ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;

        // Perfect 2-step match: next item exactly fills the post residual
        if (post_residual as u32) == next_item_size {
            score -= 60.0;
        } else if pr >= nxt {
            // Next item fits here: reward proportional closeness to exact match
            let slack = pr - nxt;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item will NOT fit in this bin: penalize leaving a gap
            // that is smaller than the next item (wasted dead space)
            let gap_ratio = pr / nxt;
            score += 10.0 * gap_ratio;
        }

        // Coupling with mean residual: bins whose post residual deviates
        // strongly from the fleet mean are less flexible for future items
        let dev = (pr - mean_residual).abs();
        score += 0.08 * dev;
    } else {
        // Last item: pure best-fit, no future to plan for
        score -= 0.5 * (bin_capacity as f64 - post_residual as f64);
    }

    // ---- Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin ----
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // ---- New-bin candidate handling (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; make it unattractive unless the
        // item is a very poor fit for everything else. Penalize by the
        // fraction of the bin that would remain empty and by how many
        // alternatives exist.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 30.0 + 40.0 * waste + 3.0 * open_bins_count as f64;

        // If no open bin fits (this is the only option), soften the penalty
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Slight preference to consolidate into fewer bins as the stream matures
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.5 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post residual is small relative to capacity.
    score -= (1.0 - post_residual as f64 / cap) * 30.0;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 18.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / cap);
        } else {
            // next item won't fit here; slight penalty proportional to wasted opportunity
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: penalize opening a new bin unless the fit in open bins is bad.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: its residual equals capacity, so add an opening penalty.
        score += 45.0;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 30.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
        }
        // Large items relative to capacity are fine to start a fresh bin.
        if item_size as f64 / cap > 0.5 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Global state: when many open bins with high mean residual exist, prefer consolidating
    // into bins with below-average residual (fill the emptier-feeling bins first).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.5;
    }

    // Mild pressure to use existing bins when few are open.
    if open_bins_count > 0 && bin_residual != bin_capacity {
        score -= 5.0 / (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mildly tolerate larger residuals (bins stay flexible).
    // Later (progress ~ 1): strongly penalize residuals, pushing tight fits.
    let tightness = 1.0 + 2.0 * progress * progress;
    score += tightness * (norm_pr * norm_pr) * 40.0;

    // Smooth reward for near-perfect fits, weighted by remaining stream.
    let fit_quality = 1.0 - norm_pr;
    score -= 30.0 * fit_quality * fit_quality * (1.0 - 0.5 * progress);

    // Lookahead coupling: penalize if the next item cannot use the post-residual,
    // smoothly scaled by how much would be wasted relative to next item.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 25.0 * gap * gap * (1.0 - progress);
        // Reward when next item exactly fits the post-residual (smooth quadratic).
        let match_q = 1.0 - ((next_item_size as f64 - pr).abs() / cap);
        score -= 15.0 * match_q * match_q * match_q;
    }

    // Last-chance bin: strong smooth bonus to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - 0.3 * progress);
    }

    // Slight preference to consolidate when many bins are open (smooth in count).
    let open_norm = (open_bins_count as f64).ln_1p();
    score += 3.0 * open_norm * norm_pr;

    // Deviation from mean residual: prefer bins that differ smoothly from average
    // to create diversity of residual sizes.
    let dev = (pr - mean_residual) / cap;
    score -= 8.0 * dev * dev;

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 60.0 * (1.0 - scarcity) * (0.5 + 0.5 * progress);
        // If it's the only fitting option (new bin), make it the natural fallback.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item sizes
    let classes: [u32; 8] = [10, 20, 25, 33, 50, 60, 75, 90];
    let mut harmonic_bonus = 0.0f64;
    for &c in classes.iter() {
        if post_residual % c == 0 && post_residual > 0 {
            harmonic_bonus += 12.0; // post residual is exactly reusable by a future class
            break;
        }
    }

    // Lookahead: does next_item_size exactly fill post_residual?
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0; // perfect closure, strongly prefer
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: reward proportional to how tightly it fits
        let tight = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - tight / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this residual: penalize proportional to leftover
        score += 8.0;
    }

    // Integer-division thresholds on post_residual
    let pr = post_residual;
    if pr == 0 {
        score -= 100.0; // perfect fill, always best
    } else if pr < 10 {
        score += 20.0; // dead space below minimum item size
    } else if pr <= 20 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Opening a new bin wastes the mean residual of existing bins
        let waste_penalty = mean_residual * 0.8 + open_bins_count as f64 * 2.0;
        score += 40.0 + waste_penalty;
        // If the item is huge relative to capacity, new bin is less bad
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        // If next item is large and nothing fits it later, fresh capacity helps
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Prefer filling bins that are already low on residual (tight packing)
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_frac * 10.0;

    // Progression: early in stream, slightly favor consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * harmonic_bonus;
    score += progress * harmonic_bonus * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (< 10) are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // next item won't fit here; penalize leaving a gap that blocks it
            score += 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        // Neutral baseline; add mild pressure so existing decent fits win.
        score += 20.0 + 1.5 * open_bins_count as f64;
        // Early in stream, opening fresh bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins far from the mean (more deterministic).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: only attractive when it enables a perfect
    // two-item pairing with the lookahead, otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0; // perfect pair: item + next fill bin exactly
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // good pair potential
        } else {
            score += 30.0; // avoid wasting a fresh bin
        }
        return score;
    }

    // Exact 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // post_residual still usable by the next item, but not perfectly.
        let waste = (post_residual - next_item_size) as f64;
        score -= 20.0 - 0.25 * waste;
    }

    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (well-filled bins).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Small bonus for high fill ratio early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * (10.0 + 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Even better if next item then fits almost exactly.
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score -= 10.0;
            }
        } else {
            // Post-residual would be wasted relative to the next item's demand.
            let slack_waste = (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
            score += 0.35 * slack_waste;
        }
    } else {
        // Last item: strongly prefer filling existing bins completely.
        score -= 30.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0 + 2.0 * open_bins_count as f64;

        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);

        // If no open bin fits (this call is the only candidate), opening is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If many open bins already have large residuals, prefer reusing them instead.
        if mean_residual > 40.0 {
            score += 0.5 * (mean_residual - 40.0);
        }
    }

    // Mild preference for bins with residuals below the mean (consolidate fuller bins).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight preference for using fuller bins as stream progresses.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fullness * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // that grows super-linearly for large leftover space (wasted capacity).
    let mut score = pr + 0.9 * (pr / cap) * pr;

    // Smooth stream-progress coupling: late in the stream, tight fits matter more,
    // so amplify the post-residual penalty as progress -> 1.
    let late = progress * progress;
    score *= 1.0 + 0.6 * late;

    // Reward bins whose post-residual closely matches the next item's size
    // (smooth Gaussian-like affinity), stronger later in the stream.
    if next_item_size > 0 {
        let gap = pr - next_ratio * cap;
        let affinity = (-(gap * gap) / (2.0 * (0.25 * cap) * (0.25 * cap))).exp();
        score -= 14.0 * affinity * (0.5 + progress);
    }

    // Penalize creating dead space that nothing typical can use:
    // smooth coupling between post-residual and mean residual of open bins.
    let dead = (pr - mean_residual) / cap;
    score += 6.0 * dead * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoid opening a new bin), scaled smoothly by how full the bin already is.
    if fitting_bins_count == 1 {
        let fill = 1.0 - (bin_residual as f64) / cap;
        score -= 20.0 * (0.4 + fill);
    }

    // Mild reward for filling bins deeply (high fill fraction), smooth in item size.
    score -= 5.0 * fit_ratio * (1.0 - pr / cap);

    // Discourage spreading across too many open bins when residuals are large.
    score += 0.4 * (open_bins_count as f64).ln() * (mean_residual / cap);

    // Slight preference for keeping a fresh empty bin available early on;
    // penalize opening a new bin when a reasonable fit exists.
    if bin_residual == bin_capacity {
        let scarcity = (-(fitting_bins_count as f64)).exp();
        score += 10.0 * (1.0 - scarcity) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the smallest plausible item (1) is worthless; anything that leaves a
    // residue too small for the lookahead item is a partial waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This residue can only be filled by items smaller than the next one.
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Harmonic class: classify post_residual by capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    if frac == 0.0 {
        score -= 8.0; // perfect fill
    } else if frac <= 0.05 {
        score -= 4.0;
    } else if frac <= 0.25 {
        score += 1.5; // awkward quarter-slab residue
    } else if frac <= 0.5 {
        score -= 0.5;
    } else {
        score += 0.25; // large residue: bin stays flexible anyway
    }

    // Integer-division threshold: residues divisible into big chunks are fine.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 0.8;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placements
    // are genuinely poor (large waste or item barely fits anywhere).
    if bin_residual == bin_capacity {
        let waste_now = mean_residual - score;
        let _ = waste_now;
        let base = cap * 0.55;
        score += base;
        if next_item_size > 0 && item_size >= next_item_size && fitting_bins_count <= 2 {
            score -= 4.0; // big item now, next is smaller: fresh bin is fine
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 3.0 * (1.0 - progress); // open bins more freely early
    }

    // Mild preference to spread load when many bins are open and mean residual is high.
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual {
        score -= 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 4.0; // tiny gap => heavily penalized
    } else if pr == 0.0 {
        score -= 25.0; // perfect fit: reward strongly
    } else if pr < 20.0 {
        score += 6.0; // moderately risky gap
    }

    // Reward filling bins that are already fairly full (low residual).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 12.0;

    // Open-bin pressure: when many bins are open, prefer consolidation.
    let open_pressure = (open_bins_count as f64).ln() * 3.0;
    score += open_pressure * (pr / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item could use the post-residual gap, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0;
    } else if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
        // gap too small for next item: penalize proportionally
        score += (pr / (next_item_size as f64)) * 5.0;
    }

    // New-bin candidate (empty bin): penalize so it is chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
        // But if the item is large, opening fresh is less bad.
        score -= (item_size as f64 / 100.0) * 15.0;
    }

    // Mild stream-progression tiebreak: later in stream, be greedier
    // about tight fits.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * (30.0 - pr).max(0.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect/near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 + 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use.
        score += 0.5 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Relative to mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last chance bin before opening a new bin: strong bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize wasting a nearly empty bin when many bins are open.
    if bin_residual != bin_capacity {
        score += 0.2 * (open_bins_count as f64);
    }

    // New-bin candidate: neutral-ish baseline, penalized unless current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 40.0;
        score += if poor_fit { 30.0 } else { 250.0 };
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Late-stream consolidation: tighten bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: small post-residual is good (less dead space), but
    // extremely small residuals (< ~10) are wasted slivers.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness;           // reward tight fits non-linearly

    // Penalize unusable slivers: post residual too small for the smallest item (1..100 range).
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post) / 10.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next > 0.0 {
        if post >= next {
            score -= 8.0 * (1.0 - (post - next) / cap);
        } else {
            // next item won't fit here; slight penalty scaled by overflow size
            score += 3.0 * ((next - post) / cap).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (new bin gets residual == cap, high base score anyway).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among several candidates, mildly prefer tighter competition scaling
        score -= 2.0 * (fitting_bins_count.min(6) as f64 - 1.0);
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins harder, penalize opening new space.
    let open = open_bins_count as f64;
    score += 0.15 * open.max(1.0).ln() * (post / cap);
    score -= 0.5 * (mean_residual / cap).max(0.0) * (1.0 - tightness);

    // Time horizon: early in the stream, keep bins flexible (prefer larger post
    // residual); late in the stream, aggressively close bins (favor tight fits).
    score += (1.0 - progress) * 6.0 * tightness;
    score -= progress * 10.0 * tightness * tightness;

    // New-bin candidate tuning: an empty bin should only win when the item is
    // large and would leave a very poor fit elsewhere.
    if bin_residual == bin_capacity {
        score += 18.0; // default penalty for opening a new bin
        // If the item is big, new bin becomes relatively more attractive.
        score -= 0.25 * item;
        // If few bins fit the item, opening fresh space is more acceptable.
        score -= 10.0 * (1.0 - (fitting_bins_count.min(4) as f64) / 4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    let t = progress * (1.0 - progress) * 4.0; // peaks mid-stream, 0 at ends
    score -= 12.0 * t * (1.0 - (pr / cap)).powi(2);

    // Reward tight fits increasingly as the stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= 20.0 * progress * tightness * tightness;

    // Penalize large post-residual dead space, quadratically.
    score += 0.15 * (pr / cap) * (pr / cap) * cap;

    // Last-chance bin bonus (smoothly weighted by fit scarcity).
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * t;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - (gap / cap).abs());
        } else {
            score += 4.0 * (-gap / cap);
        }
    }

    // Mild dispersion penalty: prefer bins near mean residual.
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).powi(2) * cap;

    // New-bin candidate: penalize slightly unless open bins are scarce.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Harmonic class of post_residual: residues mod small integers
    // classify "usable" leftover space. Residues near 0 mod 10 or mod 25
    // are more likely to host future items.
    let pr = post_residual;
    let r10 = (pr % 10) as f64;
    let r25 = (pr % 25) as f64;
    score += 0.6 * r10;
    score += 0.4 * (25.0 - r25).min(r25) * 0.5;

    // Integer division thresholds: leftover in the "dead zone" [1,9] is
    // nearly unusable (min item 1, but typical items larger).
    if pr >= 1 && pr <= 9 {
        score += 30.0;
    }
    // Sweet spot: leftover that exactly matches the next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 25.0;
        } else if pr > next_item_size && pr - next_item_size <= 5 {
            score -= 8.0;
        }
        // If next item cannot fit here at all, mild penalty unless pr tiny.
        if pr < next_item_size {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual
    // space of this empty slot; penalize unless current fit is terrible
    // or bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = mean_residual * open_bins_count as f64;
        // Base cost of a fresh bin.
        score = (bin_capacity as f64) * 0.9;
        // Early in the stream, keep open bins compact; later, allow spread.
        score -= 20.0 * progress;
        // If mean residual across open bins is small (bins nearly full),
        // a new bin is reasonable.
        score -= (mean_residual / bin_capacity as f64) * 15.0;
        // Many open bins with lots of trapped waste -> discourage new bins.
        score += waste * 0.05;
        // If item is large relative to capacity, new bin is fine.
        score -= 0.3 * item_size as f64;
    }

    // Prefer fuller bins overall: deviation from mean residual.
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual too small to ever hold the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Unusable for the known next item -> likely dead space
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0 + (next_item_size - post_residual) as f64;
    }
    // Perfect fill reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage filling
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.15 + 0.25 * progress);

    // Prefer bins with below-mean residual (tighter bins get priority)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it attractive only when current bin would leave a bad gap
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual < next_item_size && post_residual > 0;
        if bad_fit {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with mild normalization.
    let cap = bin_capacity as f64;
    score += 0.05 * (post_residual as f64 / cap) * 100.0;

    // 2-step lookahead: reward when next item fits snugly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            let slack_after_next = post - nxt;
            // Strong reward if next item exactly/nearly fills the bin (perfect 2-chain).
            if slack_after_next <= 5.0 {
                score -= 40.0 - 4.0 * slack_after_next;
            } else {
                // Reward proportional to how well next item uses the remaining space.
                score -= 8.0 * (nxt / post).min(1.0);
            }
        } else {
            // Next item won't fit here: penalize bins whose post_residual is awkwardly
            // large relative to next item (dead space likely).
            let gap = nxt - post;
            if gap < nxt {
                score += 0.10 * gap;
            }
            // Very small post_residual is fine (bin effectively closed) — small bonus.
            if post <= 5.0 {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Contextual pressure: when few bins fit the item overall, discourage opening new bins.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average.
    let mean_r = mean_residual;
    if bin_residual < bin_capacity {
        score += 0.15 * ((bin_residual as f64) - mean_r);
    }

    // Progression: early in stream, be more willing to open new bins for large items;
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses (favor consolidation).
        score += 10.0 + 20.0 * progress;
        // But if item is large and bin_residual of open bins is awkward, new bin
        // naturally scores well via post_residual; add small bonus early.
        if progress < 0.2 {
            score -= 5.0;
        }
    } else {
        // Existing bin: reward more as stream progresses.
        score -= 5.0 * progress;
    }

    // Penalize leaving post_residual in the "unusable middle zone" (too small for
    // typical items, too large to consider bin closed) — dead space avoidance.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score -= 8.0; // nearly closed bin is good
    } else if pr >= 10 && pr < 25 {
        score += 6.0; // awkward dead zone
    }

    // Mild penalty when many bins are open (encourage closing bins, reducing spread).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty amplifies bad fits.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * 4.0);

    // Lookahead: if the next item fits into the post residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual as f64 - next_item_size as f64;
        score -= 8.0 + slack_after_next * 0.15;
    }
    // If next item won't fit here, penalize slightly more when it leaves big dead space.
    else if next_item_size > post_residual {
        score += (next_item_size as f64 - post_residual as f64) * 0.05;
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is penalized, but less so
    // when open bins are crowded (low mean residual) or stream is late.
    if bin_residual == bin_capacity {
        score += 25.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= mean_residual * 0.35;      // crowded open bins -> new bin more attractive
        score -= progress * 6.0;            // late in stream, consolidation matters less
        if open_bins_count == 0 {
            score -= 100.0;                 // no alternative
        }
    }

    // Slight preference for bins whose residual deviates below the mean
    // (keeps a portfolio of residual sizes for future items).
    score += (mean_residual - bin_residual as f64) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual)
    let mut score = pr;

    // Smooth non-linear coupling: post_residual interacts with stream progress.
    // Early on, keep bins flexible (penalize very low post_residual mildly);
    // late in stream, strongly reward low post_residual (seal bins tightly).
    let flexibility = (1.0 - progress) * (norm_pr * (1.0 - norm_pr) * 4.0) * cap * 0.3;
    score += flexibility;

    // Polynomial penalty for dead space that is hard to reuse, modulated by progress
    let dead = norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);
    score += dead * 0.4;

    // Reward using a bin when it's the last fitting option
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += diff * (0.5 + 0.5 * progress);
        // Exact match bonus
        if diff < 0.5 {
            score -= 15.0;
        }
    }

    // Mild preference toward consolidating into fewer bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr) * 2.0;

    // Nudge toward bins with residuals near the mean (keeps pool balanced)
    score += ((pr - mean_residual) / cap).abs() * 10.0 * (1.0 - progress);

    // New-bin candidate handling: empty bin gets a baseline penalty so it is
    // chosen only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 40.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exact fills are perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small dead space is more reusable.
    let pr = post_residual;
    let class = pr / 10; // integer division classes 0..=10
    match class {
        0 => score -= 60.0,          // 1..9: nearly full, good
        1 => score -= 40.0,          // 10..19
        2 => score -= 25.0,          // 20..29: fits medium items
        3 => score -= 15.0,
        4 => score -= 10.0,
        5 => score -= 8.0,           // ~50: still flexible
        6 => score -= 6.0,
        7 => score -= 4.0,
        _ => {}                       // large residual: mild
    }

    // Next-item lookahead: if the post residual exactly fits the next item, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            // next item won't fit here; penalize leaving residuals in awkward classes
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
        // Harmonic coupling: next item in same decile class as residual is efficient
        if next_item_size / 10 == pr / 10 && pr >= next_item_size {
            score -= 20.0;
        }
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor host.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 80.0;
        // Large items justify a fresh bin more (they fragment any bin anyway).
        if item_size > 60 {
            score -= 60.0;
        }
        // Many open bins with slack: reuse them instead.
        score += open_bins_count as f64 * 3.0;
        // If mean residual comfortably exceeds item, reuse is fine.
        if mean_residual > item_size as f64 + 20.0 {
            score += 40.0;
        }
    } else {
        // Using an existing bin is generally good.
        score -= 30.0;
        // Waste penalty: residual wasted relative to bin capacity fraction.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score -= fill_frac * 50.0;
    }

    // Modulo-3 harmonic on item size: mid-size items (30/60) pack well into residuals
    // that are multiples of 10; small reward for class alignment.
    if bin_residual % 10 == item_size % 10 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Late in stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Post-residual that cannot fit the smallest possible item is pure waste.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 25.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Open-bin pressure: prefer using existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.6 + 0.8 * progress);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Lookahead: reward leaving a gap that can fit the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize mildly.
        score += 15.0;
    }

    // Prefer bins with residuals near mean (balance), slightly.
    score -= 0.3 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect lookahead fit (next item can still leave a small remainder chain).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0;
    }
    // Bad lookahead: next item cannot fit in the leftover space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }
    // Dead space penalty: leftover too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative to mean residual: prefer bins tighter than the average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin would leave a very bad fit
    // or no bins fit well; empty bin starts at full residual so penalize mildly by default.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 10.0; // discourage new bin when a 2-item chain is plausible elsewhere
        }
    }

    // Slight preference for filling bins earlier in the stream to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Mild pressure to keep open bin count low.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Detect brand-new empty bin candidate.
    let is_new_bin = bin_residual == bin_capacity;

    // Core tightness preference: reward small post residuals nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: strongly reward bins whose residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 0.15 * slack.min(50.0);
    } else if next_item_size > 0 {
        // Penalize creating residual that cannot host the lookahead item,
        // scaled by how "wasted" the leftover space is.
        score += 0.25 * (post_residual as f64).min(next_item_size as f64);
    }

    // Last-chance bin: if this is the only open bin that fits, using it
    // avoids opening a new bin; reward it (unless a new bin would be better).
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is attractive when the item
    // fits poorly everywhere else, or residuals across bins are already small.
    if is_new_bin {
        let avg_pressure = mean_residual / bin_capacity as f64;
        // Early stream: opening bins is cheap; late stream: consolidate.
        let open_cost = 20.0 + 60.0 * progress;
        let poor_fit_elsewhere = if fitting_bins_count > 0 {
            let min_post_elsewhere = post_residual as f64; // new bin residual is large
            0.0
        } else { 0.0 };
        // Reward opening when mean residual is low (few good hosts) or early.
        score += open_cost - 10.0 * (1.0 - avg_pressure);
        // If other bins fit, discourage new bin unless their residuals are large.
        if fitting_bins_count > 0 {
            score += 8.0 * avg_pressure;
        }
        // Dead-space guard: never open a new bin for a tiny item late in stream.
        if item_size < bin_capacity / 4 && progress > 0.5 {
            score += 30.0;
        }
    } else {
        // Existing bin: mild penalty proportional to global bin count pressure
        // to discourage fragmenting many bins when consolidation is possible.
        let consolidation = (post_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 5.0 * consolidation.max(-1.0).min(1.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;
    let mean_norm = mean_residual / cap;

    // Core: reward tight fits with a smooth polynomial decay in post_residual.
    let mut score = post * (1.0 + fit_ratio * post_norm);

    // Non-linear coupling with stream progress: later in the stream,
    // dead space is more costly (quartic-ish growth of penalty).
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += post_norm * post_norm * 40.0 * (0.5 + progress_coupling);

    // Reward bins whose residual is near the mean (balanced packing),
    // penalize outliers smoothly.
    let deviation = (post_norm - mean_norm).abs();
    score += deviation * deviation * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress_coupling;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Next item won't fit here: penalize leaving large unusable-ish space.
            let waste = (post - nxt) / cap;
            score += 8.0 * waste.max(0.0);
        }
    }

    // New-bin candidate: penalize so we only open when open bins fit poorly.
    if bin_residual == bin_capacity {
        let base_penalty = 60.0 + 30.0 * (1.0 - progress);
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            // how badly does the best existing fit compare? approximate via post_residual
            (post as f64) * 0.2
        };
        score += base_penalty + desperation;
    } else if open_bins_count > 0 {
        // Mild reward for keeping bins busy rather than spreading items.
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: capacity divided into 10 classes of 10 units.
    let cap = bin_capacity as f64;
    let class = (post_residual / 10).min(9) as f64;

    // Dead-space penalty grows super-linearly for mid-range residuals that are hard to fill.
    // Residuals in [1..9] and [51..60] are historically poor targets.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual >= 51 && post_residual <= 60 {
        score += 8.0;
    }
    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can exactly host the next item (harmonic pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            let nxt = next_item_size as f64;
            let pair_class = ((post_residual - next_item_size) / 10).min(9) as f64;
            // Prefer bins whose leftover after next item lands in a good class (small or zero).
            score -= 10.0 - pair_class * 0.8;
            // Extra reward if next item fills more than half of the post residual.
            if nxt > 0.5 * post_residual as f64 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this bin's remainder: mild penalty scaled by class.
            score += 2.0 + class * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer tightest fit; post_residual already encodes this.
        score += (fitting_bins_count as f64 - 1.0) * 0.3;
    }

    // Modulo coupling: residuals divisible by 10 are "clean" slots.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    // Odd residuals are slightly worse (harmonic misalignment).
    if post_residual % 2 == 1 {
        score += 1.5;
    }

    // Late in the stream, consolidate: prefer bins below mean residual (tighter bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 - mean_residual) * 0.25 * (0.5 + progress);

    // New-bin candidate: penalize opening a bin unless item is large and nothing fits well.
    if bin_residual == bin_capacity {
        let big_item = item_size >= 60;
        let poor_fit = post_residual as f64 >= 0.35 * cap;
        if big_item && poor_fit {
            score -= 5.0; // allow new bin for large items with poor existing fit
        } else {
            score += 12.0 + 10.0 * (1.0 - progress);
        }
        // If next item is small, new bin is more attractive (room for both).
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity && item_size >= 50 {
            score -= 8.0;
        }
    }

    // Small global tie-breaker against bin index drift via mean residual.
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fill is ideal
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mild penalty if this leaves a large gap
        score += 3.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor
    // (large post_residual waste) or no tight option exists.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64;
        score += open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if post_residual == bin_residual {
            // penalize opening new bin when an existing bin would leave less dead space
            score += mean_residual.min(bin_capacity as f64) * 0.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        // Perfect lookahead match: next item exactly fills the bin
        let match_quality = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - match_quality / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space penalty: next item cannot use this residual
        score += 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits relative to mean residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Penalize bins far above mean residual (fragmented space)
    if (bin_residual as f64) > mean_residual {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Last-chance bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer it when residual is very small
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual {
            score += 15.0; // discourage wasting a fresh bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can serve next item too
        }
    }

    // Late-stream consolidation: fewer open bins preferred
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64 / (fitting_bins_count.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residual too small for the next (lookahead) item.
    if next_item_size > 0 && post_residual > 0 {
        let gap = next_item_size as f64 - post_residual as f64;
        if gap > 0.0 {
            // Waste that likely cannot be used soon.
            score += 0.6 * gap;
            // Stronger penalty late in the stream when waste matters more.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 0.4 * gap * progress;
        } else {
            // Post-residual fits the next item: strong reward.
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Mild penalty for using a bin when many bins already fit the item
    // (prefer keeping flexibility among fitting bins via tightness alone).
    if fitting_bins_count > 1 {
        score += 0.3 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins whose residual is below the mean (consolidating fuller bins),
    // leaving larger residuals in emptier bins for future items.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // New empty bin candidate: neutral-ish base so it wins only when all
    // open fits are poor. Penalize opening bins when open bins exist and
    // one of them has a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        // If no existing bin can fit (fitting_bins_count counts only open bins
        // including this one for the new-bin call), relax the penalty.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        // Early in the stream, opening bins is cheap; late, avoid fragmentation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Large items consume most of a bin: slight extra reward for placing them
    // in bins where they leave minimal residue.
    if item_size >= bin_capacity * 3 / 4 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_fit = it / cap;
    let norm_post = pr / cap;

    // Smooth base: quadratic waste penalty with cubic stream coupling.
    let mut score = pr as f64;
    score += 18.0 * norm_post * norm_post * (1.0 + progress);
    score -= 6.0 * norm_fit * (1.0 - norm_fit) * (1.0 - progress);

    // Reward tight fits smoothly via post-residual decay term.
    score -= 10.0 * (-norm_post * 6.0).exp() * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Scarcity pressure: fewer fitting bins -> prefer reuse.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mean-residual deviation: penalize bins far below mean residual (fragmenting).
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 8.0 * dev * dev;

    // Lookahead: if next item fits exactly into post_residual, reward heavily (smooth).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let ng = gap / cap;
        score -= 12.0 * (-ng * 8.0).exp();
        // If next item cannot fit here, mild penalty for hoarding space.
        if (next_item_size as f64) > pr {
            score += 3.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling: penalize opening a fresh bin unless item is large
    // and current bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64).ln().max(0.0);
        let big_item = (norm_fit - 0.5).max(0.0);
        let waste = norm_fit; // residual left = capacity - item
        let mut nb = 30.0 + 20.0 * waste * waste * 4.0;
        nb -= 25.0 * big_item * (1.0 + progress);
        nb -= 4.0 * crowded;
        // If no open bin could fit, opening is fine (fitting_bins_count==0 for opens,
        // but new bin call may still see fitting count) — smooth relief:
        if fitting_bins_count == 0 {
            nb -= 100.0;
        }
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small dead space" classes are penalized less.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // capacity fraction left over

    // Penalize leftovers that are too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Integer-division harmonic thresholds: leftover in [10,25) is a good
    // target for small items; reward it.
    if post_residual >= 10 && post_residual < 25 {
        score -= 8.0;
    }
    if post_residual >= 25 && post_residual < 50 {
        score -= 4.0;
    }

    // Reward near-perfect packing (waste fraction small).
    score -= 12.0 * (1.0 - frac) * (1.0 - frac);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly
    // or closely, reward this placement (harmonic chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 10.0 * (1.0 - slack as f64 / cap);
        // Exact chain match: modulo-harmonic bonus.
        if slack == 0 {
            score -= 20.0;
        }
    }
    // Penalize placements that leave a residual just barely below the next
    // item size (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are genuinely poor fits. Add a base penalty, waived when open bins
    // are fragmented or the item is large.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits, must open
        } else if fitting_bins_count == 1 {
            score -= 10.0; // only one alternative; mild preference to open
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // Large items justify fresh bins.
        if item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
        // If mean residual across open bins is small, open bins are nearly
        // full anyway; opening is fine.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Prefer bins with residual close to item size (tight fit) among open bins.
        score -= 5.0 * (1.0 - (bin_residual as f64 - item_size as f64) / cap);
        // Spread penalty: if many bins fit, slight preference for tighter ones
        // is already captured; add mild bonus when bin_residual matches item
        // harmonic class (both divisible by 10).
        if item_size % 10 == 0 && bin_residual % 10 == 0 {
            score -= 3.0;
        }
    }

    // Mild global pressure: many open bins -> consolidate, prefer filling
    // existing bins over new ones (handled above); also scale score slightly
    // to keep ordering stable.
    score *= 1.0 + 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tightest fit).
    score = post_residual as f64;

    // Strict dead-space penalty: small gaps (< 10, minimum item size) are unusable.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 60.0; // full waste, heavily penalize
    } else if post_residual < 20 {
        score += 15.0; // risky small gap
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward filling a bin substantially (post_residual small relative to capacity).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: many open bins -> favor compacting into existing bins,
    // penalize opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins fit poorly
        // or post_residual would be dead space.
        let poor_fit = dead || post_residual > (bin_capacity as f64 * 0.45) as u32;
        let pressure = open_bins_count as f64 / 8.0;
        if poor_fit {
            score -= 30.0 + 10.0 * pressure;
        } else {
            score += 40.0 + 15.0 * pressure;
        }
    } else {
        // Existing bin: reward using it, more so when many bins are open.
        score -= 5.0 + (open_bins_count as f64).min(20.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // blocks the next item
    }

    // Early stream: be more conservative about opening new bins early
    // (bins may combine later); late stream: compact aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty when this bin's residual is far from mean residual
    // (prefer balancing? no — prefer using below-mean bins to drain them).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (low dead space)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * diff;
        if post_residual as i64 == next_item_size as i64 {
            score -= 300.0; // perfect two-item fill
        } else if (post_residual as f64) > next_item_size as f64 {
            // next item fits: slight bonus scaled by tightness
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize creating small dead space
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative residual context: prefer bins tighter than the mean
    score += 0.6 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize spreading across many open bins lightly
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: only attractive when the item is huge relative to
    // typical residuals or no good fit exists
    if bin_residual == bin_capacity {
        score += 250.0; // default: prefer existing bins
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 400.0; // fresh bin enables perfect 2-item fill
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of value as post_residual grows
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(2) * 20.0;

    // Exact / near-exact fill bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to prefer tighter competing bins
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin
        score += 40.0;
        // If the item leaves a big hole in any existing bin anyway, opening new bin is fine
        let would_waste = (bin_residual - item_size).max(0) as f64;
        // If this bin is NOT the last chance, opening a fresh bin wastes residual space
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // Lookahead: if next item fits in the leftover of an existing bin, prefer existing
        if next_item_size > 0 {
            let next_fits_existing = (bin_residual as f64 - item_size as f64) >= next_item_size as f64;
            if next_fits_existing {
                score += 30.0;
            } else {
                score -= 15.0;
            }
        }
        // Late in stream: avoid opening bins that will stay nearly empty
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // Many open bins with large mean residual: reuse instead
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += (mean_residual - 30.0) * 0.5;
        }
        let _ = would_waste;
    } else {
        // Lookahead synergy: placing here leaves room for the next item
        if next_item_size > 0 {
            if post_residual as f64 >= next_item_size as f64 {
                score -= 12.0;
            } else if post_residual > 0 {
                // dead space that next item cannot use
                score += (next_item_size as f64 - post_residual as f64) * 0.3;
            }
        }
        // Prefer bins with residual close to item (best-fit coupling)
        score += (bin_residual as f64 - item_size as f64).abs() * 0.1;
        // Early stream: keep bins flexible, penalize large residual consumption slightly
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 && post_residual > 40 {
            score += 8.0;
        }
    }

    // Global pressure: when many bins open, reward consolidation into existing bins
    if open_bins_count > 4 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth coupling of post_residual with stream progress:
    // later in the stream, waste matters more (convex amplification)
    let progress_amp = 1.0 + 1.5 * progress * progress;
    score *= progress_amp;

    // Interaction: residual tightness vs mean residual across open bins.
    // Prefer bins whose residual is below the mean (already committed space)
    let mean_gap = mean_residual - post;
    score += 0.35 * mean_gap.abs() * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead: reward if next item can fit into post_residual (chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        // penalize dead space that next item cannot use, smoothly in post_residual
        score += 0.08 * post * (next_item_size as f64 / cap);
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
        // but allow new bin if post_residual would be very tight elsewhere
        if post < 3.0 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near multiples of small
    // denominators are more reusable by future items.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit, best possible outcome
    } else if pr <= 10 {
        -35.0 // tiny dead space, effectively full bin
    } else {
        // modulo structure: residuals divisible by 10 or 5 pair well with
        // typical item granularities
        let m10 = (pr % 10) as f64;
        let m5 = (pr % 5) as f64;
        let harmony = (10.0 - m10) * 0.8 + (5.0 - m5) * 0.6;
        // integer-division thresholds: which size classes can still fit
        let fits_next = if next_item_size > 0 && next_item_size <= pr { 1.0 } else { 0.0 };
        let fits_next_exact = if next_item_size > 0 && next_item_size == pr { 1.0 } else { 0.0 };
        -fits_next_exact * 45.0 - fits_next * 18.0 + harmony * 0.5
    };
    score += class_bonus;

    // Quadratic dead-space penalty: large residuals are wasteful.
    let frac = pr as f64 / cap;
    score += 30.0 * frac * frac;

    // Lookahead coupling: if the next item cannot fit here, mild penalty
    // unless this bin becomes near-full anyway.
    if next_item_size > 0 && next_item_size > pr && pr > 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item would leave an awkward mid-range residual elsewhere, or when
    // open bins are already crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // new bin starts with full residual = cap, so baseline score is high;
        // subtract to make it competitive, but keep a threshold penalty.
        score -= 55.0 + 25.0 * progress;
        // If current item is large, a fresh bin wastes less space elsewhere.
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        // If many bins can fit the item, prefer reusing one of them.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // If the best alternative residual would be small and awkward
        // (post_residual in dead zone 11..30), new bin is more attractive.
        if pr > 10 && pr < 30 {
            score -= 12.0;
        }
    }

    // Crowd-spread: when many bins are open with high mean residual, encourage
    // consolidation into existing bins rather than spreading.
    if !is_new_bin && mean_residual > cap * 0.5 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: smaller post_residual relative to item size is better.
    if item_size > 0 {
        score -= (item_size as f64) * (1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0)) * 1.5;
    }

    // Dead-space penalty: small unusable gaps (post_residual < 10, min item size)
    // are pure waste; penalize quadratically.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * (10.0 - post_residual as f64) * 2.0;
    }

    // Medium dead-space zone: gaps in [10, 20) are hard to fill later.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item would leave a large, awkward gap in every existing bin, or when few
    // bins fit the item and the stream is early (room to consolidate later).
    if bin_residual == bin_capacity {
        // Base cost for a new bin: discourage unless justified.
        score += 30.0 + open_bins_count as f64 * 4.0;
        // If the item would leave a big residual in the new bin and the next
        // item likely pairs with it, opening a new bin is attractive.
        if next_item_size > 0 && post_residual >= next_item_size as u32 {
            score -= 20.0;
        }
        // Early in the stream, allow new bins more freely to build diverse residuals.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 {
            score -= 10.0;
        }
        // If very few bins can fit the item, new bin is less costly.
        if fitting_bins_count <= 2 {
            score -= 12.0;
        }
    }

    // Open-bins pressure: penalize placements that keep many bins barely used;
    // prefer filling bins whose residual deviates below the mean (consolidation).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.5;
        score += open_bins_count as f64 * 0.3;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 12.0;
    }
    // Penalize if post residual is just barely too small for the next item
    // (near-miss wasted pairing).
    if next_item_size > 0 && post_residual + 1 == next_item_size as u32 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too; reward proportional to tightness of the pair.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 200.0 - 0.5 * pair_waste;
        } else {
            // Next item won't fit here; penalize leftover dead space relative to next item.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when the item fits
    // very poorly everywhere (large post_residual waste avoided by fresh capacity).
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; new bin is only chosen if open bins score worse.
        score += 50.0;
        // Late in the stream, slightly discourage opening extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Mild reward for keeping many open bins from growing further waste.
    if open_bins_count > 0 && post_residual < 10 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-fit residual (tight packing).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit is valuable: subtract proportional to how well next item fits.
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - (slack_after_next as f64) / (bin_capacity as f64));
        } else {
            // Next item cannot follow here: penalize leaving mid-range dead space.
            let dead = post_residual as f64;
            if dead > 0.0 {
                score += 6.0 * (dead / 100.0);
            }
        }
    } else {
        // Last item: purely minimize post residual.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty for wasting capacity in an abundant choice.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // Global state: if mean residual is low (bins nearly full), reward using existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_res_gap = (mean_residual - post_residual as f64).abs();
    score += 0.15 * mean_res_gap;

    // Late in the stream, consolidate: penalize opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no open bin fits well.
        let desperation = if fitting_bins_count == 0 {
            0.0
        } else {
            (item_size as f64) * 0.5 + 30.0
        };
        let time_pressure = 20.0 * progress;
        score += desperation + time_pressure - (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // Existing bin: slight reward scaled by how full the bin already is.
        let fill = (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);
        score -= 8.0 * fill;
    }

    // Nonlinear coupling: exact-fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let mean_res_n = mean_residual / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Dead-space penalty: post-residual that is too small to fit the next item
    let next_fits = if next_item_size > 0 { (next_item_size as u32 <= post_residual) as i32 } else { 1 };
    let dead = if next_item_size > 0 && next_fits == 0 {
        (norm_next - norm_pr).max(0.0)
    } else {
        0.0
    };
    score += 2.5 * dead * (1.0 + 2.0 * dead);

    // Smooth reward: post-residual that exactly accommodates the lookahead item
    let snug = if next_item_size > 0 {
        let d = norm_pr - norm_next;
        (-d * d / 0.02_f64).exp()
    } else {
        0.0
    };
    score -= 1.2 * snug;

    // Progress coupling: later in the stream, tighten more aggressively
    score += 0.6 * progress * norm_pr * norm_pr;

    // Interaction with mean residual: avoid bins far from the fleet mean (keeps spread tight)
    let dev = (norm_pr - mean_res_n).abs();
    score += 0.5 * dev * dev * (0.5 + progress);

    // Scarcity: last fitting bin gets a bonus to use it rather than open a new bin
    if fitting_bins_count <= 1 {
        score -= 0.8;
    } else {
        score += 0.15 * (fitting_bins_count.min(10) as f64).ln();
    }

    // New-bin candidate: heavily penalize so it is only chosen when all open bins are terrible fits
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        // Penalize proportional to how well the item would actually fit a fresh bin (large item => less waste later)
        score = cap + pr * 0.5 - 0.3 * norm_item;
        if fitting_bins_count <= 1 && open_bins_count > 0 {
            // still prefer an existing last-chance bin
            score += 1.5;
        }
    }

    // Mild reward for filling bins deeply overall
    score -= 0.3 * norm_item * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual into modulo buckets
    let class = post_residual % 10;
    // Residuals in "awkward" classes (1..9 mod 10 with small values) are dead space
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny unusable slivers
    } else if class >= 1 && class <= 4 && post_residual < 40 {
        score += 8.0; // hard-to-fill awkward zone
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic fraction of capacity used by this placement
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_fraction;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive,
    // but not so attractive it steals good fits from open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 - 30.0;
        // If current bin would leave a bad residual, opening fresh is better
        if post_residual > 0 && post_residual < 15 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins already: discourage proliferation
        score += open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item could exactly fill the post_residual, reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits comfortably
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here: residual likely wasted
        score += 6.0;
    }

    // Prefer bins whose residual is already below average (denser bins)
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // dead space threshold: gaps too small for the smallest plausible item
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        // gaps that cannot fit the lookahead item are also dead-ish
        let dead_next = if next_item_size > 0 && post_residual < next_item_size { 0.5 } else { 0.0 };
        score += 60.0 * dead + 25.0 * dead_next;
        // superlinear penalty as post_residual shrinks toward the dead zone
        score += 40.0 / (1.0 + post_residual as f64);
    } else {
        // perfect fit: strong reward
        score -= 80.0;
    }

    // Reward using a bin that is the last chance before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: prefer consolidating when many bins are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.4 + 0.6 * progress);

    // Prefer bins below mean residual (tighter bins get priority)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: baseline competitive score; opened only when all
    // open bins have poor fits (large residuals / dead-space penalties).
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // late in the stream, opening new bins is cheaper than hoarding dead space
        score -= 20.0 * progress;
        return score;
    }

    // mild reward for leaving room for a similar next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space relative to mean residual.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chained fit
        } else if post_residual >= next_item_size {
            let slack_after_next = (post_residual - next_item_size) as f64;
            // reward next item fitting, scaled by how compact the chain stays
            score -= 25.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // next item cannot follow in this bin: penalize, worse if item is big
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.15 * miss;
        }
    } else {
        // Last item: prefer minimal post_residual
        score += 0.0;
    }

    // Last-chance bin bonus: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins give poor fits
    if bin_residual == bin_capacity {
        // Neutral-ish base for fresh bin; discourage when good fits exist elsewhere
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin anyway
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin supports the lookahead chain
        }
    } else {
        // Slight reward for consolidating into already-open bins
        score -= 5.0;
        // Prefer fuller bins (small residual) among open bins
        score += 0.10 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Stream progression: later in stream, be more conservative with dead space
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post_residual as f64 * 0.25;

    // Crowding: many open bins -> favor filling existing ones harder
    if open_bins_count > 3 {
        score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: tiny post-residual means minimal dead space.
    if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < 20 {
        score -= 12.0;
    }

    // Lookahead coupling (k=2): reward if the next item can also land here,
    // penalize residual that is unusable w.r.t. the upcoming item.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0;
        } else {
            // Dead-space penalty scaled by how much of the residual is wasted.
            score += (post_residual as f64).min(30.0) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (but not for the brand-new empty bin itself).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: default penalty so existing bins are preferred,
    // relaxed for large items where a fresh bin is a natural home.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= 50 {
            score -= 12.0;
        }
        if item_size >= 70 {
            score -= 8.0;
        }
        // If the next item is bigger than the current one, opening a fresh bin
        // now wastes capacity; discourage it.
        if next_item_size > 0 && next_item_size > item_size {
            score += 12.0;
        }
        // Late in the stream, avoid spawning bins with small items.
        let t = step_index as f64 / (total_items.max(1) as f64);
        if item_size < 30 && t > 0.5 {
            score += 15.0;
        }
    }

    // Mild dispersion penalty: prefer bins whose post-residual stays close to
    // the fleet mean, keeping residual capacity balanced across open bins.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // Slight pressure against accumulating many open bins with large residuals.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Base: prefer smaller post-residual, with mild non-linear (quadratic) sharpening.
    let mut score = pr + 0.6 * (pr / cap) * pr;

    // Smooth non-linear coupling of post-residual with stream progress:
    // late in the stream, tight fits matter more (dead space is costlier).
    let tight = 1.0 - (pr / cap);
    score -= 8.0 * progress * tight * tight;

    // Reward near-perfect fits more strongly as the stream advances (smooth cubic coupling).
    let perfect = (1.0 - (pr / cap)).powi(3);
    score -= 6.0 * perfect * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a bin, with penalty decaying as
    // existing bins become crowded (mean residual small relative to item).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let crowding = (mean_residual / cap).clamp(0.0, 1.0);
        score += 15.0 * (1.0 - 0.5 * crowding) * (1.0 - 0.3 * progress);
        // If the item would leave a very usable chunk (>= next item), new bin is less bad.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 4.0;
        }
    } else {
        // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Penalize leaving awkward slivers (small but nonzero post-residual)
        // that likely cannot host future items (items >= 1).
        if pr > 0.0 && pr < 1.0 {
            score += 5.0;
        }
        let sliver = (pr / cap).clamp(0.0, 1.0);
        score += 3.0 * sliver * (1.0 - sliver) * 4.0 * (sliver - 0.5) * (sliver - 0.5);
        // If next item fits exactly in the post-residual, reward chaining.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 7.0 * (1.0 + 0.5 * progress);
        }
    }

    // Mild preference for consolidating into bins with below-average residual
    // (keeps large-capacity bins available for big future items).
    if !is_new_bin {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 2.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 create dead-space classes.
    let post_class = (post_residual % 10) as f64;
    score += 0.35 * post_class; // penalize awkward residues that can't be filled by typical items

    // Integer-division thresholds: bins whose post residual falls in "dead zones" get penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 3.0; // sweet spot: likely fillable by small items
    }

    // Fractional capacity coupling: how full the bin will be after placement.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fill * fill; // reward high fill quadratically

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive if current bin would leave a big awkward residual
    // and the next item could pair with the leftover.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: mildly worse than a decent fit.
        score = bin_capacity as f64 * 0.55;
        if post_residual > 0 {
            // opening a new bin when open bins exist is penalized unless fit is terrible
            if open_bins_count > 0 && fitting_bins_count > 0 {
                score += 15.0;
            }
        }
    }

    // Lookahead coupling: if next item fits exactly into post residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 14.0;
        } else if next_item_size <= post_residual {
            let leftover2 = post_residual - next_item_size;
            score -= 5.0;
            score += 0.25 * (leftover2 % 10) as f64;
            if leftover2 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; slight penalty proportional to overshoot class
            score += 0.08 * ((next_item_size - post_residual) % 20) as f64;
        }
    }

    // Late in the stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 2.0 * progress;
    }

    // Spread-awareness: if mean residual is high, prefer bins below mean (tighten them).
    let dev = mean_residual - post_residual as f64;
    score += 0.10 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable sliver: heavy penalty on top of the raw residual.
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Marginal gap: moderate penalty.
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward gaps that can still host a typical next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward when the gap exactly fits the lookahead item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: mild dead-space penalty.
        score += 5.0;
    }

    // Last-chance bin: strongly prefer filling it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening/using fresh space is cheaper, so dampen the penalty
    // on the new-bin candidate implicitly by rewarding consolidation.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // New-bin candidate handling: only attractive when it avoids bad gaps.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Cheaper to open a bin early in the stream (more future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 25.0;
        // If all existing placements would leave slivers, opening a bin is fine.
        if post_residual >= 10 {
            score -= 18.0;
        }
        // If no open bin fits, this call is the fallback anyway.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: post_residual can still hold next item comfortably.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward proportional fit, penalize slack quadratically (dead space).
        score -= 25.0 - 0.15 * slack;
        score += 0.02 * slack * slack;
    }
    // Post-residual too small for next item: penalize unusable fragments.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 0.35 * post_residual as f64;
    }

    // Compare against mean residual of open bins: prefer bins that tighten the mean.
    let mean_diff = post_residual as f64 - mean_residual;
    score += 0.20 * mean_diff;

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless current bin fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in stream, new bins are cheap; late, avoid proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If many open bins already, discourage another one.
        score += 1.5 * open_bins_count as f64;
    }

    // Prefer filling fuller bins when many bins are open (bin count pressure).
    score -= 0.5 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * (open_bins_count as f64).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness * tightness);

    // Penalize dead space thresholds: residuals too small for the minimum item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Perfect chaining: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor fits (large waste) or bins are plentiful.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used sparingly.
        score += 30.0;
        // If current item leaves a good residual in a fresh bin (tight packing
        // potential), reduce the penalty.
        let fresh_tightness = post_residual as f64 / bin_capacity as f64;
        score -= 25.0 * (1.0 - fresh_tightness);
        // Late in the stream, discourage opening bins that won't be filled.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many bins already open and mean residual is high, prefer reuse.
        if mean_residual > item_size as f64 * 2.0 {
            score += 15.0;
        }
    }

    // Global state coupling: mildly prefer bins below mean residual
    // (balances load across open bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: as the stream progresses, weight tightness more heavily
    // since leftover space is less likely to be used.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * tightness;

    // Discourage spreading items across many bins when few remain.
    if open_bins_count > 0 && fitting_bins_count > 2 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
