    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: normalized post residual, non-linearly penalized
    let post_norm = post_residual as f64 / cap;
    let tight = (1.0 - post_norm).powi(3); // smooth reward for tight fits

    // Base tightness reward, amplified as stream progresses
    score -= tight * (30.0 + 40.0 * progress);

    // Perfect fit bonus (smooth surrogate via cubic coupling)
    let perfect = 1.0 - (post_residual as f64 / (cap * 0.5)).powi(2);
    if post_residual == 0 {
        score -= 50.0;
    } else {
        score += perfect.abs() * 0.0; // keep smooth, no-op coupling
    }

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post_residual as f64 >= ns {
            // next item fits: reward, scaled by how snugly it will fit later
            let snug = 1.0 - ((post_residual as f64 - ns) / cap);
            score -= 12.0 * snug * (1.0 + progress);
        } else {
            // next item cannot fit here: mild penalty for leaving awkward space
            score += 6.0 * (ns - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0 * (1.0 + 0.5 * progress);
    }

    // Penalize opening a new bin when good open options exist late in stream
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let mean_r = mean_residual.max(0.0);
        // new bin attractive only if mean residual is small relative to item
        let attractiveness = (mean_r - item_size as f64).max(0.0) / cap;
        score += 20.0 - 25.0 * attractiveness;
        // early in stream, opening bins is cheaper
        score -= 15.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Mean-residual dispersion coupling: prefer bins close to mean residual
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // Mild penalty for very small dead space that is hard to reuse
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by large
    // chunks (e.g. 25, 50) remain usable by common item sizes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that are "harmonically clean" (nice fractions of capacity).
    if post_residual % 50 == 0 {
        score -= 18.0;
    } else if post_residual % 25 == 0 {
        score -= 10.0;
    } else if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // Penalize dead-space zones: residuals below 10 are unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic class of (post_residual - next_item_size)
            let nxt = post_residual - next_item_size;
            if nxt % 50 == 0 { score -= 14.0; }
            else if nxt % 25 == 0 { score -= 8.0; }
            else if nxt % 10 == 0 { score -= 4.0; }
            score -= 6.0; // general reward for keeping chain alive
        } else {
            // Next item won't fit here; residual becomes final dead space.
            score += pr * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight-fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 12.0;
    } else if fill_ratio < 0.3 && bin_residual < bin_capacity {
        score += 6.0; // wasteful low fill in an existing bin
    }

    // New-bin candidate logic: only attractive early or when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0);
        score = cap * 0.9 + progress * 20.0 + crowding * 2.0;
        // Opening a new bin is good if next item is large and current bins are tight.
        if next_item_size >= 60 && mean_residual < next_item_size as f64 {
            score -= 25.0;
        }
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even a modest future item are "dead" — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few bins -> allow new bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += pressure * (0.5 + 0.5 * progress);

    // New-bin candidate (empty bin): make it unattractive unless the current
    // bin would leave a large dead gap or the fit is very poor.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if placing here would waste a lot (large post_residual relative to
        // capacity is fine on empty bin; instead new bin is good when the item is huge).
        if item_size >= 80 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Empty bin preserves full flexibility for the lookahead item.
            score -= 10.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement strongly (chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual can't hold the next item: mild dead-space penalty scaled by gap.
        score += (post_residual as f64) * 0.15;
    }

    // Prefer bins below mean residual (tighter bins) slightly.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits tightly into post residual (within a small slack).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / 20.0).max(0.0);
    }

    // Penalize when next item does NOT fit the post residual (wasted lookahead opportunity),
    // especially when post residual is small but nonzero (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        let unusable = dead < 10.0;
        score += if unusable { 25.0 } else { 8.0 };
    }

    // Reward tight fills relative to mean residual of open bins.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness);

    // Prefer bins with residual below mean (filling fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New empty bin candidate: keep it attractive only when no good fit exists
    // (i.e., current bin would leave large dead space).
    if bin_residual == bin_capacity {
        let would_waste = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10);
        score = if would_waste { 40.0 } else { 95.0 };
        if open_bins_count == 0 {
            score = 0.0;
        }
    }

    // Mild late-stream preference to consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual becomes unusable dead space.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score -= 25.0; // tiny leftover is fine (item nearly fills bin)
    } else {
        // penalize large leftover proportionally
        score += (post_residual as f64 / bin_capacity as f64) * 15.0;
    }

    // Exact-fill bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item could fit into the post-residual,
    // keep this bin attractive; otherwise penalize.
    if next_item_size > 0 {
        if (post_residual as i64) - (next_item_size as i64) >= 0 {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // chain fit: next item exactly fills post-residual is excellent
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: empty bin gets a penalty so we prefer existing bins,
    // unless all existing fits are poor (large post_residual with no lookahead fit).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 45.0;
        // late in the stream, opening new bins is cheaper than fragmenting
        new_bin_penalty -= progress * 20.0;
        // if many bins are open and fragmented, slightly favor consolidation
        new_bin_penalty += (open_bins_count as f64).ln() * 5.0;
        // if mean residual across bins is small, existing bins are crowded -> new bin ok
        if mean_residual < item_size as f64 {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for filling more-full bins first (best-fit bias via residual)
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Time-horizon modulation: early stream, be conservative (favor tight packing);
    // late stream, slightly favor any fit to avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity
    let mut score = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (quadratic growth in pr)
    let pr_norm = pr / cap;
    score += 0.9 * progress * pr_norm * pr_norm * cap * 0.01;

    // Reward filling the bin well: interaction of item size with progress
    score -= 0.35 * (it / cap) * (1.0 - progress);

    // Penalize bins that leave residual too small for typical next items
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 0.25 * (nxt / cap) * (pr / cap);
        } else {
            score += 0.4 * (1.0 - pr / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly prefer this bin if it is the only fitting one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.5;
    }

    // Slight preference for compacting into fewer bins when many are open
    score += 0.05 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (mean_residual / cap);

    // New-bin candidate: make it unattractive unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 1.0 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (mod-based dead-space classes) ---
    // Residuals that are "usable" by typical item sizes get a reward; awkward
    // dead-space classes (tiny slivers) get penalized.
    let pr = post_residual;
    let class = pr % 10; // harmonic class mod 10
    match class {
        0 => score -= 12.0,                 // perfectly reusable residual
        1 | 2 => score += 6.0,              // sliver dead space, nearly unusable
        3 | 4 | 5 | 6 | 7 => score -= 3.0,  // decent mid-range residual
        8 | 9 => score += 2.0,              // borderline usable
        _ => {}
    }

    // Integer-division thresholds: residual large enough for a "big" item
    if pr >= 40 { score -= 5.0; }
    if pr >= 20 && pr < 40 { score -= 1.5; }
    if pr > 0 && pr < 10 { score += 4.0; } // nearly-closed bin is fine

    // --- Tightness reward: fraction of bin consumed by this item ---
    let fill_frac = item_size as f64 / cap;
    score -= 10.0 * fill_frac; // favor placing into bins where item fills a lot

    // --- Exact fit: huge reward ---
    if post_residual == 0 { score -= 25.0; }

    // --- Lookahead coupling (k=2): does the next item fit the post residual? ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as f64) >= nxt {
            // next item chains nicely into this bin
            score -= 6.0 * (nxt / cap);
        } else if pr > 0 {
            // next item won't fit here; residual becomes dead space
            score += 3.0 * (pr as f64 / cap);
        }
    }

    // --- Last-chance bin: strongly prefer using it before opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // --- New-bin candidate handling: bin_residual == bin_capacity ---
    if bin_residual == bin_capacity {
        // Opening a new bin is good when many bins are open and residuals are
        // fragmented, or when the item is small and we want to preserve big gaps.
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut newbin_bonus = 4.0 * fragmentation + 3.0 * progress;
        if item_size <= 20 { newbin_bonus += 4.0; }       // small item: fresh bin keeps options
        if next_item_size >= item_size && next_item_size > 0 { newbin_bonus += 2.0; }
        score -= newbin_bonus;
    } else {
        // Mild penalty for stuffing an already-crowded bin pool when mean
        // residual is high (bins are fragmented; prefer consolidation instead).
        if mean_residual > 0.6 * cap && open_bins_count > 3 {
            score += 2.0;
        }
    }

    // --- Progress modulation: late in stream, be conservative (avoid new bins) ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 2.0 * progress; // reuse existing bins more aggressively late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0; // only fits smallest items
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Reward bins whose residual was already small (consolidating waste).
    let prior_tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * prior_tightness;

    // Open-bin pressure: when many bins are open, prefer reusing existing bins
    // over opening new ones; when few are open, opening new bins is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.8 * bin_pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when all fits are bad.
    if bin_residual == bin_capacity {
        score += 22.0;
        // But if the next item is large and this placement leaves a bad gap,
        // opening a fresh bin becomes attractive.
        if next_item_size > post_residual && next_item_size > 0 {
            score -= 15.0;
        }
    }

    // Lookahead: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Mean-residual coupling: if this bin is tighter than average, prefer it.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: if the next item fits into the post residual,
    // this bin is a great multi-item target.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well the next item fills the remainder.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
            // Combined near-perfect two-item packing.
            if post_residual - next_item_size < 10 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize large dead space proportionally.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 8.0 * (1.0 - dead / (next_item_size as f64));
            }
        }
    } else {
        // Last item: just minimize leftover.
        score -= 10.0;
    }

    // Compare post_residual against mean residual: leaving less than average
    // residual than the fleet average is good consolidation.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 5.0 * (1.0 - pr / (mean_residual + 1.0));
    } else {
        score += 4.0 * ((pr - mean_residual) / (bin_capacity as f64));
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; waived when the item is large
        // (likely to fit poorly anywhere) and there are many open bins.
        score += 25.0;
        if item_size >= 60 && open_bins_count > 3 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // new bin can host current + next comfortably
        }
    }

    // Slight late-stream consolidation pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - pr / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: strongly discount small post_residual
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (1.0 - tightness) * 30.0;

    // Penalize dead space that cannot fit the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Exact fill bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into this bin's post-residual,
    // reward; otherwise penalize proportionally to wasted potential.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // mild penalty for hoarding the best-fitting bin when alternatives exist
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate logic: only attractive when the current item fits badly
    // everywhere or residual space is highly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 45.0;
        // Cheaper to open a bin early (long horizon to amortize) and when many
        // open bins already exist but fits are poor.
        score -= 20.0 * (1.0 - progress);
        // If this bin is the only fitting option, opening new is bad (prefer reuse)
        if fitting_bins_count <= 1 {
            score += 30.0;
        }
        // Large items justify fresh bins; small items should reuse space
        score -= (item_size as f64 / 100.0) * 15.0;
        // If mean residual is high, there's slack available elsewhere: discourage new bin
        score += (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Prefer filling bins with larger residuals when many bins are open
    // (consolidation pressure proportional to open bin count).
    score += (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).min(20.0) * 1.5;

    // Slight preference for bins near the mean residual (keeps distribution balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    let mut score = pr;

    // Polynomial coupling: residual value decays non-linearly with progress
    let decay = 1.0 - progress * progress;
    score -= decay * norm_pr * cap * 0.5;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item (smooth quadratic)
    if nxt > 0.0 {
        let gap = (nxt - pr).max(0.0) / cap;
        score += gap * gap * cap * (1.5 + progress);
        // Bonus when post residual still accommodates next item
        let fits_next = (pr >= nxt) as i32 as f64;
        score -= fits_next * nxt * (0.4 + 0.6 * progress);
    }

    // Last-chance bonus: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 {
        score -= item * (1.0 + 2.0 * progress);
    }

    // Mild dispersion penalty: avoid concentrating on outlier residuals
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * cap * 0.3;

    // New-bin candidate: penalize opening a bin unless residuals are fragmented
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let fragmentation = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += cap * (0.6 + 0.6 * (1.0 - progress)) - fragmentation * cap * 0.4;
    }

    // Smooth open-bin pressure: discourage spreading across many bins early
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction buckets (1/8 granularity)
    let item_class = (item_size * 8 + bin_capacity - 1) / bin_capacity;
    let next_class = ((next_item_size as u32) * 8 + bin_capacity - 1) / bin_capacity;

    // Reward tight fits: post_residual in low harmonic classes strongly favored
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual <= bin_capacity / 8 {
        score -= 25.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 10.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 4.0;
    } else {
        score += 8.0; // wasteful half-empty bin
    }

    // Dead-space penalty: residual below the minimum item size is unusable
    if post_residual > 0 && post_residual < 1 {
        score += 100.0;
    }

    // Complementary pairing: does post_residual accommodate the next item well?
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack.min(30.0) * 0.2;
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize proportionally
        score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.3;
    }

    // Modulo coupling: item/next classes summing to a full bin is ideal
    if next_item_size > 0 && item_class + next_class == 8 {
        score -= 6.0;
    }

    // Last-chance bonus: sole fitting bin avoids opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with residual below mean (compact bins first)
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(50.0) * 0.1;
    } else {
        score += (res - mean_residual).min(50.0) * 0.1;
    }

    // Late-stream pressure: be greedier as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // New-bin candidate: make it unattractive unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 20.0;
        // Opening fresh is fine if many bins are open and item is large
        if item_size as f64 > 0.6 * cap && open_bins_count > 3 {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Strict dead-space avoidance: leftover gap that the next item cannot use
        // is wasted capacity — penalize it heavily, proportionally to its size.
        let dead = next_item_size > 0 && post_residual < next_item_size;
        if dead {
            score += post_residual as f64 * 0.6 + 12.0;
        } else if next_item_size > 0 {
            // Gap remains usable by the lookahead item: mild reward.
            score -= 3.0;
            // Extra reward if the next item fills this bin exactly too.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        }
        // Tiny unusable slivers are dead space regardless of lookahead.
        if post_residual < 3 {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — reward it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a bin, more so when many bins
    // are already open (open-bin pressure) or when mean residual is high
    // (plenty of slack available elsewhere).
    if bin_residual == bin_capacity {
        score += 15.0
            + open_bins_count as f64 * 2.0
            + (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
    } else {
        // Coupling with mean residual: prefer bins tighter than average
        // (fill the fullest bins first to consolidate dead space).
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += dev * 0.3; // bin is tighter than mean -> slight penalty (deprioritize? no: tighter bin should be favored)
        }
        // Correct: tighter bin (smaller residual) should get LOWER score.
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: strongly reward when the next item
    // exactly fills the post residual (zero total dead space over two steps).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how tight the fit is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            // Penalize leftover slack that is too small to be useful later.
            if slack > 0.0 && slack < 10.0 {
                score += 15.0;
            }
        } else {
            // Next item won't fit here after placement; mild penalty unless
            // post residual is still large enough to be valuable.
            score += 5.0;
        }
    }

    // Compare post residual against mean residual: leaving this bin far
    // below the mean wastes its potential; leaving it near mean is fine.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.15 * dev;
    } else {
        score += 0.25 * (-dev);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when the
    // current fit is very poor (large dead space and bad lookahead match).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 25.0;
        // If the item would leave a big unusable gap in an open bin,
        // opening fresh becomes attractive: reduce the new-bin penalty.
        if item_size >= 70 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 15.0;
        }
        // Many open bins with low mean residual: keep packing instead.
        score += 0.3 * open_bins_count as f64;
        if mean_residual < 20.0 {
            score += 10.0;
        }
    } else {
        // Penalize creating tiny dead space (unusable gaps).
        if post_residual < 10 {
            score += 20.0;
        }
        // Tight fits (small post residual but item nearly fills bin) are good.
        if post_residual <= 5 {
            score -= 10.0;
        }
        // Reward filling bins tightly as the stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 25.0;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits in post_residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        if open_bins_count == 0 {
            score -= 100.0;
        } else if crowding < 0.15 {
            score -= 20.0 * (0.15 - crowding) / 0.15;
        } else {
            score += 30.0 * crowding;
        }
    }

    // Mild preference to fill bins with small mean residual (consolidation).
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // Time-horizon scaling: later in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as u64 == bin_capacity as u64) as f64;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    let mut score = pr + 12.0 * (pr / cap).powi(3) * cap;

    // Smooth progress coupling: later in the stream, dead space hurts more.
    score += 20.0 * progress * (pr / cap).powi(2) * cap;

    // Lookahead: penalize leaving residual that cannot host next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 8.0 * (ns - pr) * (0.5 + 0.5 * progress);
        } else {
            // reward residual that can still fit the next item moderately
            score -= 3.0 * (1.0 - (pr - ns) / cap);
        }
    }

    // Last-chance fitting: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin, more so when good fits exist,
    // but relax the penalty late in the stream when open bins are fragmented.
    score += is_new_bin * (30.0 + 10.0 * (open_bins_count as f64).ln().max(0.0) - 15.0 * progress);

    // Slight reward for bins tighter than the mean residual (good consolidation).
    let res = bin_residual as f64;
    score -= 2.0 * ((mean_residual - res) / cap).tanh();

    // Mild fragmentation penalty for very small post residuals that are hard to reuse.
    if pr > 0.0 && pr < 10.0 {
        score += 6.0 * (1.0 - pr / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic on (post_residual, next_item_size):
    // reward chains where the lookahead item fits the leftover space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual >= next_item_size {
            score -= 12.0;
            // exact modulo harmony: leftover is an exact multiple of next size
            let m = post_residual % next_item_size.max(1);
            if m == 0 {
                score -= 6.0;
            } else if m < 10 {
                score += 4.0; // near-harmonic but leaves unusable crumb
            }
        } else {
            // lookahead does not fit: penalize proportional to the miss
            score += (nxt - post) * 0.3;
        }
    }

    // Dead-space penalty: residuals below the minimum item size are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // no open bin fits: opening is mandatory
            score -= 25.0;
        } else {
            // opening a new bin while others fit is wasteful;
            // harsher when fewer alternatives exist
            let frac = fitting_bins_count as f64 / open_bins_count.max(1) as f64;
            score += 30.0 + 10.0 * (1.0 - frac);
        }
    } else if fitting_bins_count == 1 {
        // this is the last open bin that can take the item: strongly prefer it
        score -= 10.0;
    }

    // Stream-phase modulation: early on, tolerate moderate leftovers to keep
    // bins flexible; late in the stream, tighten fits via modulo-20 classes.
    let phase = step_index as f64 / total_items.max(1) as f64;
    let class = (post_residual % 20) as f64;
    score += class * 0.05 * (1.0 - phase);

    // Slight pull toward bins below mean residual (consolidating emptier bins).
    score -= (mean_residual - post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for even the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 15.0; // perfect closure
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base aversion to new bins, growing with number of open bins.
        score += 8.0 + 1.5 * open_bins_count as f64;
        // But if the item is large relative to mean residual, existing bins are poor hosts.
        if (mean_residual < item_size as f64 + 5.0) && open_bins_count > 0 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 25.0; // chains perfectly
        } else if gap > 0 && gap < 10 {
            score += 15.0; // next item would leave a sliver
        } else if gap > 0 {
            score -= 3.0; // next item can still use the space
        }
    }

    // Open-bin pressure: mild preference to consolidate into fewer bins early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect pairing), penalize mismatches.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (-gap / 12.0).exp(); // reward tight pairing with next item
        // Slight penalty if post_residual is large but cannot fit next item
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    } else {
        // Last item: prefer smallest residual as usual
        score += 0.0;
    }

    // Compare post_residual against mean residual: leaving much more than
    // average residual wastes space; leaving much less fragments the bin.
    if post_residual as f64 > mean_residual + 10.0 {
        score += 5.0;
    } else if post_residual as f64 <= mean_residual {
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual after
    // placement would be large enough to serve the next item well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 55.0 + 25.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            penalty -= 30.0; // fresh bin can pair with next item
        }
        if post_residual < 10 {
            penalty += 20.0; // fresh bin nearly filled -> actually good
            penalty -= 60.0;
        }
        score += penalty;
    }

    // Discourage leaving tiny unusable dead space (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste of the placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Penalize leaving dead space that can't fit the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // dead space for lookahead item
        } else if post_residual >= next_item_size {
            score -= 3.0; // bin remains usable for next item
        }
        // Strong reward if next item exactly consumes the post-residual.
        if post_residual as f64 == next_item_size as f64 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // When many bins are open, prefer filling existing ones over opening new.
    score += open_bins_count as f64 * 0.6;

    // New-bin candidate: make it unattractive unless the fit into open bins is bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Allow new bin late in the stream when mean residual is large (fragmented state).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * mean_residual * 0.05;
    }

    // Penalize bins whose residual deviates badly from the mean (keep pool coherent).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    // Slight preference for larger residual bins early, tighter bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (bin_residual as f64) * 0.02;
    score -= progress * (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 1.0 };

    // Base: prefer tight fits (low post residual), with non-linear shaping.
    let mut score = post * (1.0 + 0.35 * progress);

    // Quadratic dead-space penalty: small post residuals are great, large ones bad.
    score += 0.012 * post * post / cap;

    // Reward near-exact fits smoothly.
    score -= 12.0 * (1.0 - (1.0 - fit_ratio).abs()).powi(3) * (1.0 + progress);

    // Cubic coupling of post residual with stream progress: late stream, avoid waste more.
    score += 0.9 * (post / cap).powi(3) * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 18.0 + 10.0 * progress;
    } else {
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in the post residual, reward leaving that gap.
    if next_item_size > 0 {
        let gap_diff = (post - next_item_size as f64).abs();
        score -= 6.0 * (-gap_diff / 8.0).exp();
    }

    // New-bin candidate handling: penalize opening a new bin, more so early and when
    // open bins are few; relax when many bins are open with scattered residuals.
    if bin_residual == bin_capacity {
        let scatter = (mean_residual - post).abs();
        score += 25.0 + 30.0 * (1.0 - progress) - 8.0 * ((open_bins_count as f64).ln().max(0.0)) + 0.15 * scatter;
    }

    // Mild penalty for bins deviating from mean residual (balance pressure).
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into buckets of 10.
    let post_class = post_residual / 10;
    score += (post_class as f64) * 3.5;

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic residue classes: post residuals that are multiples of common item
    // sizes (10, 20, 25, 50) remain "fillable" and should be rewarded.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 12.0;
    }
    // Odd, unusable slivers are penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 20.0 - (gap as f64).min(20.0);
            // Harmonic check: next item leaves another clean class.
            let next_post = gap;
            if next_post % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // Next item cannot use the leftover: leftover is more likely dead space.
            score += 6.0;
            if post_residual < next_item_size && post_residual < 15 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
        if post_residual <= 5 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer using existing bins when they give a decent fit (post_residual small).
        if post_residual as f64 <= mean_residual * 0.4 {
            score += 40.0; // discourage opening a new bin for a good fit elsewhere
        } else {
            score -= 10.0; // open a fresh bin rather than wreck a tight one
        }
        // Late in the stream, consolidating into open bins matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // Many open bins: bias toward filling them instead of opening more.
        score += (open_bins_count as f64) * 1.5;
    } else {
        // Mild preference for tighter existing bins via mean residual contrast.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0; // moderate waste zone
    }

    // Reward very tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins, favor filling existing ones.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: default to opening only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when open bins score badly.
        score += 55.0 + 0.8 * open_bins_count as f64;
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 18.0 * (11.0 - gap as f64);
        }
    }
    // If next item would NOT fit here anyway, mildly penalize leaving a medium gap.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 20 {
        score += 6.0;
    }

    // Mean-residual coupling: bins far below mean residual are "fresher"; prefer filling
    // bins whose residual is close to the mean (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Late-stream urgency: as the stream nears its end, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual == 0 as u32 as bool) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            score -= 25.0 - diff.min(30.0) * 0.5;
        } else {
            score += 8.0 + diff * 0.4;
        }
    }

    // Penalize dead space relative to mean residual
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer tight bins over loose ones
    let tightness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= tightness * 10.0;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 10.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly hold the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 4.0 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            // Perfect match for the next item: strong reward.
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0; // base cost of opening a new bin
        // Cheaper to open a new bin when few open bins or late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        if open_bins_count == 0 {
            score -= 40.0;
        }
        // If the item fits poorly anywhere (huge item), opening a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        // If lookahead won't fit post-placement in a typical bin, fresh bin helps.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Slight preference for bins with residuals below the mean (consolidating space).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 0.5 * diff.min(20.0);
        } else {
            score += 0.3 * (-diff).min(20.0);
        }
    }

    // Prefer filling bins with larger residuals early on (keep small residual bins flexible).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score += (1.0 - progress) * (bin_residual as f64) * 0.05;
    }

    // Gentle tie-breaker: spread load across many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: reward tight fits (small post_residual), with a smooth non-linear
    // polynomial shaping so near-zero residuals are strongly favored.
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post);

    // Stream-progress coupling: early on, prefer filling bins snugly (mild);
    // later, penalize leaving dead space more aggressively via smooth term.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score += 8.0 * progress_coupling * norm_post * norm_post;

    // Non-linear interaction: post_residual vs mean residual deviation.
    let dev = (post - mean_residual) / cap;
    score += 6.0 * dev * dev * dev.abs() * cap;

    // Lookahead coupling: if next item fits into post_residual, reward this bin
    // smoothly (chaining placements); scale reward by how snugly the next fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post - next_item_size as f64) / cap;
        score -= 4.0 + 6.0 * snug * snug;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: penalize dead space smoothly.
        let waste = norm_post * norm_post;
        score += 10.0 * waste * (1.0 + progress);
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 3.0 + 5.0 * (1.0 - norm_post);
    }

    // New-bin candidate shaping: an empty bin should be chosen only when the
    // item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        score += 5.0 + 12.0 * (1.0 - big_item) * (1.0 - big_item);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space left behind (capacity fractions).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Class A: near-perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Dead-space class: residual too small for the minimum item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0; // unusable dead space penalty
    }

    // Harmonic quarter classes on capacity fraction.
    if frac > 0.0 && frac <= 0.25 {
        score += 30.0;      // tiny sliver, likely dead
    } else if frac <= 0.5 {
        score -= 10.0;      // half-ish residual, reusable
    } else if frac <= 0.75 {
        score -= 20.0;      // comfortable residual
    } else {
        score -= 5.0;       // large residual, item was small
    }

    // Modulo-10 harmonic class of post_residual: residuals aligned to
    // common item size classes (10s) are more reusable.
    let m = post_residual % 10;
    if m == 0 {
        score -= 25.0;
    } else if m <= 2 {
        score += 12.0;
    } else if m >= 8 {
        score += 6.0;
    }

    // Integer-division thresholds: post_residual / next_item_size.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here too -> chain reward, scaled by fit tightness.
        let slack = post_residual - next_item_size;
        let tight = if slack <= 5 { 60.0 } else if slack <= 15 { 30.0 } else { 10.0 };
        score -= tight;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this residual; penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
        if post_residual > 0 && post_residual < 10 {
            score += 120.0; // but not if it creates dead space
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap as f64 * 0.9 + open_bins_count as f64 * 2.0;
        // Large item with poor alternatives -> new bin is fine.
        if item_size >= 60 {
            score -= 40.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If next item is small, an open bin with residual can serve it later.
        if next_item_size > 0 && next_item_size <= 20 {
            score += 25.0;
        }
    }

    // Slight preference to fill bins when many are open (bin-count pressure).
    score += open_bins_count as f64 * 0.3;

    // Prefer tighter fits overall: residual dominates, but dampen when
    // mean residual is already low (bins are nearly full everywhere).
    if mean_residual < 15.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: gaps too small to hold even the smallest item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    // Mildly wasteful mid-range dead space.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // but discourage opening new bins when existing ones fit well.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 25.0;
    }
    // Penalize if next item cannot fit the residual and residual is small anyway.
    if next_item_size > post_residual && post_residual < 20 && post_residual > 0 {
        score += 15.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    // to consolidate space into fewer larger gaps.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: make empty bins moderately expensive so they are only
    // chosen when all open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if the item is huge relative to mean residual, opening fresh is fine.
        if (item_size as f64) > mean_residual * 0.85 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (small post residual).
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    }

    // 2-step lookahead: reward post_residual that exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Perfect chain: item + next item fills bin exactly.
        if post_residual as i64 == next_item_size as i64 {
            score -= 45.0;
        }
        // Penalize leaving a residual too small for the next item (dead space).
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 0.6 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    // (large dead space would be created everywhere else).
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64;
        score = waste + 8.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin can chain with next item
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't open new bin when a last-chance bin exists
        }
        if post_residual >= 20 {
            score += 10.0;
        }
    }

    // Late in stream: consolidate harder, avoid new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit via post_residual (already in score).

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers are worse than moderate space
    }

    // Lookahead coupling: reward if next item fits in post_residual (chain packing).
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 5.0;
        }
        // If next item would exactly fill this bin after current placement
        if next_item_size == post_residual as u32 {
            score -= 18.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: many open bins -> encourage consolidation into existing bins.
    let crowding = open_bins_count as f64 / (1.0 + step_index as f64);
    score -= crowding * 3.0;

    // Global residual pressure: if mean residual is low, protect remaining space;
    // if mean residual is high, prefer filling bins aggressively.
    if mean_residual > 40.0 {
        score -= 4.0;
    } else if mean_residual < 15.0 {
        score += 3.0;
    }

    // Time horizon: late in stream, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it only wins when fits are bad.
        score += 30.0;
        // Allow new bin when existing fit is terrible (large post_residual elsewhere)
        // and early enough that many items remain.
        let items_left = total_items.saturating_sub(step_index) as f64;
        if post_residual as f64 <= 15.0 && items_left > 20.0 {
            score -= 20.0;
        }
        // Late stream: discourage new bins even more.
        if progress > 0.8 {
            score += 25.0;
        }
    } else {
        // Existing bin: mild bonus proportional to how full it already is.
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fullness * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space (waste), with a non-linear (quadratic-ish) growth
    // so small leftovers are cheap but large dead space is heavily punished.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth progress coupling: as the stream advances, tighten packing
    // (waste becomes more costly relative to remaining opportunity).
    score *= 1.0 + 0.6 * progress * (pr / cap);

    // Lookahead: if the next item can no longer use this leftover, the residual
    // is likely dead space — penalize proportionally to how far short it falls.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            let unusable = (nxt - pr) / cap;
            score += 25.0 * unusable * (1.0 + progress);
        } else {
            // Reward residuals that can still host the next item (keeps bin useful).
            score -= 4.0 * (pr - nxt) / cap;
        }
    }

    // Last-chance bin: strongly prefer using it instead of opening a new bin,
    // scaled by how tight the fit is.
    if fitting_bins_count == 1 {
        let tightness = 1.0 - pr / cap;
        score -= 12.0 + 10.0 * tightness;
    }

    // Many open bins: mildly discourage spreading across too many bins
    // unless the fit is good; encourage consolidation.
    score += 0.4 * open_bins_count as f64 * (pr / cap);

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (fill the emptier-looking bins first keeps flexibility).
    score += 0.15 * (mean_residual - pr);

    // New-bin candidate (empty bin): give it a moderate score so it wins only
    // when all open bins would create significant dead space.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: slightly worse than a perfect fit, better than waste.
        score = cap * 0.45 + 0.3 * (item_size as f64 / cap) * cap;
        if next_item_size > 0 {
            // If the next item fits perfectly alongside (item + next == capacity),
            // opening a fresh bin is attractive.
            if (item_size as f64 + next_item_size as f64 - cap).abs() < 1.0 {
                score -= 30.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: capacity fractions ---
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0..1 fraction of capacity left

    // Dead-space classes: residuals that few item sizes can still use
    // are penalized, "harmonic" residuals (nice fractions) are rewarded.
    if post_residual == 0 {
        score -= 25.0; // perfect fit
    } else {
        // modulo arithmetic on post_residual: residuals divisible by
        // common small item increments are more reusable
        let m10 = (post_residual % 10 == 0) as i32;
        let m5 = (post_residual % 5 == 0) as i32;
        let m20 = (post_residual % 20 == 0) as i32;
        score -= 6.0 * m10 as f64;
        score -= 3.0 * m5 as f64;
        score -= 4.0 * m20 as f64;

        // penalize unusable tiny dead space (1..5): nothing fits later
        if post_residual < 5 {
            score += 4.0;
        }
        // penalize awkward mid-range residuals (e.g. 51..59) that only
        // very small items can fill
        let awkward = (51..=59).contains(&post_residual) || (31..=39).contains(&post_residual);
        if awkward {
            score += 5.0;
        }
    }

    // --- Coupling with next_item_size (lookahead k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // this bin can also host the next item: strong reward,
            // scaled by how snugly the next item fits
            let snug = 1.0 - (post_f - next_item_size as f64) / cap_f;
            score -= 12.0 + 8.0 * snug;
        } else {
            // next item won't fit here; slight penalty unless residual
            // is already near zero
            score += 1.5;
        }
    }

    // --- Last-chance logic ---
    if fitting_bins_count == 1 {
        // this is the only bin that fits; strongly favor using it
        // over opening a new bin
        score -= 18.0;
    } else if fitting_bins_count > 4 {
        // many alternatives: mild penalty to keep diversity
        score += 1.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // opening a new bin: base cost plus a term encouraging packing
        // into existing bins when the stream is early/mid
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap_f * 0.5 + 20.0 * (1.0 - progress);
        // if next item is large, a fresh bin is more attractive
        if next_item_size >= 60 {
            score -= 10.0;
        }
        if item_size >= 70 {
            // large item in fresh bin wastes less of existing bins
            score -= 5.0;
        }
    }

    // --- Mean residual coupling: prefer bins below mean residual
    // (fill the emptier-relative bins first to consolidate) ---
    score += 0.15 * (mean_residual - post_f);

    // --- Slight preference for tighter fits overall ---
    score += 0.05 * (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead-space gaps strongly (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // over opening new bins (penalize the empty-bin candidate implicitly).
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open,
        // but allow it when the fit elsewhere would create dead space.
        score += 20.0 * pressure;
    } else {
        score -= 2.0 * pressure;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 18.0;
        } else {
            score -= gap as f64 * 0.3;
        }
    }
    // Penalize if next item cannot use the leftover (dead space ahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Late in the stream, consolidate: slightly favor tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.05 * progress;

    // Mean residual coupling: bins far below mean residual are worth filling.
    if (mean_residual - bin_residual as f64).abs() > 30.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // residual can host next item; reward closeness to perfect pairing
            let chain_waste = post_residual - next_item_size;
            score -= 300.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportional to dead space
            score += 50.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // Relative-to-mean residual shaping: prefer bins with residual below mean
    // (compact bins absorb items, keeping larger residuals available)
    if bin_residual as f64 > mean_residual {
        score += 0.4 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - bin_residual as f64);
    }

    // Penalize creating tiny unusable dead space (hard to fill later)
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Early stream: be slightly conservative, keep flexibility
    let progress = step_index as f64 / total_items as f64;
    score += 30.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        score += 60.0 + 5.0 * open_bins_count as f64;
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score += 250.0; // an open bin could chain with next item; avoid new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize leaving small unusable gaps (dead space 1..=15 is wasted).
    if post_residual > 0 && post_residual < 16 {
        score += 25.0;
    }
    // Reward near-perfect closures.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty if this bin could have held it.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fill_ratio < 0.5;
        // Prefer new bin early or when item is large relative to capacity and fits are loose.
        if poor_fit && item_size >= bin_capacity / 2 {
            score -= 20.0 * (1.0 - progress);
        } else {
            score += 45.0 + 10.0 * open_bins_count as f64;
        }
    }

    // Global state coupling: if mean residual is high, prefer bins below the mean
    // (consolidate into emptier bins to leave big gaps elsewhere).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    // Slight preference for bins with more remaining space when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // base: prefer small post residual, smoothed polynomial
    let mut score = x * x * (3.0 - 2.0 * x);

    // non-linear coupling of post_residual with stream progress
    let progress_coupling = x.powf(2.0 + t) * (1.0 - t);
    score += 20.0 * progress_coupling;

    // dead space penalty: unusable residual relative to typical item sizes
    let dead = (x - 0.1).max(0.0);
    score += 15.0 * dead * dead * (1.0 + t);

    // reward tight fits
    score -= 10.0 * (1.0 - x).powi(3);

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * t;
    }

    // lookahead: next item fits comfortably in post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = pr - nxt;
        if slack >= 0.0 {
            score -= 6.0 * (slack / cap);
        } else {
            score += 4.0 * (-slack / cap);
        }
    }

    // pressure from many open bins
    score += 0.05 * open_bins_count as f64 * x;

    // mean residual alignment
    score += 0.1 * (mean_residual - pr).abs() / cap;

    // slight preference to keep new-bin candidate from winning unless necessary
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that lie in "reusable" classes
    // (multiples of common item sizes 10..80 -> classes of 5 and 10).
    let class5 = (post_residual % 5 == 0) as f64;
    let class10 = (post_residual % 10 == 0) as f64;
    let class20 = (post_residual % 20 == 0) as f64;
    score -= 4.0 * class5 + 6.0 * class10 + 4.0 * class20;

    // Dead-space penalty: small nonzero residuals are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Tight fit reward: ratio of item to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or next item will need fresh space anyway.
    if bin_residual == bin_capacity {
        let bad_fit = tightness < 0.4;
        let next_needs_fresh = next_item_size > 0 && next_item_size >= post_residual.max(1) * 0 + bin_capacity && false;
        let _ = next_needs_fresh;
        let next_wont_fit_here = next_item_size > 0 && next_item_size > post_residual;
        if bad_fit || (next_wont_fit_here && post_residual < next_item_size && post_residual < 25) {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    }

    // Lookahead: if next item exactly matches post_residual class, reward leaving it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: prefer bins near the mean residual (balanced packing)
    // early, but prefer consuming large residuals late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15 * (1.0 - progress);
    score -= progress * (post_residual as f64) * 0.3;

    // Integer division threshold: residual bands via capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        score -= 18.0; // perfect closure
    } else if post_residual <= quarter {
        score += 3.0;
    } else if post_residual <= half {
        score -= 2.0;
    } else {
        score -= 5.0;
    }

    // Mild penalty for too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals that are too small for the
    // smallest plausible item (1..100 range, but typical min ~10) are wasted.
    let dead_threshold = 9u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0;
    }
    // Slightly less harsh for near-dead residuals that only fit tiny items.
    if post_residual >= dead_threshold && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (post_residual small but usable).
    if post_residual > 0 && post_residual <= 25 {
        score -= 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; penalize candidates that leave large slack.
    let pressure = (open_bins_count as f64).sqrt() * 1.5;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the fit in this bin is bad
    // (large post_residual dead space) or no real bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // But if the item would leave a bad gap elsewhere, opening a fresh bin
        // becomes relatively better; the raw post_residual term already reflects
        // the gap in the empty bin (= capacity - item), so boost when that is small.
        if post_residual < 20 {
            score -= 45.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward
    // leaving that space available.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 * (1.0 - diff / bin_capacity as f64);
    }

    // Late in the stream, tighten up: prefer compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "lonely tight" bin — finishing it off is good.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: strongly reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to leftover after next
            let after_next = post_residual - next_item_size;
            score -= 100.0 + after_next as f64 * 0.5;
        } else {
            // dead space for next item: penalize the unusable gap
            let gap = next_item_size - post_residual;
            score += gap as f64 * 2.0;
        }
    }

    // Penalize small unusable residuals relative to typical item sizes
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Compare residual against mean residual: prefer filling below-mean (wasted) bins
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: keep it neutral-ish, only attractive when current fit is bad
    if bin_residual == bin_capacity {
        score += 80.0;
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize small post-residuals that are too small for typical future items
    // (dead space), but reward exact/near-exact closure.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 6.0; // tiny dead space of 1..9 is nearly unusable
        } else {
            // dead space penalty grows as post_residual shrinks relative to smallest useful chunk
            let usable = (post_residual as f64 / 30.0).min(1.0);
            score -= 8.0 * (1.0 - usable);
        }
    } else {
        score -= 20.0; // perfect closure is excellent
    }

    // Lookahead coupling: if next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // extra reward if next item then nearly closes the bin
        let after_next = post_residual - next_item_size;
        if after_next < 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty proportional to wasted lookahead
        score += 3.0;
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so that any
    // decent existing fit beats it, but a very poor fit (large post_residual on a
    // full-ish bin) lets the new bin win.
    if bin_residual == bin_capacity {
        score += 30.0;
        // early in the stream, opening bins is cheaper (fewer open bins penalty later)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 40.0; // must open a bin
        }
    }

    // Prefer filling bins that are already relatively empty when mean residual is high
    // (spread load), and prefer fuller bins when mean residual is low (consolidate).
    if bin_residual < bin_capacity {
        let bin_fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score -= 5.0 * (bin_fullness - mean_fullness);
    }

    // Mild penalty for accumulating too many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * progress;

    // Prefer bins whose residual is close to item size in absolute terms.
    score -= 10.0 / (1.0 + (bin_residual - item_size) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, tighten tolerance for wasted space
    let late = progress * progress;
    score += 25.0 * late * norm_post;

    // Penalize dead space that cannot fit plausible future items
    let dead = (post - next_item_size as f64).max(0.0) / cap;
    score += 15.0 * dead * dead;

    // Reward tight fits (post_residual near zero) with smooth discount
    score -= 10.0 * (1.0 - norm_post).powi(4);

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - late + 0.5);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Favor opening a new bin only when the fit would be very poor,
    // i.e. when item is small relative to capacity (large post-residual).
    if bin_residual == bin_capacity {
        let openness = (item_size as f64 / cap).powi(2); // small item -> small openness
        score -= 8.0 * openness * (1.0 - progress);
        // discourage opening new bins when good fits exist elsewhere
        if fitting_bins_count > 1 {
            score += 20.0 * (1.0 - openness);
        }
    } else if fitting_bins_count == 1 {
        // strongly prefer using the last fitting existing bin over a new bin
        score -= 20.0;
    }

    // Mild global pressure: many open bins -> prefer consolidating into existing ones
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Slight deviation from mean residual: prefer bins with residual close to item fit
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Penalize residuals in "dead zones" that few future items can fill.
    // Harmonic classes via integer division thresholds on post_residual.
    let class = post_residual / 10; // 0..=10 classes
    match class {
        0 => score -= 25.0,           // near-perfect fit: strongly reward
        1 => score -= 15.0,           // excellent fit
        2 => score -= 8.0,            // good fit
        3 | 4 => score += 3.0,        // awkward mid zone
        5 | 6 => score += 6.0,        // half-full-ish: mediocre
        7 => score += 2.0,            // can host medium items
        _ => {}                        // large residual: neutral
    }

    // Reward residuals that are harmonic multiples of common item sizes (modulo logic).
    if post_residual > 0 {
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                score -= 4.0;
                break;
            }
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 10.0 + (slack as f64).min(15.0) * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this residual: penalize proportionally.
        score += (post_residual as f64) * 0.1;
    }

    // New-bin candidate handling: only prefer empty bin when open bins are crowded
    // or the fit is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (mean_residual / cap + 1.0);
        let poor_fit = (item_size as f64) < 0.35 * cap;
        if mean_residual < 0.2 * cap || (poor_fit && progress > 0.3) {
            score -= 12.0 + crowd * 0.5;
        } else {
            score += 40.0; // discourage opening new bins by default
        }
    }

    // Mild tie-break toward tighter bins overall.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item (or the lookahead item) are pure waste.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0; // unusable sliver
    }
    // Penalize residuals that cannot fit the known next item either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 30.0 * tightness * tightness;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing
    // bins and penalize the new-bin candidate.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 35.0 + 4.0 * open_bins_count as f64;
        // Opening a new bin is acceptable late in the stream or when existing
        // residuals are large and fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if post_residual as f64 > mean_residual {
            score -= 20.0 * progress;
        }
    } else {
        score -= 2.0 * open_bins_count as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Prefer bins whose residual is close to the mean (keeps bin states balanced).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits perfectly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot follow into this bin; slight penalty if we leave large gap.
            score += 3.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or many bins are open with high residual spread.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.5 * cap;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / cap);
        if poor_fit {
            score -= 15.0 + congestion;
        } else {
            score += 45.0 + 5.0 * congestion;
        }
    }

    // Time horizon: early in the stream, be more conservative with existing bins
    // (keep flexibility); late in the stream, fill bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * tightness;
    score += (1.0 - progress) * 4.0 * (post_residual as f64 / cap);

    // Prefer bins whose residual deviates from the mean in a useful way
    // (below-mean residual bins are "nearly full" -> use them first).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth non-linear coupling: penalize large post_residual more as stream progresses
    let poly = norm_pr * norm_pr * (0.5 + progress) + norm_pr * norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 40.0 * poly;

    // Reward tight fits (small post_residual), stronger late in the stream
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.4 + 0.6 * progress);

    // Dead-space penalty: post_residual too small for typical items is wasted
    let dead = if pr > 0.0 { (norm_item * (1.0 - norm_pr)).max(0.0) } else { 0.0 };
    score += 15.0 * dead * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + 0.5 * progress);
    }

    // Lookahead: reward if next item fits in post_residual, penalize otherwise
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 10.0 * (next_item_size as f64 / cap);
        } else {
            score += 8.0 * (1.0 - pr / cap);
        }
    }

    // Crowd penalty: many open bins -> prefer consolidating into tighter bins
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * crowd * norm_pr;

    // Mean-residual deviation: prefer bins whose residual diverges from mean (extreme fits)
    let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
    score -= 5.0 * dev * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - norm_item) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless current bin is a poor host.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin.
        score = cap * 0.9;
        // Attractive if the item is large and would leave a well-structured residual.
        let frac = item_size as f64 / cap;
        if frac > 0.8 {
            score -= 30.0; // big item nearly fills a fresh bin: good
        }
        // If many bins fit the item, prefer reusing one of them.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
        // Late in the stream, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        return score;
    }

    // Harmonic class of post_residual: reward residuals in "reusable" classes.
    // Class A: post_residual divisible by 10 (aligns with typical item granularity).
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Class B: post_residual divisible by 25 (quarter-capacity harmonics).
    if post_residual % 25 == 0 {
        score -= 6.0;
    }
    // Dead-space class: tiny residuals that nothing (min size 1..) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
            // Harmonic check: next item leaves a class-A residual too.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this bin's residual: penalize wasted space.
            score += next_item_size as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer tighter bins: residual close to item size is efficient.
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * 10.0;

    // Penalize bins far from mean residual (keeps residual distribution uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Integer-division threshold: bins whose residual class (residual/20) matches
    // the item's class get a small consistency reward.
    if (bin_residual / 20) == (item_size * 2 / 20) {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1..=100 range,
    // but small gaps < 12 are statistically hard to fill) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (post_residual near zero).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly;
    // if it cannot fit, penalize the dead space created.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins when few bins needed;
    // encourage using existing bins more when many are open.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins whose residual is below the mean (tighter bins) to consolidate space.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // New-bin candidate logic: an empty bin gets a baseline cost that scales with
    // stream progress (early on, opening bins is cheap; late, prefer filling existing).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 + 70.0 * progress + open_bins_count as f64 * 1.5;
        // If no open bin fits (this call is the only option), make new bin cheap.
        if fitting_bins_count == 0 {
            score = 5.0;
        }
        // Large item with lookahead: opening fresh may be fine.
        if item_size >= 50 && next_item_size >= 40 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits: perfect fit strongly preferred.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio * fit_ratio;
    }

    // Penalize dead space relative to typical next item needs.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless it offers an excellent fit
    // (i.e., item nearly fills a fresh bin) or late in the stream with
    // many fragmented bins.
    if is_new_bin {
        let fill = item_size as f64 / bin_capacity as f64;
        let mut penalty = 12.0 * (1.0 - fill);
        if fill > 0.85 {
            penalty -= 20.0; // big item into fresh bin is fine
        }
        if fitting_bins_count > 1 {
            penalty += 5.0; // alternatives exist, don't open new bin
        }
        if progress > 0.7 && mean_residual < item_size as f64 {
            penalty -= 8.0; // late stream, existing residuals unusable
        }
        score += penalty;
    }

    // Prefer bins whose residual is close to mean residual (balance),
    // scaled mildly by stream progress.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs() * (0.5 + progress);

    // Slight preference for fuller bins early (compact packing).
    score += 0.1 * bin_residual as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with stream-dependent curvature
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr * norm_pr);

    // Reward near-perfect fits more strongly as stream progresses
    score -= 14.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Penalize creating dead space unusable by the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && nxt > pr {
            score += 8.0 * (1.0 - nxt / (nxt + pr)) * (1.0 + progress);
        } else if nxt > 0.0 {
            // reward leaving space exactly matching next item
            score -= 6.0 * (1.0 - (pr - nxt).abs() / cap) * (1.0 - progress);
        }
    } else {
        score += 3.0 * norm_pr;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + 0.5 * progress);
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Mild dispersion pressure: prefer bins below mean residual early, above late
    score += 2.0 * ((pr - mean_residual) / cap) * (0.5 - progress);

    // Slight preference for consolidating into fewer bins when many are open
    score -= 0.15 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: make empty bins attractive only for poor fits elsewhere
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress * norm_pr;
        if next_item_size > 0 && (next_item_size as f64) > item_size as f64 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let post_frac = post_residual as f64 / cap;
    let class = (post_frac * 10.0).floor() as i64; // 0..=9 decile of dead space

    // Reward small dead space non-linearly; dead space in the lowest deciles is cheap.
    score += 8.0 * post_frac * post_frac;

    // Penalize "awkward" residual classes that rarely admit future items.
    // Residuals in (0,10] and (10,20] are nearly unusable for items >= 10..80 range,
    // but with unknown 1..100 items small residuals are still usable; instead
    // penalize the mid-band 30..50 which is a classic dead zone.
    if post_residual >= 30 && post_residual <= 50 {
        score += 12.0;
    }

    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic modulo coupling: does the post-residual lie in the same
    // modular class as the next item? If post_residual mod 10 == next_item_size mod 10
    // and next item fits, reward the chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        let m = (post_residual % 10) as i64 - (next_item_size % 10) as i64;
        let harmonic_match = (m == 0) as f64;
        score -= 6.0 * harmonic_match;
        // General lookahead: next item fits exactly into the residual.
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Next item leaves a further small residual (chained tight packing).
        if post_residual - next_item_size <= 10 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small for the lookahead: this bin becomes dead.
        score += 4.0 * (1.0 - post_frac);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has full residual. Prefer opening
    // a new bin only when all open bins would leave a large dead zone.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // Cheaper to open a new bin when many bins are already open and
        // mean residual is high (fragmented state).
        score += 0.5 * open_bins_count as f64;
        if mean_residual > 40.0 {
            score -= 10.0;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 60 {
            score -= 8.0;
        }
    }

    // Slight preference for tighter bins early in the stream (keep loose bins
    // available for large items later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * (bin_residual as f64 - post_residual as f64) * 0.02;

    // Small tie-breaker proportional to fill ratio.
    score -= (cap - post_residual as f64) / cap * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead space relative to capacity: waste ratio penalty.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 20.0;

    // If next item could exactly use the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if post residual is too small for the next item (dead end).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
        // But allow new bin if current bin would leave very tight dead space.
        if post_residual < 10 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Late in stream, prefer tighter fills to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), but with diminishing returns
    // so that small differences in dead space matter less than lookahead matching.
    score = (post_residual as f64).powf(1.25);

    // --- 2-step lookahead: reward bins whose post_residual matches next_item_size ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match (post_residual == next_item_size) gets a strong bonus.
        if diff == 0.0 {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Bin can host the next item too: bonus proportional to closeness of match.
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize dead space more when
            // the leftover is unusable but not tiny.
            score += 4.0 + 0.15 * diff;
        }
    } else {
        // Last item: pure tight-fit, no future to plan for.
        score -= 5.0;
    }

    // --- Compare bin's residual against the mean residual of open bins ---
    // Bins with residual below mean are "dying" bins; using them consolidates waste.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly favor it ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // A fresh bin is only attractive when existing bins fit poorly:
        // penalize it by the item size (bigger items leave more absolute waste risk),
        // but give a discount when many bins are open and fragmented.
        score += 20.0 + 0.3 * item_size as f64;
        if open_bins_count > 8 {
            score -= 8.0;
        }
        // If next item is large and this item is small, a new bin is reasonable.
        if next_item_size > 60 && item_size < 40 {
            score -= 10.0;
        }
    }

    // --- Stream progression: early on, be conservative (keep bins flexible);
    // late in the stream, pack aggressively into tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize tiny dead space only when it's truly unusable (below smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Dead-space penalty grows if post-residual can't fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // keeps a useful option for next item
        } else {
            score += 12.0; // lookahead item can't use this bin's remainder
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when the item is
    // large relative to capacity (worth a fresh canvas) or no tight option exists.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // Penalize opening new bins for small items; slight reward for large ones.
        score += 55.0 * (1.0 - frac) * (1.0 - frac);
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If many open bins already exist, discourage spreading.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Reward using existing bins, more so when they're below the mean residual
        // (i.e., we're consolidating fuller bins).
        let mr = mean_residual.max(1.0);
        if (bin_residual as f64) < mr {
            score -= 10.0;
        } else {
            score += 6.0;
        }
        // Mild reward for reducing the number of open bins' average residual spread.
        score -= 3.0 * fill_ratio;
    }

    // Late-stream consolidation: as the stream ends, prefer filling existing bins fully.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Smooth polynomial coupling of post_residual with stream progress.
    let t = progress;
    let w = 0.5 + 0.5 * t; // later in stream -> weight residual waste more
    let mut score = pr * (0.6 + 0.8 * w * w);

    // Non-linear waste shaping: penalize small-but-nonzero residuals (dead space)
    let x = pr / cap;
    score += 12.0 * x * (1.0 - x) * (1.0 - x);

    // Reward tight fits (small post_residual) with smooth quadratic bonus
    score -= 10.0 * (1.0 - x) * (1.0 - x);

    // Lookahead coupling: penalize if post_residual can't fit next item but is large enough to be wasted
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            // next item still fits in leftover: mild reward
            score -= 3.0 * (gap / cap);
        } else {
            // leftover is dead space relative to next item: penalize proportionally
            score += 6.0 * (-gap / cap) * (1.0 - t);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: default penalty so it's chosen only when open bins fit poorly
    if is_new_bin {
        score += 15.0 + 10.0 * t;
        // allow new bin if all open bins would leave large dead space
        if pr >= 0.35 * cap {
            score -= 30.0;
        }
    } else {
        // mild preference for fuller bins among open ones
        score -= 2.0 * (1.0 - bin_residual as f64 / cap);
    }

    // Mean residual coupling: if this bin is far from mean residual, slight penalty
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quanta of 10
    let post_class = (post_residual / 10) as f64;
    let post_rem = (post_residual % 10) as f64;
    score += post_rem * 0.9; // penalize non-aligned dead space

    // Reward tight fits (small post residual)
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Reward residuals that match harmonic classes likely usable by future items
    // (items 1..100; common sizes cluster near multiples of 10)
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 6.0 * post_class.min(5.0);
    }

    // Lookahead coupling: does next item fit in post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // perfect harmonic match bonus
            if post_residual == next_item_size {
                score -= 20.0;
            } else if post_residual.saturating_sub(next_item_size) <= 5 {
                score -= 8.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score = cap - (item_size as f64); // residual after placing in fresh bin
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        } else {
            score += 15.0; // discourage wasting fresh bin when fits exist
            // allow fresh bin for large items leaving awkward remainders
            if item_size > 70 {
                score -= 10.0;
            }
        }
    }

    // Late in stream: consolidate, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (mean_residual / cap);

    // Mild pressure from number of open bins
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (proportional dead-space tax).
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin residual (best-fit sharpening).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Last chance: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits poorly everywhere else. Penalize new bins mildly, scaled by
    // open-bin pressure.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 1.5;
        // If lookahead item can use the leftover of this placement, new bin
        // becomes more attractive (pairing large items together).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    } else {
        // Open-bin pressure: with many open bins, prefer consolidating into
        // bins that remain usable; with few bins, mild preference for tight fit.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (mean_residual - post_residual as f64) * 0.3 * (1.0 - progress);
    }

    // Penalize leaving residuals that exactly block the lookahead item's fit
    // elsewhere is unknown; instead reward residuals >= next_item_size so the
    // bin stays useful.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins where the NEXT item also fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: next item lands here too -> big reward.
            score -= 40.0 + 0.35 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here; penalize leftover dead space
            // that is too small to be useful for typical items.
            if post_residual < 10 {
                score += 60.0; // tiny dead space is wasted capacity
            } else {
                score += 0.25 * post_residual as f64;
            }
        }
    } else {
        // Last item: just prefer tightest fit.
        score += 0.1 * post_residual as f64;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare against mean residual: placing into a below-average-residual
    // bin keeps large-capacity bins free for larger future items.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate (empty bin): make it attractive only when the fit
    // is poor or no good alternative exists.
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual {
            // Opening fresh bin keeps residual high; mildly attractive early.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 20.0 * (1.0 - progress);
        } else {
            score += 25.0; // discourage new bins when existing fits are tight
        }
    }

    // Slight preference for filling more of the bin relative to capacity.
    score -= 0.2 * (item_size as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_frac = (mean_residual / c).clamp(0.0, 1.5);

    // ----- Brand-new empty bin candidate -----
    if bin_residual == bin_capacity {
        // No open bin exists at all: opening is forced, make it win decisively.
        if open_bins_count == 0 {
            return -1000.0 + pr;
        }
        let mut s = pr; // leftover space in the fresh bin (c - item_size)
        // Opening cost: grows with stream progress (late bins stay underused).
        s += 25.0 + 30.0 * progress;
        // If existing open bins already hold plenty of room on average, opening more is wasteful.
        s += 12.0 * mean_frac;
        // Many alternatives already fit this item -> keep consolidating.
        s += 4.0 * (fitting_bins_count as f64).min(6.0);
        // Mild penalty when the bin population is already large.
        s += 1.5 * (open_bins_count as f64).min(10.0);
        // Lookahead coupling for the fresh bin.
        if nis > 0.0 {
            if pr >= nis {
                // Reward a tight chain with the next item (scaled down near the end).
                let tight = 1.0 - (pr - nis) / c;
                s -= 30.0 * tight * (1.0 - 0.4 * progress);
            } else {
                // Fresh bin would itself strand dead space for the next item.
                let frac = (nis - pr) / nis;
                s += (15.0 + 35.0 * frac) * (0.7 + 0.3 * mean_frac.min(1.0));
            }
        }
        return s;
    }

    // ----- Existing open bin -----
    // Tighter fit is better; amplify tightness pressure as the stream matures.
    let mut s = pr * (1.0 + 0.35 * progress);

    if pr <= 0.0 {
        // Perfect closure: bin exactly filled, zero waste.
        s -= 40.0;
    } else if nis > 0.0 {
        if pr >= nis {
            // The next item can chain into this bin; reward tighter chains.
            let tight = 1.0 - (pr - nis) / c;
            s -= 30.0 * tight * (1.0 - 0.4 * progress);
        } else {
            // Dead zone: leftover is too small for the next item -> stranded space risk.
            let frac = (nis - pr) / nis;
            s += (15.0 + 35.0 * frac) * (0.7 + 0.3 * mean_frac.min(1.0));
        }
    }

    // Last chance: this is the only open bin that can take the item.
    // Strongly prefer it over spawning a new bin.
    if fitting_bins_count <= 1 {
        s -= 70.0;
    }

    s
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (0.5 + progress) - norm_post * norm_post * norm_post * (1.0 + 2.0 * progress);
    score += 40.0 * poly;
    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (10.0 + 20.0 * progress);
    // Penalize last-chance bins when fit is poor
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score += (1.0 - norm_post) * 15.0;
    }
    // Lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 8.0 * (1.0 - diff / cap).max(0.0);
    }
    // Mild penalty when bin residual deviates from mean residual
    score += 0.05 * (pr - mean_residual).abs();
    // Slight preference to reuse open bins vs opening new ones late in stream
    score += if bin_residual == bin_capacity { 5.0 + 10.0 * (1.0 - progress) } else { 0.0 };
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of the item: divide capacity into 4 classes.
    let item_class = item_size / 25; // 0..3
    let next_class = (next_item_size as u32) / 25;

    // Reward pairing complementary harmonic classes: small item into a bin
    // whose residual belongs to a "harmonic" band matching next item size.
    if !is_new_bin {
        // Dead space penalty: superlinear waste for tiny unusable residuals.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
        // Perfect fit reward.
        if post_residual == 0 {
            score -= 40.0;
        }

        // Harmonic coupling: reward when post_residual band matches next item's
        // class band (i.e., the leftover is a "harmonic multiple" of next item).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0 + 0.5 * (post_residual as f64 / next_item_size as f64);
        } else if next_item_size > 0 && post_residual > 0 {
            // leftover too small for lookahead item: penalize proportionally
            score += 0.6 * (next_item_size - post_residual as u32) as f64;
        }

        // Integer-division threshold on post_residual: residues in the
        // [1..25) band are the most fragile; in [25..50) they can host
        // class-1 items; keep those attractive.
        let band = post_residual / 25;
        score -= 3.0 * band as f64;

        // Last-chance bin: strongly prefer using it before opening a new one.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Prefer tighter bins (small residual before placement) mildly.
        score += 0.15 * bin_residual as f64;

        // Late in stream: consolidation matters more; penalize spread.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 0.2 * (bin_residual as f64 - mean_residual).abs();
    } else {
        // New-bin scoring: base cost of opening a bin.
        score = 0.5 * bin_capacity as f64;

        // Open new bin only if item is large (harmonic class >= 2) or
        // existing bins are quite full on average.
        if item_class >= 2 {
            score -= 20.0;
        }
        if mean_residual < (item_size as f64) {
            score -= 25.0;
        }
        // If many bins already fit the item, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 35.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Lookahead harmony: new bin is good if next item also large.
        if next_class >= 2 {
            score -= 10.0;
        }
        // Early stream: slightly cheaper to open bins (build diversity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Open-bin pressure: discourage proliferation of bins unless fit is good.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item is large or many bins open.
        score += 15.0 - 0.05 * open_bins_count as f64;
        if item_size > 60 {
            score -= 20.0;
        }
    } else {
        score += 0.02 * open_bins_count as f64;
    }

    // Mild progression term: later in stream, prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: post_residual equals next item -> big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Remaining gap after the lookahead item; smaller gap is better.
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 - gap.min(30.0) * 0.3;
        } else {
            // Dead space below the next item size: penalize proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.6;
        }
    }

    // Perfect fit of the current item.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Tight fit relative to capacity: reward small post_residual.
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize bins far below mean residual (fragmented bins) mildly.
    score += ((mean_residual - bin_residual as f64).abs()) * 0.05;

    // Prefer reusing open bins over opening new ones as stream progresses.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        score -= 3.0;
    }

    // Prefer filling bins with larger residual when many bins are open.
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0 * (open_bins_count.min(20) as f64 / 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: residual left behind that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 18.0;
            // Extra reward when next item fills the remaining space well.
            let nxt_fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * nxt_fill;
        } else {
            // Next item won't fit here: penalize leaving awkward residual.
            if post_residual < next_item_size as f64 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base hesitation to open new bins while open bins exist.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= 0.25 * item_size as f64;
        // If no open bin fits well (mean residual low relative to item), encourage new bin.
        if (mean_residual as u32) < item_size + 5 && bin_capacity >= item_size {
            score -= 20.0;
        }
    }

    // Global pressure: when many bins are open with high mean residual, prefer
    // consolidating into existing bins (penalize spreading).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (mean_residual / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean (balance load) mildly.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Slight preference for bins with less residual overall (best-fit flavor).
    score += 0.03 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: minimize leftover space, with a non-linear (quadratic) penalty on waste.
    let mut score = post + 0.35 * (post / cap) * post;

    // Smooth polynomial coupling of waste with stream progress:
    // early on, waste is tolerable; late in the stream, dead space is costly.
    let waste_weight = 0.5 + 1.6 * progress * progress + 0.9 * progress * (1.0 - progress);
    score += waste_weight * (post / cap) * post;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - (post / (item + post + 1.0));
    score -= 6.0 * tightness * tightness;

    // Penalize bins whose residual deviates far below the mean residual
    // (isolating a nearly-full bin wastes its scarcity elsewhere).
    let dev = (mean_residual - post) / cap;
    score += 1.2 * dev * dev * cap * 0.1;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (scaled smoothly by how full it becomes).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * (1.0 - post / cap);
    }

    // Lookahead: reward if the next item exactly fills the post residual,
    // penalize if next item cannot use the leftover.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= 5.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate handling: a fresh bin has residual == capacity.
    // Prefer opening a new bin only when all fitting options are poor
    // (large waste) or the stream is early and flexibility is valuable.
    if bin_residual == bin_capacity {
        let flexibility_bonus = 3.0 * (1.0 - progress);
        score += flexibility_bonus;
        // Discourage new bins when the item fits snugly somewhere already:
        // estimate waste if placed here (item alone in empty bin).
        let fresh_waste = (cap - item) / cap;
        score += 4.0 * fresh_waste * fresh_waste * cap * 0.1;
    }

    // Mild congestion term: many open bins -> consolidate rather than spread.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residual values that are "reusable" sizes
    // (divisible into common item classes 1..100), penalize dead space that
    // cannot host typical future items.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus: f64 = if pr % 10 == 0 {
            -6.0 // round-class residual: highly reusable
        } else if pr % 5 == 0 {
            -3.0
        } else if pr >= 10 {
            -1.0
        } else {
            8.0 // tiny dead space (<10): nearly useless
        };
        score += class_bonus;

        // Perfect fit gets strongest reward.
        if pr == 0 {
            score -= 25.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chaining).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr && pr - next_item_size <= 5 {
            score -= 12.0;
        } else if next_item_size <= pr {
            score -= 4.0;
        }
        // If next item cannot fit here anyway, mild penalty for wasting the slot.
        if next_item_size > pr && pr < 10 {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets baseline cost so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.15 * open_bins_count as f64;
    }

    // Prefer filling bins with larger residuals when mean residual is high
    // (spread usage), mildly.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Late in the stream, tighten packing: penalize loose fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Medium dead space (10..=20) is mildly penalized since few items fit.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tightness ratio: reward bins whose fill fraction is high.
    let tightness = (item_size as f64) / (bin_residual as f64);
    score -= 25.0 * tightness;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones and
    // encourage consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / 10.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 35.0 + 12.0 * open_pressure;
    } else {
        score -= 6.0 * open_pressure;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that the next item cannot use: extra penalty.
        score += 10.0;
    }

    // Late in the stream, prefer tighter packing overall.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Prefer bins below mean residual (fill emptier bins first, keep tight bins tight).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step match: post_residual == next_item_size is a perfect pairing.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Dead space: post_residual too small to hold the next item is likely wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 1.5 * gap;
        // Extra penalty for very tight unusable slivers.
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Reward closeness to mean residual: bins near average keep flexibility.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * diff;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave tiny waste
    // and the item fits very snugly; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.9 {
            score -= 25.0; // huge item: fresh bin is fine
        }
    }

    // Slight preference for fuller bins as the stream progresses.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill * (0.5 + 0.5 * step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Base: penalize wasted space quadratically, scaled by capacity.
    let waste = post_residual as f64;
    score += 0.35 * (waste / bin_capacity as f64) * waste;

    // New-bin candidate: strongly penalize unless the fit is very tight
    // or no open bin can otherwise take the item.
    if is_new_bin {
        score += 60.0;
        if post_residual <= 5 {
            score -= 45.0; // near-perfect fit justifies a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 70.0; // forced to open a new bin
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 25.0 * (1.0 - progress);
    } else {
        // Last-chance bonus: if this is the only bin that fits, avoid waste elsewhere.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Reward snug fits.
        if post_residual <= 3 {
            score -= 15.0;
        } else if post_residual <= 10 {
            score -= 6.0;
        }
        // Lookahead: penalize leaving a residual that is awkwardly close to but
        // smaller than the next item (dead space for the future item).
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // residual can host the next item: reward proportionally to tightness
                let slack = (post_residual - next_item_size) as f64;
                score -= 8.0 * (1.0 - slack / bin_capacity as f64);
            } else {
                // dead space relative to next item
                score += 0.25 * (next_item_size - post_residual) as f64;
            }
        }
        // Prefer filling bins with below-average residual (balance avoidance of
        // many half-empty bins) but only mid-stream.
        if (bin_residual as f64) < mean_residual {
            score -= 4.0 * (1.0 - progress);
        } else {
            score += 2.0 * progress;
        }
        // Mild penalty for spreading across many open bins.
        score += 0.5 * open_bins_count as f64 * progress;
    }

    // Global tiny tie-breaker on residual.
    score += 0.01 * post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post_residual, with non-linear (quadratic) coupling
    let mut score = post + 0.9 * (post / cap) * post;

    // Smooth interaction: waste penalty grows with stream progress
    score += 4.0 * (post / cap).powi(2) * (0.5 + progress);

    // Reward filling bins tightly (fraction of bin consumed, squared)
    score -= 3.0 * (item / cap).powi(2) * 10.0;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    } else {
        // Mild penalty when many bins compete (spread items, keep flexibility)
        score += 0.6 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 2.0 * (gap / cap);
        }
    }

    // Penalize bins far from mean residual (keep residuals homogeneous, smooth term)
    let dev = (res - mean_residual) / cap;
    score += 3.0 * dev * dev * cap * 0.1;

    // New-bin candidate: make it costly unless residuals are nearly exhausted
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        // Cost decreases smoothly as existing bins get fuller / progress advances
        score += 30.0 - 18.0 * mean_fill - 10.0 * progress;
        if fitting_bins_count == 1 {
            score += 40.0; // never open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but penalize "dead space"
    // residuals that are too small to ever be useful (harmonic class < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Harmonic classes of post_residual: classify by decade buckets.
    // Residuals in [10,30) are moderately useful; [30,60) good; [60,100) best.
    let pr = post_residual;
    if pr >= 60 {
        score -= 8.0;
    } else if pr >= 30 {
        score -= 4.0;
    } else if pr >= 10 {
        score -= 1.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits, but how snugly? modular harmonic residue
            let leftover = pr - next_item_size;
            if leftover < 10 {
                score -= 18.0; // near-perfect chain
            } else {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: mild penalty if we consumed space it needed
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when current fits are bad.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; make it unattractive when open bins give decent fits.
        score = bin_capacity as f64 - 5.0;
        if fitting_bins_count == 1 {
            // forced-ish: new bin becomes competitive
            score = bin_capacity as f64 - 20.0;
        }
        if post_residual == bin_capacity {
            // placing a huge item (>= item near capacity) in fresh bin is fine
            score = (bin_capacity - item_size) as f64;
        }
    }

    // Late-stream pressure: as stream progresses, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 4.0 * (mean_residual / bin_capacity as f64);
    }

    // Mean residual coupling: if this bin's residual is far above mean, it's a
    // good "sponge" bin; if far below, prefer not to fragment it further.
    let res_f = bin_residual as f64;
    if res_f < mean_residual - 20.0 {
        score += 5.0;
    } else if res_f > mean_residual + 20.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver (min item size is 1..100, small gaps rarely reusable)
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Fractional fit quality: tighter packing favored
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fit_ratio;
    }

    // Penalize bins whose residual is already small relative to capacity (avoid wasting tight bins on loose fits)
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += 10.0 * (1.0 - residual_frac) * (1.0 - item_size as f64 / bin_residual.max(1) as f64);

    // Open-bin pressure: with many open bins, discourage opening new ones
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 25.0 + 3.0 * pressure;
        // If only this new bin can fit the item, must open it
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it over opening a new bin
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover: leftover likely dead space
            score += 15.0;
        }
    }

    // Late in stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !new_bin_candidate {
        score -= 10.0 * progress;
    }

    // Slight preference for bins below mean residual (balance load)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits snugly in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit here: residual likely becomes dead space.
    if next_item_size > 0 && next_item_size > post_residual {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 5.0; // tiny dead space is fine
        } else {
            score += dead * 0.6; // penalize unusable gap
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (consolidate space), avoid burning down large-residual bins unnecessarily.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Slight preference for filling more-open bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score += open_bins_count as f64 * 0.05 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when residual is full (empty) and the
    // item leaves little waste there or current fit is poor.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = 100.0 + waste * 0.5;
        if next_item_size > 0 && next_item_size <= waste as u32 {
            score -= 30.0;
        }
        if fitting_bins_count == 1 {
            score += 80.0; // don't open a new bin when one exists that fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of capacity consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: post_residual small relative to capacity
    score -= 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize creating dead space that cannot fit the next item (lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving exactly enough room for the next item (chained fit)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Penalize picking from a large pool of fitting bins unless the fit is tight:
    // prefer tight fits among many candidates.
    if fitting_bins_count > 1 {
        score += 0.15 * (fitting_bins_count as f64 - 1.0) * (post_residual as f64 / bin_capacity as f64);
    }

    // Coupling with global state: if mean residual is high, we have slack everywhere,
    // so prefer bins where this item closes out a residual well.
    if mean_residual > 0.0 {
        score += 0.3 * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
    }

    // Time horizon: early on, be conservative with open bins (avoid waste);
    // late in the stream, aggressively fill existing bins.
    if progress > 0.7 {
        score -= 2.0 * fill_frac;
    } else if progress < 0.2 {
        score += 0.5 * (1.0 - fill_frac);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Base penalty for opening a new bin
        score += 8.0 * pressure;
        // But large items early are fine in a fresh bin
        score -= 6.0 * fill_frac * (1.0 - progress);
        // If the item would leave a very awkward residual in any existing bin
        // (next item won't fit anywhere well), fresh bin may be better.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 2.0;
        }
    }

    // Mild preference for bins with lower-than-mean residual (consolidate slack)
    if (bin_residual as f64) < mean_residual {
        score -= 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = (bin_residual as u64) == (bin_capacity as u64);

    // Base: prefer minimal post-residual, with a non-linear (quadratic) penalty
    // that grows super-linearly as post_residual increases (dead space aversion).
    let x = post / cap; // normalized post residual in [0,1]
    let mut score = post * (1.0 + x * x);

    // Smooth stream-progress coupling: dead space is more acceptable early,
    // increasingly costly as the stream nears completion.
    score += 30.0 * progress * x * (1.0 + progress);

    // Lookahead coupling: reward post-residual that still accommodates the next item,
    // penalize post-residuals that are awkward (too small but nonzero) for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // fits next item: subtract a smooth reward proportional to how "useful" the leftover is
            let slack = (post - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            // cannot fit next item: penalize unusable residue smoothly
            let gap = (nxt - post) / cap;
            score += 18.0 * gap * (2.0 - gap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: opening a bin is cheap early (plenty of stream left to fill it),
    // expensive late. Also discourage opening when many bins already fit the item.
    if is_new_bin {
        score = 40.0 + 120.0 * progress * progress + 6.0 * (fitting_bins_count as f64);
    } else {
        // Mild penalty for very loose fits when many alternatives exist.
        if fitting_bins_count > 1 {
            score += 2.0 * x * (fitting_bins_count as f64 - 1.0).min(5.0) as f64;
        }
        // Reward bins whose residual is below the mean (efficient consolidation).
        score -= 4.0 * ((mean_residual - bin_residual as f64) / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small remainder classes" are more likely to be filled later.
    let pr = post_residual;
    let class = pr % 10; // decile remainder class
    score -= (10 - class) as f64 * 0.35; // reward residues near multiples of 10

    // Integer-division threshold: residues <= 10 are near-perfect closures.
    if pr <= 10 {
        score -= 8.0;
    } else if pr <= 20 {
        score -= 3.0;
    } else if pr >= 60 {
        // large dead space penalty, scaled by fraction of stream completed
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (pr as f64 - 60.0) * (0.4 + 0.6 * progress);
    }

    // Modulo coupling with next item: if the leftover can exactly host the
    // next item (or a harmonic fraction of it), strongly reward.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 12.0;
        } else if pr >= next_item_size && (pr - next_item_size) <= 10 {
            score -= 6.0;
        } else if next_item_size % 10 == 0 && pr % next_item_size.max(1) == 0 && pr > 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    // or the item is huge relative to residual.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / cap;
        let tight = bin_residual as f64 - item_size as f64;
        if tight < 15.0 || fit_ratio > 0.7 {
            score -= 20.0; // opening fresh bin is fine for big items / tight fits
        } else {
            score += 25.0 + mean_residual * 0.2; // discourage abandoning open bins
        }
    }

    // Mild preference for bins below mean residual (tighter packing).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    // Slight exploration pressure early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits generally (fraction of bin consumed).
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Open-bins pressure: penalize bins in proportion to how many are open,
    // encouraging consolidation when many bins exist.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the dead-space penalty is severe.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot use the leftover, penalize creating stranded space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Mean-residual coupling: prefer bins with residual below the mean (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    // New-bin candidate handling: empty bin gets a moderate default penalty so it
    // is chosen only when open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Next item fits into post residual: mild reward proportional to snugness
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Dead space: post residual too small for the next item -> penalty scaled by deadness
    if next_item_size > 0 && post_residual < next_item_size {
        let deadness = post_residual as f64 / next_item_size as f64;
        score += 18.0 * (1.0 - deadness);
    }

    // Tight fit reward relative to mean residual across open bins
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(30.0) * 0.5;
    } else {
        score += (pr - mean_residual).min(30.0) * 0.3;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and can absorb the item well
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 15.0 + 2.0 * open_bins_count as f64;
        }
        // If item is small, a fresh bin wastes capacity
        if item_size < bin_capacity / 3 {
            score += 20.0;
        }
    }

    // Late in stream: favor consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: minimize wasted space quadratically.
    let cap = bin_capacity as f64;
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 24.0 * tight * tight;

    // Penalize dead space that no future item (>=10) can ever use.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect closure
    }

    // Lookahead coupling: reward leaving a residual that the next item can use.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n && post_residual as f64 - n < 10.0 {
            score -= 18.0; // next item fills this bin nearly perfectly
        } else if post_residual as f64 >= n {
            score += 2.0;
        } else {
            score -= 3.0; // next item forces a new bin anyway; keep flexibility elsewhere
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = (post_residual as f64 / cap) - 1.0; // = -item_size/cap for a new bin
        // Cost of opening rises with number of open bins and progress.
        score += 55.0 + 0.6 * open_bins_count as f64 + 20.0 * progress;
        // But if the item is huge relative to mean residual space, new bin may be right.
        let mean_r = if mean_residual.is_finite() { mean_residual } else { cap };
        if (item_size as f64) > mean_r + 0.35 * cap {
            score -= 50.0;
        }
        let _ = pressure;
    }

    // Slight preference for bins below mean residual (consolidate slack).
    let mean_r = if mean_residual.is_finite() { mean_residual } else { cap };
    score += 0.15 * ((bin_residual as f64) - mean_r);

    // Mild time-decay on residual penalty: late in stream, tight packing matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_frac = item_size as f64 / cap;
    let next_frac = next_item_size as f64 / cap;

    // Base: quadratic penalty on wasted residual, smoothed by progress
    let mut score = pr * (1.0 + 0.9 * progress);

    // Cubic coupling: small residuals late in the stream are acceptable (tight fits),
    // large residuals early are heavily penalized
    score += 0.002 * pr * pr * (1.0 - progress) - 0.001 * pr * pr * progress;

    // Reward tight fits (small post_residual relative to item) with smooth term
    score -= 8.0 * fit_frac * (1.0 - pr / cap);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 + 6.0 * next_frac;
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty proportional to gap
        score += 1.5 * (next_frac - pr / cap).max(0.0);
    }

    // New-bin candidate: penalize opening a new bin, more so early/mid stream;
    // relax slightly late when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        score = cap * (1.2 + 0.8 * (1.0 - progress)) - 10.0 * fragmentation * progress;
    }

    // Mild diversity term: prefer bins whose residual deviates from mean
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Harmonic class logic on post_residual: classify leftover space into residue
    // classes modulo 10. Leftovers in classes 0..10 are "usable" by future items
    // (sizes 1..100); odd, prime-adjacent residues are harder to reuse.
    let pr = post_residual as i64;
    let residue_class = pr % 10;
    let class_bonus: f64 = match residue_class {
        0 => 18.0,          // perfectly divisible leftover: highly reusable
        5 => 12.0,          // half-class: medium items fit well
        2 | 4 | 6 | 8 => 9.0, // even classes: many item sizes fit
        1 | 3 | 7 | 9 => 3.0, // odd classes: harder to fill
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: leftover >= 50 is a "half bin" worth protecting;
    // leftover in 1..=9 is near-dead space, penalize gently (but not too much,
    // a nearly-full bin is a success).
    if post_residual >= 50 {
        score -= 8.0;
    } else if post_residual <= 9 {
        score += 4.0;
    }

    // Dead-space penalty scaled by how far into the stream we are: early on,
    // leave flexibility; late, just fill bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / cap) * 10.0;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if ni == pr {
            score -= 25.0;
        } else if ni > pr {
            score += 6.0; // next item won't fit here anyway; keep bin flexible
        } else {
            let next_fit_quality = ni as f64 / pr.max(1) as f64;
            score -= 10.0 * next_fit_quality;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (penalize the new-bin alternative implicitly by
    // rewarding this one).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mean-residual coupling: when open bins are on average roomy, prefer
    // compacting into tighter bins; when bins are tight overall, tolerate slack.
    score += (mean_residual / cap) * 6.0;

    // New-bin candidate handling: an empty bin has residual == capacity and
    // post_residual == capacity - item_size. Only open a new bin when the item
    // is large relative to all available residuals or there are no good fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 30.0;
        // But if item is big (>= 70) or no other bin fits well, opening is fine.
        if item_size >= 70 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in the stream, fewer bins matter less than tight packing.
        if progress > 0.8 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item can use are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fill
    } else if post_residual < next_item_size.max(min_item) {
        // gap unusable by the next item; penalize proportionally to how "dead" it is
        score += 12.0 + (post_residual as f64) * 0.25;
    } else {
        // gap usable by next item: reward
        score -= 6.0;
    }

    // Tight fit reward: fraction of residual consumed
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_frac;

    // Last chance: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    score += (open_bins_count as f64) * 0.35;

    // New-bin candidate: only attractive when nothing fits well anywhere
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // early stream: opening bins is cheap and gives future flexibility
        if (step_index as f64) / (total_items.max(1) as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual deviates below the mean (fill the emptier bins first)
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly or well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 400.0; // perfect chain: post residual matches next item exactly
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64); // tighter chain fits preferred
        } else {
            // next item cannot fit: post residual becomes dead space
            score += 0.05 * (post_residual as f64);
        }
    }

    // Prefer bins whose residual deviates from mean residual (tighter-than-average bins get priority)
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when a good fit exists in an open bin
    if bin_residual == bin_capacity {
        score += 100.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 50.0;
        }
    }

    // Late-stream tightening: as stream progresses, prefer filling bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
