    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead synergy: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item cannot use leftover; penalize proportional waste.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: minimize leftover aggressively.
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // global residuals are large/fragmented or stream is early.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty so we only open when open bins fit poorly.
        score += 20.0;
        // Early in the stream, opening bins is cheaper (more future items to fill).
        score -= 10.0 * (1.0 - progress);
        // Many open bins with high mean residual => fragmentation; opening fresh
        // bin can be preferable to jamming into a bad fit.
        if mean_residual > 30.0 && open_bins_count > 3 {
            score -= 8.0;
        }
        // If item is large relative to capacity, a fresh bin is natural.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 6.0;
        }
    }

    // Mild preference to keep bins balanced: avoid dumping into bins whose
    // residual deviates far below the mean (keeps options open).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.08 * dev;
    }

    // Small global load balancing term.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let phase = std::f64::consts::PI * progress;
    let wave = 0.5 * (1.0 + phase.sin());
    score += 12.0 * norm_pr * norm_pr * (1.0 - wave);
    score -= 18.0 * norm_pr * (1.0 - norm_pr) * wave;

    // Penalize dead space scaled by progress and item size
    score += 8.0 * norm_pr * norm_pr * norm_item * (1.0 + progress);

    // Lookahead: reward residual that can fit the next item (smooth)
    if next_item_size > 0 {
        let fit = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let soft = 1.0 / (1.0 + ((pr - next_item_size as f64) / 10.0).exp());
        score -= 15.0 * soft * norm_next;
        score += 10.0 * (1.0 - soft) * norm_pr * progress;
        let _ = fit;
    }

    // Last-chance bin bonus when few fitting bins exist
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 - norm_item);
    }

    // Crowd/mean-residual coupling
    let crowd = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += 5.0 * (mean_residual / cap - norm_pr).abs() * (1.0 + crowd);

    // New-bin candidate: penalize opening early, more later
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction bands
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Dead-space penalty: very small post_residual creates unusable residue
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= quarter {
        score -= 6.0;
    }

    // Harmonic band rewards: residual exactly divisible by common item classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    // Half-full residual is a good "flex" state
    if post_residual.abs_diff(half as u32) <= 5 {
        score -= 3.0;
    }
    // Third-band residual also useful
    if post_residual.abs_diff(third as u32) <= 4 {
        score -= 2.0;
    }

    // Lookahead coupling: does this bin still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
            // exact harmonic match with next item
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // placing here strands the next item from this bin
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += bin_capacity as f64 * 0.9;
        // more attractive late in stream or when few bins fit
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 30.0;
        if fitting_bins_count == 0 {
            score -= bin_capacity as f64 * 0.95;
        } else if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // large items prefer fresh bins
        if item_size > half {
            score -= 15.0;
        }
    }

    // Prefer tighter bins among equals (small residual = well-used bin)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let unusable = (post_residual < 10) || (next_item_size > 0 && post_residual < next_item_size && post_residual < 20);
        if unusable {
            score += 40.0 + (10 - post_residual.min(10)) as f64 * 3.0;
        }
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Perfect-for-next-item bonus: residual exactly accommodates lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        // Residual too small for next item but not tiny: mild penalty.
        score += 5.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over opening new ones; make the new-bin candidate less attractive.
    let pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus pressure; only attractive when
        // no decent fit exists (few fitting bins) or item is large.
        score += 30.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    } else {
        // Existing bin: slight bonus when bins are numerous.
        score -= pressure * 0.25;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean-residual coupling: when average residual is high, prefer bins
    // below the mean (consolidate), penalize bins above it.
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.3;
    }

    // Late-stream tightening: as the stream progresses, avoid creating
    // any residual that can't serve future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fill is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0 + (next_item_size as f64) * 0.5;
        } else {
            // dead space that next item cannot use
            score += 15.0;
        }
        // exact 2-chain: post_residual == next_item_size exactly
        if post_residual == next_item_size {
            score -= 120.0;
        }
    }

    // Penalize tiny unusable residuals (< 10, minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Tight fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 50.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless they're bad fits
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if no good fit exists (large dead space everywhere), opening new bin is fine
        if mean_residual < (item_size as f64) * 1.1 {
            score -= 80.0;
        }
    }

    // Relative to mean residual: prefer placing into bins with below-average residual
    // (keeps many medium bins rather than one huge + fragmented ones)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: bonus grows as post_residual shrinks relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post residual, reward this placement;
    // otherwise penalize leaving residual that neither chains nor is small.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - chain_fit / cap);
        } else {
            // Dead space for the next item: penalize proportionally to how unusable it is.
            let gap = (post_residual as f64) - (next_item_size as f64);
            if gap > 0.0 {
                score += 2.0 * gap / cap;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin opening when a reasonable fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin.
        score += 10.0;
        // More reluctance when many bins are open (consolidation pressure).
        score += 0.5 * (open_bins_count as f64).sqrt();
        // Slight relaxation early in the stream (exploration) and when
        // existing bins are very full on average.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * (1.0 - progress);
        let mean_fullness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score -= 6.0 * mean_fullness;
        // If nothing else can fit the item, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
    }

    // Small global-state coupling: prefer bins whose residual is near the mean
    // (balanced depletion) slightly more than outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let post_norm = post_residual as f64 / bin_capacity as f64;

    // Non-linear coupling: tight fits (small post_residual) rewarded more as stream progresses.
    let tightness = (1.0 - post_norm).powf(2.0 + 3.0 * progress);
    score -= 25.0 * tightness * fit_ratio;

    // Smooth penalty for post_residual just below next item size (near-miss dead space).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        let near_miss = (-gap * gap * 400.0).exp();
        score -= 8.0 * near_miss * (1.0 - progress);
    }

    // Reward last-chance bins smoothly.
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 - post_norm);
    }

    // Penalize opening a new bin, more strongly early in the stream.
    if bin_residual == bin_capacity {
        score += 30.0 + 25.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    } else {
        // Mild preference for bins below mean residual (balance).
        score += 0.1 * (mean_residual - bin_residual as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer bins that leave little wasted space.
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 defines "dead-space classes".
    // Residuals in [0,9] are near-unusable; [10,19] can host the smallest items; etc.
    let pr = post_residual;
    let class = pr % 10;
    let decade = pr / 10;

    // Penalize residuals that are too small to ever host the smallest item (size 1..10 band).
    if pr > 0 && pr < 10 {
        score += 12.0 - (pr as f64); // worst at pr == 9 (max waste, near-zero utility)
    }

    // Reward "harmonically clean" residuals: multiples of 10 align with typical size classes.
    if class == 0 && pr > 0 {
        score -= 3.0;
    } else if class >= 1 && class <= 4 {
        score += 1.5; // awkward sliver
    }

    // Perfect fit gets a strong reward.
    if pr == 0 {
        score -= 15.0;
    }

    // Tight fit: item occupies >= 80% of the bin's current free space.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.8 {
            score -= 6.0 * fill_ratio;
        } else if fill_ratio < 0.3 && bin_residual < bin_capacity {
            score += 4.0 * (0.3 - fill_ratio); // dumping a small item into a big hole
        }
    }

    // Lookahead coupling: if the next item can fit into post_residual, this bin stays useful.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 2.5;
            // Extra reward when next item harmonizes with the leftover class.
            if pr % 10 == 0 || next_item_size % 10 == 0 {
                score -= 1.5;
            }
        } else {
            // Leftover won't host the next item: dead space likely.
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Mild penalty so open bins are preferred for decent fits...
        score += 4.0;
        // ...but if all open bins would leave terrible waste, opening fresh is better.
        // Detect "poor fit" via large post_residual on open bins: mean_residual large relative to item.
        if bin_residual > 0 {
            let waste_signal = mean_residual - item_size as f64;
            if waste_signal > 20.0 {
                score -= 10.0; // open bins are bloated with unusable space -> new bin wins
            }
        }
        // Late in the stream, consolidate rather than proliferate bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Mild pressure against having many open bins with scattered residuals.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward exact / near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // making the new-bin candidate (residual == capacity) less attractive.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would be stranded by a tight leftover, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 15.0;
    }

    // Mean-residual coupling: if this bin is far tighter than average, prefer it.
    score += 0.3 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying quadratically for near matches.
        if diff == 0.0 {
            score -= 40.0;
        } else if diff <= 10.0 {
            score -= 25.0 * (1.0 - diff / 10.0);
        } else {
            score += 0.15 * diff;
        }

        // Next item fits in the resulting residual at all -> mild bonus.
        if post_residual >= next_item_size {
            score -= 3.0;
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Penalize creating tiny unusable dead space (nothing fits but bin is wasted).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 8 {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Relative to mean residual: bins tighter than average are preferred to
    // consolidate, keeping looser bins flexible for future items.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Late in the stream, tighten packing more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage fragmentation, prefer tight fits.
    if open_bins_count > 4 {
        score += 0.05 * (open_bins_count as f64 - 4.0) * post_residual as f64 / 10.0;
    }

    // New-bin candidate: only attractive if current item is small and no good
    // fit exists; make empty bin a mediocre default (slight penalty).
    if bin_residual == bin_capacity {
        score += 8.0;
        // But if item is large relative to capacity and would leave big gap in
        // any other bin, opening fresh is fine.
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // scaled by how well the next item would fill that space.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 8.0 + 14.0 * fill;
    } else if next_item_size > 0 {
        // Penalize leaving dead space that the next item cannot use.
        let waste = (next_item_size - post_residual.min(next_item_size)) as f64;
        score += 0.35 * waste;
    }

    // Last chance: strongly prefer the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global pressure: when many open bins exist, prefer consolidation
    // into bins with below-average residual (pack fuller bins first).
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score += 0.25 * dev; // lower residual than mean -> dev>0 -> lower score
    }

    // Time horizon: late in the stream, be more conservative about
    // fragmentation; early, allow exploration of loose fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin's post_residual is large,
    // so add a switching penalty that shrinks when the current fit is bad
    // (large post_residual in an existing bin) or when many bins are open.
    if bin_residual == bin_capacity {
        let escape_bonus = if open_bins_count > 0 {
            (post_residual as f64 / 12.0) + (open_bins_count as f64).ln().max(0.0) * 4.0
        } else {
            0.0
        };
        score += 18.0 - escape_bonus.min(16.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post residual)
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space is costlier, so amplify large residuals.
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * cap * (0.25 + 0.75 * progress);

    // Reward lookahead compatibility: if next item fits into post-residual, subtract.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack_after_next = pr - nxt;
            let fit_quality = 1.0 - (slack_after_next / cap).powi(2);
            score -= 8.0 * fit_quality * (1.0 - progress * 0.5);
        } else {
            // Next item won't fit here: mild penalty scaled by how much it overflows.
            let overflow = (nxt - pr) / cap;
            score += 4.0 * overflow * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes the mean residual
    // already sitting in open bins; penalize proportionally, but relax late
    // when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 6.0 + 10.0 * mean_fill * (1.0 - progress * 0.6);
    }

    // Mild diversity pressure: many open bins with large mean residual ->
    // prefer consolidating into existing space.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: classify leftover space by capacity fractions
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual <= 10 -> nearly full bin, excellent
    if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual <= 20 {
        score -= 40.0;
    } else if post_residual <= 34 {
        // mid-small leftover: half-capacity class boundary (C/3..C/2)
        score -= 10.0;
    } else if post_residual <= 50 {
        // large leftover: dead-space risk, penalize proportionally
        score += (pr - 34.0) * 1.5;
    } else {
        // very large leftover: strongly penalize (wasted space)
        score += (pr - 50.0) * 3.0;
    }

    // Modulo-arithmetic coupling: leftover divisible by small units is reusable
    if post_residual % 10 == 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next fits: leftover is usable, mild reward scaled by tightness
            let tightness = next_item_size as f64 / pr;
            score -= 30.0 * tightness;
        } else {
            // next item cannot use the leftover: penalize dead space more
            score += 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if current fit is terrible
    if bin_residual == bin_capacity {
        // neutral base for new bin; make it attractive only vs. bad fits
        score = 60.0 + pr;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
    }

    // Slight preference for tighter bins overall (small residual before placement)
    score += (bin_residual as f64) * 0.05;

    // Stream progression: later in stream, be greedier about closing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual <= 20) as i32 as f64;

    // Mean residual context: if open bins are generally loose, discourage adding loose bins
    if (mean_residual - pr).abs() < 5.0 && pr > 40.0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= ~15) are nearly worthless.
    if post_residual < 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few bins
    // -> allow filling more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (progress + 0.3);
    score += 0.6 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item could use this bin's post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // We destroyed the ability to fit the next item; penalize.
        score += 15.0;
    }

    // Mean-residual coupling: placing into a bin below mean residual keeps
    // balance of usable space; penalize draining already-low bins further
    // when alternatives exist.
    if (bin_residual as f64) < mean_residual && post_residual > 0 && post_residual < 25 {
        score += 12.0;
    }

    // New-bin candidate evaluation: an empty bin is a fallback; make it
    // moderately attractive only when the fit here would be very poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If current placement leaves a tiny dead gap, opening fresh may win.
        if post_residual > 0 && post_residual < 10 {
            score -= 55.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 40.0 * progress;
        // Many open bins already: opening more is expensive.
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly or nearly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 55.0; // perfect chain fit
        } else if diff <= 5.0 {
            score -= 25.0;
        } else if diff <= 10.0 {
            score -= 12.0;
        } else {
            // Penalize leaving a gap the next item cannot use well.
            score += diff * 0.15;
        }
        // If next item cannot fit into post_residual at all, dead space risk.
        if post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Compare post_residual against mean residual: prefer bins whose
    // resulting residual is below average (tight packing).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.3;
    } else {
        score += (pr - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): make it attractive only when there
    // are few alternatives or the item is large relative to typical space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { fitting_bins_count as f64 };
        // Default penalty so open bins win; reduced when item is large
        // or late in the stream where consolidation matters more.
        let mut new_bin_penalty = 45.0;
        if item_size >= 60 {
            new_bin_penalty -= 15.0;
        }
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            new_bin_penalty -= 10.0; // pair may fill a fresh bin perfectly
        }
        new_bin_penalty -= progress * 10.0;
        score += new_bin_penalty.max(5.0) + scarcity * 0.5;
    }

    // Mild penalty for creating very small unusable gaps (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Slight preference to fill bins with larger current residual first
    // (keeps tighter bins available for small items).
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: scaled by residual fraction.
    let res_frac = bin_residual as f64 / cap;
    let post_frac = post_residual as f64 / cap;
    score -= (1.0 - post_frac) * (1.0 - post_frac) * 30.0;

    // Dead-space penalty for unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits in post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here: penalize wasting residual
        score += 6.0 * post_frac;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins with below-average residual (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer open bins,
    // but relax it as stream progresses and open-bin count grows.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let penalty = 18.0 - 10.0 * progress + 0.3 * open_bins_count as f64;
        score += penalty.max(4.0);
    }

    // Slight penalty for leaving exactly half-ish residuals that are hard to fill later.
    if post_residual > 40 && post_residual < 50 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * prn * prn);

    // Non-linear polynomial coupling of post-residual with stream progress
    let coupling = prn * prn * (1.0 - progress) + prn * progress * progress;
    score += 20.0 * coupling;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - prn;
    score -= 10.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit a plausible next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 8.0 * (ns - pr) / cap * (1.0 + progress);
        } else {
            // Smooth reward when the leftover could host the next item
            score -= 6.0 * (1.0 - (pr - ns) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }

    // Slight penalty when many bins are open relative to progress (fragmentation)
    let frag = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 2.0 * frag * prn * progress;

    // New-bin candidate: keep it moderately attractive only when no tight fit exists
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 10.0 * (1.0 - progress) - 5.0 * (fitting_bins_count as f64).recip();
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 capture "dead space quality".
    // Small residues that are near-useless for typical items get penalized heavily.
    let residue_class = post_residual % 10;
    let class_penalty: f64 = match residue_class {
        0 => -6.0,   // perfectly round leftover, very reusable
        1 | 2 => 8.0, // nearly full, dead space
        3 | 4 => 3.0,
        5 => -3.0,   // half-decade residual, decent target
        6 | 7 => 1.5,
        8 | 9 => 5.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Tight fit reward: quadratic in how much of the bin the item fills.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 14.0 * fill_ratio * fill_ratio;

    // Penalize leaving a residual that no plausible next item (>=10) can use.
    if post_residual < 10 {
        score += 12.0; // dead space creation
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Lookahead coupling: reward if next_item_size fits exactly into post_residual,
    // penalize if next item cannot fit anywhere else and this bin is its only chance.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        }
        if next_item_size > post_residual && fitting_bins_count == 1 {
            score += 5.0; // forcing a bad split before a forced open
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when existing
    // residuals are poor. Make an empty bin mildly attractive by default but
    // discouraged when tight fits exist (its score is just capacity-ish baseline).
    if bin_residual == bin_capacity {
        // baseline: new bin wastes nothing now but defers consolidation
        score = (bin_capacity - item_size) as f64 + 4.0;
        if fitting_bins_count >= 1 {
            score += 10.0; // existing bins fit -> prefer them
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // large next item may justify reserving fresh space
        }
    }

    // Stream progression: early on, be conservative (keep bins flexible);
    // late in the stream, aggressively close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: when open bins are mostly empty, discourage fragmenting;
    // when they are mostly full, favor filling this one.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Mild penalty per extra open bin to discourage sprawl.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are pure waste; penalize them super-linearly.
    let dead_zone: f64 = 20.0;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * (dead_zone - post_residual as f64) * 1.5;
    }

    // Reward tight fits: small relative post residual gets a bonus.
    let rel = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - rel) * 10.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use the leftover; mild penalty if leftover is small.
        if post_residual < next_item_size {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < dead_zone {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins over opening new ones.
    score += (open_bins_count as f64).sqrt() * 0.8;

    // New-bin candidate handling: an empty bin has huge post residual; make
    // it attractive only when the current fit would create large dead space
    // or when the item barely fits elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // Attractive if the item is large (poor fit likely elsewhere).
        if item_size > bin_capacity / 2 {
            score -= (item_size as f64 - bin_capacity as f64 / 2.0) * 1.2;
        }
        // Lookahead synergy: next item pairs well with leftover after placing
        // current item in a fresh bin.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        // Fewer open bins -> opening new bins is cheaper.
        score -= (open_bins_count as f64).max(1.0).recip() * 5.0;
        // Early in stream, new bins are relatively cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual) — already the base.

    // 2-step lookahead: reward when post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: subtract a large bonus.
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional to how well next item fits into leftover space.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize leftover dead space that is too small
            // to be useful (below minimum item size 1..100 unknown, use item_size as proxy).
            let dead = post_residual as f64;
            if dead < item_size as f64 {
                score += 25.0 * (1.0 - dead / (item_size as f64).max(1.0));
            }
        }
    } else {
        // Last item: prefer filling an existing bin as tightly as possible.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual far above mean are "loose";
    // prefer packing into bins whose residual is near mean (balanced packing),
    // but reward packing into below-mean bins (shrinking outliers).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible (huge post_residual).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin should only win when the fit into it
    // would be better than into any open bin. Penalize opening a new bin mildly,
    // more so when many bins are open (consolidation pressure grows over stream).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // But if the item is large relative to capacity and fit is good in a fresh bin,
        // a new bin is naturally fine; the base post_residual term handles that.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 55.0;
        }
    }

    // Non-linear penalty on wasted capacity: quadratic in post_residual normalized.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste * waste;

    // Slight preference to pack earlier-opened bins (implicit via open_bins_count
    // tie-breaking): fewer open bins is better, reward bins when many are open.
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally to fill ratio.
    let fill = (item_size as f64) / cap;
    score -= 2.5 * fill * (bin_residual as f64);

    // Penalize creating small unusable dead space (post_residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: bonus if next item fits the post residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * (next_item_size as f64);
        } else if next_item_size as f64 > post_residual as f64 {
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely better.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin scaled by how many bins already fit the item.
        score += 25.0 + 8.0 * (fitting_bins_count as f64);
        // Early in stream, opening bins is cheaper (build diversity); late, expensive.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - t);
        // If item is large and mean residual is small, new bin is attractive.
        score -= 0.15 * (item_size as f64) * (mean_residual / cap);
    }

    // Slight preference for bins with residual below mean (use crowded bins first).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Mild penalty for many open bins: encourage consolidation.
    score += 0.02 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Core: penalize wasted space, with non-linear (quadratic/cubic) shaping.
    let mut score = pr / c;
    score += 0.6 * (pr / c).powi(2);
    score += 0.35 * (pr / c).powi(3);

    // Tight-fit reward: small post residual relative to item size.
    let tightness = 1.0 - (pr / it.max(1.0)).min(1.0);
    score -= 1.4 * tightness * tightness;

    // Last-chance bonus: only this bin fits; strongly favor using it.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 2.5 + 0.02 * pr as f64;
    }

    // Lookahead coupling: reward if next item fits well into the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let fit_next = (nx <= pr) as i32 as f64;
        score -= 0.9 * fit_next * (1.0 - (gap / c).min(1.0));
        score += 0.5 * (gap / c) * (1.0 - fit_next);
    }

    // Stream-progress coupling: later in the stream, be more aggressive about
    // filling existing bins (penalize post residual more), smooth polynomial.
    let p2 = progress * progress;
    score += (0.8 * p2 + 0.4 * progress) * (pr / c);
    score -= 0.7 * p2 * tightness;

    // Mean-residual interaction: if this bin is far from the mean residual,
    // smooth penalty for creating outlier dead space.
    let dev = ((pr - mean_residual) / c).abs();
    score += 0.45 * dev * dev;

    // New-bin candidate: penalize opening a new bin, more so with many open bins
    // and early/mid stream; relax slightly late when open bins are fragmented.
    if bin_residual == bin_capacity {
        let frag = (open_bins_count as f64 / (1.0 + mean_residual / c * 10.0)).min(3.0);
        score = 3.0 + 0.05 * open_bins_count as f64 + 1.2 * (1.0 - progress) - 0.3 * frag;
        // If item is small and many bins fit, opening a new bin is less bad.
        score -= 0.4 * (it / c);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // Tight-fit reward: prefer bins where item fills most of the residual.
    let fill_ratio = it / res.max(1.0);
    score -= 20.0 * fill_ratio * fill_ratio;

    // Reward near-perfect packing (post_residual close to 0).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Harmonic class logic on post_residual: dead space in awkward
    // classes (1..9 mod 10) is nearly unusable for items >=10.
    let class = post_residual % 10;
    if post_residual > 0 && class != 0 {
        // penalize non-decade dead space, worse the smaller the class
        score += 0.8 * (10 - class) as f64;
    }
    // Decade-class residuals (10,20,...) are reusable; reward them.
    if post_residual >= 10 && class == 0 {
        score -= 4.0;
    }

    // Lookahead: penalize if post_residual can't hold next item but is
    // small enough to be wasted; reward if next item fits exactly-ish.
    if next_item_size > 0 {
        if (nxt - post).abs() <= 2.0 && post >= nxt {
            score -= 10.0; // next item will seal this bin perfectly
        } else if post < nxt && post > 0 {
            score += 0.5 * (post.min(nxt)) * 0.1; // mild dead-space penalty
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes open capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins late in stream or when item is large (poor fits
        // elsewhere likely) and few bins fit the item.
        let item_frac = it / cap;
        let new_bin_penalty = 25.0
            - 18.0 * item_frac
            - 10.0 * progress
            - 3.0 * (open_bins_count as f64).ln().max(0.0)
            - 8.0 * (fitting_bins_count == 0) as i32 as f64;
        score += new_bin_penalty.max(-5.0);
    } else {
        // Slight preference for fuller bins among open ones.
        score -= 5.0 * (1.0 - res / cap);
    }

    // Mean-residual coupling: when average slack is high, avoid dumping
    // items into already-loose bins; encourage consolidating slack.
    score += 0.05 * (mean_residual - post).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space trap: residuals too small to ever fit a future item (min size 1, but
    // realistically items >= 10) are pure waste. Penalize the "unusable gap" band hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-but-usable fit: reward small post_residual within usable range.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * tightness * tightness;

    // Pressure: with many open bins, prefer filling existing ones; opening new bins
    // should only happen when this bin would leave a bad gap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: an empty bin should only win when placing here would create
    // a dead gap, or when the bin is already nearly full of small leftovers.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0 + 2.0 * open_bins_count as f64;
        // But if placing the item in an existing bin creates a dead gap, new bin wins.
        if post_residual > 0 && post_residual < 10 {
            score -= 80.0;
        }
        // Lookahead: if the next item fits exactly in the leftover of this placement,
        // keep using open bins instead of opening a new one.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 30.0;
        }
    }

    // Lookahead synergy: leaving exactly room for the next item is excellent.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 20.0; // next item leaves a dead gap; discourage
        }
    }

    // Mild preference for bins below mean residual (balance loads).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step fit: big reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += gap * 0.45;
        }
        // If next item would also fit exactly after this placement, extra reward.
        if next_item_size <= post_residual {
            let two_step_waste = post_residual - next_item_size;
            score -= (two_step_waste as f64).min(20.0) * 0.5;
        }
    } else {
        // Last item: prefer tightest fit strongly.
        score *= 1.5;
    }

    // Penalize large dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: baseline penalty so it's chosen only for poor fits.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
        // Opening a new bin is more attractive if many items remain relative to open bins.
        if open_bins_count > 8 {
            score -= 10.0;
        }
    }

    // Slight preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let size = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mean_res = mean_residual;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open = open_bins_count as f64;

    let post_frac = post / cap;
    let size_frac = size / cap;
    let next_frac = if next > 0.0 { next / cap } else { 0.0 };

    let mut score = post;

    // Dynamic waste penalty: leaving large leftovers becomes worse as the stream progresses.
    let waste_coef = (0.10 + 0.20 * progress) * cap;
    score += waste_coef * post_frac * post_frac;

    // Reward perfect fits that fully close a bin.
    if post == 0.0 {
        score -= 0.10 * cap;
    }

    // Lookahead: reward bins whose leftover can also host the next item.
    if next > 0.0 {
        // Near the end of the stream, packing the next item together is more valuable.
        let lookahead_scale = 1.0 + 0.5 * progress;
        if next <= post {
            score -= (0.40 + 0.35 * next_frac) * cap * lookahead_scale;
            // Extra reward for a perfect two-item chain (bin becomes exactly full after next item).
            if post == next {
                score -= 0.15 * cap;
            }
        } else {
            // Next item likely won't fit here; penalize potential dead space.
            score += 0.12 * cap * (1.0 - post_frac) * next_frac;
        }
    }

    // Coupling with global residual state: leftovers far below the mean are more
    // likely to become unusable dead space, while above-mean leftovers stay useful.
    let mean_coef = 0.10 + 0.10 * progress;
    score += mean_coef * (mean_res - post);

    // Last-chance adjustment: if this is the only open bin that fits, prefer using it
    // unless opening a fresh bin would serve the next item better.
    if fitting_bins_count == 1 {
        let fresh_post = cap - size;
        let mut bonus = 0.25 * cap * (1.0 - post_frac) * (1.0 - post_frac);
        if next > 0.0 && next > post && next <= fresh_post {
            bonus = 0.0;
        }
        score -= bonus;
    }

    // New-bin candidate: add an opening cost that grows with stream progress and
    // with the number of already open bins.
    if bin_residual == bin_capacity {
        score += (0.18 + 0.30 * progress) * cap + 0.02 * cap * open;
        // Small items leave a fresh bin mostly empty; make that less attractive.
        score += 0.25 * cap * (1.0 - size_frac);
        // If the next item cannot fit in the fresh bin either, opening now is less useful.
        if next > 0.0 && next > post {
            score += 0.10 * cap * next_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post_residual (tight fit), with a smooth convex penalty.
    let mut score = post + 12.0 * (post / cap) * (post / cap) * cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize very small post_residual more);
    // later, favor tight packing aggressively.
    let flex = (post / cap).powi(2);
    score += 20.0 * (1.0 - progress) * flex * cap;
    score -= 15.0 * progress * (1.0 - post / cap);

    // Waste relative to mean residual: bins far below mean are attractive.
    score -= 0.3 * (mean_residual - post) * (mean_residual / cap);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: reward leaving a residual that can host the next item,
    // penalize residuals that are awkwardly small for it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: baseline cost of opening a fresh bin, softened
    // when many items remain or the current item barely fits anywhere.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        score = 55.0 + 60.0 * (1.0 - progress) - 25.0 * scarcity - item / cap * 10.0;
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post_residual.
    score -= 12.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64);

    // Perfect / near-perfect fits get harmonic class bonuses.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class logic: classify post_residual by integer division into
    // capacity-fraction bands. Dead space below the smallest item class (1..=10)
    // is nearly unusable -> penalize.
    let band = post_residual / (bin_capacity / 8).max(1); // bands of ~12
    score += band as f64 * 4.0;

    // Modulo arithmetic: post_residual in the awkward 11..=19 range (too small
    // for most items, too big to waste) is the classic dead zone.
    let m = post_residual % 20;
    if post_residual >= 11 && post_residual <= 19 {
        score += 18.0;
    }
    if m == 0 && post_residual > 0 {
        score -= 6.0; // round harmonic residual (20/40/60/80) is reusable
    }

    // Next-item lookahead: reward residuals that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward if next item then fits harmonically (post2 small).
            let post2 = post_residual - next_item_size;
            if post2 <= 10 {
                score -= 10.0;
            }
        } else {
            score += 6.0; // this bin becomes dead after this placement
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large post_residual means poor fit here anyway) or few bins open.
    if bin_residual == bin_capacity {
        score = 45.0
            + mean_residual * 0.3
            + (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin helps the larger next item too
        }
    }

    // Stream progression: early on, prefer consolidation into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but avoid leaving
    // dead space that is too small to ever be useful.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 25.0; // perfect fill
    } else if post_residual < 10 {
        // small but potentially usable dead space
        score += 6.0;
    }

    // 2-step lookahead: strongly reward leaving exactly room for next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to wasted lookahead
            let deficit = (next_item_size - post_residual) as f64;
            score += 0.35 * deficit;
        }
    } else {
        // last item: maximize fill
        score -= 20.0;
    }

    // Relative-to-mean residual coupling: prefer bins that keep the fleet
    // of open bins balanced (avoid one bin hoarding all residual).
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // Last-chance bin: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // a fresh bin or open bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (item_size as f64 / bin_capacity as f64) * 40.0
            + 25.0 * (1.0 - mean_residual / bin_capacity as f64)
            + 10.0 * (1.0 - progress);
        score = bin_capacity as f64 - pressure;
        // discourage opening new bins when a decent fit exists
        if fitting_bins_count > 0 && (item_size as f64) <= mean_residual {
            score += 18.0;
        }
    }

    // Mild penalty for very loose fits (large post_residual waste).
    if post_residual > 50 {
        score += 0.10 * ((post_residual - 50) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 60.0 * tightness * tightness;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item would fit exactly into the post-residual, reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (post_residual as f64 - next_item_size as f64).recip().min(1.0);
        } else {
            // next item cannot use the leftover; penalize proportionally to wasted space
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Time horizon: early in the stream, be conservative (favor compacting into
    // existing bins); late in the stream, allow more new bins since totals matter less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 45.0 * (1.0 - 0.5 * progress);

    // New empty bin candidate: give it a calibrated baseline score so it is
    // chosen only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score = new_bin_penalty + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits; must open a new bin
        }
        // If next item is large and current item is small, prefer packing now.
        if next_item_size > 50 && item_size < 30 {
            score += 20.0;
        }
        return score;
    }

    // Global state coupling: many open bins with low mean residual -> favor
    // filling bins tightly rather than spreading items.
    if open_bins_count > 3 && mean_residual < 25.0 {
        score -= 10.0;
    }

    // Prefer bins whose residual is close to the item size (best-fit flavor).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Base: prefer small post-residual (tight fit), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * post_norm * post_norm);

    // Reward filling the bin well as the stream progresses (smooth coupling).
    score -= (cap - post) * (0.35 + 0.45 * t) / cap * 10.0;

    // Penalize dead space that is too small to be useful later, smoothly.
    let dead = if post > 0.0 { (cap / post).ln() } else { 5.0 };
    score += 6.0 * (dead * 0.3).min(2.0);

    // Lookahead: if the next item fits in the post-residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 4.0 * (1.0 - nxt / cap) * (0.5 + t);
        } else {
            score += 3.0 * (nxt - post) / cap * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 + fit_ratio);
    }

    // New-bin candidate: mildly penalize so it's chosen only when open bins fit poorly,
    // but relax late in the stream when many bins are open.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - 0.4 * t) + 0.05 * open_bins_count as f64;
    } else {
        // Slight preference for bins with below-average residual (consolidation).
        score += 2.0 * ((bin_residual as f64 - mean_residual) / cap).clamp(-1.0, 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near multiples of small sizes
    // (e.g. divisible by 10, 20, 25) are more reusable -> reward them.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        40.0 // perfect fit: fully packed bin is ideal
    } else if pr % 50 == 0 {
        25.0
    } else if pr % 25 == 0 {
        18.0
    } else if pr % 20 == 0 {
        15.0
    } else if pr % 10 == 0 {
        12.0
    } else if pr % 5 == 0 {
        6.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Dead-space penalty: small unusable residues (hard to fill later).
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if next item cannot fit, penalize.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let npr = pr - next_item_size;
            score -= 10.0 + (npr % 10 == 0) as i32 as f64 * 5.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bin baseline: worse than a decent fit, better than dead space.
        score += 20.0;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
        }
        // Late in stream, avoid opening bins unless item is large.
        if progress > 0.8 && item_size < 60 {
            score += 10.0;
        }
        // Large items pair well with fresh bins.
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    // Mild preference for filling bins with low mean residual (tighter bins).
    score += (mean_residual - pr as f64) * 0.3;

    // Prefer using more-opened bins to consolidate before creating new ones.
    if open_bins_count > 0 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small to hold even the smallest plausible item is waste.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny sliver: essentially dead space forever.
            score += 60.0;
        } else if post_residual < item_size.min(next_item_size.max(1)) {
            // Gap can't fit current-typical follow-up sizes; partial dead space.
            score += 25.0;
        }
    }

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Alignment with mean residual: prefer bins close to average (balanced packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: baseline cost; only attractive when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If nothing fits well, opening a fresh bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item + next item fills bin perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead credit: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack);
    }
    // Penalize leaving dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists (post_residual small elsewhere).
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in stream, new bins are cheaper to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty for very large item relative to residual (tight squeeze risk).
    if item_size as f64 / bin_residual as f64 > 0.9 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: small post_residual that is too small for typical future items
    // (items >= 10) is wasted space; but tiny leftover (< min item) is unavoidable.
    let min_item = 1.0f64;
    if post_residual as f64 > min_item && (post_residual as f64) < 0.15 * cap {
        score += 15.0 * (1.0 - post_residual as f64 / (0.15 * cap));
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: leftover is likely dead space
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin starts at score == capacity (100).
    // Make it competitive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Mild discount so a new bin beats genuinely bad fits, but loses to decent fits.
        score -= 20.0;
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If many bins are open already, discourage spreading.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Prefer bins with below-mean residual (consolidate emptier bins? no —
        // prefer filling bins that are already low on space to close them out).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 10.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with a convex penalty
    // that grows super-linearly for large leftover dead space.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late, punish it more strongly.
    let progress_weight = 0.5 + 1.5 * progress * progress + 0.7 * progress;
    score += progress_weight * norm_pr * cap * 0.3;

    // Reward filling a bin nearly completely, smoothly scaled by progress.
    let fill_ratio = 1.0 - norm_pr;
    score -= 4.0 * fill_ratio * fill_ratio * fill_ratio * (0.6 + progress);

    // Interaction: if the lookahead item fits the post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 3.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        // Post-residual cannot host next item: mild penalty, stronger late.
        score += 1.5 * (1.0 + progress) * norm_next;
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good
    // fitting bins exist and progress is high.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 5.0 + 2.0 * open_pressure + 4.0 * progress;
        // But if item is huge and mean residual is small, new bin is fine.
        score -= 6.0 * norm_item * (1.0 - mean_residual / cap).max(0.0);
    }

    // Slight preference for bins below mean residual (balance spreading),
    // smooth quadratic coupling.
    let diff = (pr - mean_residual) / cap;
    score += 0.5 * diff * diff * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" does the leftover fall in?
    // Bins whose leftover lands in a small, well-defined class are more likely to be
    // completed by future small items, so reward tight fits.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual == 0 {
        score -= 40.0; // perfect fit, ideal
    } else if post_residual < eighth {
        score -= 25.0; // near-perfect: dead space is tiny
    } else if post_residual <= quarter {
        score -= 10.0; // small leftover class
    } else if post_residual % 10 == 0 {
        score -= 6.0; // leftover is a multiple of 10 -> likely matchable with typical item sizes
    }

    // Penalize large leftover classes more when many bins are already open (fragmentation risk)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > bin_capacity / 2 {
        score += 8.0 + 12.0 * progress;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many are already open.
        score = cap_f + 20.0 + 3.0 * open_bins_count as f64;
        // If lookahead item is large relative to capacity, a fresh bin is more valuable.
        if next_item_size > 0 {
            let nl = next_item_size as f64 / cap_f;
            if nl > 0.6 {
                score -= 15.0;
            } else if nl > 0.0 && nl < 0.2 {
                score += 10.0; // tiny next item: keep current bins' flexibility instead
            }
        }
        // Early in the stream, opening bins is cheaper (builds a portfolio of residuals).
        if progress < 0.25 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced fragmentation),
    // and mildly prefer bins that can also host the lookahead item after this placement.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * mean_gap;
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: gaps below the minimum item size (1..20)
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Reward tight fits
    score -= 25.0 * (item_size as f64 / bin_residual as f64);

    // Pressure from number of open bins: prefer filling existing bins when many are open
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it if it fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }

    // New bin candidate: penalize opening a new bin mildly, scaled by open bins
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 3.0;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // bin will be exactly filled by next item
        } else if post_residual > next_item_size {
            // next item fits too; reward tightness of the two-step packing
            let two_step_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.35 * two_step_waste;
        } else {
            // next item cannot fit here; penalize by the shortfall
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize creating small unusable dead space (hard-to-fill residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Relative to mean residual: prefer bins that are already tighter than average.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New empty bin candidate: penalize opening a new bin unless residuals elsewhere are large.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.3 * mean_residual;
    }

    // Early in stream: mild preference to consolidate into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead reward: strongly favor bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        // Exact-fit chain bonus for the follow-up item
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 + 8.0 * (1.0 - chain_fit / bin_capacity as f64) + 6.0 * progress;
    } else if next_item_size > 0 {
        // Penalize leaving a gap that wastes the lookahead
        let waste = (next_item_size.saturating_sub(post_residual)) as f64;
        score += 0.15 * waste;
    }

    // Dead-space penalty: small post-residuals that can't fit typical items (>=10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - 2.0 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 5.0 * progress;
    }

    // Crowd penalty: prefer less crowded bins when many bins are open
    if open_bins_count > 4 {
        score += 0.4 * ((open_bins_count as f64).ln() * (post_residual as f64 / bin_capacity as f64));
    }

    // Global residual coupling: if mean residual is high, encourage consolidation
    // into already-open bins (tight packing), penalizing new-bin creation.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New-bin candidate: base penalty grows with mean residual of open bins
        score += 18.0 + 0.5 * mean_residual;
        // But if the item is large and open bins are all too small on average,
        // opening a new bin becomes attractive: relax the penalty.
        let avg_room = mean_residual.max(0.0);
        if (item_size as f64) > avg_room + 5.0 {
            score -= 14.0 + 0.4 * (item_size as f64 - avg_room);
        }
        // Late in the stream, avoid spawning bins for small tail items
        if progress > 0.8 && item_size < 40 {
            score += 10.0 * progress;
        }
    } else {
        // Reward tight fits in existing bins
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= 6.0 * tightness * (1.0 - progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer bins whose post-residual is small (tight fill),
    // with a non-linear polynomial shaping of residual waste.
    let post_norm = post / cap;
    let mut score = post * (1.0 + 0.9 * post_norm * post_norm);

    // Smooth coupling with stream progress: later in the stream,
    // dead space becomes more costly (poly-quadratic in progress).
    score += 18.0 * progress * post_norm * post_norm * cap;

    // Reward tight fits: item filling a large fraction of the bin.
    let fill_frac = item / cap;
    score -= 14.0 * fill_frac * fill_frac * (1.0 + progress);

    // Interaction: post-residual relative to mean residual across bins.
    // A bin far below mean residual is "dirtier" — penalize mildly.
    let mean_norm = mean_residual / cap;
    score += 6.0 * (post_norm - mean_norm).abs();

    // Lookahead coupling: if next item could still use the post-residual,
    // reward leaving a usable gap; otherwise penalize awkward gaps.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // Gap is reusable by the next item: reward proportionally.
            score -= 10.0 * (nxt / cap) * (1.0 - post_norm);
        } else {
            // Dead space that next item cannot use: penalize non-linearly.
            let unusable = (nxt - post) / cap;
            score += 22.0 * unusable * unusable * cap / cap.max(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        // Multiple options: mild penalty so best-fit ordering still dominates.
        score += 2.0 * (fitting_bins_count.min(8) as f64);
    }

    // New-bin candidate (empty bin): make it attractive only when the
    // alternative would strand a large item or the stream is early.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Neutral base for a fresh bin; slightly above a perfect fit,
        // but below bins that would create large unusable dead space.
        score = 0.55 * cap * (1.0 - 0.5 * progress) + 8.0 * fill_frac;
        if next_item_size > 0 && next_item_size as f64 > item {
            // Next item is larger: a fresh bin preserves flexibility.
            score -= 12.0 * (next_item_size as f64 / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        // Near-perfect fit: residual too small for any item (min size 1..10 band).
        score -= 25.0;
    }

    // Harmonic class logic: residuals that are multiples of 10 align with
    // common item-size granularities and are more likely reusable later.
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if next item nearly fills the residual.
        if post_residual - next_item_size <= 10 {
            score -= 8.0;
        }
    } else if post_residual > 0 {
        // Dead space: residual too small for the next item.
        score += 6.0;
        // Harmonic penalty: awkward non-aligned dead space (modulo threshold).
        if post_residual % 10 != 0 && post_residual < 20 {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin so it only wins when
    // existing bins would create worse dead space (its base post_residual is
    // already large, so it wins only in genuinely poor-fit situations).
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the stream is late and many bins are open, avoid bin sprawl.
        if step_index as f64 / total_items.max(1) as f64 > 0.5 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Mild tie-breaker: prefer bins below the mean residual (consolidating
    // fuller bins leaves larger residuals concentrated in fewer bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. Items 1..100 unknown distribution, so treat gaps
    // below a conservative "usable floor" as dead space.
    let dead_floor = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_floor {
        score += (dead_floor - post_residual as f64) * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Coupling: small post_residual relative to capacity is good, but
    // penalize leaving gaps that cannot host the lookahead item.
    if next_item_size > 0 {
        if (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
            // Gap unusable by next item: dead-space penalty scaled by gap size.
            score += (post_residual as f64) * 0.6;
        } else if next_item_size <= post_residual {
            // Gap can host lookahead: reward proportional to tightness.
            score -= (post_residual as f64 - next_item_size as f64).min(30.0) * 0.5;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 25.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins and
    // encourage consolidating into existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 20.0 + 3.0 * open_bins_count as f64;
        // Early in the stream, new bins are cheaper (few open bins anyway).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    } else {
        // Reward using existing bins, scaled by open-bin pressure.
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Mean-residual coupling: if mean residual is large, existing bins have
    // room; prefer them and penalize new bins further.
    if bin_residual != bin_capacity {
        score -= (mean_residual / bin_capacity as f64) * 8.0;
    } else {
        score += (mean_residual / bin_capacity as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post = post_residual as f64;
    let mut score = post;

    // --- 2-step lookahead matching ---
    // Reward bins whose post_residual closely matches the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // Gradual reward within a 25-unit matching window.
        let match_bonus = 20.0 * (1.0 - diff / 25.0).max(0.0);
        score -= match_bonus;
        // Extra reward for an exact lookahead match (next item closes this bin).
        if post_residual == next_item_size {
            score -= 10.0;
        }
        // Penalize near-miss dead space: post_residual positive but just
        // below the next item (that space is likely wasted).
        if post > 0.0 && post < nxt {
            score += 0.5 * (nxt - post).min(10.0);
        }
    }

    // --- Last-chance bonus ---
    // If this is the only open bin that fits the item, use it rather than
    // opening a new bin (unless the fit is catastrophically bad).
    if bin_residual < bin_capacity && fitting_bins_count == 1 {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // An empty bin loses to any reasonable open-bin fit.
            score += 25.0;
            // Late in the stream, opening a bin is even less attractive
            // (fewer future items to fill it).
            let progress = if total_items > 0 {
                step_index as f64 / total_items as f64
            } else {
                0.0
            };
            score += 15.0 * progress;
            // On the final item, a fresh bin is almost pure waste.
            if next_item_size == 0 {
                score += 20.0;
            }
        }
        // If fitting_bins_count == 0, the new bin is the only option:
        // keep the plain base score so it gets selected.
    }

    // --- Fleet consolidation nudge ---
    // Mildly penalize leaving a residual far above the fleet mean
    // (poor consolidation relative to other open bins).
    if bin_residual < bin_capacity && post > mean_residual + 30.0 {
        score += 0.2 * (post - mean_residual - 30.0);
    }

    // --- Fuller-bin preference ---
    // Small reward for placing into bins that are already mostly full,
    // reinforcing best-fit behavior beyond raw post_residual.
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer small post-residual (tight fit).
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 40.0;
        }
        // Penalize leaving a gap just above the next item (dead space trap).
        if post_residual > next_item_size && post_residual - next_item_size <= 3 {
            score -= 60.0;
        }
        // If next item cannot fit here anyway and post_residual is tiny, fine.
        if next_item_size > post_residual && post_residual <= 10 {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize creating unusable dead space relative to minimum item size (assume ~1,
    // but weight fragmentation): small leftover gaps are worthless if too small for
    // typical items.
    let frag = if post_residual > 0 && post_residual < 10 { 10 - post_residual } else { 0 };
    score += frag as f64 * 8.0;

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Default: opening a new bin is worse than any reasonable existing fit.
        // But if existing fits are terrible (high post_residual everywhere) or this
        // is the last chance, allow opening.
        let mut new_bin_score = 400.0
            + (open_bins_count as f64) * 5.0
            + mean_residual * 0.3;

        // If item is large and would leave a big gap in any bin, opening a fresh bin
        // may be better: reward when item fills most of a fresh bin.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.8 {
            new_bin_score -= 250.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += progress * 150.0;

        score = new_bin_score;
    }

    // Slight preference for filling already-open bins (reduce bin count pressure)
    // when many bins are open.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += 12.0 * prn * prn * (0.5 + progress) - 6.0 * prn * prog2;

    // Penalize large dead space late in the stream (cubic coupling).
    score += 20.0 * prn * prn * prn * (0.3 + prog3);

    // Reward tight fits: small post_residual gets a smooth discount.
    let tight = (it / cap) * (1.0 - prn);
    score -= 15.0 * tight * (1.0 + progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = pr - next_item_size as f64;
        score -= 8.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        // Next item won't fit in residual: mild penalty for unusable remainder.
        score += 5.0 * prn * (1.0 - progress);
    }

    // New-bin candidate (residual == capacity): keep it expensive unless
    // item is huge relative to capacity and stream is late.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) * (1.0 - it / cap) + 10.0;
    }

    // Mild preference for consolidating into bins below mean residual.
    score += 2.0 * ((pr - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Harmonic class logic: classify post_residual into capacity-fraction classes.
    // Residuals that are multiples of common item sizes (10,20,25,50) are more reusable.
    let pr = post_residual;
    let reusable = (pr % 10 == 0) as i32 + (pr % 25 == 0) as i32 + (pr % 50 == 0) as i32;
    score -= 8.0 * reusable as f64;

    // Integer-division thresholds: dead space zones are penalized.
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable sliver
    } else if pr >= 10 && pr < 20 {
        score += 10.0; // only fits tiny items
    } else if pr > 50 {
        score -= 6.0; // roomy leftover, still very usable
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 20.0; // perfect pair
        }
    } else if next_item_size > post_residual {
        score += 6.0; // next item won't fit here anyway
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened casually.
        score += 15.0;
        // But if the current bin would leave a nasty dead zone and next item is large,
        // opening fresh becomes competitive.
        if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
            score -= 20.0;
        }
        // Late in stream with many open bins, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Slight preference for bins below mean residual (balance load).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Mild pressure against bin sprawl.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Mid-range gaps (10..=19) are moderately wasteful.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // (avoid opening a new bin) unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor tight fills.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
            if post_residual == next_item_size {
                score -= 40.0;
            }
        }
        // If next item would leave this bin's residual useless anyway, soften penalty.
        if next_item_size > post_residual && post_residual < 10 {
            score += 10.0;
        }
    }

    // Prefer bins with below-mean residual (concentrate filling).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if the fit leaves a large usable gap
        // and no tight option exists.
        score += 40.0 * (1.0 - progress);
        if post_residual < 20 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // 2-step lookahead: if the next item exactly fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize proportionally to leftover after that
            let second_left = post_residual - next_item_size;
            score -= 20.0 - 0.2 * second_left as f64;
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize creating small unusable dead space relative to item scale.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean coupling: bins with residual far above mean waste space.
    score += 0.3 * ((bin_residual as f64 - mean_residual).max(0.0));

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item or crowded state). Otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64;
        let base = 40.0 + 0.5 * crowding + 20.0 * progress;
        // If item is large relative to typical residual, new bin is reasonable.
        let big_item_bonus = if item_size as f64 > mean_residual { -30.0 } else { 0.0 };
        let last_chance_bonus = if fitting_bins_count == 0 { -100.0 } else { 0.0 };
        score += base + big_item_bonus + last_chance_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item, the better.
    let tightness = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for the smallest plausible next item.
    if post_residual < next_item_size && post_residual > 0 {
        score += 0.6 * (post_residual as f64) * (1.0 - (step_index as f64 / total_items.max(1) as f64).min(1.0));
    }

    // Lookahead bonus: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global pressure: when many bins are open relative to progress, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > mean_residual.max(1.0) {
        score -= 2.0 * (1.0 - progress);
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 25.0 + progress * 10.0;
        score = base;
        if fitting_bins_count == 0 {
            score -= 30.0; // forced: no alternative
        } else if fitting_bins_count == 1 {
            score += 5.0; // existing last-chance bin should win instead
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 5.0; // big item, fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: prefer small post_residual more strongly as stream progresses
    let coupling = norm_pr * norm_pr * (1.0 + progress) * 50.0;
    score += coupling;

    // Reward tight fits via cubic interaction between fill ratio and progress
    let fill = norm_item;
    score -= fill * fill * fill * (1.0 + 2.0 * progress) * 40.0;

    // Penalize dead space relative to mean residual (non-linear)
    let dead = (pr - mean_residual) / cap;
    score += dead * dead * 30.0;

    // Last-chance bonus: strongly favor this bin if it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= (next_item_size as f64 / cap) * 20.0;
        } else {
            score += (next_item_size as f64 / cap) * 15.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" residue classes (divisible by common item sizes) are favored.
    let pr = post_residual;
    let useful = (pr == 0)
        || (pr % 10 == 0)
        || (pr % 20 == 0)
        || (pr % 25 == 0)
        || (pr % 50 == 0);
    if useful { score -= 8.0; }

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if pr > 0 && pr < 10 { score += 25.0; }

    // Perfect fit is always excellent.
    if pr == 0 { score -= 60.0; }

    // Lookahead coupling: reward when the leftover can host the next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            score -= 6.0 + (slack as f64).sqrt() * 2.0;
            // Harmonic bonus if post-residual class matches next item's class.
            if pr % next_item_size.max(1) == 0 { score -= 5.0; }
        } else {
            // Next item cannot use this leftover: penalize tight leftovers.
            score += 4.0 + (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Brand-new empty bin candidate: neutral baseline, slightly worse than
    // a decent fit, but beats very poor fits via the penalties above.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 6.0;
    }

    // Prefer filling bins far below the mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Mild penalty for fragmenting many open bins.
    if open_bins_count > 8 { score += 0.4 * (open_bins_count as f64 - 8.0); }

    // Integer-division threshold: favor post residuals in high half-quadrants.
    let quadrant = pr / (bin_capacity / 4).max(1);
    score -= quadrant as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // (items are >= 1, but typical stream items are large), so penalize
    // post_residual values in the "dead zone" heavily.
    if post_residual > 0 {
        let dead_limit: u32 = 10; // gaps smaller than the smallest item class
        if post_residual < dead_limit {
            score += (dead_limit - post_residual) as f64 * 12.0;
        }
        // Moderate gaps (10..=20) are partially usable; mild penalty.
        else if post_residual <= 20 {
            score += (20 - post_residual) as f64 * 0.8;
        }
        // Large residuals are valuable space; reward keeping them intact
        // only when the fit is loose (avoid wasting big space on small items).
        if post_residual > 50 && item_size < 40 {
            score += (post_residual - 50) as f64 * 0.6;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Tight fit reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize new-bin competition).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating into
    // existing bins; with few open bins, allow spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin to enable a chained perfect fill.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual && post_residual - next_item_size < 10 {
            // next item would create dead space here; slight penalty
            score += 5.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; prefer filling fragmented bins first.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.3;
    }

    // New-bin candidate handling: an empty bin gets a baseline score that
    // makes it attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream position and
        // how many bins already fit the item.
        let mut new_bin_cost = 25.0;
        if fitting_bins_count > 0 {
            // There are alternatives; make new bin less attractive unless
            // they all look bad (their scores already carry dead-space penalties).
            new_bin_cost += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Early in the stream, opening bins is cheaper (room to consolidate).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost *= 1.0 - 0.3 * progress;
        // If the next item is large and current item is small, opening a fresh
        // bin may be wasteful; penalize slightly.
        if next_item_size > 60 && item_size < 30 {
            new_bin_cost += 8.0;
        }
        score = new_bin_cost + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always excellent.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 == nr {
            score -= 250.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual as f64 - nr;
            // reward closeness of the next item to the leftover space
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += 0.6 * post_residual as f64;
        }
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * fill_ratio * fill_ratio;

    // Penalize creating very small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it unattractive unless it is genuinely the best option
    // (i.e., no open bin fits well). Compare against mean residual.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // If open bins are mostly full (low mean residual), a new bin is fine;
        // otherwise penalize opening a new one.
        score += 30.0 + 400.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity {
            score += 200.0;
        }
    }

    // Mild preference to consolidate across open bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let next = next_item_size as f64 / cap;

    // Base: post residual (lower post residual => tighter fit => lower score)
    let mut score = r;

    // Smooth polynomial coupling: reward tight fits more as stream progresses
    let tightness = 1.0 - (r / cap);
    score -= tightness * tightness * (fit * (1.0 + progress)) * cap * 0.35;

    // Dead-space penalty: small post residual that next item can't use
    if next > 0.0 {
        let usable = if next <= r { 1.0 } else { (r / next).powi(3) };
        score += (1.0 - usable) * cap * 0.25 * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor this bin if it's the only one that fits
    if fitting_bins_count == 1 {
        score -= cap * 0.6 * (1.0 - progress * 0.3);
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    let mean_ratio = mean_residual / cap;
    score += (open_bins_count as f64).ln() * mean_ratio * 2.0;

    // New-bin candidate: neutral-ish baseline with slight late-stream preference
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.25 * progress) - fit * cap * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small post_residual).
    if post_residual <= 3 {
        score -= 40.0;
    } else if post_residual <= 8 {
        score -= 20.0;
    }

    // Harmonic class of post_residual: residues divisible by 5 or 10 are
    // more reusable by typical item sizes, so reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Penalize post_residuals that are too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits, but leaves a "dead" remainder: penalize proportionally.
        let next_left = post_residual - next_item_size;
        if next_left < 10 {
            score += 4.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this bin's remainder: penalize dead space.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current bin's
    // post_residual would be unusable dead space.
    if bin_residual == bin_capacity {
        score += 45.0;
        if post_residual > 20 {
            score -= 10.0; // large item, fresh bin is fine
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.05;

    // Slight preference to fill bins more aggressively later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally
    let dead_zone: f64 = 20.0;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But allow new bin if current bin would leave a large dead gap anyway
        if (post_residual as f64) < dead_zone {
            score -= 20.0;
        }
    }

    // Lookahead coupling: reward leaving space usable by the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Prefer bins with below-mean residual (tighter packing candidates)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post-residual, this is a perfect pairing -> strong reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits: penalize leftover after both placements
            // (dead space after the 2-step chain).
            let chain_waste = post_residual - next_item_size;
            score += chain_waste as f64 * 0.8;
            // Slight reward for keeping the chain going at all.
            score -= 20.0;
        } else {
            // Next item cannot use the residual: residual becomes dead
            // space unless small. Penalize proportionally.
            let dead = post_residual as f64;
            score += dead * 1.2;
        }
    }

    // Compare post_residual against the mean residual across open bins.
    // Leaving a residual close to the mean keeps future flexibility;
    // leaving much less than mean creates unusable small slivers.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = pr / mean_residual;
        if rel < 0.25 && pr > 0.0 {
            score += 60.0 * (0.25 - rel); // tiny sliver penalty
        } else if rel > 2.0 {
            score += 15.0 * (rel - 2.0); // hoarding large residual penalty
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // relative to capacity, or every open fit would be terrible.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Base cost of a new bin.
        score += 250.0;
        // Large items justify a fresh bin.
        score -= fit_ratio * 200.0;
        // If next item is also large, a fresh bin keeps large-item pairing.
        if next_item_size >= bin_capacity / 2 {
            score -= 80.0;
        }
        // Late in the stream, avoid opening bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && fit_ratio < 0.5 {
            score += 100.0 * progress;
        }
    }

    // Mild preference for tighter existing bins (best-fit flavor).
    score += (bin_residual as f64 - post_residual as f64) * 0.1;

    // Slight bias to fill bins early in the stream to keep bin count low.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= (1.0 - progress) * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress-based horizon: slightly prefer consolidating into open bins late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress;

    // Global pressure: many open bins with slack -> discourage spreading waste.
    score += 0.08 * mean_residual;
    score += 0.4 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Extra reward for near-exact two-item packing.
            let gap = post_residual - next_item_size;
            score -= 0.3 * (20 - gap.min(20)) as f64;
        } else if post_residual > 0 {
            // Penalize leaving dead space that the next item cannot use.
            score += 4.0 + 0.15 * post_residual as f64;
        }
    }

    // Tight fit reward: nearly empty post-residual is excellent.
    if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 6.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): penalize mildly so it only wins
    // when no open bin offers a decent fit; the penalty grows with open-bin count.
    if bin_residual == bin_capacity {
        score += 12.0 + 1.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm);
    score -= 40.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses.
    let fit = 1.0 - pr_norm;
    score -= 25.0 * fit * fit * progress;

    // Penalize large dead space, escalating late in the stream.
    score += 15.0 * pr_norm * pr_norm * progress;

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // New-bin candidate: mildly penalize opening bins early, less late.
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins deviating below the mean (tighter bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Harmonic class penalty: residuals in the "dead zone" classes
    // (post_residual % capacity in 1..10) are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 + 0.5 * (10 - post_residual) as f64;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Extra harmonic bonus when post_residual is an exact multiple class match
        if post_residual % next_item_size.max(1) == 0 {
            score -= 3.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this leftover: mild penalty, stronger late in stream.
        score += 2.0 + 4.0 * progress;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless fits are scarce.
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 25.0; // few alternatives -> opening a bin is acceptable
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score += 5.0; // new bin also can't promise a good follow-up
        }
    }

    // Prefer bins already tighter than the fleet mean (consolidation pressure).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Integer-division threshold: post_residual classes divisible into clean
    // quarters of capacity are slightly preferred (predictable future fits).
    let quarter = bin_capacity / 4;
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
