pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match between post_residual and next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item packing
        } else if post_residual > next_item_size {
            // next item still fits here: mild reward proportional to tightness
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item cannot use leftover: dead space penalty, worse if leftover tiny
            let dead = post_residual as f64;
            score += 10.0 + (20.0 - dead.min(20.0)) * 1.5;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter than average).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize so we only open a new bin when fits are terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If lookahead predicts a perfect fit elsewhere, opening fresh is still bad.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0;
        }
    }

    // Late in the stream, consolidate: favor closing out existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (open_bins_count as f64).recip().max(0.01);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor low post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that is too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: if the next item can fit into post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item would fit better elsewhere, mild penalty for leaving a large gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (post_residual as f64) * 0.35;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item is large and existing bins would leave big unusable gaps.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = mean_residual / (bin_capacity as f64);
        // Base cost of opening a new bin.
        let mut new_bin_score = bin_capacity as f64;
        new_bin_score -= 40.0 * (item_size as f64) / (bin_capacity as f64);
        // More open bins with high mean residual -> discourage new bins.
        new_bin_score += (open_bins_count as f64).sqrt() * 8.0 * waste_pressure;
        // Early in the stream, opening new bins is cheaper (more future items to fill).
        new_bin_score -= 20.0 * (1.0 - progress);
        // If other bins fit, opening a new bin should lose by default.
        if fitting_bins_count > 0 {
            new_bin_score += 15.0;
        }
        score = new_bin_score;
    }

    // Global state coupling: many open bins with high residuals -> prefer
    // consolidating into existing bins (penalize new bins implicitly, reward fits).
    if bin_residual < bin_capacity {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.05 * consolidation;
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    let mut score = pr;

    // Reward tight fits with smooth non-linear coupling
    score -= (fill * fill * fill) * 30.0;

    // Penalize dead space relative to item size (nonlinear)
    score += (pr / (item_size.max(1) as f64)).powi(2) * 8.0;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (0.5 + 0.5 * progress);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: penalize if post_residual can't fit next item but bin_residual could
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni && bin_residual as f64 >= ni {
            score += 15.0 * (ni - pr) / cap;
        }
        // Reward leaving space exactly usable by next item
        if pr >= ni {
            score -= 10.0 * (1.0 - (pr - ni) / cap).abs().min(1.0);
        }
    }

    // Mean-residual coupling: prefer bins near mean residual (smooth)
    score += ((pr - mean_residual) / cap).powi(2) * 10.0;

    // New-bin candidate handling: penalize opening new bins smoothly,
    // more so early in the stream and when other bins fit
    if bin_residual == bin_capacity {
        score += 40.0
            + 25.0 * (1.0 - progress)
            + (fitting_bins_count as f64) * 6.0
            + mean_residual * 0.3;
    }

    // Mild stream-progress term: later items tolerate fragmentation less
    score += progress * (pr / cap) * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic on post_residual: penalize small unusable leftovers,
    // reward classes that remain harvestable by typical future items.
    let class = post_residual / 10;
    score += match class {
        0 => {
            if post_residual == 0 { -70.0 } else { 45.0 } // perfect fit rewarded, 1..9 dead space punished
        }
        1 => 12.0,   // 10..19: marginal space
        2 => 4.0,    // 20..29: usable for small items
        3 => 0.0,    // 30..39: neutral
        _ => -3.0,   // large residual: still flexible
    };

    // Lookahead coupling (k=2): reward bins that can also host the next item.
    if next_item_size > 0 && bin_residual != bin_capacity {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: brand-new empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            // No (or only this) alternative: opening a new bin is fine, cheap score.
            score = 10.0 + item_size as f64 * 0.1;
        } else {
            // Good fits exist elsewhere: make the new bin expensive unless item is huge.
            score = 60.0 + item_size as f64 * 0.4
                - if item_size > 70 { 30.0 } else { 0.0 };
        }
    }

    // Mild stream-phase adaptation: early on, keep bins open and flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the leftover space, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Chain-fit quality: leftover after the lookahead item.
        let chain_left = post_residual - next_item_size;
        if chain_left < 10 {
            score += 8.0; // would create new dead space
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This placement destroys space the next item could have used in this bin.
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins slightly,
    // but discourage opening a NEW bin (bin_residual == capacity) unless
    // the item fits very poorly in existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's only chosen when fits are bad.
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open a new bin
        } else {
            // Penalize more if this bin would be a tight fit elsewhere anyway.
            if post_residual as f64 >= mean_residual {
                score += 15.0;
            }
        }
        // Late in the stream, prefer closing out bins tightly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    } else {
        // Mild reward for using existing bins, stronger when many are open.
        score -= 6.0 + (open_bins_count as f64).min(20.0);
    }

    // Last-chance bin: strongly favor filling the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Slight preference for bins with below-average residual (denser bins),
    // keeps packing concentrated.
    score += 0.15 * (post_residual as f64 - mean_residual).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // post_residual too small for next item: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Relative-to-mean residual: bins with residual far below mean are "scarce space",
    // filling them is good; bins with large residual can absorb future items anyway.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: only open a new bin when current item barely fits
    // nothing well (penalize new bin unless residual is full capacity AND item is large)
    if bin_residual == bin_capacity {
        score += 80.0;
        if item_size > bin_capacity / 2 {
            score -= 60.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Progression: later in stream, be less willing to open bins (pack tightly)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits strongly (post_residual small relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residual too small for typical future items (1..100)
    if post_residual < 20 && post_residual > 0 {
        score += 12.0 * (20.0 - post_residual as f64);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item won't fit here; mild penalty proportional to mismatch
        score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: only one bin can fit the item; use it rather than open new
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Many alternatives: mild penalty to discourage wasting a scarce-fit bin
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying over time and with many open bins
        let mut new_bin_cost = 20.0
            - 10.0 * progress
            - 0.5 * (open_bins_count as f64).min(10.0);
        // If no open bin fits (this is the only candidate), strongly favor new bin
        if fitting_bins_count == 0 {
            new_bin_cost -= 60.0;
        }
        // If next item is large and current item small, deferring packing is fine
        if next_item_size >= item_size && item_size <= 30 {
            new_bin_cost -= 5.0;
        }
        score += new_bin_cost.max(-60.0);
    }

    // Global state: high mean residual across open bins -> prefer filling existing bins
    if mean_residual > 40.0 {
        score -= 0.10 * (mean_residual - 40.0);
    }

    // Late in stream: consolidate aggressively, avoid leaving many half-full bins
    if progress > 0.8 {
        score += 6.0 * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling: dead-space penalty grows non-linearly with
    // post_residual, modulated by stream progress.
    let dead = pr_norm * pr_norm;
    score += 40.0 * dead * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * fit_ratio;

    // Last-chance bonus: strongly favor the only bin that fits, scaled smoothly.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - fit_ratio * 0.5);
    }

    // Lookahead coupling: penalize if next item cannot use the resulting residual,
    // reward if it can; smooth interaction with progress.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 1e-9 || nxt <= pr {
            score -= 12.0 * (1.0 - progress) * (nxt / cap);
        } else {
            score += 15.0 * (1.0 - progress) * (1.0 - pr_norm);
        }
    }

    // Mild preference for filling bins below the mean residual (balance pressure).
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: neutral-ish baseline so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress - 10.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes of common item sizes
    let pr = post_residual as i64;
    let nis = next_item_size as i64;

    // Reward if next item fits exactly into post_residual (perfect chaining)
    if nis > 0 {
        if nis == pr {
            score -= 60.0;
        } else if nis <= pr {
            // Reward proportional to how well next item fills the remainder
            let fill = nis as f64 / pr.max(1) as f64;
            score -= 25.0 * fill;
        } else {
            // Next item won't fit: penalize dead space in fine-grained residue classes
            let cls = pr % 10;
            score += 6.0 + cls as f64 * 0.8;
        }
    }

    // Integer-division thresholds on post_residual: small remainders are good
    if pr <= 10 {
        score -= 20.0;
    } else if pr <= 20 {
        score -= 8.0;
    } else if pr > 50 {
        score += 5.0; // leaving large residual suggests a better split existed
    }

    // Modulo arithmetic on residual vs. capacity fractions
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr == half as i64 || pr == quarter as i64 || pr == (bin_capacity * 3 / 4) as i64 {
        score += 4.0; // canonical splits are reusable; slight penalty vs odd fits
    } else if pr % 5 == 0 {
        score -= 1.5; // multiples of 5 tend to match item sizes
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base cost of a fresh bin; discount late in stream or with many open bins
        score += 35.0 - (step_index as f64 / total_items.max(1) as f64) * 10.0
                 - open_bins_count as f64 * 0.3;
        if pressure > 0.0 {
            score -= 45.0; // nothing fits, must open a bin
        }
        // If next item is huge, a fresh bin is more flexible
        if nis > 50 {
            score -= 5.0;
        }
    }

    // Tight fits are excellent: small post_residual relative to item
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 10.0 / (1.0 + tightness);

    // Mild penalty for scattering across many bins with large mean residual
    if mean_residual > 40.0 && post_residual as f64 > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no future item can use are heavily penalized.
    if post_residual > 0 {
        // Minimum plausible item size is small; treat residual below a tight threshold as dead space.
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // very hard to fill
        } else if post_residual < 35 {
            score += 8.0; // moderately awkward gap
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 40.0;
    }

    // Reward filling a bin deeply (low post-residual relative to capacity).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Pressure from number of open bins: with many open bins, prefer compacting
    // into existing bins; with few open bins, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.15 * bin_pressure;

    // Coupling with mean residual: if open bins are generally tight, avoid
    // spreading; if they are loose, this bin's post-residual matters more.
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += 0.05 * mean_gap;

    // Lookahead: if the next item would fit into the post-residual, reward
    // leaving exactly that much space (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0; // near-perfect chain
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 5.0; // next item won't fit here; gap likely wasted
        }
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // It should only win when existing bins offer terrible fits.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, scaled by stream progress and
        // how many bins are already open.
        score += 30.0 + 0.2 * open_bins_count as f64;
        // If this is a last-chance situation for other bins, make the new bin
        // very unattractive so the existing bin is chosen.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
        // Early in the stream with few bins, opening a new bin is more acceptable.
        if progress < 0.2 && open_bins_count < 3 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if lookahead_gap == 0.0 {
            score -= 500.0; // chain fit: this bin will be perfectly consumed by next item too
        } else {
            score += 0.5 * lookahead_gap;
        }
        // If next item can't fit anywhere else, prefer leaving room for it
        if post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Small post-residual is dead space; penalize relative to smallest plausible item (1..100 interface).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when it beats poor fits.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of existing bins; penalize mildly,
        // but reduce penalty when existing bins would leave very tight/awkward fits.
        let tightness = if bin_residual >= item_size {
            (bin_residual - item_size) as f64
        } else {
            0.0
        };
        score += 60.0;
        // If the best alternative leaves huge waste, new bin becomes competitive:
        score -= 0.3 * (mean_residual / bin_capacity as f64).max(0.0) * 0.0; // keep neutral baseline
        let _ = tightness;
        // Early in the stream, fresh bins are cheap; later, consolidation matters more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
    }

    // Prefer bins already below mean residual (consolidating waste into fuller bins).
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

