    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            score += 10.0;
        }
        // Perfect chain: post residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = (post_residual as f64 / bin_capacity as f64) * 30.0;
        // Base penalty keeps new bins behind decent fits.
        score += 55.0 - desperation - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // If many open bins are nearly empty, opening another is cheap.
        if mean_residual > 0.75 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Mild preference for filling bins below the mean residual (balance avoidance).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 5.0;
    }

    // Late-stream consolidation: prefer existing bins more as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    // Penalize very fragmented bin populations slightly.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
