    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post residual, with a smooth quadratic coupling
    let mut score = pr + 0.6 * (pr * pr) / cap;

    // Tight fit reward: smooth gaussian-like bonus around zero post residual
    score -= 12.0 * (-(pr * pr) / (2.0 * 15.0 * 15.0)).exp();

    // Penalize leaving dead space that cannot serve the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            // waste penalty grows smoothly with the shortfall
            let shortfall = (nx - pr) / cap;
            score += 8.0 * shortfall * shortfall * cap;
        } else {
            // reward reserving space for the next item
            score -= 6.0 * (1.0 - pr / cap) * (nx / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // New-bin candidate handling: penalize opening a new bin early,
    // relax slightly as the stream progresses; also penalize when
    // decent fitting alternatives exist.
    if bin_residual == bin_capacity {
        let alt_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += 25.0 * (1.0 - 0.5 * progress) + 5.0 * alt_pressure.ln();
        // opening a new bin is fine if current bins are very fragmented
        if mean_residual < 0.25 * cap {
            score -= 10.0;
        }
    }

    // Late stream: consolidate residuals more aggressively
    score -= 4.0 * progress * (1.0 - pr / cap);

    // Mild preference for filling bins that are already partially used
    if bin_residual < bin_capacity {
        score -= 2.0 * (1.0 - bin_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by modulo classes.
    // Residuals that are "small but usable" (<= 10) are near-perfect fits -> strong reward.
    // Residuals in awkward mid classes (11..=19) are dead space -> penalize.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 35.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual <= 19 {
        // awkward dead zone: penalize proportionally to how small (unusable) it is
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Integer-division thresholds: post_residual bucketed by 20s.
    // Buckets that can still host next_item_size are valuable.
    let bucket = post_residual / 20;
    match bucket {
        0 => score -= 5.0,
        1 => score += 3.0,
        2 => score -= 2.0,
        _ => {}
    }

    // Lookahead coupling: reward bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // prefer exact-ish match for the next item (harmonic pairing)
            score -= 25.0 - (slack / 10.0).min(20.0);
        } else {
            score += 8.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, adjusted by stream phase and
    // congestion. Early in the stream, opening bins is cheap; late, avoid it.
    if bin_residual == bin_capacity {
        let phase = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 40.0 * phase + (open_bins_count as f64) * 0.5;
        // if next item is large and current item is small, new bin slightly better
        if next_item_size > 60 && item_size < 30 {
            score -= 10.0;
        }
        return score;
    }

    // Prefer bins with below-mean residual (consolidate fullness).
    let res_frac = bin_residual as f64 / cap;
    let mean_frac = mean_residual / cap;
    score += (res_frac - mean_frac) * 15.0;

    // Fractional capacity classes of the item itself: large items should go
    // into the emptiest fitting bins; small items prefer tight bins.
    if item_size > 50 {
        score -= res_frac * 8.0;
    } else {
        score += (1.0 - res_frac) * 4.0;
    }

    // Modulo-10 harmonic bonus: post residuals that are multiples of 10
    // align with the common size grid, making future packing easier.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let min_useful = 10u32; // smallest plausible future item
        if post_residual < min_useful {
            score += 1000.0; // absolute dead space
        } else if post_residual <= 20 {
            score += 30.0 + (20 - post_residual) as f64 * 3.0;
        } else if post_residual <= 35 {
            score += 12.0;
        }
        // Reward perfect fit strongly
        if post_residual == 0 {
            score -= 500.0;
        }
    } else {
        score -= 500.0;
    }

    // Waste ratio coupling: relative fill quality
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 40.0;

    // Open-bin pressure: discourage spreading into many bins; but if this bin
    // is the last chance to fit, strongly favor using it.
    score += open_bins_count as f64 * 1.5;
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        // Cost of opening a new bin: moderate, rises with stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 60.0 + 40.0 * progress + pressure * 2.0;
        // If next item could use this bin's residual elsewhere, prefer existing bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_cost += 25.0;
        }
        score = new_bin_cost;
    }

    // Lookahead: if the residual left can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 15.0 + (next_item_size as f64 / post_residual as f64) * 10.0;
    }

    // Slight preference for bins below mean residual (consolidate fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect lookahead match (within small tolerance).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap > 0 && gap <= 5 {
            score -= 30.0 - 4.0 * gap as f64;
        }
        // Penalize dead space too small for the next item but also small in absolute terms.
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    }

    // Reward tight packing: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Relative to mean residual: prefer bins already below-average residual (well-filled).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 60.0 && next_item_size > 0 && post_residual < next_item_size;
        let mut penalty = 35.0;
        if fitting_bins_count == 0 {
            penalty = -100.0; // must open new bin
        } else if poor_fit {
            penalty = 10.0;
        }
        score += penalty;
    }

    // Late in stream: prefer closing out bins, avoid excessive fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && post_residual < 10 && post_residual > 0 {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6) * 30.0;

    // Penalize large dead space relative to typical item size.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score -= 12.0; // nearly perfect fill bonus
        } else {
            score += dead * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward it.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // Next item won't fit here; slightly penalize leaving awkward gaps
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += 0.25 * (next_item_size as f64 - gap);
            }
        }
    }

    // Global state: when many bins are open with large mean residual,
    // prefer consolidating into existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_bonus = 40.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, discounted when few bins fit the item
        // or mean residual across open bins is low (nothing useful to pack into).
        score += 55.0 - new_bin_bonus;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    } else {
        // Existing bin: small bonus when its residual is above mean (use the fat bins).
        if bin_residual as f64 > mean_residual {
            score -= 3.0;
        }
    }

    // Mild time-horizon shaping: early on, be conservative with bin fill;
    // later, pack aggressively to close out bins.
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Tie-break: prefer bins with more residual among equals (keeps small bins tight).
    score += bin_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth non-linear growth
    let mut score = pr + 18.0 * norm_pr * norm_pr * cap;

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly
    score += 24.0 * norm_pr * norm_pr * norm_pr * cap * (progress * (1.0 - progress) * 4.0 + 0.25);

    // Interaction with mean residual: avoid bins whose fill deviates badly
    score += 0.15 * (mean_residual - pr).abs();

    // Last chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: reward bins whose leftover could host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - ((pr - nxt) / cap));
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // New empty bin candidate: penalize mildly so it is chosen only when
    // open bins have poor fits (their scores will exceed this via dead-space terms)
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress - 10.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (large, common denominators) are better than dead space.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Dead-space penalty: very small residuals are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_f / 10.0);
    }

    // Harmonic reward: leftover that is a "nice" fraction of capacity
    // (>= 1/2, 1/3, 1/4) is more likely reusable later.
    let nice = if frac >= 0.5 { 1.0 } else if frac >= 1.0/3.0 { 0.6 } else if frac >= 0.25 { 0.3 } else { 0.0 };
    score -= 15.0 * nice;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits, but measure how tightly
            let gap = post_residual - next_item_size;
            score -= 20.0 * (1.0 - gap as f64 / cap_f);
        } else {
            // next item cannot use this leftover: penalize large leftovers less
            // if they are still class-nice, more if they are awkward.
            score += 8.0 * (1.0 - nice);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer tighter fits overall: reward small post_residual relative to mean.
    score -= (mean_residual - post_f).clamp(-cap_f, cap_f) * 0.15;

    // Mild preference for filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - frac);

    // Discourage opening new bins when many bins are open and this one fits well.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: neutral residual plus penalty that grows
        // with open bins count; harmonic class of a fresh bin is "nice" (frac=1)
        // so compensate to keep it comparable.
        score += 25.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize large post-residuals only mildly (they may still be usable),
    // but reward residuals that can host mid-size items later.
    if post_residual >= 10 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let open_pressure = (open_bins_count as f64) * 1.5;
    score -= open_pressure * (item_size as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (tight fit measure).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.8;

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would leave this bin's post-residual dead, penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 6.0;
    }

    // New-bin candidate: keep it neutral-ish; only prefer it when existing bins
    // would create dead space or when open bins are few relative to stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let dead_space_cost = if post_residual > 0 && post_residual < 10 { 120.0 } else { 0.0 };
        score += 5.0 - open_pressure * 0.5 - progress * 4.0 + dead_space_cost;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward a perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0; // ideal: this bin will be exactly filled next step
        } else if (post_residual as u32) >= next_item_size {
            // next item fits: reward proportionally to how small the leftover remains
            score -= 25.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving dead space that blocks lookahead
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    } else {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Penalize very small post residuals (unusable dead space) unless it's a perfect match.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 15.0;
    }

    // Reward filling bins tightly relative to the mean residual across open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current bin's fit is poor (large post residual) and the lookahead item is large.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0;
        let big_lookahead = next_item_size as f64 > 60.0;
        if poor_fit || big_lookahead || next_item_size == 0 {
            score -= 5.0; // encourage fresh bin for big items / end of stream
        } else {
            score += 25.0; // discourage wasteful bin opening when decent fits exist
        }
    }

    // Slight pressure to consolidate: fewer open bins is better late in the stream.
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: leaving zero dead space is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Non-linear penalty on tiny unusable leftovers (dead space < 10).
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 2.5;
        }
    }

    // Reward bins whose post-residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra coupling: reward chaining when the residual closely matches next item.
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 6.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // Forced opening: make it win over any bad fit.
            score -= 200.0;
        } else {
            // Discourage opening a new bin when alternatives exist,
            // scaled by how many bins are already open and mean residual.
            score += 35.0 + open_bins_count as f64 * 3.0;
            if mean_residual > item_size as f64 * 1.5 {
                score += 15.0; // plenty of slack elsewhere; don't open
            }
        }
    }

    // Mild global-state coupling: spread load when many bins are open
    // and mean residual is high (favor bins below-mean to balance).
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    // Dynamic time horizon: early in stream, be slightly more conservative
    // about tight fits (future items unknown); later, pack greedily.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap; // normalized fullness after placement
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: prefer small post residual (tight fit), smoothed non-linearly
    let mut score = post * (1.0 + 0.8 * fill * fill);

    // Reward near-perfect fits with a smooth cubic coupling
    score -= 30.0 * fit_ratio * fit_ratio * fit_ratio;

    // Dead-space penalty: post residual that cannot fit a typical future item
    let dead = (post - next_item_size as f64).max(0.0) / cap;
    score += 25.0 * dead * dead;

    // Lookahead: if the next item fits in the post residual, reward; else penalize smoothly
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 12.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (-gap / cap) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize so it's chosen only when fits elsewhere are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress + 0.05 * open_bins_count as f64;
        // But allow fresh bin if existing residuals are tight on average
        score -= 10.0 * (mean_residual / cap).powi(2);
    }

    // Mild stream-progress coupling: late in the stream, tolerate larger post residual less
    score += post * 0.3 * progress * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual (mod-based dead-space classes) ----
    // Residuals divisible by 10 are "harmonious" (likely reusable by future items);
    // odd / prime-ish leftovers are penalized.
    let pr = post_residual;
    let class_penalty = match pr % 10 {
        0 => -14.0,                       // perfectly harmonious residual
        1 | 3 | 7 | 9 => 10.0,            // awkward prime-ish leftovers
        5 => 2.0,                         // half-class, mildly awkward
        _ => 0.0,                         // even class, neutral
    };
    score += class_penalty;

    // Small residuals that can never host the smallest item are dead space.
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // ---- Lookahead coupling: does the next item fit into the post residual? ----
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward proportionally to how snugly the next item nests here.
            let slack = (pr - next_item_size) as f64;
            score -= 18.0 - slack * 0.15; // snug fit (small slack) rewarded most
            // Harmonic bonus if next item leaves a class-0 residual again.
            let npr = pr - next_item_size;
            if npr % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize unless residual
            // is large enough to still be generically useful.
            score += 6.0;
        }
    } else {
        // Last item of the stream: just dump it anywhere it fits.
        score -= 25.0;
    }

    // ---- Tightness reward: near-exact fills are excellent ----
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.85 {
        score -= 12.0;
    } else if fill_ratio > 0.6 {
        score -= 5.0;
    }

    // ---- Last-chance bin: if this is the only fitting bin, strongly prefer it ----
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin wastes nothing now but forfeits consolidation.
        // Base cost: slightly worse than a decent existing fit.
        let mut nb = 30.0 + post_residual as f64; // = capacity, large
        // Early in the stream, keep options open (cheap to open bins);
        // late in the stream, prefer packing into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb += progress * 40.0;
        // If many bins are open with scattered residuals, opening more is bad.
        nb += open_bins_count as f64 * 1.5;
        // If mean residual across open bins comfortably fits the item,
        // opening a new bin is clearly wasteful.
        if mean_residual >= item_size as f64 {
            nb += 25.0;
        }
        // Exception: huge items with no harmonious existing fit.
        if item_size > 70 && fitting_bins_count == 0 {
            nb -= 50.0;
        }
        score = score.min(score) + nb; // replace with new-bin cost
        return score;
    }

    // ---- Mean-residual alignment: prefer bins close to the fleet mean ----
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // ---- Late-stream urgency: consolidate aggressively as stream ends ----
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.12);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * fill_ratio * 40.0;

    // Zero residual is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * 0.4 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open_bins_count is low, less when high.
        score += 15.0 + pressure;
        // If next item is large and this bin would be nearly perfect for it, soften.
        if next_item_size > 0 && (bin_capacity as f64 - mean_residual).abs() < 5.0 {
            score -= 10.0;
        }
    } else {
        score -= pressure * 0.3;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; penalize leaving a gap it almost fits.
        if post_residual >= next_item_size.saturating_sub(3) {
            score += 8.0;
        }
    }

    // Prefer bins below mean residual (consolidate emptier bins' space).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fill.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when the leftover exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // leftover can host next item, but penalize proportionally to waste after that
            let second_waste = (post_residual - next_item_size) as f64;
            score -= 100.0 - 0.5 * second_waste;
        } else {
            // leftover too small for next item: dead-space penalty grows with tightness
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    }

    // Penalize large dead space relative to smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable slivers
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive for very large items or perfect-ish fits.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio < 0.85 {
            score += 150.0; // discourage wasting a fresh bin on small items
        } else {
            score -= 20.0; // big items may justify a fresh bin
        }
        // early in stream, opening bins is cheap; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
    }

    // Mild pressure to spread load when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Reward tight fits (small dead space)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize large dead space, especially when it can't fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item won't fit here; penalize blocking space slightly
        score += 15.0;
    }

    // New-bin candidate handling: only open a new bin when it's genuinely better
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 90.0;
        // but if no existing bins fit, opening is necessary
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        // if the only fitting bin would leave bad dead space, prefer new bin
        if fitting_bins_count == 1 {
            let waste_if_forced = bin_residual.saturating_sub(item_size);
            if waste_if_forced > 30 {
                score -= 120.0;
            }
        }
        // early in stream, more liberal opening
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 50.0 * (1.0 - progress);
    }

    // Global state coupling: many open bins with high mean residual -> consolidate
    if open_bins_count > 2 {
        let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
        score += 10.0 * consolidation;
    }

    // Prefer using bins with smaller residuals overall (best-fit flavor)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    // Base: reward tight fits via non-linear decay of post_residual.
    let mut score = post * (1.0 + 0.5 * post / cap);

    // Smooth coupling: as the stream progresses, prefer filling bins tighter
    // (larger post_residual penalized more strongly later).
    score += post * (0.6 * progress + 0.4 * progress * progress) * fit_ratio;

    // Dead-space penalty: small post_residual that is still unusable by next item.
    if next_item_size > 0 {
        let waste = (next_item_size as f64 - post).max(0.0);
        score += 2.0 * waste * (0.5 + 0.5 * progress);
    } else {
        // Last item: strongly reward exact fits.
        score -= 5.0 * (1.0 - post / cap);
    }

    // Reward when this bin is the only fitting option (avoid opening new bins).
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * fit_ratio;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    score += 0.1 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    // Smooth bonus for compacting large items into large residuals.
    score -= 1.5 * fit_ratio * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify residual into capacity-fraction classes
    let q = bin_capacity / 4; // quarter class = 25
    let class = post_residual / q; // 0..4 harmonic class of post residual

    // Reward tight fits: small post_residual is good
    match class {
        0 => score -= 40.0,                       // near-perfect fill
        1 => score -= 18.0,                       // good fill
        2 => score -= 6.0,                        // moderate
        _ => {}                                   // wasteful
    }

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo coupling: post_residual divisible by small classes is more reusable
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    // Lookahead: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // harmonic match: next item lands in same residue class band
            let nclass = (post_residual - next_item_size) / q;
            if nclass == class {
                score -= 10.0;
            }
            if post_residual - next_item_size <= 5 {
                score -= 20.0; // chain of tight fits
            }
        } else {
            score += 12.0; // next item won't fit here -> dead-ish space
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize leaving many bins open with scattered residuals
    if open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0) * 0.5;
    }

    // Prefer bins with residual below mean (consolidate large gaps)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if current item is large relative to capacity and no tight option exists,
        // opening fresh is acceptable
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 70.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 15.0; // larger item coming; fresh bin useful
        }
    }

    // Stream progression: late in stream, be more aggressive about filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 6.0;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 12.0;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Reward exact closure.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when this bin's fit is poor.
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64 * 0.5;
        if fitting_bins_count <= 1 {
            score -= 40.0; // no real alternative, allow new bin
        }
        if next_item_size > 0 && next_item_size as f64 <= mean_residual {
            score += 15.0; // next item might use existing residuals instead
        }
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect 2-step match (bin will be exactly filled after next item).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Reward: post_residual can accommodate next item exactly or leave small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.6 * (post_residual as f64 - next_item_size as f64).min(30.0);
    } else if next_item_size > 0 {
        // Penalize dead space below next item size (wasted residual).
        score += 2.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Penalize creating very small unusable slivers relative to mean residual.
    if post_residual < 10 {
        score += 120.0;
    }

    // Prefer bins tighter than the mean residual (good fits).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 150.0 - 100.0 * progress;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 50.0; // pairing two identical items in a fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small is already favored by base term.
    // Extra reward when the item nearly fills the bin exactly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Penalize creating dead space that few items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny slivers are nearly useless
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * (over / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.3 * (item_size as f64);
    }

    // New-bin candidate handling: only attractive when current open bins have
    // poor residuals relative to the item, or late in the stream with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for large items that would leave slivers elsewhere
        score -= 40.0 * fit_quality;
        // But penalize opening new bins when many open bins could still absorb the item
        if fitting_bins_count > 0 {
            score += 12.0 * (fitting_bins_count as f64).min(8.0);
        }
        // Slightly favor new bins early when mean residual is low (bins are full)
        score += 0.2 * (mean_residual - item_size as f64).max(-50.0).min(50.0);
        // Mild late-stream penalty for proliferation of bins
        score += 5.0 * progress;
    }

    // Discourage using high-residual bins wastefully when other bins fit too.
    if bin_residual != bin_capacity && fitting_bins_count > 1 {
        let waste = post_residual as f64 - mean_residual;
        if waste > 0.0 {
            score += 0.1 * waste;
        } else {
            score += 0.1 * waste; // bins tighter than average get a small bonus
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer minimal post residual (tight fits), smoothly warped.
    let mut score = post_norm.powf(1.5) * cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, tight packing matters more (penalize large residuals).
    let coupling = post_norm * post_norm * (0.5 + 2.0 * progress * progress);
    score += coupling * cap * 0.5;

    // Reward near-perfect fills with a smooth quadratic bonus.
    let perfect = 1.0 - post_norm;
    score -= perfect * perfect * item_norm * cap * 0.4;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize opening bins early, allow it late when
    // the fit would be poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 18.0 * (1.0 - progress) + 6.0;
        score += new_bin_penalty;
        // If this item would leave a large dead space anyway, opening is fine.
        score += (post_norm - 0.5).max(0.0) * cap * 0.3;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            // post residual can't fit next item: mild penalty for stranding space.
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Prefer bins with residuals below the mean (consolidate waste) via smooth term.
    let mean_norm = mean_residual / cap;
    score += (post_norm - mean_norm) * (post_norm - mean_norm) * cap * 0.3;
    score -= (mean_norm - post_norm) * 3.0;

    // Slight preference for bins with less absolute residual among many open bins.
    score += open_bins_count as f64 * 0.05 * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "reusable"
    // residue classes (multiples of 10, small complements) are preferred.
    let cap_frac = post_residual as f64 / bin_capacity as f64;
    let residue_class = post_residual % 10;
    let class_bonus = match residue_class {
        0 => 12.0,                       // perfectly aligned leftover
        1..=3 => 4.0,                    // near-aligned, tiny dead space
        8..=9 => 2.0,                    // will absorb a small item later
        _ => -6.0,                       // awkward mid-range dead space
    };
    score -= class_bonus;

    // Integer-division thresholds: penalize leaving > half a bin wasted,
    // reward filling past the halfway harmonic.
    if post_residual > bin_capacity / 2 {
        score += (post_residual - bin_capacity / 2) as f64 * 0.35;
    } else {
        score -= (bin_capacity / 2 - post_residual) as f64 * 0.15;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if next item cannot fit any residual of this class, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.12;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.25;

    // Late in the stream, consolidate harder: reward low post_residual more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += cap_frac * (8.0 + 10.0 * progress);

    // New-bin candidate: opening a bin is only attractive when nothing fits well
    // (few fitting bins) or residuals are all tiny; otherwise penalize heavily.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln() * 22.0 };
        score += 45.0 + scarcity - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance: punish tiny unusable gaps hard ---
    if post_residual > 0 && post_residual < 10 {
        // gap too small for any item (min size 1..10): severe penalty
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        // likely-dead zone for typical distributions
        score += 12.0;
    }

    // Reward very tight fits (near-perfect packing)
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Fractional waste ratio: penalize wasting most of the residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // --- Lookahead: if next item fits the post-residual, reward this placement ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.15;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // placement blocks the next item in this bin
        score += 6.0;
    }

    // --- Last-chance pressure: if this is the only bin that fits, prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is justified when item fits poorly in existing bins,
        // or when open bins are already fragmented (low mean residual).
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let poor_fit = fit_ratio < 0.5;
        if poor_fit || fragmentation < 0.15 || open_bins_count == 0 {
            score -= 22.0;
        } else {
            // discourage unnecessary bin proliferation
            score += 15.0 + open_bins_count as f64 * 1.5;
        }
    } else {
        // Mild pressure to prefer filling existing bins as open count grows
        score -= open_bins_count as f64 * 0.8;
    }

    // Slight preference for consolidating into bins with lower residual overall
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space relative to capacity.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // 2-step lookahead: reward if the next item exactly fills or fits well into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            // Perfect 2-item fill: strong reward.
            score -= 60.0;
        } else {
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize proportionally.
        score += 12.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Favor bins whose residual deviates below the mean residual (tighter bins absorb items well).
    score -= 0.5 * (mean_residual - bin_residual as f64).max(0.0);
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large relative to capacity
    // and no tight fit is available elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > bin_capacity / 2 && next_item_size > post_residual.min(bin_residual) {
            score -= 20.0;
        }
    }

    // Early in the stream, allow more bin spreading to build flexible residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: minimize wasted space quadratically.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * tightness * tightness * (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead coupling: penalize residuals that cannot host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving space exactly usable by the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to the lookahead item.
            score += 5.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    score += 0.4 * open_bins_count as f64 * tightness;

    // Global residual dispersion: if this bin's residual is far below mean,
    // it's a laggard bin — prefer filling it to close it out.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 0.3 * diff.min(50.0);
    } else {
        score += 0.15 * (-diff).min(50.0);
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, aggressively fill any bin that fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score -= 4.0 * progress;
    } else if post_residual > 0 && post_residual < 20 {
        score += 3.0 * (1.0 - progress); // avoid tiny dead space early on
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's fit would be very poor (large dead space) or the item is huge.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        // Baseline cost of a fresh bin; offset by how badly existing bins fit.
        score = 45.0 + 0.5 * waste;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin nicely hosts the next item too
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
        if item_size >= 80 {
            score -= 20.0; // large items deserve clean space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // tight fits (small post_residual) are rewarded more strongly as the stream matures.
    let norm_post = post / cap;
    let coupling = norm_post * norm_post * (1.0 + 2.0 * progress) + norm_post * progress;
    score += 40.0 * coupling;

    // Reward filling a bin completely (post_residual near zero gets a smooth bonus).
    let fill = 1.0 - norm_post;
    score -= 25.0 * fill * fill * fill;

    // Penalize leaving residual that cannot fit the lookahead item (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 12.0 + 20.0 * (nxt - post) / cap;
        } else {
            score -= 6.0 * (1.0 - (post - nxt) / cap).abs();
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize moderately so it wins only when fits are terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * (1.0 - progress);
    }

    // Mild pressure toward consolidating open bins.
    score += 0.3 * open_bins_count as f64 * norm_post;

    // Smooth tie-break: prefer bins whose residual is close to the mean.
    score += 0.5 * (bin_residual as f64 - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;

    // --- Tight-fit reward: the smaller the post residual relative to capacity, the better ---
    let tightness = 1.0 - pr as f64 / cap;
    score -= 12.0 * tightness;
    if pr == 0 {
        score -= 25.0; // perfect fill
    }

    // --- Dead-space penalty for tiny unusable residuals (harmonic class 1..9) ---
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // --- Harmonic modulo-10 classes of post_residual ---
    let class = (pr % 10) as f64;
    match pr % 10 {
        0 => score -= 4.0,             // round residual: highly reusable
        1..=3 => score += 6.0 + class, // awkward slivers
        4..=6 => score += 1.0,         // marginal
        _ => {}                        // 7..9: naturally okay, base score suffices
    }

    // --- Lookahead chaining: reward bins whose residual can host the next item ---
    if next_item_size > 0 && next_item_size <= pr {
        let slack_after_next = pr - next_item_size;
        score -= 3.0;
        if slack_after_next < 10 {
            score -= 4.0; // next item nearly fills this bin too
        }
    } else if next_item_size > pr {
        // residual too small for the next item: mild penalty proportional to waste
        score += 1.5;
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        score += 35.0; // default: prefer existing bins
        if item_size >= 60 {
            score -= 20.0; // large items justify fresh bins more readily
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress; // late in the stream, consolidate into open bins
        if open_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // --- Nudge toward bins below mean residual (balance across open bins) ---
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize bins whose residual deviates above the mean (fragmented bins).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 + 10.0;
        // If this is a last-chance situation for existing bins, new bin is bad.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        score -= 0.3 * next_item_size as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Lookahead synergy: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (item exactly fills the bin).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item fits into the post-residual,
    // reward this bin heavily; scale reward by how tightly the next item fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack_after_next * 1.5;
        // Perfect two-item packing is best.
        if post_residual == next_item_size {
            score -= 400.0;
        }
    } else if next_item_size > 0 {
        // Dead space relative to the next item: penalize unusable leftover space.
        let dead = post_residual as f64;
        let usable = if next_item_size > bin_capacity {
            0.0
        } else {
            dead.min(next_item_size as f64)
        };
        score += (dead - usable) * 0.8;
    }

    // Compare against the mean residual of open bins: prefer bins whose residual
    // is tighter than average (filling already-partially-filled bins).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.5;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits nowhere well (large item, poor fits elsewhere). Penalize the
    // fresh bin mildly so tight fits in existing bins win, but keep it
    // competitive when existing bins would leave big dead space.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Early in the stream, allow new bins more readily to keep options open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 30.0;
    }

    // Slight penalty for very small post-residuals that are too small for any
    // plausible item (dead space below minimum item size of 1 handled naturally,
    // but discourage residuals < 10 when not zero).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild preference for using fewer bins: if many bins are open, favor
    // consolidating into existing bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward bins that absorb a large fraction of their residual (tight fit).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 12.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead (k=2): reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Dead space relative to the next item: penalize small leftovers.
            score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.08;
        }
    }

    // New-bin candidate: penalize by default, relax as stream progresses
    // and when the fleet of open bins is already fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let mut nb = item_size as f64 * 0.5 + 22.0;
        nb -= (mean_residual / cap) * 25.0;
        nb -= progress * 12.0;
        nb -= (open_bins_count as f64).min(20.0) * 0.3;
        score += nb;
    }

    // Mild preference for bins tighter than the fleet average.
    score += (mean_residual - bin_residual as f64) * 0.04;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post_residual, with non-linear damping of tiny residuals (dead space)
    let mut score = pr;

    // Smooth polynomial coupling: normalized residual^2 penalizes large wasted space,
    // modulated by stream progress so late in the stream waste is punished harder.
    let norm_res = pr / cap;
    score += 12.0 * norm_res * norm_res * (0.4 + 1.2 * progress);

    // Reward tight fits: item filling a large fraction of the bin
    let fill = it / cap;
    score -= 8.0 * fill * fill * (1.0 - progress * 0.5);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: slight penalty to avoid fragmenting choice
        score += 1.5 * ((fitting_bins_count as f64).ln());
    }

    // New-bin candidate: penalize opening a new bin mildly, more so early in stream
    // and when other bins fit; but attractive when post_residual would be very small.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 4.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        if pr >= nxt {
            score -= 10.0 / (1.0 + diff * 0.15);
        } else {
            score += 2.0 * (1.0 - pr / cap);
        }
    }

    // Mean-residual coupling: if this bin's residual deviates from mean, small penalty
    // to keep bin pool homogeneous (smooth quadratic term).
    let dev = r - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Open-bin pressure: many open bins -> prefer filling existing ones (smooth)
    score -= 0.4 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible into
    // coarse classes via integer division and modulo arithmetic.
    let cap = bin_capacity as f64;
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Reward near-perfect fits (small post_residual), strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else {
        // Penalize leftover space by its "harmonic class":
        // leftovers that are multiples of small item sizes are more reusable.
        let pr = post_residual;
        let class = pr / 10; // integer division class 0..=9
        score += class as f64 * 2.0;
        // Modulo harmony: leftover divisible by 10 is more likely reusable
        if pr % 10 == 0 {
            score -= 4.0;
        }
        if pr % 5 == 0 {
            score -= 2.0;
        }
        // Dead space: leftover too small for the smallest plausible item
        if pr < 20 {
            score += 15.0;
        }
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can chain into this bin: strong reward,
            // scaled by how tight the chained fit is.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - (chain_slack / cap) * 10.0;
        } else {
            // Next item cannot use this bin's leftover: mild penalty,
            // worse when the leftover is just barely too small.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 {
                score += 6.0;
            }
        }
    } else {
        // Last item: prioritize perfect closure.
        if post_residual == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we
    // prefer existing bins with good fits, but is attractive when the item
    // is large and no open bin leaves a healthy residual.
    if bin_residual == bin_capacity {
        score = cap * 0.55; // baseline ~55
        if item_size >= half {
            // Large items start fresh bins happily.
            score -= 15.0;
        }
        if item_size % 10 == 0 {
            score -= 3.0; // round-size items pack cleanly in fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // item + next fit together in a fresh bin
        }
        // If many bins are open and mean residual is high, prefer reusing them.
        score += (open_bins_count as f64).min(20.0) * 0.5;
        if mean_residual > item_size as f64 {
            score += 5.0;
        }
    }

    // Stream progression: late in the stream, consolidate harder into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    } else {
        score += progress * 10.0;
    }

    // Fractional capacity coupling: bins whose residual is a small fraction
    // of capacity after placement are efficient.
    let frac = post_residual as f64 / cap;
    score += frac * frac * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: post_residual in (0..10) is unusable for typical
    // items (sizes >= 1 here, but small gaps rarely help). Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }

    // Moderate dead space (10..20) is only useful for tiny items.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 120.0;
    }
    // If next item fits within post residual, mild reward.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item cannot fit in post residual, the residual becomes dead space;
    // penalize proportionally to how close the next item is to fitting.
    else if next_item_size > 0 && next_item_size <= bin_capacity {
        let miss = (next_item_size - post_residual) as f64;
        if miss < 10.0 {
            score += 15.0 - miss;
        }
    }

    // New-bin candidate: only attractive if no open bin fits well,
    // or if this bin would leave a bad residual anyway.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        } else {
            // Opening a new bin is a fallback: make it slightly worse than a
            // decent existing fit but better than a terrible one.
            score = bin_capacity as f64 * 0.5 + open_bins_count as f64;
            if fitting_bins_count == 1 {
                // Last-chance bin exists; strongly prefer using it.
                score += 40.0;
            }
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // tight-fitting bins; few open bins -> be less picky.
    let pressure = (open_bins_count as f64) / ((total_items.max(1) as f64).sqrt() + 1.0);
    score -= pressure * (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Last-chance bin bonus: if this is the only fitting bin, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Alignment with mean residual: prefer bins whose residual after placement
    // is close to the mean (keeps bin states homogeneous, easier future packing).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step lookahead match: the next item
    // exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 1000.0; // perfect chain: pack current + next exactly
        } else if post_residual as u32 > next_item_size {
            // next item fits too; reward proportionally to tightness
            let slack = (post_residual as u32 - next_item_size) as f64;
            score -= 200.0 - slack.min(200.0);
        } else {
            // next item cannot fit here: penalize leaving dead space
            let waste = (next_item_size - post_residual as u32) as f64;
            score += waste * 1.5;
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // Penalize leaving residual far from mean (fragmentation signal).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate detection (empty bin). Only attractive when the item
    // is large relative to residual space typical of open bins, or when the
    // current bin's fit would be poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 1.2;
        // Attract new bin for large items when current alternatives are tight.
        if item_size as f64 > mean_residual {
            score -= (item_size as f64 - mean_residual) * 1.0;
        }
        // If many bins can already fit the item, discourage opening a new one.
        score += fitting_bins_count as f64 * 20.0;
        // If next item is small, new bin may still be useful for future pairs.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 30.0;
        }
        // Perfect pair in a fresh bin: current + next exactly fill it.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 500.0;
        }
    }

    // Slight preference to fill earlier bins (reduce bin count over time).
    score += step_index as f64 * 0.001;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: heavily favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 24.0 * fit_ratio * fit_ratio;

    // Penalize creating tiny unusable dead space (waste pockets).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for the next item: mild penalty for stranding space.
        score += (post_residual as f64) * 0.6;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying with stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 45.0 - 15.0 * progress;
        // Cheaper to open a new bin when open bins are already fragmented.
        open_cost -= (open_bins_count as f64).min(10.0) * 0.5;
        // If mean residual is large relative to item, prefer reusing bins.
        if mean_residual > item_size as f64 * 1.3 {
            open_cost += 18.0;
        }
        // If the next item is large, a fresh bin is attractive.
        if next_item_size >= 60 {
            open_cost -= 10.0;
        }
        score += open_cost;
    }

    // Slight global pressure: when many bins are open, prefer consolidating into
    // bins with below-average residual (tighter bins).
    if bin_residual != bin_capacity && open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear coupling: tight fits are better late in the stream
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 60.0 * tightness * (0.5 + progress);
    // Penalize dead space quadratically, scaled by stream progress
    score += 40.0 * norm_pr * norm_pr * (0.3 + progress);
    // Reward using a bin when it is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Lookahead coupling: prefer bins whose post residual matches next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 15.0 * (1.0 - diff / cap).powi(2);
    }
    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress);
    }
    // Interaction with mean residual: prefer bins deviating from mean toward tightness
    let dev = (pr - mean_residual) / cap;
    score -= 8.0 * dev * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: mod-10 buckets capture "usable chunks".
    let pr = post_residual;
    let harmonic = pr % 10;
    // Residuals in {0} are perfect; {1..9} are dead space; {10..19} can host min items.
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else if pr < 10 {
        score += 25.0 + (10 - pr) as f64; // tiny dead space is worst
    } else if pr < 20 {
        score += 5.0; // can still host small items
    } else {
        score -= (pr / 10) as f64 * 2.0; // larger chunks remain useful
    }

    // Fraction-of-capacity coupling: reward filling toward capacity quarters.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Integer division threshold on next_item_size vs post_residual: lookahead fit.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here too: strong reward, scaled by tightness.
            score -= 20.0 + (pr - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit: mild penalty, worse if pr is small dead space.
            score += (next_item_size - pr) as f64 * 0.1;
        }
        // Harmonic class match: next item's decade class equals residual's decade class.
        if next_item_size / 10 == pr / 10 && pr > 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many bins fit: prefer the tightest (post_residual already does this),
        // but add slight penalty to avoid hoarding on one bin.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's
    // already "fragmented" — using it is fine; if far above mean, prefer it.
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.15;

    // Stream progression: late in stream, be greedier about perfect fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (pr == 0) as i32 as f64 * 10.0;

    // New-bin candidate: penalize opening a new bin unless nothing else is good.
    if bin_residual == bin_capacity {
        score += 45.0
            + (open_bins_count as f64) * 1.5
            - (1.0 - fill_frac) * 0.0;
        // If item is large (>50% capacity), a fresh bin is more acceptable.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Late stream with many open bins: avoid proliferation.
        if progress > 0.5 && open_bins_count > 4 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit the lookahead item are wasted.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0 + 0.5 * post_residual as f64;
    }

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual.
    score -= 0.8 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by open-bin pressure.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        // Mild pressure to fill existing bins when many are open.
        score += 0.05 * open_bins_count as f64;
    }

    // Prefer bins below mean residual slightly (keep residuals balanced).
    score += 0.1 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared post-residual normalized, so small dead space is heavily favored.
    let norm_post = post_residual as f64 / bin_capacity as f64;
    score += norm_post * norm_post * 30.0;

    // Exact fill is excellent.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item,
    // scaled by how large the next item is (big next items make the fit more valuable).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + (next_item_size as f64 / 100.0) * 25.0;
        } else {
            // Penalize leaving residual that is too small for the next item (dead space)
            let waste = (post_residual as f64 - next_item_size as f64).abs();
            score += waste * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Relative-to-mean residual coupling: prefer bins whose residual deviates
    // from the mean in a way that yields tight packing.
    score -= (mean_residual - bin_residual as f64) * 0.2;

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or few bins fit the item.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        let size_factor = (item_size as f64 / 100.0) * 30.0;
        let scarcity_factor = if fitting_bins_count == 0 { 25.0 } else if fitting_bins_count == 1 { 10.0 } else { 0.0 };
        score = base_penalty - size_factor - scarcity_factor + post_residual as f64;
    }

    // Mild stream-progression pressure: later in the stream, be slightly more
    // conservative about spreading items across bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward filling bins deeply: the more of the bin we consume, the better.
    score -= item_size as f64 * 0.35;

    // Tight-fit reward: quadratic bonus for small leftover space.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    if bin_residual == bin_capacity {
        // Candidate for a brand-new empty bin.
        // Penalize opening a new bin when existing bins already fit the item.
        score += 55.0 * fitting_bins_count as f64;

        // If this item would leave awkward dead space AND the next item is large,
        // a fresh bin is more attractive (large item pairs with fresh capacity).
        if next_item_size > 0 {
            let next_big = next_item_size as f64 / bin_capacity as f64;
            let dead = post_residual as f64 / bin_capacity as f64;
            if dead > 0.0 && dead < 0.25 && next_big > 0.5 {
                score -= 30.0;
            }
            // If next item would fit in the post-residual of a fresh bin, opening is fine.
            if (next_item_size as f64) <= post_residual as f64 {
                score -= 12.0;
            }
        }
        // Late in the stream, avoid proliferating bins with leftover capacity.
        score += 20.0 * progress;
    } else {
        // Existing bin that fits.
        // Last-chance bonus: if this is the only bin that fits, using it avoids a new bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        } else if fitting_bins_count == 2 {
            score -= 15.0;
        }

        // Lookahead: reward leaving a gap that accommodates the next item,
        // penalize leaving a gap that strands the next item.
        if next_item_size > 0 {
            if (next_item_size as f64) <= post_residual as f64 {
                score -= 10.0;
            } else {
                // Dead space: leftover too small for the next item.
                let stranded = 1.0 - (post_residual as f64 / (next_item_size as f64).max(1.0));
                score += 8.0 * stranded;
            }
        }

        // Coupling with global state: prefer bins whose residual is near the mean
        // (balanced depletion), especially early in the stream.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * dev * (1.0 - progress);

        // Slight preference for bins with larger residual when many bins are open
        // (drain the fullest-fitting ones to consolidate).
        score -= 0.08 * bin_residual as f64 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (low post_residual), with non-linear polynomial shaping.
    let mut score = pr * pr / cap;

    // Smooth coupling of post_residual with stream progress: late in the stream,
    // dead space becomes more costly (quadratic ramp).
    score += pr * (pr / cap) * progress * 0.8;

    // Reward when the lookahead item can still fit into the leftover space.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fill_after_next = pr - next_item_size as f64;
        score -= (next_item_size as f64 / cap) * (1.0 + fill_after_next / cap) * 6.0;
    } else if next_item_size > 0 {
        // Lookahead won't fit here: penalize proportionally to the wasted gap.
        score += (pr / cap) * 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - pr / cap);
    }

    // New-bin candidate: penalize opening a new bin, but relax the penalty when
    // existing bins fit poorly (high mean residual spread) or many bins already open.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln() + 1.0;
        score += 12.0 + crowding * 1.5;
        // Smooth relaxation: if no good fit exists elsewhere, new bin is less bad.
        score -= (mean_residual / cap) * 4.0;
        score -= progress * 3.0;
    }

    // Mild preference for bins already below mean residual (consolidation).
    score -= ((mean_residual - pr) / cap).max(-1.0).min(1.0) * 1.5;

    // Small smooth tie-breaker against very fragmented bins.
    score += ((bin_residual as f64) / cap).powi(3) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Dead-space penalty: residuals that few item sizes can use are expensive.
    // Harmonic classes: residual mod 10 buckets — small odd leftovers are nearly unusable.
    let harmonic = post_residual % 10;
    if harmonic != 0 {
        score += (10 - harmonic) as f64 * 0.8; // distance to next multiple of 10 penalized
    } else {
        score -= 3.0; // perfectly aligned leftover: reward
    }

    // Fractional class thresholds on post_residual
    if frac < 0.10 {
        score += 12.0; // tiny unusable sliver
    } else if frac < 0.25 {
        score += 4.0;
    } else if frac < 0.5 {
        score -= 2.0;
    } else if frac < 0.75 {
        score -= 5.0;
    } else {
        score -= 8.0; // large leftover, very reusable
    }

    // Integer-division class of next item vs post residual: does the next item fit harmonically?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Coupling: reward when next item's class matches leftover class
            let class_match = (post_residual % 20) == (next_item_size % 20);
            if class_match {
                score -= 6.0;
            }
            // Reward proportional to how well next item fills the leftover
            let fill = next_item_size as f64 / post.max(1.0);
            score -= fill * 10.0;
        } else {
            // Next item won't fit here: penalize leaving a residual in a "dead zone"
            score += (post_residual as f64) * 0.05;
        }
    } else {
        // Last item: just minimize waste
        score += (post_residual as f64) * 0.02;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        score += pressure + (open_bins_count as f64) * 0.5;
        // Late in stream, avoid opening new bins unless residual classes are bad
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mean residual coupling: when open bins are generally full, prefer tight fits
    if (mean_residual - post).abs() < 5.0 {
        score -= 2.0;
    }

    // Prefer bins whose residual is closest to item size (tight fit), scaled by harmonic class
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (wasted capacity).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable gap
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 100.0;
    }

    // Reward tight fits (item consumes a large fraction of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Lookahead synergy: if the next item fits exactly in the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        if next_fit_ratio > 0.9 {
            score -= 50.0;
        } else {
            score -= 15.0 * next_fit_ratio;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; slight penalty unless
        // post_residual is near zero (dead space anyway).
        if post_residual >= next_item_size.saturating_sub(5) {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity and gets
    // penalized proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
        // But if no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mean residual coupling: if current bin's residual is far below the mean,
    // it is a good consolidation target.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 5.0 * dev.min(50.0) / 10.0;
    }

    // Late in the stream, prefer closing bins tightly (dead space matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: nearly empty post-residual is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item exactly matches post_residual,
    // strongly prefer this bin (chain of perfect fits).
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        if gap == 0.0 {
            score -= 45.0;
        } else if gap <= 5.0 {
            score -= 15.0;
        } else {
            // Penalize leaving residual that neither fits next item well
            // nor is likely usable later.
            score += gap * 0.15;
        }
        // If next item cannot fit anywhere after this placement idea,
        // slight penalty unless gap is tiny.
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    // (small residual bins), penalize dumping into very roomy bins
    // unless it makes a good fit.
    let mean_gap = bin_residual as f64 - mean_residual;
    if mean_gap > 0.0 {
        score += mean_gap * 0.10;
    }

    // Last chance: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin provides a decent fit. Give it a moderate default score;
    // good fits in existing bins (post_residual small) will undercut it.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when stream is early
        // or many bins are already open (cheap to spread).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 + 25.0 * (1.0 - progress);
        // If the item is large relative to capacity, opening fresh space
        // can be wise to preserve flexibility.
        if item_size > bin_capacity * 3 / 4 {
            score -= 10.0;
        }
    }

    // Mild penalty for leaving awkward mid-range dead space.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Identify brand-new empty bin candidate.
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize opening a new bin so existing bins are preferred,
    // but relax the penalty late in the stream or when many bins are open.
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let density = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.1);
        score += 18.0 + 14.0 * (1.0 - progress) + 2.0 * density.sqrt();
    }

    // Reward tight fits: waste fraction amplifies the score.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * waste_frac * waste_frac;

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            // mild reward proportional to how well next item fills leftover
            let fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 4.0 * fill;
        } else {
            // next item won't fit here; slightly penalize leaving large dead space
            score += 2.0 * waste_frac;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // (avoid opening a new bin when the item would otherwise not fit anywhere).
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * (1.0 - waste_frac);
    }

    // Global coupling: prefer bins whose residual deviates below the mean
    // (consolidate emptier space into fewer bins).
    if !is_new_bin {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score -= 3.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_post = pr / cap;

    // Core: prefer tight fits (low post_residual), with smooth polynomial shaping.
    let mut score = pr;

    // Non-linear coupling: quadratic penalty on wasted space, modulated by stream progress.
    // Early on, waste matters less (more items to come fill gaps); later, dead space is costly.
    let waste_weight = 0.5 + 1.5 * progress;
    score += waste_weight * norm_post * norm_post * cap;

    // Reward near-perfect fits (post_residual small relative to item) with a smooth dip.
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let next_fits = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let gap_util = (next_item_size as f64 / cap).min(norm_post.max(1e-9));
        score -= 6.0 * next_fits * gap_util;
        // Penalize leaving a gap too small for the next item (unusable dead space).
        let dead = if next_fits < 0.5 && pr > 0.0 { 1.0 } else { 0.0 };
        score += 5.0 * dead * norm_post * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: default to a high score so it is only chosen when no open bin
    // offers a decent fit; relax slightly when many bins exist or item is large.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score = cap * (1.2 + 0.1 * openness) - 10.0 * fit_ratio;
    }

    // Mild diversity pressure: prefer bins below the mean residual (balancing).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity-fraction bucket it belongs to.
    let item_class = item_size / 10;                    // 1..=10 classes
    let next_class = (next_item_size / 10).max(1);      // 0 => last item

    // Reward placements where the leftover post_residual matches a harmonic
    // class boundary that a future item could fill (dead-space matching).
    let leftover_class = post_residual / 10;
    let class_match = if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits exactly into the leftover if classes align
        (leftover_class as i64 - next_class as i64).abs() as f64
    } else {
        0.0
    };
    score -= 4.0 * class_match;

    // Penalize unusable dead space: post_residual too small for anything
    // (items are >= 1, but small slivers below class-1 are worst).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward via modulo structure on capacity.
    if post_residual == 0 {
        score -= 60.0;
    } else if bin_capacity % post_residual == 0 && post_residual <= 50 {
        // leftover splits the capacity into equal usable chunks
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when the current bin would
    // be left with awkward residual or the item is huge relative to residual.
    if bin_residual == bin_capacity {
        // base cost of opening a fresh bin
        score += (bin_capacity as f64) * 0.9;
        // open a new bin if existing bins would be fragmented badly
        if post_residual < 15 && item_size > 0 {
            score -= (bin_capacity as f64) * 0.95;
        }
        // early in stream, fresh bins are cheaper to open (future flexibility)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
        // if many open bins, discourage adding more
        score += open_bins_count as f64 * 2.0;
    }

    // Tight-fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 20.0;
    } else if fill_ratio > 0.7 {
        score -= 8.0;
    }

    // Prefer bins whose residual is close to the item (minimize waste).
    score += (bin_residual - item_size) as f64 * 0.05;

    // Mean residual coupling: if this bin's residual is far above the mean,
    // it is a "loose" bin; slight penalty to keep packing tight bins first.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.03;

    // Next-item lookahead: if next item cannot fit this bin's post_residual,
    // but could fit elsewhere, mild penalty for hogging the good fit.
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
