    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter fill).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Late-stream urgency: consolidate into existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
