        }
        // late in the stream, discourage spawning extra bins
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress;
    }

    // Penalize leaving very small unusable residuals (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
