}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: squared non-linear coupling of post_residual with progress.
    let tightness = 1.0 - post / cap;
    score -= 18.0 * tightness * tightness * (0.5 + progress);

    // Penalize small post_residual that wastes little but locks the bin (dead space trap)
    // unless it is near zero (perfect fit).
    let waste = post / cap;
    score += 12.0 * waste * waste * (1.0 - progress);

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let compat = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 10.0 * compat * compat;
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty scaled by progress.
        score += 6.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin when other bins fit,
    // more so late in the stream; relax when many bins are open with high mean residual.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        let crowding = (mean_residual / cap).min(1.5);
        score += 20.0 + 25.0 * progress - 8.0 * crowding - 2.0 * open.sqrt();
    } else {
        // Slight preference for fuller bins among open ones (best-fit bias).
        score += 4.0 * (bin_residual as f64 / cap);
    }

    // Smooth progress-based drift: late stream favors consolidation.
    score -= 5.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
