    // awkward slivers for typical item sizes.
    let residue_class = post_residual % 10;
    if residue_class == 1 || residue_class == 2 || residue_class == 3 {
        score -= 5.0; // slivers often unusable -> but tight, slight reward
    } else if residue_class >= 7 {
