    // Last-chance bin: only one open bin fits this item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when current
    // open bins offer poor fits.
    if bin_residual == bin_capacity {
        // Base penalty so fresh bins are not chosen frivolously.
        score += 35.0;
