    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect closure reward
    if post_residual == 0 {
        score -= 45.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure to fill existing bins: penalize leaving large residuals in many open bins
    score += 0.2 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: reward bins that can also host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // New-bin candidate penalty: opening a fresh bin should only win when it is truly better
    if bin_residual == bin_capacity {
        score += 10.0 + 2.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / cap;

    // Exact fill is gold.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 150.0 * snug;
        } else {
            // next item does NOT fit here: penalize leaving a large unusable gap
            let gap = post_residual as f64;
            if next_item_size > post_residual {
                score += 0.5 * gap;
            }
        }
    }

    // Penalize dead space that no plausible item (>=1) can use well:
    // small post_residuals are fine (near-full), large ones wasteful.
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // tiny gap is acceptable
    }

    // Relative to mean residual: prefer bins that are already below-average residual
    // (i.e. fuller bins) so emptier bins stay flexible.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: make empty bins mildly unattractive unless
    // the item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        score += 120.0;
        if item_size as f64 > 0.6 * cap {
            score -= 100.0; // big items are fine in fresh bins
        }
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            score += 60.0; // keep fresh bins for upcoming big items
        }
    }

    // Slight preference for using fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    // Mild normalization of fit ratio.
    score += 20.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: later in stream => prefer tighter packing, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward bins that become "almost full" after placement (small post_residual is base score already).
    // Extra quadratic reward for very tight fits (dead space minimization).
    let tight = (bin_residual - item_size) as f64;
    score -= 8.0 * (1.0 - tight / bin_capacity as f64).powi(2);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Penalize leaving a residual that is too small for typical future items
    // (dead space below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: reward if next item can fit into the post residual,
    // penalize if next item is large and post residual is awkwardly close-but-insufficient.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // wasted space relative to known next item
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Global state: many open bins with high mean residual => encourage consolidating
    // into existing bins rather than spreading out.
    if open_bins_count > 0 {
        let consolidation = mean_residual / bin_capacity as f64;
        score -= 5.0 * consolidation;
        // Penalize bins whose residual deviates far above the mean (fragmentation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // New-bin candidate handling: brand-new empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases with progress (toward end, cheaper
        // to open a bin than to fragment) but increases with number of open bins.
        let mut new_bin_cost = 18.0 - 10.0 * progress + 1.5 * open_bins_count as f64;
        // If no open bin fits well (post_residual here would be capacity - item),
        // opening a new bin may be justified when the item is large.
        if item_size > bin_capacity / 2 {
            new_bin_cost -= 6.0;
        }
        score = new_bin_cost + post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual, with smooth polynomial shaping.
    let x = post / cap; // normalized post residual in [0,1]
    let mut score = x * (1.0 + 0.9 * x) * cap;

    // Non-linear interaction: waste penalization grows as stream progresses.
    let waste = post.powi(3) / (cap * cap);
    score += waste * (0.4 + 1.6 * progress * progress);

    // Perfect fit reward (smooth, no hard cutoff).
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Last-chance bonus: only bin that fits -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate penalty: opening a new bin is costly unless the
    // residual left behind would be nearly useless in an existing bin.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let useless = if post < 10.0 { 0.0 } else { post / cap };
        score += 55.0 - 40.0 * useless * useless;
        // If no open bin fits at all, opening is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post residual, reward.
    if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 0.5 {
        score -= 15.0;
    }
    // Penalize if next item cannot fit but residual is large (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size && post > 0 {
        score += 0.25 * post * progress;
    }

    // Mild diversity pressure via mean residual coupling.
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong quadratic penalty on wasted space (dead space avoidance)
    score += 0.02 * (post_residual as f64).powi(2) / cap;

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Harmonic class logic: quantize post_residual into capacity fractions
    let quarter = (bin_capacity / 4).max(1);
    let half = bin_capacity / 2;
    let post = post_residual;
    if post < quarter {
        score -= 8.0; // tiny leftover, very usable for small items
    } else if post < half {
        // medium leftover: value depends on how it composes with typical item sizes
        let m = post % quarter;
        score -= 4.0;
        score += m as f64 * 0.3; // off-grid leftovers slightly penalized
    } else if post == half {
        score -= 12.0; // exactly half free is highly flexible
    } else {
        // large leftover: still roomy, mildly good
        let m = post % (bin_capacity / 8).max(1);
        score -= 2.0;
        score += m as f64 * 0.2;
    }

    // Lookahead: bonus if next item fits exactly in the post residual
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post {
            score -= 10.0;
            // harmonic check: next item leaves a tiny remainder too
            let nr = post - next_item_size;
            if nr <= 10 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual: penalize big leftovers more
            score += (post as f64 - cap * 0.5).max(0.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        // extra reward if the fit is tight
        if post <= 15 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap + 20.0;
        // if current bin would leave a big awkward residual, opening a new bin is attractive
        if post > half {
            score -= (post as f64 - half as f64) * 0.4;
        }
        // if next item is large, a fresh bin may serve it better
        if next_item_size > item_size && next_item_size > half {
            score -= 10.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
        // many open bins: discourage adding more
        score += open_bins_count as f64 * 1.5;
    }

    // Mild preference to fill fuller bins among comparable options
    score -= (bin_residual as f64 / cap) * 2.0;

    // Mean residual coupling: if open bins are generally roomy, keep it that way
    score += (mean_residual - post as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // (min item is 1 under the interface note, but gaps < 8 waste capacity).
    if post_residual > 0 && post_residual < 8 {
        score += 25.0 + (8 - post_residual) as f64 * 4.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual >= 8 {
        // Larger usable leftovers are mildly attractive; scale by usability.
        score -= 6.0 * (post_residual.min(40) as f64 / 40.0);
    }

    // Lookahead coupling: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 5.0; // this bin becomes dead after placement
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling
    // existing bins; few open bins -> allow opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure.
        score += 20.0 + pressure * 4.0;
    } else {
        score -= pressure * 2.0;
        // Prefer bins tighter than average residual (best-fit flavor).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fill
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward decays with slack; dead space after next item is penalized
            score -= 30.0 * (1.0 - slack / (bin_capacity as f64));
            score += 0.35 * slack;
        } else {
            // next item cannot fit here: post_residual becomes pure dead space
            score += 0.5 * (post_residual as f64);
        }
    }

    // Penalize large post_residual relative to mean residual (creating outlier dead space).
    score += 0.25 * ((post_residual as f64) - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item fits poorly everywhere
    // or stream is early with few bins. Penalize opening new bins generally.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0; // new bin can chain-fill the next item
        }
        // late in stream, prefer squeezing into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-friendly placement: subtract proportional to leftover utility
            score -= (next_item_size as f64 / bin_capacity as f64) * 12.0;
        } else {
            // dead space for the known next item: penalize proportionally
            score += (next_item_size as f64 / bin_capacity as f64) * 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Penalize creating tiny unusable fragments relative to the minimum item scale.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // global residual landscape is tight or the stream is early.
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // default penalty keeps existing bins preferred
        score += 25.0;
        // relax penalty when open bins are nearly full and stream is progressing
        score -= tightness * 30.0 + progress * 5.0;
        // many open bins with slack: opening more is wasteful
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
        // if next item is large, a fresh bin is valuable
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // mild preference for bins with below-average residual (tighter bins)
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = (pr / cap).clamp(0.0, 1.0); // normalized post-residual

    // Smooth polynomial coupling of post-residual with progress:
    // early in the stream, tolerate larger residuals; late in the stream, punish them harder.
    let progress_weight = 0.5 + 2.0 * progress * progress; // smooth quadratic ramp
    score += progress_weight * cap * (x * x - x); // negative for 0<x<1, rewards tight fits more as stream advances

    // Non-linear reward for near-zero post residual (smooth "dead space" penalty inverse)
    score -= 12.0 * (-(pr / (0.15 * cap + 1.0))).exp();

    // Penalty if post-residual is in a "dead zone": too small for likely future items (smooth via logistic)
    let min_future = if next_item_size > 0 { next_item_size as f64 } else { 10.0 };
    let tightness = 1.0 / (1.0 + (-(pr - min_future) / 8.0)).exp(); // ~1 when pr << next item need
    score += 15.0 * tightness * (1.0 - progress); // early stream: don't strand bins below next item size

    // Lookahead coupling: if next item fits exactly in post-residual, reward smoothly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (-(gap / 10.0)).exp();
    }

    // Last-chance bin: smooth reward when this is the only fitting bin
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 8.0 * (1.0 + progress);
    }

    // Mean-residual coupling: prefer bins deviating smoothly below mean residual (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev - 3.0 * dev;

    // Mild preference for keeping bin count low early, opening bins late is cheaper
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate handling: neutral-ish baseline, slightly penalized unless current bins are bad fits
    if bin_residual == bin_capacity {
        let waste_pressure = (mean_residual / cap - 0.5).max(0.0);
        score = cap * 0.6 + 20.0 * waste_pressure - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that fall into
    // "usable" classes (divisible into common item sizes), penalize dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual is an exact multiple of small item sizes -> very usable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds: classify residual into coarse bands.
    let band = post_residual / 25; // 0..=4
    score -= band as f64 * 2.0;

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item exactly fills the bin.
            if next_item_size == post_residual {
                score -= 25.0;
            } else {
                score -= 8.0;
                // Reward if next item also lands on a good class boundary.
                if (post_residual - next_item_size) % 10 == 0 {
                    score -= 5.0;
                }
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted fit.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    } else {
        // Last item: prefer tightest fill (smallest post residual).
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when this bin's fit is poor.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base penalty so open bins with decent fits win.
        score += 20.0;
        // If the item leaves a large unusable residue in an open bin context,
        // a fresh bin becomes relatively better (penalty shrinks).
        let fill_ratio = item_size as f64 / cap;
        if fill_ratio > 0.7 {
            score -= 10.0 * (fill_ratio - 0.7) / 0.3;
        }
        // If no other bin fits (this call may be the only viable option),
        // the penalty is offset by the last-chance logic above.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Stream progression: early on, be more conservative about fragmenting bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    // Mean residual context: if mean residual is small, tight fits matter more.
    score += (mean_residual - pr) * 0.05;

    // Small tie-breaker favoring bins with less residual overall.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

