    }

    // Open-bin pressure: discourage scattering across many bins unless fit is good.
    score += (open_bins_count as f64) * 0.35;

    // Prefer bins below the mean residual (fills emptier bins first keeps
    // tight bins for tight needs) — but only mildly.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: empty bin should only win when item is huge or
    // no open bin is decent. Penalize opening a new bin by default.
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size >= 60 {
            score -= 45.0; // big items are fine to start fresh
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If lookahead is large and this item is small, new bin wastes space.
        if next_item_size > 0 && next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Slight late-stream conservatism: close out bins efficiently.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral-to-slightly-high baseline so that only genuinely
    // poor fits in existing bins trigger opening a fresh bin.
    if bin_residual == bin_capacity {
        return bin_capacity as f64 * 0.75 + (next_item_size as f64) * 0.25;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly consumes
    // the post residual (perfect chaining), penalize near-misses.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 18.0; // perfect match: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            score -= 6.0 - diff * 0.08; // next item still fits: mild reward decaying with slack
        } else {
            score += 4.0 + diff * 0.05; // next item won't fit here: penalize dead space
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 2.0;
    }

    // Relative-to-mean coupling: bins with residual far above the mean leave
    // more usable space elsewhere; mildly prefer using below-mean-residual bins.
    score += (post_residual as f64 - mean_residual) * 0.10;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it to
    // avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Late-stream tightening: as the stream progresses, weight tightness more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    // Small penalty for very small post residuals that create unusable slivers
    // (below the minimum item size of 1..=100 range, treat < 5 as dead).
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for future items
    // (items range 1..=100; residual below ~10 is nearly dead, residual
    // just below a "typical" item is also awkward).
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0 - 2.5 * pr; // nearly unusable sliver
        } else if pr < 25.0 {
            score += 0.6 * (25.0 - pr); // awkward gap
        }
    }

    // Perfect fill is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, big bonus; if next item cannot fit, mild penalty unless
    // post residual is tiny anyway.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let nxt_fit = nxt / post_residual.max(1) as f64;
            score -= 12.0 * nxt_fit;
        } else if post_residual > 0 && post_residual < 10 {
            score += 5.0; // sliver blocks nothing of value
        } else {
            score += 4.0; // wasted usable space relative to lookahead
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of
    // this bin if it stays behind. Penalize the empty-bin candidate in
    // proportion to the residual it would leave stranded, but relax when
    // this bin's fit is truly terrible.
    if bin_residual == bin_capacity {
        let stranded = mean_residual.min(bin_capacity as f64);
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 45.0 + 0.35 * stranded;
        // Late in the stream, consolidating into existing bins matters more.
        new_bin_score += 10.0 * progress;
        // If many bins are open and fragmented, prefer consolidation.
        new_bin_score += 0.5 * open_bins_count as f64;
        // If the current placement would leave a perfect-for-next-item gap,
        // opening a new bin is bad.
        if next_item_size > 0 && next_item_size == post_residual {
            new_bin_score += 25.0;
        }
        score = score.max(0.0) + new_bin_score;
    }

    // Mild global pressure: when mean residual is low (bins nearly full),
    // reward placements that preserve large residuals elsewhere.
    let mr = mean_residual;
    if mr < 30.0 && bin_residual < bin_capacity {
        score -= 3.0 * (30.0 - mr) / 30.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post residual, normalized by capacity
    let mut score = pr / cap;

    // Tightness reward: quadratic coupling between post_residual and item size
    let item = item_size as f64;
    let fill_ratio = item / cap;
    score -= 2.0 * fill_ratio * (1.0 - pr / cap);

    // Non-linear polynomial penalty on dead space: small residuals are fine, mid residuals are wasteful
    let r = pr / cap;
    score += 0.8 * r * r * (1.0 - r);

    // Stream progress coupling: early on, keep bins flexible (penalize very tight fits slightly);
    // late in stream, strongly prefer tight packing
    let flex = (1.0 - progress) * (progress * (1.0 - progress) * 4.0);
    score += flex * 0.5 * (1.0 - fill_ratio);
    score -= progress * 1.5 * (1.0 - r);

    // Lookahead: reward residual that can still host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 0.6 * (1.0 - (pr - nxt) / cap);
        } else {
            // residual becomes dead space for the next item
            score += 0.4 * r;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        // neutral-ish baseline; slightly penalized so tight fits in open bins win
        score += 0.35 + 0.5 * (1.0 - progress);
        // but if open bins are quite full on average, new bin is attractive
        score -= 0.6 * (mean_residual / cap).min(1.0);
    }

    // Mild penalty for proliferating many open bins early
    score += 0.02 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (mod-10 buckets) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual % 10) as f64;
    let decile = (post_residual / 10) as f64;

    // Dead-space classes: residuals that only very small items can fill are bad.
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver
    } else {
        // reward residuals that match common item-size classes (multiples of 5/10)
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 4.0;
        } else {
            score += class * 0.3; // ragged residual penalty
        }
        // deep residual (large leftover) is generally good unless it's a lone bin
        score -= decile * 0.5;
    }

    // --- Coupling with lookahead item ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: strong reward, scaled by how tight
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 12.0 + 10.0 * tight;
        } else {
            // next item won't fit: penalize proportional to wasted potential
            score += 6.0 + (next_item_size as f64 - pr).min(cap) * 0.15;
        }
    }

    // --- Last-chance logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0; // only bin that fits: strongly prefer using it
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // opening a new bin is only attractive when open bins are badly fragmented
        let frag = mean_residual / cap;
        score = cap * 0.5 + frag * 20.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
        if post_residual % 10 == 0 && item_size % 10 == 0 {
            score -= 6.0; // clean class alignment
        }
    }

    // --- Mild preference for filling older bins as stream progresses ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // Slight penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fill is the best outcome.
        score -= 100.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Tight fit reward: item occupies most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins; prefer reuse.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * fitting_bins_count as f64;
        if mean_residual > 60.0 {
            score -= 45.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Lookahead: if the next item fits the post-residual exactly, reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score += 25.0; // would create dead space for the next item
        }
    }

    // Early in the stream, be slightly more willing to open bins for big items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if item_size > 60 && progress < 0.3 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item + next item perfectly fill bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Leftover after also fitting the next item; prefer smaller leftovers.
            let extra = (post_residual - next_item_size) as f64;
            score -= 200.0 - 1.5 * extra;
        } else {
            // Next item won't fit here: penalize dead space, worse when tiny (unusable).
            let dead = post_residual as f64;
            score += 1.2 * dead;
            if dead > 0.0 && dead < 10.0 {
                score += 60.0 * (10.0 - dead);
            }
        }
    }

    // Tight fit reward relative to capacity: small post_residual overall is good
    // only if it is exactly matched; otherwise avoid stranding space.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: neutral-ish baseline, opened only when
    // existing bins offer poor fits. Slightly favor new bin late in stream
    // if mean residual across open bins is large (fragmentation).
    if bin_residual == bin_capacity {
        score = 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin can also serve next item
        }
        if mean_residual > 50.0 {
            score -= 10.0;
        }
        // Early stream: keep bins open, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
    }

    // Mild pressure to prefer bins with residuals near mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly penalize opening a new bin unless the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        score += cap * 1.5;
        // But if next item also fits the fresh bin perfectly, mild bonus.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= cap * 0.35;
        }
        return score;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * cap * 0.6;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= cap;
    } else if post_residual < 10 {
        score -= cap * 0.3;
    } else if post_residual > 40 {
        // Large dead space penalty, scaled by how full the bin already is.
        let fill = 1.0 - post_residual as f64 / cap;
        score += (post_residual as f64) * (0.5 - fill * 0.4);
    }

    // Lookahead: reward if the next item fits the post residual.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= ratio * cap * 0.5;
        } else {
            // Small post_residual that cannot host next item: mild penalty if residual is awkward.
            if post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, favor using it.
    if fitting_bins_count == 1 {
        score -= cap * 0.8;
    } else if fitting_bins_count > 1 {
        // Spread preference: with many options, prefer tighter fits (already covered) but
        // slightly penalize bins far below mean residual to keep residuals balanced.
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.15;
    }

    // Time horizon: early in the stream, be more conservative with open bins (favor consolidation);
    // late in the stream, allow slightly looser fits since fewer items remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // Many open bins: encourage closing them out by filling existing ones.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residual below mean (keeps a pool of large residuals for big items).
    if (bin_residual as f64) > mean_residual + 20.0 && item_size < 40 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: normalized post-residual (dead space penalty)
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, dead space is cheap (bins still fillable later);
    // late in the stream, dead space becomes increasingly costly.
    let x = post / cap; // normalized post residual in [0,1]
    let poly = x * x * (1.0 + progress) + x * x * x * progress;
    score += 2.0 * poly;

    // Smooth reward for tight fits: small post_residual gets quadratic discount.
    let tight = (1.0 - x).max(0.0);
    score -= 1.5 * tight * tight * (0.5 + 0.5 * progress);

    // Lookahead coupling: if next item fits into post_residual, reward this bin.
    if next > 0.0 && next <= post {
        let slack = (post - next) / cap;
        score -= 0.8 * (1.0 - slack) * (1.0 - slack);
    } else if next > post {
        // Next item won't fit here; mildly penalize leaving awkward gaps.
        score += 0.3 * (next / cap) * progress;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 1.2;
    } else if fitting_bins_count > 1 {
        // Many alternatives: slightly penalize to encourage diversity of residuals.
        score += 0.05 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate detection: brand-new empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if the item is large relative to capacity
        // (poor fit elsewhere) or stream is early with plenty of room to fill it later.
        let item_frac = item / cap;
        let early = (1.0 - progress) * (1.0 - progress);
        score = 1.5 - 0.6 * item_frac - 0.5 * early + 0.3 * progress;
        // If no other bin fits, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 2.0;
        }
    }

    // Mild penalty for proliferating open bins when mean residual is already high.
    let mean_frac = mean_residual / cap;
    score += 0.1 * mean_frac * (open_bins_count as f64).sqrt() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: waste classes ---
    // Classify dead space by integer division thresholds on post_residual.
    // Small post residuals are "sealed" bins (good); large ones risk dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Harmonic bucket: post_residual // 10 -> 0..10 classes
    let bucket = post_residual / 10;
    let bucket_penalty: f64 = match bucket {
        0 => -12.0,           // 0..9: nearly perfect fit, strongly reward
        1 => -6.0,            // 10..19: good seal
        2 => -2.0,            // 20..29: acceptable
        3 => 1.5,             // 30..39: mild waste
        4 => 3.0,             // 40..49
        5 => 5.0,             // 50..59: half-empty, risky
        6 => 7.0,
        7 => 9.0,
        8 => 11.0,
        9 => 13.0,
        _ => 15.0,            // huge residual left: bad unless new bin
    };
    score += bucket_penalty;

    // Modulo-20 harmonic coupling: residuals near multiples of 20 pair well
    // with common item sizes (10..80 range), giving tighter future fits.
    let m = (post_residual % 20) as f64;
    score -= 2.0 * (1.0 - (m / 10.0 - 1.0).abs()); // reward m near 0 or 20

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // Next item can still fit here: reward keeping this bin viable
            score -= 3.0 + 0.05 * nxt;
            // Extra reward if post_residual lands in a class that fits nxt snugly
            if (post - nxt) < 10.0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit after this placement: penalize creating
            // stranded residual that is neither sealed nor usable.
            if post > 0.0 && post < nxt {
                score += 0.10 * (nxt - post);
            }
        }
    } else {
        // Last item: pure best-fit, reward tight packing
        score -= 5.0;
    }

    // --- Last-chance logic: this is the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0; // strongly prefer using the sole fitting bin
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost plus pressure from open-bin count.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55 + 2.5 * (open_bins_count as f64).sqrt();
        // Late in the stream, prefer consolidating into open bins.
        score += 6.0 * progress;
        // If the item fits snugly anywhere conceptually (item near post class),
        // opening a bin is fine for large items.
        if item_size >= 50 {
            score -= 8.0;
        }
        // If many bins already fit the item, discourage opening a new one.
        if fitting_bins_count > 2 {
            score += 6.0 * (fitting_bins_count as f64 - 2.0);
        }
    }

    // --- Mean-residual drift: avoid bins far from the fleet mean ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Tie-break: prefer tighter fit via exact-fill bonus
    if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: quadratic penalty on post_residual near zero.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        score += (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack * 0.5;
        } else {
            // next item won't fit; penalize proportionally to wasted lookahead
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably from mean.
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.4;
    } else {
        score += (resid - mean_residual) * 0.2;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: make opening a new bin costly unless current fits are terrible.
    if bin_residual == bin_capacity {
        // empty bin baseline: moderately high score so it only wins on bad fits
        score += 120.0;
        // but early in stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 60.0;
        // if next item is large and won't fit elsewhere well, fresh bin is attractive
        if next_item_size >= item_size && next_item_size > 50 {
            score -= 40.0;
        }
    }

    // Late stream: consolidate, penalize spreading across many bins.
    if progress_proxy(step_index, total_items) > 0.7 && open_bins_count > 3 {
        score += open_bins_count as f64 * 1.5;
    }

    // Tightness reward: bins that become very full are good placements.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * fill * 80.0;

    score
}

#[inline]
fn progress_proxy(step_index: usize, total_items: usize) -> f64 {
    if total_items == 0 { 0.0 } else { step_index as f64 / total_items as f64 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate detection
    let is_new_bin = bin_residual == bin_capacity;

    // Progress through the stream
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Tightness reward: strongly favor minimal post residual (best-fit core)
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;

    // Last-chance bonus: if this is the only bin that can fit, strongly favor it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Penalize new bins: opening a bin is expensive unless nothing fits well
    if is_new_bin {
        // Base penalty for opening a new bin
        score += 25.0;
        // More penalty when many bins are open (fragmentation risk)
        score += open_bins_count as f64 * 1.5;
        // Less penalty late in the stream (fewer future interactions)
        score -= progress * 10.0;
        // If no open bin fits at all, new bin is the only option: cancel penalty
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Reward using existing bins, more so when open bin count is high
        score -= 5.0 + 0.5 * open_bins_count as f64;
    }

    // Lookahead: if next item would fit the post-residual, reward leaving this bin usable
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
        // Extra reward if post residual closely matches next item (good chaining)
        let chain_gap = post_residual as f64 - next_item_size as f64;
        score -= (10.0 - chain_gap).max(0.0) * 0.5;
    } else if next_item_size > 0 {
        // Penalize creating dead space that next item cannot use
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Global residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Slight penalty for very large leftover slivers (unusable space)
    if post_residual > 0 && post_residual < 10 {
        score += 3.0; // small sliver, but item nearly fills bin — actually good
        score -= 10.0; // net reward: near-perfect fit
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = post / cap;
    let fill = item / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = post * (1.0 + 0.35 * fit_ratio * (1.0 - fit_ratio));

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post-residual) are worth more.
    score -= 18.0 * progress * (1.0 - fit_ratio).powi(2) * fill;

    // Penalize large unusable dead space quadratically.
    if post < item {
        let dead = (item - post) / cap;
        score += 25.0 * dead * dead * cap;
    }

    // Lookahead coupling: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = (post - nxt).abs();
        score -= 8.0 * (1.0 - slack / cap) * (post >= nxt) as i32 as f64;
        score += 5.0 * (slack / cap).powi(2);
    }

    // Last-chance bonus: only one fitting bin -> strong smooth reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - fit_ratio);
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - fit_ratio;
        score += 45.0 * (1.0 - tightness.powi(3));
        score += 10.0 * (1.0 - progress);
    }

    // Mild diversity term: prefer bins deviating from mean residual smoothly.
    score += 0.15 * (res - mean_residual).powi(2) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into classes via integer division.
    let class = post_residual / 10; // 0..10 classes
    // Small post_residual classes are "dead space" classes -> penalize more than linear.
    match class {
        0 => { score += 40.0; }              // unusable sliver
        1 => { score += 25.0; }              // nearly dead
        2 => { score += 12.0; }              // poor
        3 => { score += 5.0; }               // marginal
        4 | 5 => { score -= 6.0; }           // sweet spot: half-ish fill
        6 => { score -= 3.0; }
        7 => { score -= 1.0; }
        _ => {}                              // large residual, neutral
    }

    // Modulo coupling: perfect-fit residues (multiples of 10) get a bonus.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Exact fit: zero residual is excellent.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: prefer leaving harmonic-compatible residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: slightly penalize tight residuals
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin has huge residual; make it unattractive
    // unless the item fits badly in all open bins (fitting_bins_count == 1 refers to it)
    // or open bins are very full on average.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 55.0;
        // But if no open bin fits well (this is the only fitting bin), relieve penalty.
        if fitting_bins_count == 1 {
            score -= 70.0;
        }
        // Open new bins earlier when stream is young and many bins will be needed.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is small, new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Mild preference for bins tighter than the mean (best-fit flavor).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 2.0;
    } else if resid_f > mean_residual * 1.5 {
        score += 2.0;
    }

    // Small tie-breaker toward later steps consolidating into fewer bins.
    score -= (open_bins_count.min(20) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest plausible
    // item threshold are "unusable" dead space -> heavy penalty.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward snug fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) / (post_residual as f64 + item_size as f64) * 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 6.0;
        // But allow a new bin if current bin leaves a gap that fits nothing useful.
        if post_residual > 0 && (post_residual as f64) < dead_threshold {
            score -= 30.0;
        }
    }

    // Lookahead: if next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 5.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (concentrate filling into emptier-relative bins) early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64) < mean_residual {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // (or near-exactly) matches the next item's size.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        // Perfect match: next item exactly fills the bin -> big reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to tightness of the 2-step fit.
            let slack = post - nxt;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving large dead space.
            let dead = nxt - post;
            score += 0.6 * dead;
        }
    } else {
        // Last item: prefer the tightest possible fit.
        score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 20.0;
    }

    // Reward tight fits overall (small post_residual relative to capacity).
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Coupling with mean residual: prefer bins tighter than the mean,
    // penalize bins looser than the mean (they waste space elsewhere).
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 0.4 * (mean_residual - post_f).min(50.0);
    } else {
        score += 0.4 * (post_f - mean_residual).min(50.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so late in the stream or when
        // many bins are already open.
        score += 55.0 + 0.2 * open_bins_count as f64 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // But if the next item would perfectly fill the new bin too, soften.
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 15.0;
        }
    }

    // Mild stream-phase modulation: early on, be slightly more willing to
    // spread items (keep residual flexibility); late, pack tightly.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * phase * (post_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but discount tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // dead space penalty: sliver that nothing (min size 1..100, but small) can use
    }

    // Tight fit reward: ratio of item to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless residuals are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win.
        score += 12.0;
        // But if the item is large relative to mean residual, opening fresh may be better.
        let tightness = mean_residual / bin_capacity as f64;
        if item_size as f64 > mean_residual * 0.9 {
            score -= 20.0;
        }
        if tightness < 0.25 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: if next item would fit in post_residual, reward; if next item
    // is large and post_residual is small, penalize stranding capacity.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 6.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size as f64 - post_residual as f64).min(15.0) * 0.4;
        }
    }

    // Global state: many open bins with high mean residual -> consolidate, avoid new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dispersion = (mean_residual - bin_residual as f64).abs();
    score += dispersion * 0.15;

    // Late in the stream, favor closing out bins (reduce open count pressure).
    score += progress * (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Mild preference for filling bins with larger residuals early (keep small-residual
    // bins for small items later).
    if !is_new_bin {
        score -= (bin_residual as f64 - item_size as f64).max(0.0) * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post_residual (tight packing), smoothed polynomial.
    let mut score = post;

    // Non-linear coupling: tight fits matter more as the stream progresses.
    let tightness = 1.0 - (post / cap);
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let waste = (nxt - post) / cap;
            score += 60.0 * waste * waste * (1.0 + progress);
        } else {
            // Reward residuals that exactly accommodate the next item.
            let gap = (post - nxt) / cap;
            score -= 25.0 * (1.0 - gap) * (1.0 - gap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 + 20.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin, more so late in the stream
    // or when many bins are open with slack mean residual.
    if bin_residual == bin_capacity {
        let slack = (mean_residual / cap).max(0.0);
        score += 45.0 + 30.0 * progress + 15.0 * slack;
    }

    // Mild penalty for leaving residuals in a "bad zone" (too small for typical items),
    // modeled as a smooth bump around small residuals.
    let r = post / cap;
    score += 12.0 * (-((r - 0.05) * (r - 0.05)) / 0.005).exp() * (1.0 - progress);

    // Slight preference for bins whose residual deviates below the mean (consolidating slack).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins partitioned by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Modulo-class logic: residuals in classes that commonly pair with
    // mid-size items (multiples of 10, 20, 25) are more reusable.
    let m10 = post_residual % 10 == 0;
    let m20 = post_residual % 20 == 0;
    let m25 = post_residual % 25 == 0;
    if m10 { score -= 8.0; }
    if m20 { score -= 6.0; }
    if m25 { score -= 6.0; }

    // Dead-space penalty: residuals in awkward harmonic classes
    // (1..9 mod 10 with small values) are hard to fill.
    let rmod = post_residual % 10;
    if post_residual > 0 && rmod >= 1 && rmod <= 4 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // Next item won't fit here; slight penalty proportional to gap class.
            let gap = next_item_size - post_residual;
            score += (gap % 10) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Fractional thresholds on post_residual relative to capacity.
    if frac < 0.05 {
        score -= 25.0;
    } else if frac > 0.5 {
        // Large leftover: less urgent to fill precisely, mild penalty
        // so tight bins get priority.
        score += 10.0 * (frac - 0.5);
    }

    // Stream progression: late in the stream, consolidation matters more;
    // early on, be slightly more willing to spread items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - frac);

    // Mean residual coupling: when mean residual is low, preserve big
    // residual bins; when high, prefer filling the emptiest-feeling bins.
    score += 0.05 * (mean_residual - pr);

    // New-bin candidate: penalize opening a new bin unless existing bins
    // would leave very awkward residuals.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If next item is large and current item is small, new bin is OK.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone = 15.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 3.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins that can also host the lookahead item in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        // Leftover too small for next item: mild dead-space penalty.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    } else {
        // Favor filling already-open bins; slightly prefer bins below mean residual (emptier).
        score += 0.1 * open_bins_count as f64;
        if (bin_residual as f64) < mean_residual {
            score += 3.0;
        } else {
            score -= 2.0;
        }
    }

    // Early in stream: keep bins flexible (avoid committing to tight fits too early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && post_residual > 0 {
        score += 5.0 * (1.0 - progress / 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: baseline score, penalize opening a new bin unless
    // the current item is large and would leave very poor fits elsewhere.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 1.05; // slightly worse than a perfect fit anywhere
        // Encourage new bin for items that leave a large awkward residual in others
        let tight_fit_bonus = (item_size as f64 / bin_capacity as f64).powi(3) * 30.0;
        score -= tight_fit_bonus;
        // If many bins fit the item, opening a new bin is wasteful
        score += (fitting_bins_count as f64).min(8.0) * 4.0;
        // Late in the stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        return score;
    }

    // Reward tight fits: small post_residual is good (already base score).
    // 2-step lookahead: reward if the NEXT item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward decays with leftover slack after the lookahead item
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item does NOT fit: post_residual is likely dead space,
            // penalize proportionally to how much it exceeds the next item
            let excess = (next_item_size - post_residual) as f64;
            score += excess * 0.35;
        }
    } else {
        // Last item: minimize residual directly (base score handles it).
        score -= 5.0;
    }

    // Penalize creating residual that is below the minimum item size (dead space)
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item.max(0.0) + 0.0 && post_residual > 0 {
        // tiny residual is fine actually (nearly full bin) — small reward
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Coupling with mean residual: prefer bins below the mean residual
    // (fill emptier-but-fitting bins keeps a pool of tight bins for small items)
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    // Mild penalty for very large leftover residuals relative to capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score += (frac - 0.5) * 20.0;
    }

    // Progress-aware consolidation: later in stream, tighten packing
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - frac) * progress * 10.0;

    // Discourage spreading across too many open bins when few fitting options exist
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * (frac * 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on leftover space
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize wasting a large residual on a small item when many bins fit the item
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // even better: next item nearly fills the remainder
            let gap = post_residual as f64 - next_item_size as f64;
            if gap < 10.0 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here; penalize leaving awkward residual
            score += 5.0;
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // existing residuals are poor fits or the item is large
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 45.0;
        // attractive when item is large (hard to place later)
        score -= (item_size as f64 / 100.0) * 40.0;
        // attractive when few bins fit the item (placement pressure)
        score -= (fitting_bins_count as f64) * 8.0;
        // attractive when open bins have low mean residual (little room anywhere)
        score += (mean_residual / 100.0) * 30.0 - 30.0;
        // early in stream, more willing to open bins (long horizon to fill them)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 15.0;
        // if many open bins, discourage spreading
        score += (open_bins_count as f64).sqrt() * 3.0;
    }

    // Global state: when mean residual is high, prefer bins with residual above mean
    // (consolidate space into fewer bins)
    if bin_residual < bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score -= diff * 0.15;
    }

    // Time horizon: late in the stream, avoid leaving any residual at all
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: quadratic reward for tight fits (low post_residual)
    let mut score = post * (1.0 + 0.02 * post / 10.0);

    // Dead-space penalty: residuals too small for the smallest item are wasted
    let dead = if post > 0 && post < 10 { (10.0 - post) * 2.0 } else { 0.0 };
    score += dead;

    // Smooth non-linear coupling with stream progress:
    // early on, tolerate loose fits (spread items); late, push tight packing.
    let progress_coupling = 40.0 * progress * (1.0 - norm_post) * (1.0 - norm_post)
        - 20.0 * (1.0 - progress) * norm_post;
    score -= progress_coupling;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Many open bins: encourage filling existing ones rather than spreading
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_post);

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        if post >= next_item_size as f64 {
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            score += 5.0 * (gap / cap);
        }
    }

    // New-bin candidate: penalize opening a new bin unless residual is large
    // relative to mean residual of open bins (smooth soft threshold).
    if bin_residual == bin_capacity {
        let mean_nz = if mean_residual > 0.0 { mean_residual } else { cap };
        let spread = (norm_post * cap - mean_nz) / cap;
        score += 25.0 - 10.0 * (spread.max(0.0) + 0.5 * progress);
    }

    // Mean-residual alignment: prefer bins whose residual matches the average
    score += 0.1 * (norm_post * cap - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quantize post_residual into buckets
    // Small residuals are "dead space" — penalize by class, not linearly.
    let class = post_residual / 10; // 0..=10 harmonic class
    match class {
        0 => score -= 8.0,               // near-perfect fill
        1 => score -= 4.0,               // excellent
        2 => score -= 1.5,
        3 => score += 1.0,
        4 => score += 2.5,               // awkward zone (40-50 free)
        5 => score += 3.0,
        6 => score += 1.5,
        _ => {}                          // large residual: neutral, item was small
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can follow here: strong reward, scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 6.0 - (tight / 20.0).min(4.0);
        } else if next_item_size <= bin_residual {
            // Next fits only before placement (weird ordering) — slight penalty
            score += 1.0;
        } else {
            // Next item cannot use this bin either way; residual value drops
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should win only when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = (bin_capacity as f64) * 0.9;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin is flexible for the future
        }
        if fitting_bins_count == 0 {
            score -= (bin_capacity as f64) * 0.9; // forced: must open
        } else if fitting_bins_count == 1 {
            // An existing last-chance bin should usually win instead.
            score += 2.0;
        }
    }

    // Discourage spreading items thin across many open bins when residuals
    // are already fragmented.
    if open_bins_count > 2 {
        let frag = ((mean_residual - post_residual as f64).abs()) / 10.0;
        score += frag.min(3.0);
    }

    // Mild late-stream tightening: near the end, prefer filling bins fully.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 * (class as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (< 10) are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps below the minimum item size are pure waste; gap of 0 is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize gaps that cannot fit the lookahead item (k=2) if they could otherwise be used.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0; // reward leaving room for the next item
    }

    // Last-chance bin: strongly favor using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by pressure of too many open bins.
        score += 70.0 - 3.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin can absorb the next item too
        }
    }

    // Open-bin pressure: with many open bins, prefer tighter packing.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below the mean residual (tighter bins).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 * 0.4);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if the next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item completion
        } else if next_item_size < post_residual {
            // Next item fits: reward proportionally to how much it fills the remaining space.
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - fill_after / bin_capacity as f64);
        } else {
            // Next item does NOT fit here: penalize wasted potential.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * gap;
        }
    } else {
        // Last item: just minimize post_residual (already base).
    }

    // Coupling with mean residual: bins with residual far below mean are "tight" —
    // reward using them to keep loose bins flexible.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.4 * (mean_residual - residual_f);
    } else {
        score += 0.2 * (residual_f - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., many fitting bins means we should use an existing one).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 15.0; // must open a bin anyway
        } else {
            // Discourage opening a new bin when alternatives exist,
            // unless the item is large and current bins would leave big dead space.
            let waste_elsewhere = 5.0;
            score += waste_elsewhere + 0.3 * open_bins_count as f64;
            // If the item is huge, a fresh bin may be the only sensible home.
            if item_size >= 70 {
                score -= 20.0;
            }
        }
    }

    // Mild stream-progression pressure: later in the stream, consolidate more aggressively.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact fit: massive reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // Dead space below minimum item size is nearly unusable.
        score += 6.0;
    }

    // Penalize leaving residual that the next item cannot use (lookahead).
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += 4.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
        } else if (post_residual as u32) == next_item_size {
            // Perfect chain: leave exactly enough for next item.
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 10.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // High mean residual across bins: encourage filling laggards.
    if bin_residual as f64 > mean_residual {
        score -= 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Late in the stream: tighten packing, avoid new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // New-bin candidate: penalize moderately, but allow it when item is large
    // relative to available fitting options or current bin is too full.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let poor_fit = post_residual as f64 > 0.0 && post_residual < 20;
        let mut penalty = 8.0 + 10.0 * (1.0 - progress);
        if big_item > 0.6 { penalty -= 6.0; }
        if poor_fit { penalty -= 9.0; }
        if fitting_bins_count == 0 { penalty = -5.0; }
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post residual (tight fit), normalized
    let mut score = pr / cap;

    // Dead-space penalty: residuals that are too small for typical items are wasted.
    // Smooth quadratic dead-space term peaking for very small nonzero residuals.
    let dead = (1.0 - pr / cap).max(0.0);
    if pr > 0.0 {
        score += 0.35 * dead * dead * (1.0 - pr / (cap * 0.5)).abs().min(1.0);
    }

    // Reward tight fits more strongly as stream progresses (consolidate early, preserve flexibility early).
    score -= 0.6 * (1.0 - pr / cap) * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits exactly into post_residual, reward; if it nearly fits, slight penalty.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - ((pr - next_item_size as f64) / cap);
        score -= 0.45 * fit_quality * (1.0 - progress);
    } else if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 0.25 * gap * gap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 0.8;
    }

    // Many open bins: mild penalty to encourage consolidation.
    score += 0.02 * (open_bins_count as f64).powf(1.2) * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual is near/below mean (consolidation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.15 * dev * dev;

    // New empty bin candidate: penalize unless it would otherwise be necessary.
    if bin_residual == bin_capacity {
        score += 1.2 - 0.4 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: classify dead space into
    // coarse buckets via integer division on post_residual.
    let pr = post_residual;
    let class = pr / 10; // 0..=10 harmonic class
    // Penalize residuals that are "just barely unusable" (dead zones).
    let dead_penalty: f64 = match class {
        0 => -20.0,                    // near-perfect fit
        1 => -6.0,                     // small gap, still flexible
        2 | 3 => 4.0,                  // awkward mid gap
        4 | 5 => 8.0,                  // dead zone: too small for medium items
        6 | 7 => 2.0,                  // moderate gap, recoverable
        _ => 0.0,                      // large residual, fine
    };
    score += dead_penalty;

    // Reward exact or near-exact fits more strongly.
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 5 {
        score -= 15.0;
    }

    // Tightness ratio coupling: prefer bins where item fills a large fraction.
    let fill = item_size as f64 / cap;
    score -= 12.0 * fill;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if pr <= 10 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0;
            // Extra reward if next item exactly consumes remaining space.
            if next_item_size == pr {
                score -= 12.0;
            }
        } else {
            // Next item won't fit here: penalize leaving a gap just below it.
            let gap = pr as f64;
            if gap > 0.0 && (next_item_size as f64 - gap) < 10.0 {
                score += 6.0;
            }
        }
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Baseline neutral score ~ capacity; open a new bin only when existing
        // bins offer bad fits (high scores) or bins are numerous relative to need.
        score = cap * 0.9;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins are open, discourage more bins.
        score += (open_bins_count as f64).sqrt() * 2.0;
        // Large items relative to mean residual: new bin may be wise.
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "dense"; finishing it is good.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= (dev / cap).min(1.0) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below 10 are unusable for future items
    // (min item size 10), so penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (10.0 - post_residual as f64) * 2.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to current residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: slightly above a perfect fit,
        // scaled by pressure so it only wins when fits are poor.
        score = bin_capacity as f64 + open_bins_count as f64 * 3.0
            - (mean_residual / bin_capacity as f64) * 5.0;
        // If the next item is large, an empty bin is valuable.
        if next_item_size > 50 {
            score -= 10.0;
        }
    } else {
        // Many open bins with high mean residual: favor consolidating into
        // existing bins rather than spreading.
        score += open_bins_count as f64 * 0.5;
    }

    // Lookahead coupling: if this placement leaves room exactly (or nearly)
    // for the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always excellent
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            score -= 500.0; // perfect two-item fill
        } else if post_residual as u32 > next_item_size {
            // next item fits: reward closeness of resulting residual to 0
            score -= 120.0 * (1.0 - diff / bin_capacity as f64);
            // extra reward if the chain nearly empties the bin
            let chain_residual = post_residual as f64 - nxt;
            if chain_residual <= 10.0 {
                score -= 80.0 * (1.0 - chain_residual / 10.0);
            }
        } else {
            // next item does NOT fit this bin after placement:
            // penalize leaving a dead pocket smaller than typical items
            score += 60.0 * (1.0 - post_residual as f64 / 100.0);
        }
    }

    // Compare post_residual relative to mean residual of open bins:
    // prefer bins that consume more slack than average.
    score -= 1.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin
        score += 90.0;
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * progress;
        // if several bins fit, opening new bin is wasteful
        if fitting_bins_count > 1 {
            score += 150.0;
        }
        // if this is the only fitting option (only new bin fits), it's fine
        if fitting_bins_count <= 1 {
            score -= 160.0;
        }
        // lookahead: new bin leaves huge residual that fits next item trivially; neutral
    }

    // Mild preference for tighter bins overall
    score += 0.3 * (bin_residual as f64 - post_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward: strongly favor bins that get filled exactly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small dead space quadratically: waste < 15 is costly.
        let waste = post_residual as f64;
        if waste < 15.0 {
            score += (15.0 - waste) * (15.0 - waste) * 0.4;
        }
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
        // Extra reward if next item fills the remainder almost exactly.
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 10.0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving a sliver that nothing can use.
        score += 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: residual == capacity means empty bin.
    // Base penalty for opening a new bin; reduced when current fit is bad
    // or many bins are open (fragmentation already high).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0;
        // If the item fits poorly in existing bins, opening a new bin is cheaper.
        let fit_quality = item_size as f64 / bin_capacity as f64;
        if fit_quality < 0.35 {
            new_bin_penalty -= 12.0;
        }
        // Late in the stream, avoid opening bins for marginal gains.
        new_bin_penalty += progress * 10.0;
        // If many bins are open, prefer consolidating into them.
        if open_bins_count > 4 {
            new_bin_penalty += (open_bins_count.min(20) as f64) * 1.5;
        }
        score += new_bin_penalty;
    }

    // Global state coupling: prefer bins below mean residual when mean is high
    // (rebalance fragmentation), prefer above-mean bins when mean is low.
    if mean_residual > 0.0 {
        let dev = bin_residual as f64 - mean_residual;
        if mean_residual > bin_capacity as f64 * 0.5 {
            score -= dev * 0.15;
        } else {
            score += dev * 0.15;
        }
    }

    // Mild preference for larger residuals early (keep big spaces flexible),
    // tighter consolidation later.
    score += (1.0 - progress) * (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let n_bins = open_bins_count as f64;

    // Base: prefer tight fits (low post residual), with smooth polynomial shaping
    let mut score = pr;

    // Non-linear coupling: quadratic + quartic reward for very small post residual
    score -= 60.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 25.0 * norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Stream progress interaction: late in the stream, tighten further (smooth)
    let late = progress * progress;
    score -= 40.0 * late * (1.0 - norm_pr);
    score += 30.0 * progress * norm_pr * norm_pr;

    // Penalize dead space relative to mean residual (smooth coupling)
    let dev = (pr - mean_residual) / cap;
    score += 20.0 * dev * dev.abs();

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 75.0 * (1.0 - norm_pr);
    } else {
        score += 8.0 * (fit - 1.0).ln().max(0.0);
    }

    // Lookahead: reward leaving space for the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        let slack = ((pr - nx) / cap).max(0.0);
        score -= 45.0 * fit_next * (1.0 - slack * slack) * (1.0 - late * 0.5);
        score += 15.0 * (1.0 - fit_next) * progress;
    }

    // Mild penalty for spreading across many open bins when residual is large
    score += 0.5 * n_bins * norm_pr * progress;

    // Penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = (pr / cap) - (1.0 - item_size as f64 / cap); // = 0 when item fits perfectly
        score += 55.0 - 50.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
        score += 10.0 * fit * (1.0 - poor_fit.abs().min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of 10 are
    // "usable" slots for typical item sizes; others create dead space.
    let r = post_residual;
    let class = r % 10;
    let class_penalty = match class {
        0 => -30.0,
        1 | 9 => 6.0,
        2 | 8 => 3.0,
        3 | 7 => 1.0,
        4 | 6 => 4.0,
        _ => 8.0,
    };
    score += class_penalty;

    // Integer-division threshold: post_residual in [0,10) is a near-perfect fill.
    if r < 10 {
        score -= 25.0;
    } else if r < 20 {
        score -= 8.0;
    } else if r > 60 {
        score += 5.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly
    // or lands in a good harmonic class.
    if next_item_size > 0 {
        if next_item_size <= r {
            let gap = r - next_item_size;
            if gap % 10 == 0 {
                score -= 20.0;
            } else if gap <= 5 {
                score -= 10.0;
            } else {
                score += (gap as f64) * 0.15;
            }
        } else {
            // next item can't use this bin's remainder anyway
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor filling it rather than opening new.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when it beats
    // wasting space in an existing bin.
    if bin_residual == bin_capacity {
        // neutral baseline; slight penalty so tight existing fits win
        score += 12.0;
        if item_size >= 60 {
            score -= 6.0;
        }
    } else {
        // reward tight fits in existing bins relative to mean residual
        if (post_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Stream progression: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Penalize leaving residues that few future items can use (small odd gaps).
    if r >= 1 && r <= 9 && r % 2 == 1 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 100.0;
    } else if post_residual >= 30 {
        // Large leftover remains flexible; mild reward.
        score -= 6.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good alternatives exist
    // or many bins are already open (open-bin pressure).
    if bin_residual == bin_capacity {
        score += 40.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // If next item is large, a fresh bin may still be useful later; soften penalty slightly.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += 0.15 * open_bins_count as f64;

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 30.0;
    }
    // If next item cannot fit in the post-residual, slightly penalize wasting flexibility.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Stream progression: later in the stream, prefer closing bins tightly (dead space matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small dead space (unusable slivers)
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward tight chain
            let two_left = post_residual - next_item_size;
            score -= 10.0 - (two_left as f64).min(10.0);
            if two_left == 0 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here after placing: penalize relative gap
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / cap) * 20.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.15;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when item is large
    // relative to residual and opening fresh space may serve future items.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // opening a new bin leaves post_residual = cap - item; prefer it when
        // item is large (poor fit anywhere) and many bins already open
        score = 45.0 - frac * 30.0 + (open_bins_count as f64).min(20.0) * 0.5;
        if next_item_size > 0 && (next_item_size as f64) >= post_residual as f64 {
            // next item also large: fresh bin more attractive
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    } else {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more strongly as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity as f64 - post_residual as f64) * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: prefer leaving room for the next item when possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size {
            // this bin could have taken next item but won't after this placement
            score += 6.0;
        }
        // If next item exactly matches post_residual, big reward.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: empty bin gets a base offset so we only open
    // new bins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0 + 30.0 * (1.0 - progress);
        // Opening a bin early is cheaper when few bins are open.
        score -= open_bins_count as f64 * 1.5;
        // If the item is large relative to capacity and mean residual is low,
        // opening a new bin is more attractive.
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * frac * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 10.0;
        }
    } else {
        // Prefer filling more-full bins (best-fit flavor) with nonlinearity.
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * fill * fill;
        // Slight penalty when many bins are open and this fit is loose.
        if post_residual as f64 > mean_residual {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Smooth base: reward tight fits (low post_residual)
    let mut score = post * (1.0 + 0.35 * post_norm * post_norm);

    // Non-linear coupling of post_residual with stream progress:
    // early on tolerate slack; late in stream penalize residual more sharply
    let progress_coupling = 1.0 + 0.9 * progress * progress + 0.6 * progress * post_norm;
    score += post * 0.25 * progress_coupling;

    // Smooth polynomial penalty for dead space relative to mean residual state
    let mean_gap = post - mean_residual;
    score += 0.15 * mean_gap * mean_gap / (cap * cap) * (1.0 + progress);

    // Last-chance bonus: smooth reward when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 6.0 * (1.0 - post_norm) * (1.0 - post_norm);
    } else {
        score += 0.8 * (fitting_bins_count as f64).ln() * post_norm;
    }

    // Lookahead: smooth reward if next item fits into post_residual
    if next_item_size > 0 {
        let next_fit = (post_residual as f64 - next_item_size as f64).max(0.0) / cap;
        let usable = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= 4.0 * usable * (1.0 - next_fit) * (1.0 + 0.5 * progress);
    }

    // Mild penalty on crowded bin landscape, smoothed by fill ratio
    score += 0.05 * (open_bins_count as f64) * fit_ratio * post_norm;

    // New-bin candidate handling: empty bin gets neutral-ish score that
    // becomes attractive only when the item fits poorly everywhere
    if bin_residual == bin_capacity {
        score = cap * (1.0 - fit_ratio) * (1.0 + 0.3 * progress) + 2.0;
        if fitting_bins_count <= 1 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let pr = post_residual as u32;
    let class = pr % 10;
    let fifth = (pr * 5) / bin_capacity; // 0..=5 capacity-fifth bucket

    // Reward residuals that belong to "useful" harmonic classes (multiples of 5, 10, 25, 50)
    let harmonic_bonus = match pr {
        0 => 60.0,                    // perfect fit is best
        x if x % 50 == 0 => 40.0,
        x if x % 25 == 0 => 30.0,
        x if x % 10 == 0 => 22.0,
        x if x % 5 == 0 => 12.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Small dead space is penalized quadratically (unusable slivers)
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * (10 - pr) as f64 * 0.6;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if (pr as u32) >= next_item_size {
            score -= 18.0 + (next_item_size as f64) * 0.25;
        } else {
            // dead space unless next item is small enough later
            score += (next_item_size - pr) as f64 * 0.35;
        }
    } else {
        // last item: prefer tightest fill
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tightness = (item_size as f64) / cap;
        // base penalty for opening a new bin
        score += 45.0;
        // relax penalty under pressure or for big items that would leave tiny slivers elsewhere
        score -= pressure * 70.0;
        if fitting_bins_count > 0 {
            let best_possible = mean_residual;
            if (best_possible - item_size as f64) < 8.0 {
                score -= 30.0; // existing bins would leave near-perfect fits anyway
            }
        }
        score -= tightness * 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Late-stream consolidation: as stream progresses, avoid spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (open_bins_count as f64) * 0.05 * (fifth as f64);

    // Fifth-bucket tiebreak: finer granularity within class
    score += fifth as f64 * 0.4 + class as f64 * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bonus: only one bin fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Prefer bins that can also hold the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, favor filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.6 + 0.4 * progress);
    score += pressure * 0.8;

    // New-bin candidate calibration: neutral-ish score, penalized when
    // open bins are few, rewarded when mean residual is fragmented/high.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.9
            + open_bins_count as f64 * 1.5
            - mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let pr = post_residual as f64;
    let nx = next_item_size as f64;

    // Relative-to-mean residual alignment: prefer bins whose post-placement
    // residual sits below the open-bin average, preserving larger cavities
    // for larger future items.
    score += 0.30 * (pr - mean_residual);

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step match: the next item exactly fills this bin.
            // Strong reward so we sacrifice a loose current fit to set up
            // an exact future fill.
            score -= 60.0 + 0.5 * nx;
        } else if next_item_size as u32 <= post_residual {
            // Next item still fits here: favor this bin, with a mild
            // penalty on the second-order leftover.
            let leftover2 = pr - nx;
            score -= 10.0 + 0.15 * leftover2;
        } else {
            // Next item cannot use this leftover: dead-space penalty
            // scaled by how much space is stranded.
            score += 4.0 + 0.25 * pr;
        }
    }

    // Last-chance bin: this is the only open bin that can host the item,
    // so declining it forces a new bin. Favor using it (unless it is the
    // brand-new-bin candidate itself).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0;
    }

    // New-bin candidate penalty: opening a bin fragments capacity.
    // Penalize progressively as the stream advances (fewer chances to
    // recover stranded space) and as more bins are already open.
    if is_new_bin {
        score += 3.0 + 8.0 * progress + 0.10 * open_bins_count as f64;
        // Never open a bin for the final item if any open bin can fit it.
        if next_item_size == 0 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: tight fit reward (post_residual already encodes waste).

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving space that still fits the next item,
    // penalize residual that is too small to be useful for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space relative to lookahead: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // New-bin candidate handling: empty bin gets a moderate default score;
    // it should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Penalize opening new bins early / when few bins exist.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;

        // But if the current item is large relative to mean residual, new bin is attractive.
        if (item_size as f64) > mean_residual {
            score -= 25.0;
        }
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 2 {
            score += 10.0 * fitting_bins_count as f64;
        }
    } else {
        // Prefer fuller bins: reward low residual relative to mean.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Mild preference for bins that are mostly full already.
        let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * fill_ratio;
    }

    // Late-stream pressure: consolidate more aggressively as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity;

    // Base: prefer small post-residual, with non-linear sharpening.
    let mut score = post + 0.35 * (post * post) / cap;

    // Tight-fit reward: coupling of post_residual with item fraction.
    let fill = item_size as f64 / cap;
    score -= 12.0 * fill * (1.0 - post / cap).powi(2);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: usually penalized, less so late in stream or with big item.
    if is_new_bin {
        score += 25.0 - 15.0 * progress;
        // If lookahead won't fit typical residual, opening a fresh bin is more attractive.
        let nxt = next_item_size as f64;
        if nxt > 0.0 && nxt > post {
            score -= 10.0;
        }
        // Fewer open bins -> cheaper to open new bin.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    } else {
        // Reward spreading load when mean residual is high relative to this bin.
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 4.0 * dev;
    }

    // Lookahead synergy: if next item fits this bin's post-residual, reward.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 6.0 * (next_item_size as f64 / cap);
    }

    // Smooth stream-progress coupling: late stream tolerates tighter residuals.
    score -= 8.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: heavily favor bins with small post_residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.9;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    let cap = bin_capacity as u32;
    let pr = post_residual;
    // Dead-space penalty grows sharply for unusable slivers (<10, min item size).
    if pr < 10 && pr > 0 {
        score += 45.0;
    }
    // Harmonic buckets: perfect halves/quarters/thirds of capacity are valuable.
    if pr == cap / 2 {
        score -= 12.0;
    } else if pr == cap / 4 || pr == cap / 3 {
        score -= 8.0;
    } else if pr % 10 == 0 {
        score -= 3.0; // round residuals pair well with decimal item sizes
    } else if pr % 5 == 0 {
        score -= 1.0;
    } else {
        score += 2.0; // awkward non-round residual
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0;
        } else if slack < 10 {
            score -= 18.0;
        } else {
            score -= (10.0 - slack.min(10) as f64) * 0.5;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Bin becomes dead space and next item can't use it either.
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are
    // crowded or the fit here is terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // Cheaper to open new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
        // If many bins already open and mean residual is low, opening is fine.
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        if mean_residual < 15.0 {
            score -= 25.0;
        }
        // If the next item is huge, a fresh bin is attractive.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Prefer filling bins that are already relatively full (small residual).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.15;

    // Slight penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable gaps: dead space that likely can't fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (post_residual small relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
        score -= 80.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        // residual too small for next item: mild penalty for stranding space
        score += 12.0;
    }

    // New-bin candidate handling: empty bin has post_residual = capacity - item.
    // Make it attractive only when no good fit exists; add a fixed opening cost
    // that tight fits and last-chance bonuses can overcome.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening a new bin is worse when many bins are already open.
        score += 0.3 * open_bins_count as f64;
        // But attractive late in the stream if residuals are fragmented.
        if mean_residual < 25.0 && open_bins_count > 2 {
            score -= 20.0;
        }
    }

    // Slight early-stream preference for keeping bins balanced.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect 2-step fit bonus
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size > post_residual {
            // next item cannot follow here; mild penalty proportional to leftover
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer tightest fill
        score -= 30.0;
    }

    // Penalize post_residual far above mean residual (wasteful slack relative to fleet)
    score += 0.6 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        // worse to open new bin when other bins fit
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        // opening a new bin is better late in the stream when bins are fragmented
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score -= 5.0;
        }
        // big item relative to residual mean: fresh bin is fine
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() < 5 {
            score -= 20.0;
        }
    }

    // slight tie-break: prefer bins with less residual before placement (tighter bins)
    score += 0.1 * bin_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly: post_residual close to 0 is good.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize small but unusable dead space (post_residual < 10 can never fit anything).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size > bin_residual {
        // Next item won't fit here anyway; less pressure to preserve space.
        score -= 2.0;
    }

    // Penalize opening a new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            let best_alt = (bin_capacity as f64 - item_size as f64).abs();
            10.0 * (1.0 - best_alt / bin_capacity as f64)
        };
        // New bin is attractive only if item is large relative to capacity or no good fit exists.
        score += 14.0 - 0.15 * item_size as f64 + pressure;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
        // Many open bins with large mean residual: better to fill those.
        score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Slight preference for bins below mean residual (balancing residual distribution).
    if bin_residual < bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let tightness = 1.0 - (pr / bin_capacity as f64);

    let mut score = pr;

    // Smooth non-linear coupling: reward tight fits more as stream progresses
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that is too small for plausible future items (smooth gate)
    let dead = (pr - next_item_size as f64).max(0.0) / bin_capacity as f64;
    score += 8.0 * (1.0 - (-pr * 0.12).exp()) * (1.0 - dead);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 15.0 * progress;
    }

    // Prefer bins below mean residual (less crowded) mildly
    score += 0.05 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize so it's chosen only when no open bin fits well
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 10.0 - 20.0 * (fitting_bins_count == 0) as i32 as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, reward
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: penalize leftover space non-linearly (dead space quadratically).
    score += (post_residual as f64) * (post_residual as f64) / cap * 0.05;

    // Perfect fit bonus (post_residual == 0) strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic class of post_residual: residues mod 10 that are hard to fill later.
    let res_class = post_residual % 10;
    if post_residual > 0 {
        // Small awkward residues (1..=5) are dead space; larger residues (>=10) reusable.
        if res_class >= 1 && res_class <= 5 && post_residual < 10 {
            score += 8.0;
        }
        if post_residual >= 10 {
            score -= 3.0; // residual still large enough to host typical items
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Exact chain fit: post_residual == next_item_size gives perfect fill next step.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual cannot host next item: penalize proportionally to how close it was.
        let gap = (next_item_size - post_residual) as f64;
        if gap < 10.0 {
            score += gap * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate logic: only attractive when current bin would leave bad residue
    // or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base new-bin score: neutral-ish, scaled by stream progress.
        score = cap * 0.6;
        // Attractive if mean residual of open bins is small (bins nearly exhausted).
        score -= (mean_residual / cap) * 20.0;
        // Early in stream: prefer consolidation into open bins.
        score += (1.0 - progress) * 15.0;
        // If many open bins, opening a new one is fine.
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
        // If lookahead item is large, a fresh bin is useful.
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    // Mild penalty for placing into bins with much larger residual than needed (waste aversion).
    let waste_ratio = (bin_residual - item_size) as f64 / cap;
    score += waste_ratio * 2.0;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: very small post_residual is excellent.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead space penalty: gaps too small to ever hold an item (min size 1..100 unknown,
    // so treat gaps below a conservative threshold as wasted, scaled by how dead they are).
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }

    // Penalize gaps that cannot fit the next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward keeping room for the next item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size).min(30) as f64 * 0.5;
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it over opening new.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // but allow it when many bins are open (consolidation phase).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 - 0.4 * progress);

    // New-bin candidate: penalize mildly so it's only chosen when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if next item is large and mean residual is tiny, opening fresh is fine.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 45.0;
        }
    }

    // Slight preference for bins with residual close to item size (best-fit shaping).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Two-step lookahead: exact match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chain of two perfect fits
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to how snugly it lands
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 120.0 - slack_after_next * 1.5;
        } else {
            // dead space: next item cannot use the leftover
            score += (post_residual as f64) * 0.8 + 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize new-bin candidate mildly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 90.0;
        // Opening a new bin is attractive only if mean residual across open bins is already low.
        score -= (mean_residual - 30.0).max(0.0) * 1.2;
    }

    // Prefer bins tighter than the average residual (good fits cluster).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight late-stream pressure to consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by fill fraction.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 20.0 * (1.0 - fill_ratio);

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Near-perfect fit: residual below minimum item size is dead space anyway.
        score -= 30.0;
    } else {
        // Dead-space penalty grows when residual becomes unusable for typical items.
        score += (post_residual as f64).powf(1.4) * 0.15;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if post_residual tightly matches next item.
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 8.0;
            }
        } else {
            // Penalize leaving a gap just below the next item's size (wasted opportunity).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 10.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many options, mild preference for tighter bins is already covered.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin should only win when open bins offer bad fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // Cheaper to open a new bin early in the stream (more items to amortize),
        // or when many open bins are already fragmented.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can host next item fully — mild discount.
            score -= 5.0;
        }
        // If the only alternative is poor (item barely fits nowhere else), new bin less penalized.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Placing into an existing bin keeps bin count down; small structural bonus.
        score -= 5.0;
        // Prefer bins with below-average residual (consolidate fragmentation).
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3;
    }

    // Late-stream urgency: avoid opening bins when near the end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (open_bins_count as f64).powf(0.5) * 0.1;

    // Mild noise-free tie-break by residual parity structure: prefer residuals
    // that are multiples of 5 (common item sizes make these reusable).
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Core: prefer minimal post residual, with non-linear sharpening
    let mut score = post + 0.35 * (post * post) / cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Dead-space penalty: post residual that can't fit typical future items
    if post < 10.0 {
        score += 6.0 * (10.0 - post) / 10.0; // near-full is fine, mild
    } else if post < 30.0 {
        // awkward gap zone
        score += 4.0 * (1.0 - (post - 10.0) / 20.0);
    }

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 5.0 * (1.0 - (post - nx) / cap);
        } else {
            score += 3.0 * ((nx - post) / cap);
        }
    }

    // Last chance: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // spread penalty: prefer bins with more competition resolved by tightness
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Prefer bins below mean residual (keeps balance, saves large residuals)
    score += 0.08 * (post - mean_residual).max(0.0);

    // New-bin candidate: only attractive when stream is early or current bins are bad fits
    let is_new_bin = bin_residual == bin_capacity && post == bin_residual as f64 - item_size as f64 && bin_residual as f64 == cap;
    if is_new_bin {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = cap - post; // baseline = full empty residual
        score += 8.0 + 3.0 * open_pressure * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 20.0; // must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "usable" for
    // typical small items (multiples of 10 classes) are rewarded.
    let post = post_residual;
    let class = post % 10;
    let harmonic_bonus = match class {
        0 => 6.0,               // perfectly harmonic residual
        1 | 9 => 3.0,
        2 | 8 => 2.0,
        3 | 7 => 1.0,
        4 | 6 => 0.5,
        _ => -1.5,              // residue 5 is the worst dead-space class
    };
    score -= harmonic_bonus;

    // Integer-division threshold: residuals in [50, 100) can host half-capacity
    // items; residuals < 20 are near-dead. Penalize creating tiny leftovers.
    if post < 20 {
        score += 4.0 * (20 - post) as f64 / 20.0;
    }
    if post >= 50 {
        score -= 2.0;
    }

    // Lookahead coupling: reward if the next item fits exactly / well in the
    // post-residual (harmonic pairing), penalize if next item won't fit at all.
    if next_item_size > 0 {
        if next_item_size <= post {
            let waste = (post - next_item_size) as f64;
            if waste == 0.0 {
                score -= 8.0; // perfect lookahead fit
            } else if waste <= 10.0 {
                score -= 4.0;
            } else {
                score -= 1.0;
            }
        } else {
            score += 2.0; // next item can't use this bin's remainder
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: default mild penalty so we prefer reusing
    // open bins; relax the penalty when the current fit is bad (large
    // post_residual) or when this bin is the only fitting one.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_ratio = item_size as f64 / cap;
        let mut new_bin_score = 12.0; // base penalty for opening a bin
        if fill_ratio > 0.7 {
            new_bin_score -= 6.0; // big item: fresh bin is fine
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 15.0; // no open bin fits: must open
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            new_bin_score -= 3.0; // pairing potential in a fresh bin
        }
        // Late in the stream, avoid accumulating many open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 4.0 * progress;
        score = score.max(0.0) + new_bin_score;
        return score;
    }

    // Prefer tighter existing bins: reward small bin_residual relative to mean.
    score += (mean_residual - bin_residual as f64).max(-10.0).min(10.0) * 0.2;

    // Slight preference for bins whose residual is in a harmonic class with
    // the item size (item_size and residual share divisibility structure).
    if bin_residual % item_size.max(1) == 0 {
        score -= 1.5;
    }
    if item_size % 10 == 0 && bin_residual % 10 == 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit typical future
    // items (below a "useful threshold") are heavily penalized.
    let useful_threshold = 30.0;
    if (post_residual as f64) < useful_threshold {
        score += (useful_threshold - post_residual as f64) * 3.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // else; otherwise discourage opening a new bin under open-bins pressure.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        // If next item is large and post_residual here would be small,
        // opening a fresh bin is more attractive.
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 + 40.0 {
            score -= 12.0;
        }
    }

    // Lookahead: if next item can exactly use this bin's post_residual,
    // reward keeping this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }

    // Open-bins pressure: mildly penalize placements that keep many bins open
    // with scattered residuals.
    score += open_bins_count as f64 * 0.05;

    // Prefer bins whose residual deviates from the mean in a tight-fit way.
    let fit_quality = (bin_residual as f64 - item_size as f64) - mean_residual;
    if fit_quality < 0.0 {
        score += fit_quality * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post-residual larger than next item: penalize proportionally to leftover gap,
        // since next item could fit but leave more dead space.
        let gap = (post_residual - next_item_size) as f64;
        score += 0.5 * gap;
    }

    // Reward tight fits generally: small post_residual is good.
    score -= 0.3 * (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 10.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Compare post_residual against mean residual: creating below-mean residual
    // is efficient space usage; above-mean residual wastes capacity.
    let diff = post_residual as f64 - mean_residual;
    score += 0.4 * diff;

    // Late in the stream, consolidate: prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when bins exist.
        score += 30.0 + 70.0 * progress + 5.0 * open_bins_count as f64;
        // But if no open bin fits well, allow new bin: soften when next item is big.
        if next_item_size > item_size {
            score -= 40.0;
        }
    }

    // Slight penalty when this bin is nearly empty relative to others (avoid
    // fragmenting fresh bins when older bins can absorb the item).
    if post_residual as f64 > mean_residual + 50.0 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good; amplify sub-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    // (post_residual in awkward range 1..=10 is nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item can use the post_residual,
    // reward this bin strongly; otherwise penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 2.5;
        }
        // Perfect chain: next item exactly fills the bin afterwards
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current item is large
    // and open bins are mostly full (mean residual low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64);
        let pressure = mean_tight * mean_tight * (0.5 + 0.5 * progress);
        // Base penalty so we prefer existing bins unless pressure is high.
        score += 6.0;
        score -= 25.0 * pressure;
        // A new bin is great for very large items relative to capacity.
        score -= 0.15 * item_size as f64;
    }

    // Mild penalty for fragmenting many open bins: keep bin count low early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score += 1.5 * (1.0 - progress) * (open_bins_count as f64).sqrt();
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 60.0 * poly;
    // penalize dead space more as stream progresses
    score += progress * norm_pr * norm_pr * 40.0;
    // reward tight fits (small post_residual) smoothly
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 25.0 * (1.0 - progress);
    // lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 12.0 * (1.0 - ((pr - ns) / cap).abs());
        } else {
            score += 8.0 * ((ns - pr) / cap);
        }
    }
    // last chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (0.5 + progress);
    }
    // many fitting bins: mild penalty to prefer tighter bins
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }
    // mean residual coupling: avoid bins far above/below mean residual
    score += 5.0 * ((pr - mean_residual) / cap).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Harmonic classes: dead-space classes based on post_residual mod 10
    // Items sizes 1..100, capacity 100. Residuals in awkward classes
    // (e.g. 1..9, 11..19) are hard to fill; multiples of 10 are reusable.
    let pr_mod = post_residual % 10;
    if pr_mod == 0 && post_residual > 0 {
        score -= 12.0; // clean class residual, likely reusable
    } else if pr_mod >= 7 {
        score += 6.0; // awkward sliver class
    }

    // Penalize leaving residual that cannot fit the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // keeps future options open
        } else if post_residual > 0 {
            score += 10.0; // dead space for the known next item
        }
    }

    // New-bin candidate handling: opening a bin should be discouraged
    // unless this bin is a last resort or the fit is very poor.
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin
        score += 30.0;
        // If other bins can fit, discourage strongly unless they leave bad fit
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // If this is the only fitting option, opening a new bin is fine
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Late in the stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If mean residual across open bins is large, reuse is better
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Slight preference for bins with less residual among equals
    score += (bin_residual as f64) * 0.05;

    // Mild penalty for very large post_residual creating fragmented space
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.3;
    }

    // Harmonic threshold coupling on next_item_size classes
    if next_item_size > 0 {
        let n_mod = next_item_size % 10;
        if n_mod == 0 && post_residual >= next_item_size {
            score -= 5.0; // next item is round-sized and fits cleanly
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    let dead_zone = 12.0;
    if (post_residual as f64) < dead_zone {
        score += 60.0 * (dead_zone - post_residual as f64) / dead_zone;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the empty-bin candidate gets penalized so it only wins on true dead-space risk.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // Allow a new bin when the item would leave a bad gap everywhere else.
        if (post_residual as f64) < dead_zone && fitting_bins_count >= 1 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Slight preference to fill bins with larger residuals early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * mean_residual * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Post-residual that can still fit the next item is less wasteful.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 * (post_residual as f64 - next_item_size as f64).sqrt();
    } else if post_residual > 0 {
        // Dead space unusable by next item: penalize proportionally.
        score += 0.5 * post_residual as f64;
    }

    // Tight fit reward: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Compare against mean residual: prefer bins with residual close to item
    // (best-fit) and penalize bins far above the mean (hoarding space).
    let diff = bin_residual as f64 - item_size as f64;
    score += 0.3 * (diff - mean_residual).abs();

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are opened only when justified.
        score += 60.0;
        if next_item_size > 0 {
            // A fresh bin perfectly fits the next item: appealing.
            if bin_capacity == next_item_size + item_size {
                score -= 200.0;
            }
            // If current item leaves a residual that matches next item in a
            // fresh bin, opening is great.
            if bin_capacity - item_size == next_item_size {
                score -= 400.0;
            }
        }
        // As stream progresses and many bins are open, discourage more bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Slight preference for filling older bins first (stability).
    if !is_new_bin {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: quadratic penalty on wasted space
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit gets a strong bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Small leftovers are dead space; penalize residuals in the "hard to fill" zone
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            // Post residual too small for next item: penalize more as stream progresses
            score += 6.0 + 10.0 * progress;
        }
        // If next item exactly fills post residual, big reward
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate handling
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        score += 35.0 - 15.0 * progress;
        // But if no open bin can fit, opening is necessary
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Opening a bin for a large item is fine (large items are valuable to place anywhere)
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Global state: many open bins with large mean residual -> prefer reusing bins over opening
    if mean_residual > item_size as f64 * 1.5 && open_bins_count > 1 {
        score -= 5.0;
    }
    // If open bins are nearly full on average, opening a new bin is more acceptable
    if bin_residual != bin_capacity && (mean_residual < 15.0) {
        score += 5.0;
    }

    // Prefer placing into bins with less residual among comparable fits (best-fit flavor)
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits (low post_residual) are rewarded more strongly.
    score += 0.35 * (post / cap).powi(2) * (1.0 + 2.0 * progress);

    // Reward bins that can also hold the lookahead item (smooth interaction).
    if nxt > 0.0 && post >= nxt {
        let snug = 1.0 - ((post - nxt) / cap).powi(2);
        score -= 0.8 * snug.max(0.0);
    } else if nxt > 0.0 {
        // Lookahead won't fit: penalize creating dead space, more so later in stream.
        score += 0.5 * (nxt / cap) * (0.5 + progress);
    }

    // Penalize wasted capacity relative to mean residual (fragmentation pressure).
    score += 0.2 * ((post - mean_residual) / cap);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // New-bin candidate (residual == capacity): only attractive when the item
    // leaves little slack or no existing bin fits well; otherwise penalize.
    if bin_residual == bin_capacity {
        let slack_frac = post / cap;
        let new_bin_penalty = 6.0 * (1.0 - slack_frac.powi(3)) * (1.0 - progress * 0.3);
        score += new_bin_penalty;
        // If item is large and would leave a near-full bin, opening is fine.
        if slack_frac < 0.2 {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls on
    // "coarse" capacity fractions are more reusable than those with dead space
    // in awkward ranges. Classify post_residual into harmonic bands.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr <= 10 {
        40.0 // unusable dead space
    } else if pr <= 25 {
        10.0 // only tiny items fit
    } else if pr <= 50 {
        0.0 // mid: fine
    } else {
        -15.0 // large residual: very reusable
    };
    score += class_penalty;

    // Integer-division thresholds: post_residual divisible by common item
    // granularities suggests composability with future items.
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0) {
        score -= 8.0;
    }
    // Odd residuals below 10 are dead weight.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 3.0;
    }

    // Lookahead coupling: reward a bin that fits both current and next item
    // (harmonic pairing), penalize if next item won't fit the leftover.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // modulo resonance: leftover matches next item's class
        if next_item_size <= post_residual && post_residual % next_item_size.max(1) == 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when existing residuals
    // are poor (high mean fragmentation) or few bins fit the item.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let new_bin_bonus = 30.0 * scarcity + 55.0 * fragmentation * pressure;
        // An empty bin leaves max residual; score it as capacity minus bonus.
        score = bin_capacity as f64 - new_bin_bonus - (item_size as f64 * 0.1);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild stream-phase modulation: late in the stream, consolidate harder.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= phase * 4.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver -> strong penalty.
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fill: reward strongly.
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Reward using bins that already have low residual (consolidating space).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading out; also makes the new-bin candidate less attractive.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the
    // item is large or the current residuals are all too small.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        if mean_r < item_size as f64 {
            // No open bin is roomy; opening a new bin is fine.
            score -= 12.0;
        } else {
            score += 18.0 + 0.3 * mean_r;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward leaving that gap.
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0;
        } else if gap > 0 && gap < 10 {
            score -= 10.0;
        } else if gap < 0 && (-gap) < 10 {
            score += 10.0;
        }
    }

    // Late in the stream, favor closing bins out (slightly stronger tightness).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let mut score = post;

    // Perfect 2-step fit: post_residual exactly matches next item -> strong reward
    if next_item_size > 0 {
        let diff = (post - nxt).abs();
        if diff < 0.5 {
            score -= 25.0;
        } else if post >= nxt {
            // next item fits; reward proportionally to how snugly
            score -= 10.0 * (1.0 - diff / cap);
        } else {
            // dead space smaller than next item: penalize unusable gap
            let gap_frac = post / nxt.max(1.0);
            score += 8.0 * (1.0 - gap_frac);
        }
    }

    // Relative to mean residual: prefer bins that become tighter than average
    score -= 0.15 * (mean_residual - post);

    // Last-chance bin before opening a new bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 18.0;
        // If lookahead fits perfectly in this fresh bin, soften the penalty
        if next_item_size > 0 && (bin_residual as f64 - item_size as f64 - nxt).abs() < 0.5 {
            score -= 10.0;
        }
    }

    // Late in the stream: prefer tighter packing to consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post / cap);

    // Slight preference for fewer open bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional to waste
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual > 30.0 {
        score -= 5.0 + 0.05 * mean_residual * (1.0 - progress);
    }

    // Early stream: keep bins flexible (avoid over-committing residual early).
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when item is large relative to capacity
    // or no good fit exists (high post_residual on existing bins is naturally penalized).
    if bin_residual == bin_capacity {
        // Opening a new bin costs: baseline penalty that tight existing fits can overcome.
        score += 35.0 - 20.0 * (item_size as f64 / bin_capacity as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin has room for lookahead item
        }
    }

    score
}
